local SANDS = "https://worldofwarcraft.blizzard.com/media/short-story/war-of-the-shifting-sands"
local HAMMERS = "https://news.blizzard.com/en-us/article/14301664/muradin-hero-week"
local KING = "https://news.blizzard.com/en-us/article/24177510/challenge-the-lich-king-and-his-minions"
