local MANUAL = "https://ftp.blizzard.com/pub/misc/Warcraft%20III%20Manual.pdf"
local ASPECTS = "https://worldofwarcraft.blizzard.com/en-us/media/short-story/charge-of-the-aspects"
local DEMONS = "https://worldofwarcraft.blizzard.com/en-us/news/20056283"

A.RegisterLoreNotes({
    {id = "faction:argent-dawn",
        title = "Argent Dawn",
        kind = "Faction",
        body = "The Argent Dawn is a neutral order that calls on both Horde and Alliance to fight the evils threatening Azeroth. Its officers describe a cause beyond political allegiance: cooperation against enemies such as the Scourge matters more than the quarrels dividing the living. That principle extends to the free undead. Leonid Barthalomew, released from the Scourge by the Banshee Queen, serves the Dawn at Light's Hope Chapel.\n\nThe order combines information gathering with armed resistance. Its scouts investigate the Twilight's Hammer in Blackfathom Deeps, while its officers in the Plaguelands commission adventurers and accept scourgestones as proof of their efforts. Light's Hope Chapel coordinates opposition to the Scourge's invasion. The Dawn's reach depends on these scattered agents and volunteers acting against dangers that cross faction borders.",
        sources = {"Original Argent Officer Pureheart Classic gossip: https://warcraft.wiki.gg/wiki/Argent_Officer_Pureheart", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #1198 In Search of Thaelrid; #1199 Twilight Falls; #5462 The Dying, Ras Frostwhisper; #8414 Dispelling Evil", "Original Quartermaster Miranda Breechlock and Argent Outfitter gossip: https://warcraft.wiki.gg/wiki/Quartermaster_Miranda_Breechlock ; https://warcraft.wiki.gg/wiki/Argent_Outfitter"},
        names = {},
        related = {"place:lights-hope", "npc:leonid-barthalomew", "place:chillwind"},
        setting = "Classic / Forever"},
    {id = "faction:cenarion-circle",
        title = "Cenarion Circle",
        kind = "Faction",
        body = "The Cenarion Circle is a fellowship of druids devoted to preserving nature and its balance. Its traditions follow Cenarius and Malfurion Stormrage, while its living work joins night elves and tauren across the division between Alliance and Horde. Moonglade is a shared refuge and place of instruction, where druids learn to understand the animal forms they assume rather than merely wield their power.\n\nMalfurion's absence leaves Fandral Staghelm directing the druids from Darnassus, but the Circle has several centers of guidance. Keeper Remulos watches over Moonglade, and Hamuul Runetotem leads its work in Thunder Bluff. Tensions between Fandral and Remulos have not closed Moonglade to students of either people.\n\nIn Silithus, the Circle's calling becomes an armed defense of the land. Cenarion Hold gathers allies and supplies against the silithid and qiraji, while Commander Mar'alith's forces investigate the Twilight's Hammer and seek to expel it. Research, teaching and war all serve the same purpose: protecting a living world whose dangers cross every political border.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 26, 28, 1000: A Lesson to Learn; Trial of the Lake; The New Frontier)", "https://warcraft.wiki.gg/wiki/Cenarion_Circle", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 933, 3763, 28, 936, 5921: Crown of the Earth; Assisting Arch Druid Staghelm; Trial of the Lake; Assisting Arch Druid Runetotem; Moonglade)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8275, 8280, 8287, 8310: Taking Back Silithus; Securing the Supply Lines; A Terrible Purpose; Breaking the Code)"},
        names = {},
        related = {"npc:remulos", "npc:hamuul", "npc:fandral"},
        setting = "Classic / Forever"},
    N("faction:earthen-ring", "Earthen Ring", "Faction",
        "A fellowship of shamans devoted to understanding and preserving the elements. Je'neu Sancrea's investigations at Blackfathom Deeps seek the history of elemental disturbances and a way to resist the Twilight's Hammer's influence.",
        {824, 908}, nil, {"npc:jeneu", "group:twilights-hammer"}),
    {id = "faction:kirin-tor",
        title = "Kirin Tor",
        kind = "Faction",
        body = "The Kirin Tor is the society of mages that governs Dalaran, guided by its Council of Six. Its scholars study and catalogue spells, magical objects and artifacts, making the city a center of arcane learning. Its magi also served the Alliance of Lordaeron, carrying that learning into the wars against the Horde.\n\nArchmage Antonidas led the Kirin Tor when the Third War overtook Dalaran. Kel'Thuzad, once one of the Kirin Tor's own senior members, abandoned its restrictions on necromancy and served the Lich King. The Scourge invaded Dalaran for Medivh's spellbook; Kel'Thuzad used it to summon Archimonde, who destroyed the city.\n\nSurviving wizards now rebuild behind a vast magical dome, with mages and bound elementals patrolling the ruined outskirts. The work is secretive, but the order is not wholly cut off: Archmage Ansirem Runeweaver still receives inquiries from beyond Dalaran and applies his scholarship to dangerous magical mysteries.",
        sources = {"https://warcraft.wiki.gg/wiki/Kirin_Tor", "https://warcraft.wiki.gg/wiki/Kel%27Thuzad_and_the_Forming_of_the_Scourge", "https://warcraft.wiki.gg/wiki/Under_the_Burning_Sky_%28WC3_Undead%29", "https://warcraft.wiki.gg/wiki/Warcraft_III%3A_Reign_of_Chaos_manual", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 545, 602: Dalaran Patrols; Magical Analysis)"},
        names = {"Wizard Council of Dalaran", "Magus Senate of Dalaran"},
        related = {"city:dalaran", "npc:kelthuzad", "npc:jaina"},
        setting = "Classic / Forever"},
    {id = "faction:forsaken",
        title = "The Forsaken",
        kind = "Faction",
        body = "The Forsaken are free-willed undead who broke away from the Scourge and gathered under Sylvanas Windrunner, the Dark Lady. Their home is the Undercity beneath Lordaeron's ruined capital. They belong to the Horde, whose support gives them allies in their struggle against the Lich King.\n\nFreedom from his command is central to their identity. Bethor Iceshard seeks to recruit his old Kirin Tor colleague Gunther after discovering that he, too, escaped the Lich King's grasp. In Silverpine, however, the Forsaken also pursue territory: Dalar Dawnweaver studies Arugal's magic so that he can turn it against the wizard and secure the forest for the Dark Lady. Their independence has produced a society with ambitions and enemies of its own.",
        sources = {"https://warcraft.wiki.gg/wiki/Forsaken (independent lead, first historical paragraph)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #366 Return the Book; #422 Arugal's Folly"},
        names = {"Forsaken"},
        related = {"npc:sylvanas", "place:undercity", "npc:bethor"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "faction:scourge",
        title = "The Scourge",
        kind = "Faction",
        body = "The Scourge is the Lich King's undead army, built to destroy the living and turn death into a source of new soldiers. Its plague transformed the people of Lordaeron into undead, while necromancers raised corpses to swell its ranks. Kel'Thuzad and the Cult of the Damned helped spread the disaster by distributing infected grain.\n\nThe army began as an instrument of the Burning Legion's invasion. The demons created the Lich King to prepare Azeroth for their arrival, with dreadlords overseeing his work. Arthas Menethil became his champion and helped deliver Lordaeron to the Scourge. He later reached the Frozen Throne and united with Ner'zhul, becoming the Lich King himself.\n\nThe Scourge's hold on Lordaeron remains visible in ruined towns and hidden laboratories. Araj the Summoner commands the undead occupying Andorhal. At Scholomance, necromantic research includes experiments with black dragon eggs to create a plagued dragonflight. These strongholds show an enemy that continues to develop new weapons as well as defend its conquests.",
        sources = {"Original Warcraft III dialogue: https://gamefaqs.gamespot.com/pc/256222-warcraft-iii-reign-of-chaos/faqs/38456 (The Cult of the Damned, March of the Scourge and Trudging through the Ashes); https://warcraft.wiki.gg/wiki/The_Revelation_%28WC3_Undead%29 ; https://warcraft.wiki.gg/wiki/The_Ascension_%28WC3_Undead%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #105 Alas, Andorhal; #5531 Betina Bigglezink; #5533 Scholomance"},
        names = {"Scourge"},
        related = {"faction:argent-dawn", "npc:lich-king", "npc:kelthuzad"},
        setting = "Classic / Forever"},
    {id = "faction:silver-hand",
        title = "Order of the Silver Hand",
        kind = "Faction",
        body = "The Knights of the Silver Hand are paladins who join service to the Holy Light with the discipline of armed defenders. The order arose after the First War, when Archbishop Alonsus Faol and his apprentice Uther faced the failure of unprotected clerics against the Horde. Uther called pious knights to a new vocation: warriors able to defend the people as well as heal them. They fought for the Alliance in the Second War.\n\nThe Third War shattered that brotherhood. At Stratholme, Uther refused Arthas's command to slaughter the city's people, and the prince dismissed him and suspended his paladins from service. Arthas later returned as a death knight and killed his former mentor. Tirion Fordring remembers Uther's death as the devastation of the order; his son Taelan abandoned its standard in despair.\n\nThe Silver Hand's name and duty nevertheless survive. Paladins still train at Northshire, where recruits are taught to live as visible examples of the Light. Tirion's struggle to reclaim Taelan from the Scarlet Crusade ends with his own declaration that the order will be reborn under his leadership.",
        sources = {"https://warcraft.wiki.gg/wiki/Warcraft_II%3A_Tides_of_Darkness_manual", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 3101: Consecrated Letter)", "https://classic.battle.net/war2/units/paladin.shtml", "https://warcraft.wiki.gg/wiki/The_Culling_%28WC3_Human%29", "https://warcraft.wiki.gg/wiki/Digging_up_the_Dead", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 5845: Of Lost Honor)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 3101, 5944: Consecrated Letter; In Dreams)"},
        names = {"Knights of the Silver Hand", "Silver Hand"},
        related = {"npc:uther", "npc:tirion", "npc:taelan"},
        setting = "Classic / Forever"},
    {id = "faction:brood-nozdormu",
        title = "Brood of Nozdormu",
        kind = "Faction",
        body = "The Brood of Nozdormu is the bronze dragonflight's faction, represented in the struggle against Ahn'Qiraj by Anachronos. Its dealings with mortals carry the bitterness of the War of the Shifting Sands. After the dragons and night elves sealed the qiraji behind the Scarab Wall, Fandral Staghelm shattered the scepter Anachronos offered him, leaving their alliance broken as well.\n\nWith another war approaching, Baristolth of the Shifting Sands seeks a mortal champion worthy of the Brood's trust. The candidate must first confront Broodlord Lashlayer, then prove resolve against the silithid hives. Others can be deputized to help. Winning the bronze dragons' favor therefore means repairing an old breach while preparing for the danger stirring beyond the sealed gates.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8288)", "https://warcraft.wiki.gg/wiki/A_Pawn_on_the_Eternal_Board", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8286)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8301)"},
        names = {"Brood of Nozdormu"},
        related = {"npc:anachronos", "npc:nozdormu", "event:shifting-sands"},
        setting = "Classic / Forever"},
    {id = "faction:hydraxian-waterlords",
        title = "Hydraxian Waterlords",
        kind = "Faction",
        body = "The Hydraxian Waterlords are water elementals associated with Neptulon, represented on Azshara's coast by Duke Hydraxis. They wage an elemental struggle against the servants of air, earth and fire, and recruit mortals whose deeds can prove them useful allies. Even their work in the Plaguelands follows this purpose: Hydraxis asks that corrupted water elementals be cleansed with an aspect of Neptulon.\n\nTheir great enemy within Blackrock Mountain is Ragnaros. Hydraxis tests adventurers against Pyroguard Emberseer and the creatures of Molten Core, then demands the deaths of four powerful flamewaker captains. Those who earn the Waterlords' trust receive quintessence capable of dousing the Firelords' runes. Their alliance gives mortals a direct part in the struggle against the elemental powers entrenched beneath the mountain.",
        sources = {"https://warcraft.wiki.gg/wiki/Hydraxian_Waterlords", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 6804, 6805, 6821, 6822, 6823, 6824, 7486)", "https://warcraft.wiki.gg/wiki/Eternal_Quintessence"},
        names = {"Waterlords"},
        related = {"npc:hydraxis", "dungeon:molten-core"},
        setting = "Classic / Forever"},
    {id = "faction:thorium-brotherhood",
        title = "Thorium Brotherhood",
        kind = "Faction",
        body = "The Thorium Brotherhood consists of Dark Iron dwarves who have broken away from their clan. From Thorium Point above the Cauldron in northern Searing Gorge, they watch their former brethren and recruit help against them. This rivalry reaches directly into their work: Dark Irons steal their smithing equipment, while the Brotherhood posts contracts against the slavers and taskmasters operating below.\n\nThe Brotherhood's craftsmen possess exceptional knowledge, including plans for powerful arms whose materials must be recovered from Molten Core. Supplying those rare resources can earn access to their closely held designs. Lokhtos Darkbargainer's dealings in Blackrock Depths connect this craft to the dangerous depths of the mountain, while a formal contract involving a Sulfuron ingot shows the care with which the Brotherhood protects its business.",
        sources = {"https://warcraft.wiki.gg/wiki/Thorium_Brotherhood", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 7728, 7729, 7604)"},
        names = {"TB Ltd."},
        related = {"faction:dark-iron", "dungeon:molten-core", "dungeon:blackrock-depths"},
        setting = "Classic / Forever"},
    {id = "faction:timbermaw",
        title = "Timbermaw",
        kind = "Faction",
        body = "These furbolgs resist the corruption afflicting neighboring tribes, but attacks by outsiders have made them distrustful. They ask prospective allies to oppose the Deadwood and seek a remedy for the demonic influence over the Winterfall.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8460, 8481)"},
        names = {"Timbermaw tribe", "Timbermaw Hold (faction)", "Timbermaw Hold (reputation faction)"},
        related = {"faction:deadwood", "faction:winterfall", "place:timbermaw-hold"},
        setting = "Classic / Forever"},
    N("faction:deadwood", "Deadwood Tribe", "Faction",
        "The Deadwood furbolgs of Felwood have been driven into madness by fel corruption. Evidence of their dealings with the Winterfall raises the possibility that the trouble on either side of Timbermaw Hold shares a source.",
        {5084, 8460}, {"Deadwood tribe", "Deadwood"}, {"faction:timbermaw", "faction:winterfall"}),
    N("faction:winterfall", "Winterfall Tribe", "Faction",
        "The Winterfall furbolgs of Winterspring suffer under a corrupting demon's influence. The Timbermaw's effort to expose Xandivious offers them a chance to recover, though the quest warns that healing will be slow and conflict will persist.",
        {5084, 8481}, {"Winterfall tribe", "Winterfall"}, {"faction:timbermaw"}),
    {id = "faction:ravenholdt",
        title = "Ravenholdt",
        kind = "Faction",
        body = "Ravenholdt is an Assassin's League based in a secluded manor in the Hillsbrad hills, where Lord Jorach Ravenholdt and Fahrad draw promising rogues into their affairs. Fahrad's invitation treats finding the hidden manor as a thief's first test. Jorach later entrusts proven recruits with business whose details must remain secret.\n\nThe league has fought the Syndicate for years. Its rivals have numbers enough to withstand ordinary killing, so Ravenholdt turns the Syndicate's own discipline against it. Rogues are sent to steal members' emblems, beginning around Durnholde; a thief who loses that badge is disgraced and punished by the Syndicate itself. Ravenholdt's methods make stealth and knowledge of an enemy's habits as valuable as open force.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 6681, 8233)", "https://tbc.cavernoftime.com/quest%3D6701"},
        names = {"Assassin's League"},
        related = {"npc:jorach", "npc:fahrad", "faction:syndicate"},
        setting = "Classic / Forever"},
    {id = "faction:zandalar",
        title = "Zandalar Tribe",
        kind = "Faction",
        body = "The Zandalar Tribe sends a contingent to Yojamba Isle, off the coast of Stranglethorn Vale, to oppose Hakkar's return. Molthor leads the island's trolls and welcomes allies against the Soulflayer and his followers in Zul'Gurub. Their work includes destroying the Hakkari's bijous at the Altar of Zanza.\n\nTheir rewards also preserve older ideals. The Zandalar honor the freethinkers who challenged Hakkar's priesthood under the Gurubashi Empire despite persecution. Outsiders willing to fight the blood god can earn recognition within that tradition.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #8182 The Hand of Rastakhan", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #8240 A Bijou for Zanza", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #8053 Paragons of Power: The Freethinker's Armguards; #8054 Paragons of Power: The Freethinker's Belt"},
        names = {"Zandalar", "Zandalari"},
        related = {"dungeon:zulgurub", "npc:hakkar", "faction:hakkari"},
        setting = "Classic / Forever"},
    {id = "faction:darkspear",
        title = "Darkspear Tribe",
        kind = "Faction",
        body = "The Darkspear are the troll tribe that joined Thrall's Horde during its journey to Kalimdor. Their alliance began on an island where Sen'jin's people faced hostile humans and murlocs serving a sea witch. Thrall helped free the prisoners, but could not save Sen'jin. He welcomed the surviving trolls into his company, and together they escaped the sinking island.\n\nTheir new home brought another struggle. Zalazane's magic drove the Darkspear from the Echo Isles, and his enthralled followers continue crossing to the mainland to seize more victims. Master Gadrin calls for resistance against the witch doctor and the former tribesmen under his control.\n\nThe tribe's older ties also reach across the sea. Nimboya searches Stranglethorn for Yenniku, who had been entrusted to the Gurubashi before the Darkspear departed with Thrall. The search passes through their Bloodscalp enemies to Zanzil's hold over the missing troll, leaving the tribe seeking a way to free him.",
        sources = {"Original Warcraft III demo campaign dialogue: https://wowwiki-archive.fandom.com/wiki/Riders_on_the_Storm ; https://worldofwarcraft.fandom.com/et/wiki/The_Fires_Down_Below (English original dialogue transcript, especially ending cinematic); https://wowwiki-archive.fandom.com/wiki/Countdown_to_Extinction", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #826 Zalazane; #581 Hunt for Yenniku; #584 Bloodscalp Clan Heads; #592 Saving Yenniku"},
        names = {"Darkspear", "Darkspear trolls", "Darkspear Trolls"},
        related = {"npc:voljin", "npc:yenniku", "place:echo-isles"},
        setting = "Classic / Forever"},
    {id = "faction:bloodsail",
        title = "Bloodsail Buccaneers",
        kind = "Faction",
        body = "The Bloodsail Buccaneers are pirates operating along southern Stranglethorn Vale, where they challenge the Blackwater Raiders of Booty Bay. Fleet Master Firallon directs their fleet, whose ships include the Crimson Veil, the Riptide and the Damsel's Luck. Their raiders also prey on the port's trade and inhabitants, stealing cargo and even a sailor's enchanted glass eye.\n\nTheir rivalry threatens to become an organized assault. A scout's discovery alerts First Mate Crazz to an attack on Booty Bay, and Fleet Master Seahorn seeks the charts and orders held at the Bloodsail command post on the Wild Shore. He then calls for a strike against Firallon's leadership before the enemy can attack. The Bloodsail themselves welcome adventurers who have made enemies of Booty Bay.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #576, #587, #595, #599, #604, #608 The Bloodsail Buccaneers and related quests; #1036 Avast Ye, Scallywag"},
        names = {"Bloodsail"},
        related = {"faction:blackwater-raiders", "place:booty-bay", "book:bloodsail-orders"},
        setting = "Classic / Forever"},
    {id = "faction:steamwheedle",
        title = "Steamwheedle Cartel",
        kind = "Faction",
        body = "The Steamwheedle Cartel is a goblin trading organization whose settlements connect distant parts of Azeroth. Booty Bay, Ratchet, Gadgetzan and Everlook belong to its commercial network. Its neutrality lets it do business across the Alliance-Horde divide, with customers and profitable opportunities carrying more weight than either side's loyalties.\n\nThat outlook appears in the Argent Dawn's dealings at Everlook. The Dawn maintains a representative there to negotiate with the local government, sending reports to both Chillwind Camp and the Bulwark. Its officers describe goblin loyalty as strongly influenced by money, but also recognize the value the cartel places on diplomacy and returning customers. Steamwheedle power rests on those continuing relationships as well as its scattered trading towns.",
        sources = {"https://warcraft.wiki.gg/wiki/Steamwheedle_Cartel", "https://warcraft.wiki.gg/wiki/Classic_reputation_rewards", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 6028, 6029)"},
        names = {"Steamwheedle"},
        related = {"place:booty-bay", "place:gadgetzan", "place:everlook"},
        setting = "Classic / Forever"},
    {id = "faction:venture-company",
        title = "Venture Company",
        kind = "Faction",
        body = "The Venture Company is a goblin-run enterprise whose appetite for timber and minerals repeatedly brings it into conflict with the people living around its operations. In Mulgore, its miners continue working despite the tauren's refusal to grant mining rights. In Stonetalon, goblin crews burn and cut the forest, using shredders able to fell trees at a terrifying pace. Tauren witnesses describe the land's spirits crying out in pain and anger.\n\nIts business also reaches Stranglethorn, where miners and geologists work near Lake Nazferiti. Revilgaz's associates see the company as a commercial rival and seek samples of the strange blue crystals its geologists found near Lake Nazferiti, which Revilgaz suspects may be fuel or another catalyst. The company's enemies therefore include both defenders of threatened land and competitors pursuing their own profits; its extraction sites draw resistance for very different reasons.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 764, 1062, 1068, 201, 213)"},
        names = {"Venture Co.", "The Venture Co.", "Venture Co"},
        related = {"faction:steamwheedle", "place:booty-bay"},
        setting = "Classic / Forever"},
    N("faction:magram", "Magram Clan", "Faction",
        "A centaur clan of southeastern Desolace and a bitter enemy of the Gelkis. Its spokesman Warug measures an outsider's worth through strength demonstrated against that rival clan.",
        {1367}, {"Magram", "Magram centaur"}, {"faction:gelkis", "npc:warug"}),
    N("faction:gelkis", "Gelkis Clan", "Faction",
        "A centaur clan of southwestern Desolace, represented by the shaman Uthek the Wise. The Gelkis require enemies of the Magram to prove their intentions before offering friendship and further work.",
        {1368}, {"Gelkis", "Gelkis centaur"}, {"faction:magram", "npc:uthek"}),
    {id = "faction:wildhammer",
        title = "Wildhammer Clan",
        kind = "Faction",
        body = "The Wildhammers are a distinct dwarf clan whose exile from Ironforge led them first to Grim Batol. Although they survived the Dark Iron assault during the War of the Three Hammers, Modgud's death left their fortress tainted. They refused a return to Ironforge and founded Aerie Peak in the Hinterlands, where they drew closer to nature and bonded with gryphons.\n\nFalstad Wildhammer and the renowned Aerie Peak aviary give that heritage a living presence. The clan defends its home against the region's forest trolls and seeks to extend its influence around abandoned Horde positions such as Skulk Rock. In this era the Wildhammers welcome Alliance visitors without formally belonging to the Alliance, while treating the Horde as enemies. Their gryphons and independence distinguish them from their cousins beneath Ironforge.",
        sources = {"https://warcraft.wiki.gg/wiki/War_of_the_Three_Hammers_%28History_of_Warcraft%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 1449, 2877)", "https://warcraft.wiki.gg/wiki/Wildhammer_Clan_%28Classic%29"},
        names = {"Wildhammers", "Wildhammer dwarves"},
        related = {"npc:falstad", "event:three-hammers"},
        setting = "Classic / Forever"},
    {id = "faction:frostwolf",
        title = "Frostwolf Clan",
        kind = "Faction",
        body = "The Frostwolf Clan made its home in a hidden valley of the Alterac Mountains after Gul'dan drove it into exile. Thrall's arrival linked the secluded clan to the reunification of the orcs, but the Frostwolves chose to remain in the land they had long inhabited. Under the shaman Drek'Thar, they defend the southern reaches of Alterac Valley as part of the Horde.\n\nThe arrival of the Stormpike Expedition turned that homeland into a battlefield. The dwarves seek ore and ancient relics; the Frostwolves regard their presence as an invasion. Alliance accounts acknowledge Frostwolf territory but blame the orcs for attacking visitors who came peacefully. Each side therefore presents its war as an answer to the other's aggression. The clan calls newcomers to its defense and tests their resolve through a rite involving the recovery of a Frostwolf banner.",
        sources = {"Original Blizzard Alterac Valley introduction preserved in https://warcraft.wiki.gg/wiki/Game_Guide/Battlegrounds (Alterac Valley section only)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7141 The Battle of Alterac; #7161 Proving Grounds; #8369 Invaders of Alterac Valley; #8375 Remember Alterac Valley!"},
        names = {"Frostwolf", "Frostwolves"},
        related = {"npc:drekthar", "npc:thrall", "faction:stormpike"},
        setting = "Classic / Forever"},
    {id = "faction:syndicate",
        title = "The Syndicate",
        kind = "Faction",
        body = "The Syndicate is a criminal organization led by nobles of fallen Alterac who continue to pursue power through thieves, assassins and armed camps. In Hillsbrad, Southshore's magistrate suspects its agents of murdering his predecessor. Farther east, its killers collect bounties for the badges of Stromgarde's defenders, turning violence against the kingdom into paid work.\n\nIts ambitions also threaten the Horde. Survivors of an expedition describe being ambushed at Durnholde and taken captive; prisoners in the Alterac Mountains are forced to haul burdens and dig. Aliden Perenolde styles himself lord of the land and plans to enslave the orcs again, invoking Blackmoore's example. The Syndicate's scattered camps thus sustain both ordinary banditry and the claims of displaced rulers who hope to regain authority over others.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 505, 682, 498, 503, 506, 507)"},
        names = {"Syndicate"},
        related = {"place:durnholde", "place:southshore"},
        setting = "Classic / Forever"},
    {id = "faction:burning-blade",
        title = "Burning Blade",
        kind = "Faction",
        body = "The Burning Blade name carries a legacy of demonic corruption among the orcs. The clan was broken by that corruption; surviving blademasters who sought to free their brethren from demonic control later joined Thrall's Horde. The Burning Blade cult active in Durotar follows a very different cause, spreading demonic influence close to the new Horde's home.\n\nIts coven in the Valley of Trials summons vile familiars, while further agents operate around Skull Rock. Neeru Fireblade presents himself as a useful warlock in Orgrimmar, but Thrall knows that he serves the Shadow Council and secretly leads the Burning Blade. Thrall uses an infiltrator to exploit Neeru's confidence and investigate the allied Searing Blade in Ragefire Chasm.\n\nThe cult also has a foothold in Desolace, where Horde agents seek to capture its followers' corrupted spirits in enchanted gems. Its scattered cells make corruption an internal danger as well as an enemy beyond Durotar.",
        sources = {"https://classic.battle.net/war3/orc/units/blademaster.shtml", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 792, 794, 5726, 5727, 5728, 1435)"},
        names = {"Burning Blade cult", "Burning Blade clan"},
        related = {"faction:shadow-council", "npc:thrall"},
        setting = "Classic / Forever"},
    {id = "faction:shadow-council",
        title = "Shadow Council",
        kind = "Faction",
        body = "The Shadow Council began as Gul'dan's secret sect on Draenor, founded with Kil'jaeden's aid to tighten the Burning Legion's hold over the orcs. It manipulated the clans and spread warlock magic, helping turn their society toward the demons' purposes while that magic poisoned their homeland.\n\nIn Felwood, the Council plots with the Legion from corrupted barrow dens at Jaedenar. Its inner fortress, Shadow Hold, is protected by magical braziers that frustrate attempts to discover its leadership through scrying. Opponents seek to extinguish those wards with purified water, exposing the cult's hidden chambers as well as weakening its defenses.",
        sources = {"https://warcraft.wiki.gg/wiki/Kil%27jaeden_and_the_Shadow_Pact (original in-game chapter)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5155 Forces of Jaedenar; #5157 Collection of the Corrupt Water"},
        names = {},
        related = {"faction:burning-legion", "npc:guldan", "place:jaedenar"},
        setting = "Classic / Forever"},
    {id = "faction:blackrock-clan",
        title = "Blackrock Clan",
        kind = "Faction",
        body = "The Blackrock are an orc clan surviving the Old Horde's defeat in the Second War. Rend Blackhand, son of Blackhand, claimed the title of Warchief after taking refuge in Blackrock Spire. His followers fought the Dark Iron dwarves for the fortress; Nefarian's arrival secured their hold above, but placed Rend under the dragon's command.\n\nThe clan's attacks reach beyond the mountain. Gath'Ilzogg directs raids against Lakeshire from the captured Stonewatch Keep, while Blackrock Champions command encampments in Redridge. Helendis Riverhorn's investigation identifies the black dragonflight as the power controlling the orcs and suspects it of feeding their rage. Thrall rejects Rend's claim and calls for his death, making the Blackrock leadership an enemy of the new Horde as well as Stormwind.",
        sources = {"https://warcraft.wiki.gg/wiki/Eitrigg%27s_Wisdom", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 128, 169)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 4183)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 4974)"},
        names = {"Blackrock orcs", "Blackrock clan"},
        related = {"faction:dark-horde", "npc:rend", "npc:helendis"},
        setting = "Classic / Forever"},
    {id = "faction:grimtotem",
        title = "Grimtotem Clan",
        kind = "Faction",
        body = "The Grimtotem are a tauren clan led by Elder Crone Magatha, one of the elders of Thunder Bluff. Her clansman Maur dies in Ragefire Chasm while investigating its troggs on her behalf. Elsewhere, Grimtotem bands bring conflict to tauren settlements and the forests beyond.\n\nAt Darkcloud Pinnacle, their guarded messages attract the attention of Freewind Post. Cliffwatcher Longhorn also seeks Arnak Grimtotem for murder and kidnapping. In Feralas, the clan cages faerie dragons; Kindal and Jer'kai Moonweaver work to free the creatures and strike back at their captors.",
        sources = {"https://warcraft.wiki.gg/wiki/Grimtotem_tribe (identity and original World of Warcraft section only)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #3518 Delivery to Magatha; #5722 Searching for the Lost Satchel; #5724 Returning the Lost Satchel", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5064 Grimtotem Spying; #5147 Wanted - Arnak Grimtotem", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #2969 Freedom for All Creatures; #2970 Doling Justice"},
        names = {"Grimtotem", "Grimtotem tribe"},
        related = {"npc:maur-grimtotem", "place:freewind", "npc:kindal"},
        setting = "Classic / Forever"},
    {id = "faction:stonemaul",
        title = "Stonemaul Clan",
        kind = "Faction",
        body = "The Stonemaul ogres were driven from their old home by dragons. Rexxar appointed Mok'Morokk as their leader, but the clan's account describes his decline from a strong fighter into an overlord more concerned with power than his people.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 1166)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 1171)"},
        names = {"Stonemaul", "Stonemaul clan"},
        related = {"npc:rexxar", "npc:mokmorokk"},
        setting = "Classic / Forever"},
    {id = "faction:gordunni",
        title = "Gordunni Ogres",
        kind = "Faction",
        body = "The Gordunni occupy ruined night elf structures in Feralas's High Wilderness. Their presence is associated with damaged terrain and pressure on the region's hippogryphs, while recovered writings hint at organized ceremonies.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 2978)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 2980)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 3022)"},
        names = {"Gordunni", "Gordunni clan"},
        related = {"npc:rok-orhan"},
        setting = "Classic / Forever"},

    {id = "npc:thrall",
        title = "Thrall",
        kind = "Person",
        body = "Thrall is the orc shaman who leads the Horde from Orgrimmar, bearing Orgrim Doomhammer's armor and hammer. Once enslaved by humans, he now seeks a future in which his people can live freely and recover their shamanic traditions. Even the warlocks he permits in his city recognize that he refuses to abandon his own kin.\n\nA mysterious prophet's warning led him to gather the clans for a voyage to Kalimdor. He freed Grom Hellscream and other captive orcs before sailing from Lordaeron on captured human ships. In Kalimdor, he helped Cairne Bloodhoof's tauren survive their march across the Barrens. He later faced Mannoroth beside Grom, whose fatal victory broke the orcs' demonic blood curse.\n\nAfter the Battle of Mount Hyjal, Thrall founded Durotar, named for his father, and worked to build its capital at Orgrimmar. Rexxar's arrival drew him into defending the new homeland and protecting the Darkspear trolls. His pact with Jaina Proudmoore made him reluctant to strike at human forces near the border, but he authorized resistance if they attacked. Building a home for the Horde required both allies and the resolve to defend them.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 672, 3090)", "https://wowwiki-archive.fandom.com/wiki/Departures", "https://warcraft.blizzplanet.com/chasing-visions-warcraft-iii-reforged/", "https://warcraft.wiki.gg/wiki/The_Long_March_%28WC3_Orc%29", "https://warcraft.wiki.gg/wiki/The_Death_of_Hellscream_%28WC3_Orc%29", "https://warcraft.wiki.gg/wiki/To_Tame_a_Land"},
        names = {"Warchief Thrall"},
        related = {"npc:eitrigg", "npc:orgrim", "region:4f726772696d6d6172"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:eitrigg", "Eitrigg", "Person",
        "An orc who left the Horde in disgust at the influence of the Burning Legion's servants. Rescued from human captivity by Thrall, he returned to the new Horde and oversees recruits; his knowledge of the Blackrock also makes him an important adviser.",
        {787, 4941}, nil, {"npc:thrall", "faction:blackrock-clan"}),
    N("npc:orgrim", "Orgrim Doomhammer", "Person",
        "The former Warchief fought beside Thrall to free an internment camp, where a mounted attacker struck him from behind. Gor'mul's memory of that death haunts Hammerfall, while Orgrim's armor and hammer pass into Thrall's keeping.",
        {655, 672}, {"Orgrim"}, {"npc:thrall", "npc:gormul"}),
    N("npc:gormul", "Gor'mul", "Person",
        "A former captive who witnessed Doomhammer's death during the liberation of the camp at Hammerfall. Left behind in the escape, he wandered for years, and stories of the new Horde alone have not lifted his despair.",
        {655, 672}, nil, {"npc:orgrim"}),
    {id = "npc:grom",
        title = "Grom Hellscream",
        kind = "Person",
        body = "Grom Hellscream, chieftain of the Warsong clan, helped bind the orcs to the demons by willingly drinking their blood on Draenor. He later followed Thrall to Kalimdor, but the struggle to free his people did not end his own hunger for battle.\n\nSent to gather lumber in Ashenvale, Grom brought the Warsong into conflict with the night elves and Cenarius. Facing defeat, he drank again from a fountain corrupted by Mannoroth's blood. The strength it granted let him kill Cenarius, while placing the clan back under the demon's control.\n\nGrom admitted during their confrontation that the old chieftains had knowingly accepted the original bargain. Thrall captured him with a soul gem, and his shamans and Jaina's priests cleansed the corruption. Ashamed, Grom apologized; Thrall urged him to help save their people, and together they confronted Mannoroth. After the demon struck Thrall down, Grom killed him with his axe and suffered a mortal wound in the blast. His final victory broke the blood curse. The Horde honors his sacrifice at a monument in Ashenvale's Demon Fall Canyon.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Hunter_of_Shadows", "https://warcraft.wiki.gg/wiki/By_Demons_Be_Driven", "https://warcraft.wiki.gg/wiki/The_Death_of_Hellscream_%28WC3_Orc%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 8150)"},
        names = {"Grommash Hellscream", "Grommash", "Hellscream"},
        related = {"npc:thrall", "npc:mannoroth", "faction:horde"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:voljin",
        title = "Vol'jin",
        kind = "Person",
        body = "Vol'jin leads the Darkspear trolls and is the son of Sen'jin. After his father's death, he accepted Thrall's offer of a home with the Horde, eventually bringing his people to Durotar's Echo Isles. Their alliance was tested when Admiral Proudmoore's forces attacked. Working with Rexxar, Vol'jin helped defend the islands and then evacuate the trolls to the mainland; his magic let Rexxar's company take wing as spirit wyverns to strike the human fleet.\n\nThe islands did not become a lasting refuge. The witch doctor Zalazane enslaved Darkspear through dark magic, forcing the remaining free trolls to withdraw. Their settlement at Sen'jin Village stands near the lost home, while Vol'jin serves beside Thrall in Orgrimmar.\n\nHe also directs action against older troll enemies: his agent Zengu seeks Trol'kalar, a legendary troll-slaying sword, for use against Zul'Gurub.",
        sources = {"https://wowwiki-archive.fandom.com/wiki/The_Trolls_and_the_Horde", "https://warcraft.wiki.gg/wiki/To_Tame_a_Land", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 826, 638)"},
        names = {},
        related = {"faction:darkspear", "npc:thrall", "npc:rexxar"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:rexxar",
        title = "Rexxar",
        kind = "Person",
        body = "Rexxar is the Horde's Mok'nathal champion, a beastmaster of mixed orc and ogre ancestry whose bear companion is Misha. He helped secure the Horde's new homeland in Durotar, leading its warriors against Admiral Daelin Proudmoore at Theramore. When Thrall offered him a home afterward, Rexxar chose the wilderness while promising that the Horde could still call upon him.\n\nHe wanders Desolace between Stonetalon and Feralas. Thrall sends those seeking entry to Onyxia's lair to him, and Rexxar explains the black dragonflight's guarded admission rites. He ultimately calls for General Drakkisath's blood to activate the Drakefire Amulet, providing the Horde with a way through the brood mother's wards.\n\nHis earlier journeys also connect him with Chen Stormstout and the Stonemaul ogres. Rexxar appointed Mok'Morokk to lead the clan, though the overlord's later conduct left his people questioning that choice.",
        sources = {"https://warcraft.wiki.gg/wiki/Rexxar", "https://warcraft.wiki.gg/wiki/Rexxar_%28Warcraft_III%29", "https://wowpedia.fandom.com/wiki/A_Blaze_of_Glory_%28WC3_Orc%29", "https://classicdb.ch/?quest=6567", "https://classicdb.ch/?quest=6602", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #819; #1166; #1171; #6567; #6602"},
        names = {},
        related = {"npc:chen", "npc:mokmorokk", "relic:drakefire-amulet"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:chen", "Chen Stormstout", "Person",
        "A traveler remembered as a companion of Rexxar. A keg bearing his name turns up in the Barrens, and its inscription pairs the raising of spirits with the raising of a drink.",
        {819}, nil, {"npc:rexxar"}),
    N("npc:mokmorokk", "Overlord Mok'Morokk", "Person",
        "Rexxar appointed Mok'Morokk to lead the Stonemaul, whose former home was burned by dragons. The overlord asks others to retrieve possessions left behind, while his own people criticize his appetite for authority and neglect of their needs.",
        {1166, 1171}, {"Mok'Morokk"}, {"faction:stonemaul", "npc:rexxar"}),
    {id = "npc:bolvar",
        title = "Highlord Bolvar Fordragon",
        kind = "Person",
        body = "Highlord Bolvar Fordragon serves as Stormwind's regent while King Varian Wrynn is missing and the young Anduin occupies the throne. Lady Katrana Prestor advises the court, but she is secretly Onyxia, and her magic has bound Bolvar's mind and body. Lakeshire's pleas expose the consequences: with soldiers already committed elsewhere, he asks for proof of the black dragonflight's involvement and consults the very woman behind the deception.\n\nMarshal Windsor brings that proof into Stormwind Keep. When he reveals Prestor's true form, Bolvar has Anduin taken to safety and fights the dragonspawn exposed among the guards. Onyxia kills Windsor and escapes, but the medallion through which she controlled Bolvar shatters. Freed of her influence, he mourns Windsor's sacrifice and gives an adventurer a fragment of the medallion, hoping another dragon can make it a key to Onyxia's lair.",
        sources = {"https://warcraft.wiki.gg/wiki/Bolvar_Fordragon", "https://warcraft.wiki.gg/wiki/The_Great_Masquerade", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 4184-4186, 6403, 6501)"},
        names = {"Bolvar Fordragon", "Bolvar"},
        related = {"npc:onyxia", "npc:windsor", "npc:solomon"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:magni",
        title = "King Magni Bronzebeard",
        kind = "Person",
        body = "King Magni Bronzebeard rules Ironforge, bearing both the responsibilities of an Alliance monarch and the anguish of a father. His daughter Moira is with Emperor Dagran Thaurissan in Blackrock Depths. Magni believes his old Dark Iron enemy has enchanted her, and commissions adventurers to kill the emperor and bring her home unharmed.\n\nAfter Thaurissan's death, Moira calls him a great and honorable dwarf, saying her rescuers have ruined her life and that of her unborn child. Her message to her father names the child as the future heir to Ironforge, a Dark Iron dwarf. Yet a lingering effect of Thaurissan's spell may still be shaping Moira's account, leaving the family's future unsettled.\n\nHis concern for his subjects appears in a quieter petition: Sara Balloo's grief moves him to commission a memorial for her husband Sully, a dwarf lost in the Alliance's service.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 683, 686)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 4362, 4363)"},
        names = {"Magni Bronzebeard", "King Magni", "Magni"},
        related = {"npc:sara-balloo", "faction:dark-iron"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:sara-balloo", "Sara Balloo", "Person",
        "A widow whose grief leads her to petition Ironforge's king. Unable to face him herself, she sends a letter that prompts Magni to commission a memorial for her husband, Sully Balloo.",
        {683, 686}, {"Mrs. Balloo"}, {"npc:magni"}),
    {id = "npc:jaina",
        title = "Lady Jaina Proudmoore",
        kind = "Person",
        body = "The human mage Lady Jaina Proudmoore rules Theramore, the human refuge established on Kalimdor after Lordaeron's fall. Daughter of Admiral Daelin Proudmoore of Kul Tiras, she studied magic under Archmage Antonidas in Dalaran. During the Third War she investigated the plague of undeath with Prince Arthas, but refused to follow him when he ordered Stratholme's people slaughtered.\n\nHeeding the prophet Medivh, Jaina led survivors west across the sea. She and Thrall set aside their war to oppose the Burning Legion, joining the night elves in the defense of Mount Hyjal. That alliance became the foundation of her efforts to preserve peace between the Horde and Alliance.\n\nPeace demanded a bitter choice when her father attacked the orcs' new homeland. Jaina could not persuade Daelin to stop and refused to support his war; he died fighting the Horde. In Durotar, Kul Tiran troops still hold Tiragarde Keep, defying the pact Jaina and Thrall made against Archimonde.",
        sources = {"https://news.blizzard.com/en-us/article/16887806/jaina-hero-week", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 558: Jaina's Autograph)", "https://warcraft.wiki.gg/wiki/The_Last_Guardian_%28WC3_NightElf%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 784: Vanquish the Betrayers)"},
        names = {"Jaina Proudmoore", "Jaina"},
        related = {"npc:thrall", "npc:medivh", "event:third-war"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:tyrande",
        title = "Tyrande Whisperwind",
        kind = "Person",
        body = "Tyrande Whisperwind, High Priestess of Elune, leads the night elves from Darnassus's Temple of the Moon. She formed the Sentinels to protect their homeland while Malfurion Stormrage and the druids slept in the Emerald Dream, keeping watch through the long ages after the ancient wars.\n\nWhen the Burning Legion returned in the Third War, she used the Horn of Cenarius to awaken Malfurion. She also freed his imprisoned brother Illidan, defying Malfurion's opposition because she believed his power could help defeat the invaders. At Mount Hyjal she joined the defense alongside Jaina's humans and Thrall's orcs, accepting the sacrifice of the night elves' immortality to save their world.\n\nIn Darnassus, Tyrande receives news from the forests and honors those who protect her people and their allies. The frostsabers' friendship with the night elves is remembered as another legacy of her protection: she once saved their queen from giants.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Long_Vigil", "https://wowpedia.fandom.com/wiki/The_Awakening_of_Stormrage_%28WC3_NightElf%29", "https://warcraft.wiki.gg/wiki/Brothers_in_Blood", "https://warcraft.wiki.gg/wiki/Twilight_of_the_Gods", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 1081, 2972, 5981)"},
        names = {"High Priestess Tyrande Whisperwind", "Tyrande"},
        related = {"npc:malfurion", "npc:illidan", "npc:shandris"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:fandral",
        title = "Fandral Staghelm",
        kind = "Person",
        body = "Archdruid Fandral Staghelm leads the druids from Darnassus's Cenarion Enclave while Malfurion Stormrage is missing. He persuaded the Circle of Ancients to support growing Teldrassil, hoping the new World Tree would restore the night elves' immortality. The tree became their home, but lacked the blessings that had sustained their former way of life; troubled creatures and spreading corruption burden its groves.\n\nHis authority rests upon a much older and more painful history. In the War of the Shifting Sands, Fandral commanded the night elves against the qiraji armies pouring from Ahn'Qiraj. After Valstann's defense of Southwind Village failed, General Rajaxx killed Fandral's son before his eyes. With the dragons' aid, the survivors sealed Ahn'Qiraj behind the Scarab Wall. Fandral shattered the scepter Anachronos gave him to reopen it, unable to accept a victory that could not restore his son.\n\nIn Darnassus, Fandral directs the Cenarion Circle's collection of Un'Goro soil and cultivation of morrowgrain. He calls it research into an unfamiliar herb. Other researchers question why he needs so much of it, leaving an unease that his public explanation does not settle.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 933, 935, 3763: Crown of the Earth; Assisting Arch Druid Staghelm)", "https://warcraft.wiki.gg/wiki/The_War_of_the_Shifting_Sands", "https://warcraft.wiki.gg/wiki/The_War_of_the_Shifting_Sands_%28short_story%29", "https://warcraft.wiki.gg/wiki/War_of_the_Shifting_Sands", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 3764, 3781, 3791: Un'Goro Soil; Morrowgrain Research; The Mystery of Morrowgrain)"},
        names = {"Arch Druid Fandral Staghelm", "Archdruid Fandral Staghelm", "Staghelm", "Fandral"},
        related = {"npc:malfurion", "npc:valstann", "event:shifting-sands"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:malfurion",
        title = "Malfurion Stormrage",
        kind = "Person",
        body = "Malfurion Stormrage is the great night elf archdruid, taught by Cenarius and remembered as the first mortal druid. Illidan is his twin brother, and Tyrande Whisperwind his beloved companion. He helped lead resistance to the Burning Legion in the War of the Ancients, then spent long ages in the Emerald Dream while Tyrande and the Sentinels guarded the waking forests.\n\nTyrande awakened him when the Legion returned in the Third War. At Mount Hyjal, the night elves joined Jaina's humans and Thrall's orcs in holding back Archimonde. Malfurion called upon the ancient forest's spirits for the final defense that destroyed the invader, at terrible cost to Nordrassil.\n\nNow his absence has left Fandral Staghelm in charge of the druids. Malfurion's body lies in a mysterious coma, his spirit lost in the Emerald Dream. Yet his manifestation can still call for help against its corruption: the effort to redeem Eranikus draws Tyrande and Keeper Remulos into a struggle to defend both Malfurion and the Dream itself.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Warcraft_Encyclopedia/Malfurion_Stormrage", "https://warcraft.wiki.gg/wiki/Furion", "https://warcraft.wiki.gg/wiki/The_Sentinels_and_the_Long_Vigil", "https://warcraft.wiki.gg/wiki/Horn_of_Cenarius", "https://warcraft.wiki.gg/wiki/The_Battle_for_Mount_Hyjal", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 933, 8733, 8734, 8736: Crown of the Earth; Eranikus, Tyrant of the Dream; Tyrande and Remulos; The Nightmare Manifests)", "https://warcraft.wiki.gg/wiki/The_Warcraft_Encyclopedia/Tyrande_Whisperwind"},
        names = {"Shan'do Stormrage", "Malfurion", "Furion Stormrage"},
        related = {"npc:tyrande", "npc:fandral", "npc:remulos"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:hamuul", "Hamuul Runetotem", "Person",
        "The arch druid leads a Cenarion Circle research effort from Thunder Bluff's Elder Rise. His call for experienced helpers treats knowledge of nature as urgent work that can also demand considerable courage in the field.",
        {936}, {"Arch Druid Hamuul Runetotem", "Archdruid Hamuul Runetotem"}, {"faction:cenarion-circle"}),
    N("npc:remulos", "Keeper Remulos", "Person",
        "Remulos guides the Cenarion Circle in preserving nature and balance, and his shrine is part of a young druid's training. He also acts on Malfurion's plans when the corruption of Eranikus threatens the Dream and Nighthaven.",
        {28, 8734, 8736}, {"Remulos"}, {"faction:cenarion-circle", "npc:malfurion"}),
    N("npc:dendrite", "Dendrite Starblaze", "Person",
        "A Cenarion Circle teacher at Nighthaven who guides druids toward aquatic form. His instruction combines a timed underwater trial with a test of understanding, making the form an earned responsibility as well as a practical gift.",
        {26, 28}, nil, {"faction:cenarion-circle"}),
    N("npc:tajarri", "Tajarri", "Person",
        "A trusted warden of Moonglade and the Shrine of Remulos. She oversees the conclusion of the Trial of the Lake and explains how using the shrine honors the Circle's duty to nature and balance.",
        {28}, nil, {"npc:remulos", "npc:dendrite"}),
    {id = "npc:shandris",
        title = "General Shandris Feathermoon",
        kind = "Person",
        body = "General Shandris Feathermoon commands the Sentinel forces at Feathermoon Stronghold, the night elf outpost on Sardor Isle off Feralas. Her service beside Tyrande reaches back through the Third War: at Mount Hyjal she warned the priestess that the undead were building a base from which to attack their allies.\n\nIn the present, Shandris describes a military stretched across Kalimdor. Fighting in Ashenvale and the Stonetalon Mountains competes with the need to guard Feralas and prevent enemies from establishing footholds. The Hatecrest naga near the Ruins of Solarsal therefore threaten more than a remote island; their presence obstructs the night elves' advance into the forest.\n\nShandris also belongs to the Protectorate circle named by Quintis Jonespyre. Its private interest in Fandral Staghelm's morrowgrain research reveals concerns that its members do not wish the archdruid to overhear.",
        sources = {"https://warcraft.wiki.gg/wiki/Shandris_Feathermoon", "https://warcraft.wiki.gg/wiki/Feathermoon_stronghold", "https://warcraft.wiki.gg/wiki/Twilight_of_the_Gods", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 2867, 3787)"},
        names = {"Shandris Feathermoon", "Shandris", "General Feathermoon"},
        related = {"npc:tyrande", "npc:quintis", "region:466572616c6173"},
        setting = "Classic / Forever",
        autoLink = true},
    -- notes2 2026-11-05: Ginro's card partner and psychometrist added (#4129, #4130).
    N("npc:quintis", "Quintis Jonespyre", "Person",
        "Quintis Jonespyre is the druid of Feathermoon Stronghold, living in a little tree house there, and calls himself a servant of Malfurion and the Cenarion Circle. He can read an object's history by touch, a draining skill that has given him insight into cases others had written off. He is a poor card player, known as the King of the Bad Beats at Kalimdor Hold 'Em, and owes Ginro Hearthkindle money. He privately investigates the morrowgrain work being done for Fandral and asks that the discussion stay beyond the arch druid's hearing.",
        {3787, 3788, 4129, 4130}, {"Quint", "Jonespyre"}, {"npc:shandris", "npc:fandral", "npc:ginro"}),
    {id = "npc:falstad",
        title = "Falstad Wildhammer",
        kind = "Person",
        body = "Falstad Wildhammer is the High Thane of the Wildhammer dwarves at Aerie Peak in the Hinterlands. Troll attacks occupy his attention, leaving him impatient with visitors who bring questions while his people face immediate danger.\n\nBrohann Caskbelly's search for a missing gryphon pilot brings an inquiry to Falstad, but flight assignments belong to Gryphon Master Talonaxe. Falstad sends the messenger to that officer in the aviary. Talonaxe then identifies Rhapsody Shindigger as the rider he assigned to help Brohann.",
        sources = {"https://classicdb.ch/?npc=5635", "https://classicdb.ch/?quest=1449", "https://classicdb.ch/?quest=1450", "https://warcraft.wiki.gg/wiki/Falstad (original identity and Aerie Peak location only)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #1449; #1450"},
        names = {"Falstad"},
        related = {"faction:wildhammer", "place:aerie-peak"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:drekthar",
        title = "Drek'Thar",
        kind = "Person",
        body = "Drek'Thar is the elder shaman of the Frostwolf clan and Thrall's teacher in the traditions the orcs had nearly lost. When the escaped slave found the Frostwolf exiles, Drek'Thar taught him their ancestral ways and the shamanic heritage obscured by Gul'dan's corruption. This education helped Thrall imagine a future for his people beyond demonic servitude.\n\nDrek'Thar commands the Frostwolves from their keep in southern Alterac Valley. He opposes the Stormpike expedition's advance into the clan's home, while Alliance officers see his leadership as the obstacle to their search for artifacts. His own recollection gives the valley another meaning: this is where he witnessed Thrall challenge Orgrim Doomhammer. The general defending it is also a living witness to the new Horde's beginnings.",
        sources = {"https://warcraft.wiki.gg/wiki/The_New_Horde", "https://warcraft.wiki.gg/wiki/Drekthar", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 7141, 7142)"},
        names = {"Drek'thar"},
        related = {"npc:thrall", "faction:frostwolf", "battleground:alterac-valley"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:nathanos",
        title = "Nathanos Blightcaller",
        kind = "Person",
        body = "Nathanos Blightcaller is a champion of Sylvanas Windrunner and an agent of the Forsaken in the Eastern Plaguelands. He holds the Marris Stead and ranges through the ruined countryside against both the Scourge and the Alliance. Sylvanas counts him among her earliest champions and praises his dedication to her cause.\n\nHis farmstead is a harsh posting for those sent to help him. Nathanos greets new arrivals with open contempt and measures their usefulness by the work they can do. Even feeding his hounds requires an attack on the undead: he demands fresh living rot from Scourge corpses at Corin's Crossing, ground and prepared before it loses its potency.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5961 The Champion of the Banshee Queen, L24477", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6022 To Kill With Purpose, L24531"},
        names = {"Nathanos", "The Blightcaller", "Blightcaller"},
        related = {"npc:sylvanas", "faction:forsaken", "region:4561737465726e20506c616775656c616e6473"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:tirion",
        title = "Tirion Fordring",
        kind = "Person",
        body = "Tirion Fordring is a human paladin of the Silver Hand living in exile in the Eastern Plaguelands. Once lord of Mardenholde, he lost his standing after defending the orc Eitrigg and refusing to abandon his oath to protect him. His belief that honor belongs to individuals rather than races endures in his welcome to travelers of either faction.\n\nHe remains near his former home to watch over Taelan, the son who believes him dead. Taelan has inherited Mardenholde but joined the Scarlet Crusade, and Tirion hopes to awaken his conscience through reminders of a better life: a childhood warhammer, the discarded standard of the Silver Hand, and Renfray's family portrait. He asks for help recovering these keepsakes so that his son can remember love and honor beyond the Crusade's demands.\n\nThe effort persuades Taelan to leave, but Grand Inquisitor Isillien kills him before father and son can reunite. Tirion defeats the inquisitor and kneels beside his son's body. Grief finally breaks his long withdrawal: he vows to fight the evil around him and declares the Silver Hand reborn, taking his place as Highlord of the renewed order.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 5781, 5845, 5846, 5944)", "https://warcraft.wiki.gg/wiki/Tirion", "https://warcraft.wiki.gg/wiki/In_Dreams", "https://public.ds003.info/wcbooks/novels/Warcraft%20-%20(2000)%20Of%20Blood%20And%20Honor%20-%20Chris%20Metzen.pdf"},
        names = {"Tirion", "Lord Fordring"},
        related = {"npc:taelan", "npc:renfray", "faction:silver-hand"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:taelan",
        title = "Taelan Fordring",
        kind = "Person",
        body = "Taelan Fordring is Tirion's paladin son and the Scarlet lord of Mardenholde Keep in Hearthglen. After Tirion's banishment, Taelan was told his father had died; the boy buried a treasured toy hammer at an empty grave. The later death of Uther and destruction of the Silver Hand deepened his despair. He abandoned his old standard and entered the Scarlet Crusade, eventually recognizing that he had become the Grand Crusader's puppet.\n\nTirion's appeal reaches him through the recovered hammer, his lost standard, and a family portrait. Taelan breaks with the Crusade and sets out to meet the father he had believed dead. On the road, Grand Inquisitor Isillien intercepts and kills him. Tirion arrives too late to save his son, defeats Isillien, and vows that this loss will end his own withdrawal from the world: he will lead a renewed Order of the Silver Hand against the evil consuming Lordaeron.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 5781, 5845, 5846, 5862, 5944)", "https://warcraft.wiki.gg/wiki/In_Dreams"},
        names = {"Taelan"},
        related = {"npc:tirion", "group:scarlet-crusade", "faction:silver-hand"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:renfray", "Artist Renfray", "Person",
        "Renfray painted Tirion, Karandra, and young Taelan together during a family visit to Caer Darrow. After Tirion's trial, the artist hid the portrait beneath another painting in what became Stratholme's Scarlet Bastion, preserving a memory others sought to bury.",
        {5846, 5848}, {"Renfray"}, {"npc:tirion", "npc:taelan"}),
    N("npc:chromie", "Chromie", "Person",
        "The strange historian in Andorhal's ruined inn offers an unusual answer to Joseph Redpath's tragedy: seek a change in the past. Her magic extends the Annals of Darrowshire beyond the battle, uncovering surviving witnesses and another chance to understand what happened.",
        {5153, 5154, 5210}, nil, {"npc:joseph-redpath", "event:darrowshire"}),
    N("npc:pamela", "Pamela Redpath", "Person",
        "Pamela's spirit waits in Darrowshire for the father who went away to fight. Her lost doll, memories of her sister Jessica, and concern for Uncle Carlin make the ruined village's history painfully personal.",
        {5149, 5241, 5601}, {"Pamela"}, {"npc:carlin", "npc:jessica-redpath", "event:darrowshire"}),
    N("npc:carlin", "Carlin Redpath", "Person",
        "A survivor of Darrowshire now found at Light's Hope Chapel. He is Joseph's brother and Pamela's uncle, torn between grief for the dead and the living duty he believes he owes them.",
        {5210, 5241}, {"Carlin", "Uncle Carlin"}, {"npc:pamela", "npc:joseph-redpath"}),
    N("npc:joseph-redpath", "Joseph Redpath", "Person",
        "Joseph fought at Darrowshire, but the village's annals record his corruption and betrayal of its defenders. His family remembers the man he was, and Chromie's investigation seeks a way to free him from the fate the Scourge imposed.",
        {5153, 5154, 5210}, {"Joseph"}, {"npc:chromie", "npc:carlin", "event:darrowshire"}),
    N("npc:jessica-redpath", "Jessica Redpath", "Person",
        "Jessica escaped Lordaeron before the Scourge overtook her homeland, leaving her uncertain of her family's fate. Her plea to search Darrowshire centers on her little sister Pamela, who still remembers their games and dances together.",
        {5601}, {"Jessica"}, {"npc:pamela"}),
    N("npc:janice-felstone", "Janice Felstone", "Person",
        "Janice's apparition remains caught in panic over a package she meant to deliver before disaster overtook her home. Her urgent request draws attention to something still lying in the barn, an unfinished errand surviving amid the decay.",
        {5021}, {"Janice"}),
    N("npc:leonid-barthalomew", "Leonid Barthalomew the Revered", "Person",
        "Freed from the Scourge by the Banshee Queen, Leonid serves the Argent Dawn rather than his former masters. His knowledge of undeath makes him an important witness in the search for a way to undo Ras Frostwhisper's transformation.",
        {5462}, {"Leonid Barthalomew", "Leonid"}, {"faction:argent-dawn", "npc:sylvanas"}),
    N("npc:betina", "Betina Bigglezink", "Person",
        "A scholar of science and alchemy working against the Scourge's plan for a plagued dragonflight. She creates Dawn's Gambit to strike the undead researchers of Scholomance, while candidly admitting that the device still needs a field trial.",
        {5531}, {"Betina"}, {"faction:argent-dawn"}),
    N("npc:alexi-barov", "Alexi Barov", "Person",
        "Alexi Barov is one of the last two heirs of House Barov, whose fortune lies in Scholomance. He is undead now and lives under the protection of the Horde at the Bulwark in the Western Plaguelands. He calls his brother Weldon a miserable coward who fled during the war and so kept his worthless life as a human. Alexi wants the family's deeds recovered from Scholomance before Weldon finds them, and with his brother alive he expects a dispute over the inheritance, so he would rather see Weldon dead.",
        {5341, 5342, 5343}, {"Alexi"}, {"npc:weldon-barov", "place:bulwark", "dungeon:scholomance", "group:barov-family"}),
    N("npc:weldon-barov", "Weldon Barov", "Person",
        "Weldon Barov is the living brother and rival heir of Alexi Barov, and he sits under Alliance protection at Chillwind Camp in the Western Plaguelands. Alexi says he fled during the war. Weldon remembers that he once looked his undead brother in the face and spared him, and calls himself a fool for it. He wants the family's deeds recovered from the ruins of Scholomance before Alexi can claim what he calls his inheritance, and then Alexi dead, so that no hired band will ever come for his own head.",
        {5341, 5343, 5344}, {"Weldon"}, {"npc:alexi-barov", "place:chillwind", "dungeon:scholomance", "group:barov-family"}),
    N("npc:linken", "Linken", "Person",
        "Linken is a man in Un'Goro Crater who has lost his memory and cannot say how he came there. His sword and a few belongings stir his recollection, and the gnome J.D. Collie, who was kind to him when he arrived, remembers him mumbling about a totem and about Eridan Bluewind in Felwood. In the end he remembers that he came to fight Blazerunner, the elemental who guards the Golden Flame, as the last step of a long journey. He is no longer the hero, he says, and he asks another to finish it.",
        {3908, 3909, 3914, 3941, 3942, 3961, 3962}, nil, {"npc:donova", "region:556e27476f726f20437261746572"}),
    N("npc:donova", "Donova Snowden", "Person",
        "Donova lives beside Winterspring's unusual hot springs and knows how to temper Linken's sword there. When she learns of his missing memories, she points the investigation toward a Videre Elixir and a more difficult stage of the journey.",
        {980, 3908, 3909}, {"Donova"}, {"npc:linken"}),
    N("npc:eridan", "Eridan Bluewind", "Person",
        "A druid in southern Felwood who examines troubling objects taken from the satyr Xavaric. The flute and its associated evidence reveal the suffering of ancient beings, turning an apparent trophy into a warning of the forest's corruption.",
        {939}, {"Eridan"}),
    {id = "npc:hemet-nesingwary",
        title = "Hemet Nesingwary",
        kind = "Person",
        body = "Hemet Nesingwary is a dwarf master hunter and veteran of the Alliance's wars who leads a hunting expedition in Stranglethorn Vale. The white tiger King Bangalash is his great quarry, a beast that has repeatedly driven him back to camp. Before admitting newcomers to that hunt, he tests their skill: Hemet teaches raptor hunting, Ajeck oversees the tiger challenges, and Sir Erlgadin trains panther hunters.\n\nHemet is also the author of The Green Hills of Stranglethorn. He entrusts its manuscript to Barnil Stonepot for proofreading, only for a gust of wind to scatter pages across the jungle. Barnil seeks help reconstructing its four chapters before the master discovers the loss.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 583, 208, 338, 187, 190, 201)", "https://warcraft.wiki.gg/wiki/The_Green_Hills_of_Stranglethorn_%28Classic%29"},
        names = {"Hemet", "Master Nesingwary"},
        related = {"region:537472616e676c6574686f726e2056616c65"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:williden", "Williden Marshal", "Person",
        "Williden leads an independent expedition into Un'Goro Crater. Underestimating the land's dangers forces his party to abandon camps and vital supplies, leaving the recovery of food and research equipment essential to their survival.",
        {3881}, {"Williden"}),
    N("npc:ringo", "Ringo", "Person",
        "An explorer overcome by the heat of Un'Goro's volcanic heights. He hopes to reach Spraggle at Marshal's Refuge, but his exhaustion makes even the journey back uncertain without water and help along the way.",
        {4491}, nil, {"npc:spraggle"}),
    N("npc:spraggle", "Spraggle Frock", "Person",
        "Spraggle anxiously awaits Ringo at Marshal's Refuge. Her canteen becomes the practical means of keeping the heat-stricken explorer moving, and his safe return matters far more to her than the condition in which he arrives.",
        {4491}, {"Spraggle"}, {"npc:ringo"}),
    N("npc:muigin", "Muigin", "Person",
        "Stranded in Un'Goro and feuding with Larion, Muigin turns his attention to the crater's aggressive plants. He hopes that studying samples might teach him to command them, combining research with the prospect of getting even with his companion.",
        {4141}, nil, {"npc:larion"}),
    N("npc:larion", "Larion", "Person",
        "Larion is Muigin's estranged traveling companion in Un'Goro. Muigin blames him for their predicament and complains that Larion refuses to speak, making their quarrel another complication for the isolated expedition.",
        {4141}, nil, {"npc:muigin"}),
    N("npc:torwa", "Torwa Pathfinder", "Person",
        "Torwa Pathfinder is a tauren hunter who camps where the road from Tanaris enters Un'Goro Crater. The crater's creatures seem to him nobler versions of those found elsewhere, and he says the place cries of the Earth Mother. He pays homage to her whenever he tracks one of them, and he sets hunters against the great apes to the north and their leader, whom he calls U'cha. Long ago his brother took meat from a kill of the great beast Lar'korwi, which followed him for days and killed him near Torwa's camp. Torwa also asks druids to help him make a toxin that can calm a great creature of the crater without killing it.",
        {9063, 9052, 4289, 4301, 4290}, {"Torwa"}, {"region:556e27476f726f20437261746572", "deity:earth-mother"}),
    N("npc:ogtinc", "Ogtinc", "Person",
        "A furbolg hunter who left his tribe to aid the Cenarion Circle. From the cliffs of Azshara he teaches experienced hunters to recognize balance, using a collection of hunting trophies as a record of their lessons.",
        {8151}, nil, {"faction:cenarion-circle"}),
    N("npc:maralith", "Commander Mar'alith", "Person",
        "Mar'alith leads the Cenarion forces opposing the Twilight's Hammer in Silithus. His duty keeps him at his outpost even as his wife Natalia disappears after increasingly strange behavior, forcing him to ask others to trace her last movements.",
        {8287, 8304}, {"Mar'alith"}, {"faction:cenarion-circle", "npc:natalia"}),
    N("npc:natalia", "Natalia Mar'alith", "Person",
        "Natalia continues her research despite troubling changes in her behavior, then vanishes after heading toward Bronzebeard's camp. The hive investigation links her ensuing madness with a dangerous first expedition into the silithid hives.",
        {8304, 8309}, {"Mistress Mar'alith", "Natalia"}, {"npc:maralith"}),
    N("npc:larksbane", "Geologist Larksbane", "Person",
        "Larksbane studies the glyphed crystal prism brought to Cenarion Hold. She recognizes that the markings form a moving mechanism for communication rather than a simple inscription, exposing another layer of coordination behind the silithid.",
        {8314}, {"Larksbane"}),
    N("npc:beetix", "Beetix Ficklespragg", "Person",
        "Beetix struggles to keep her cousin Noggle alive after a poisonous encounter in Silithus. She needs venom samples from the northern desert's scorpids and skitterers to identify what struck him and finish an antidote.",
        {8277}, {"Beetix"}, {"npc:noggle"}),
    N("npc:noggle", "Noggle Ficklespragg", "Person",
        "Noggle gathers rare herbs for Cenarion Hold's alchemists. A collecting trip leaves him gravely poisoned, turning his cousin Beetix's knowledge and a search for the right venom into his best hope of survival.",
        {8277}, {"Noggle"}, {"npc:beetix"}),
    N("npc:calandrath", "Calandrath", "Person",
        "Calandrath cooks for Cenarion Hold in Silithus. Life in the desert has been hard on her. She misses the birds and trees of Auberdine, and the arid land offers little to eat. She studies the few desert herbs she can find and wonders how the Twilight's Hammer cultists of the camp to the west make their bitter sandworm meat palatable. Their recipe names the herbs differently, but she can read it, and from it she makes smoked desert dumplings, better than she expected anything of the Twilight's Hammer to taste.",
        {8307, 8313, 8317}, nil, {"place:cenarion-hold", "group:twilights-hammer", "region:53696c6974687573"}),
    N("npc:bor-wildmane", "Bor Wildmane", "Person",
        "Bor Wildmane is a tauren of the Cenarion Circle at Cenarion Hold in Silithus who sends the Hold's strongest allies against the elemental nobles that the Twilight's Hammer summons and worships, from the Templars to the Abyssal Dukes and Lords. With the new enemies inside Ahn'Qiraj, the Hold cannot lower its guard against the cult outside. He wants proof of every victory, pays well for it, and says he would do anything to leave his post and wrestle one of the creatures himself.",
        {8349, 8348, 8352, 8361, 8537, 8737}, {"Bor"}, {"place:cenarion-hold", "npc:huum", "npc:aurel-goldleaf", "region:53696c6974687573"}),
    N("npc:ranshalla", "Ranshalla", "Person",
        "Ranshalla travels to Winterspring to observe wildkin in their own habitat. A trail of magically unusual feathers leads to her research, just as she prepares to investigate the nearby caves.",
        {979}),
    N("npc:haleh", "Haleh", "Person",
        "The matron protectorate of the dragonflight at Mazthoril receives visitors by means of cobalt runes and a dragon's scale. The message carried by that scale draws her into a dispute over whether dragons can truly remain apart from mortal affairs.",
        {5160}, {"Matron Protectorate Haleh"}),
    N("npc:jeziba", "Jeziba", "Person",
        "Known as the Sculptor, Jeziba says that the objects of his craft are heroes rather than statues. The blue flight directs a traveler to him in Andorhal, praising his patience and wisdom.",
        {5162}, {"Jeziba the Sculptor", "The Sculptor"}),
    N("npc:felnok", "Felnok Steelspring", "Person",
        "An engineer in Everlook and a colleague of Tinkee. His specially made components are needed to test whether dragon whelp eggs can be frozen and preserved, connecting a Winterspring workshop with research in the Burning Steppes.",
        {4808}, {"Felnok"}),
    N("npc:kibler", "Kibler", "Person",
        "Kibler is a dealer in exotic pets in the Burning Steppes, an animal lover first and foremost, he says, but a salesman by trade. He tracks down unusual beasts for the rich and famous, keeps them in cages at his camp and domesticates them into proper pets. Worg pups from Blackrock Spire are among his wants, and so are the eggs of its spire spiders, since some buyers will pay for even the most vile of beasts.",
        {4729, 4862}, nil, {"dungeon:blackrock-spire", "region:4275726e696e672053746570706573"}),
    {id = "npc:windsor",
        title = "Marshal Windsor",
        kind = "Person",
        body = "Marshal Windsor is the Stormwind officer whose disappearance leaves the Alliance expedition in the Burning Steppes without its commander or his intelligence on the Blackrock threat. Found imprisoned in Blackrock Depths, he is furious with Bolvar Fordragon and initially believes his evidence lost. A discarded note reveals that General Angerforge and Golem Lord Argelmach hold the information, giving him a reason to hope and a way to act.\n\nRecovering the tablets leads to a prison escape and a confrontation in Stormwind. Windsor exposes Lady Katrana Prestor as Onyxia, the black dragon whose influence has compromised the kingdom's leadership. He dies during the confrontation, but Bolvar is freed from her control. Windsor's story turns a search for a missing soldier into the exposure of a threat at the heart of the royal court.",
        sources = {"https://classicdb.ch/?quest=4224", "https://classicdb.ch/?quest=4241", "https://classicdb.ch/?quest=4242", "https://classicdb.ch/?quest=4264", "https://classicdb.ch/?quest=4282", "https://classicdb.ch/?quest=4322", "https://classicdb.ch/?quest=6402", "https://classicdb.ch/?quest=6403"},
        names = {"Reginald Windsor", "Marshal Reginald Windsor", "Windsor"},
        related = {"npc:ragged-john", "npc:maxwell", "npc:onyxia"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:maxwell", "Marshal Maxwell", "Person",
        "Maxwell receives Stormwind's acting deputy in the Burning Steppes as the investigation into the Blackrock threat continues. Documents concerning General Drakkisath are brought to him as further evidence of the enemy's plans.",
        {4223, 5089}, {"Maxwell"}, {"npc:windsor", "npc:bolvar"}),
    N("npc:ragged-john", "Ragged John", "Person",
        "John was with Marshal Windsor when a Blackrock raiding party attacked them. Last reported in a cave north of the Alliance position, he is the surviving lead in the search for Windsor and the intelligence lost with him.",
        {4224}, nil, {"npc:windsor"}),
    N("npc:helendis", "Helendis Riverhorn", "Person",
        "Helendis warns Lakeshire that the black dragonflight controls the orcs of Blackrock. His sealed report changes the apparent scale of Redridge's war, turning a local orc threat into a matter for Stormwind's highest authorities.",
        {4183, 4184}, {"Helendis"}, {"npc:solomon", "npc:bolvar"}),
    N("npc:solomon", "Magistrate Solomon", "Person",
        "Lakeshire's magistrate seeks help for a township under continuing siege. Reports of black dragon involvement deepen his fear that Redridge's fall would expose Darkshire, Goldshire, and ultimately Stormwind itself.",
        {120, 4184, 4186}, {"Solomon"}, {"npc:bolvar", "npc:helendis"}),
    N("npc:keeshan", "Corporal Keeshan", "Person",
        "Keeshan survives the defeat of his regiment but is held badly wounded in a Blackrock cave. His escape requires aid from outside, and the kingdom recognizes bringing him home as service to the Alliance.",
        {219}, {"Keeshan", "John J. Keeshan"}),
    N("npc:senani", "Senani Thunderheart", "Person",
        "Senani receives hunting trophies at Splintertree Post as part of the Ashenvale Hunt. Sharptalon's threat to lumber-camp travelers gives one such hunt a purpose beyond sport, protecting the routes used by local peons.",
        {2}, {"Senani"}),
    N("npc:rok-orhan", "Rok Orhan", "Person",
        "Rok Orhan examines a scroll recovered from the Gordunni Outpost. Its depiction of a meeting or ceremony offers a clue to what the ogres are organizing in Feralas.",
        {2978}, nil, {"faction:gordunni"}),
    N("npc:yenniku", "Yenniku", "Person",
        "The Darkspear chief's youngest son was left behind when the tribe departed with Thrall. The search eventually places him with Zanzil at the Ruins of Aboraz, where freeing his soul from another's will requires Kin'weelay's specially prepared gem.",
        {581, 592}, nil, {"faction:darkspear", "npc:nimboya", "npc:kinweelay"}),
    N("npc:nimboya", "Nimboya", "Person",
        "Nimboya receives the soul gem intended to release Yenniku from Zanzil's control. The rescue is a matter of tribal memory as well as family loss: he promises that the Darkspear will preserve the deed in song and stone.",
        {592}, nil, {"npc:yenniku", "npc:kinweelay"}),
    N("npc:kinweelay", "Kin'weelay", "Person",
        "Kin'weelay prepares the means to free Yenniku by reshaping the Mind's Eye into a soul gem. The magic must first stun the captive and then draw out his soul, breaking Zanzil's control without treating the boy as merely another enemy.",
        {592}, nil, {"npc:yenniku", "npc:nimboya"}),
    N("npc:warug", "Warug", "Person",
        "The Magram's spokesman waits near their village in southeastern Desolace. He refuses to deal with outsiders until they have proved their strength against the Gelkis, making the clan feud the price of an audience.",
        {1367}, nil, {"faction:magram"}),
    N("npc:uthek", "Uthek the Wise", "Person",
        "A Gelkis shaman found near the clan's village in southwestern Desolace. Uthek asks would-be allies to fight the Magram, interpreting their deeds through the earth before admitting them to further dealings.",
        {1368}, {"Uthek"}, {"faction:gelkis"}),
    N("npc:kindal", "Kindal Moonweaver", "Person",
        "Kindal works with Jer'kai to free faerie dragons captured by the Grimtotem in Feralas. She joins the rescue herself and prepares reprisals afterward, recognizing that opening the cages alone cannot remove the threat.",
        {2969, 2970}, {"Kindal"}, {"npc:jerkai", "faction:grimtotem"}),
    N("npc:jerkai", "Jer'kai Moonweaver", "Person",
        "Jer'kai helps Kindal oppose the Grimtotem's capture of faerie dragons. She sends her signet to Tyrande as proof of the work in Feralas, linking an isolated struggle with the priesthood in Darnassus.",
        {2969, 2970, 2972}, {"Jer'kai"}, {"npc:kindal", "npc:tyrande"}),
    N("npc:jorach", "Lord Jorach Ravenholdt", "Person",
        "The master of Ravenholdt calls promising rogues to his hidden manor on confidential business. His invitation concerns something valuable that he wants recovered, offered as a test with a reward worthy of the risk.",
        {6681, 8233}, {"Jorach Ravenholdt", "Lord Ravenholdt", "Master Ravenholdt"}, {"faction:ravenholdt"}),
    N("npc:fahrad", "Fahrad", "Person",
        "Fahrad signs Ravenholdt's invitation to a promising thief and arranges the first test: finding the hidden manor. He welcomes successful candidates into a longer course of work among the Assassin's League.",
        {6681}, nil, {"faction:ravenholdt", "npc:jorach"}),
    N("npc:gunther", "Gunther Arcanus", "Person",
        "Gunther studied with Bethor Iceshard and Thule Ravenclaw in the Kirin Tor before the plague divided their lives. Having escaped the Lich King's control, he initially distrusts visitors until an enchantment on his own book reveals that Bethor is also free.",
        {366}, {"Gunther"}, {"npc:bethor", "npc:thule", "faction:kirin-tor"}),
    N("npc:hydraxis", "Duke Hydraxis", "Person",
        "Hydraxis invites mortal allies into the Waterlords' conflict with the other elements. His campaign tests their loyalty through sustained action, while his eventual reward acknowledges an achievement the Waterlords had thought beyond such fragile beings.",
        {6823, 7486}, {"Hydraxis"}, {"faction:hydraxian-waterlords"}),

    {id = "event:darrowshire",
        title = "Battle of Darrowshire",
        kind = "Event",
        body = "The Battle of Darrowshire pitted the village's militia and Alliance reinforcements against the Scourge. Davil's paladins helped hold the line, and he defeated the ghoul lord Horgus at the cost of his own life. The defense collapsed when Marduk the Black corrupted Captain Joseph Redpath's spirit. Redpath's treachery spread among the defenders, who turned on their allies and the villagers they had protected.\n\nThe ruined village remains haunted, but Chromie finds a way to help Joseph through its history. Relics gathered from the battle let its spirits rise again in the town square. Those joining their struggle must keep Davil alive until Horgus falls, then allow Redpath's corruption and defeat his corrupted form. This frees Joseph's spirit; afterward Pamela hears her father promise to return. The intervention offers release to the dead without making the village's original destruction cease to matter.",
        sources = {"https://warcraft.wiki.gg/wiki/Annals_of_Darrowshire (original Contents)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5142 Little Pamela; #5153 A Strange Historian; #5154 The Annals of Darrowshire; #5210 Brother Carlin", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5168 Heroes of Darrowshire; #5181 Villains of Darrowshire; #5206 Marauders of Darrowshire; #5721 The Battle of Darrowshire"},
        names = {"the battle of Darrowshire", "The Battle of Darrowshire"},
        related = {"npc:pamela", "npc:chromie", "npc:joseph-redpath"},
        setting = "Classic / Forever"},
    N("event:teldrassil-grown", "The Planting of Teldrassil", "Event",
        "Fandral and the leading druids grew a new World Tree after securing the Circle of Ancients' approval. Their hope of regaining immortality failed when Nozdormu and Alexstrasza withheld their blessings, leaving the new home's growth troubled and unpredictable.",
        {933, 7383}, {"planting of Teldrassil"}, {"npc:fandral"}),
    N("event:doomhammer-fall", "Doomhammer's Fall", "Event",
        "During the liberation of the camp later known as Hammerfall, Orgrim Doomhammer was struck from behind by a mounted attacker. The captive Gor'mul witnessed the death and was left behind as others escaped, carrying the memory long after the Horde returned.",
        {655}, {"death of Doomhammer"}, {"npc:orgrim", "npc:gormul"}),
    W("event:war-ancients", "War of the Ancients", "Event",
        "At Zin-Azshari, Queen Azshara's Highborne opened the way for the Burning Legion through the Well of Eternity. The war pitted resistance fighters, including Tyrande and Illidan, against both the invading demons and the queen's followers.",
        ANCIENTS, {"the War of the Ancients"}, {"npc:azshara", "faction:burning-legion", "book:war-ancients"}),
    W("npc:azshara", "Queen Azshara", "Person",
        "Azshara ruled the ancient night elf capital of Zin-Azshari. During the War of the Ancients, her Highborne strengthened the portal at the Well of Eternity to prepare for Sargeras's arrival.",
        ANCIENTS, nil, {"event:war-ancients"}),
    {id = "event:third-war",
        title = "Third War",
        kind = "Event",
        body = "The Third War brought the Burning Legion back to Azeroth through the devastation wrought by the Scourge. Kel'Thuzad's Cult of the Damned spread the plague of undeath through Lordaeron. Prince Arthas tried to stop it, but his pursuit of victory led him to Frostmourne and the Lich King's service. He returned to murder King Terenas and turn his armies against his own kingdom.\n\nThe Scourge then ravaged Quel'Thalas, where Arthas used the Sunwell to raise Kel'Thuzad as a lich. Their assault on Dalaran secured the magic needed to summon Archimonde. Meanwhile, the returned Medivh guided Thrall's Horde and Jaina Proudmoore's human survivors west to Kalimdor, where their arrival entangled them with the night elves and the Legion's advance.\n\nAt Mount Hyjal, Thrall and Jaina joined Tyrande and Malfurion in defending Nordrassil. Their combined resistance enabled Malfurion to unleash the World Tree's power against Archimonde. The victory repelled the Legion, but gravely wounded Nordrassil and cost the night elves their immortality; the shattered kingdoms and displaced peoples remained to rebuild.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Scourge_of_Lordaeron_%28History_of_Warcraft%29", "https://warcraft.wiki.gg/wiki/Sunwell_-_The_Fall_of_Quel%27Thalas", "https://warcraft.wiki.gg/wiki/Archimonde%27s_Return_and_the_Flight_to_Kalimdor", "https://warcraft.wiki.gg/wiki/The_Battle_of_Mount_Hyjal_%28History_of_Warcraft%29", "https://warcraft.wiki.gg/wiki/The_Battle_for_Mount_Hyjal"},
        names = {"The Third War", "Reign of Chaos"},
        related = {"npc:arthas", "npc:jaina", "npc:thrall"},
        setting = "Classic / Forever"},
    {id = "event:three-hammers",
        title = "War of the Three Hammers",
        kind = "Event",
        body = "The War of the Three Hammers divided the Bronzebeard, Wildhammer and Dark Iron clans after High King Modimus Anvilmar's death. Madoran Bronzebeard's clan secured Ironforge and expelled its rivals. The Wildhammers established Grim Batol, while Sorcerer-Thane Thaurissan founded a kingdom in the Redridge Mountains.\n\nThaurissan later attacked Ironforge as his wife Modgud struck Grim Batol. Both invasions failed, and the Bronzebeards and Wildhammers joined against the Dark Irons. Facing defeat, Thaurissan summoned Ragnaros. The catastrophe killed him, devastated the surrounding land and left his surviving people enslaved to the Firelord.\n\nThe Bronzebeards retained Ironforge. Grim Batol remained cursed, forcing the Wildhammers to leave and establish Aerie Peak. The war left the three clans divided between separate homes and profoundly different fortunes.",
        sources = {"https://warcraft.wiki.gg/wiki/War_of_the_Three_Hammers (independently written event overview, first/second-phase tables and Thaurissan's war section)", "https://warcraft.wiki.gg/wiki/War_of_the_Three_Hammers_%28History_of_Warcraft%29 (original-era cross-check only; no new chapter word allocation)"},
        names = {"the War of the Three Hammers"},
        related = {"faction:wildhammer", "npc:magni", "npc:ragnaros"},
        setting = "Classic / Forever"},
    {id = "event:shifting-sands",
        title = "War of the Shifting Sands",
        kind = "Event",
        body = "The War of the Shifting Sands was the ancient struggle to contain the qiraji and their silithid armies pouring from Ahn'Qiraj. Fandral Staghelm led the night elves against a seemingly inexhaustible enemy that overran Silithus and threatened the rest of Kalimdor. His son Valstann was captured after Southwind Village fell and killed before him, breaking the archdruid's spirit as his army retreated.\n\nAnachronos and the bronze dragons eventually joined the defense, with aid from the green, red and blue flights. Merithra, Caelestrasz and Arygos plunged into Ahn'Qiraj to hold back the swarm while Fandral, Anachronos and the remaining defenders raised the Scarab Wall. The barrier imprisoned an enemy they could not destroy.\n\nAnachronos fashioned a gong and scepter that could reopen the gates. Still consumed by grief, Fandral shattered the scepter. Anachronos recovered its fragments and entrusted their protection to the dragonflights. That broken key is the ancient war's unfinished legacy: the later effort to reopen Ahn'Qiraj must first restore it.",
        sources = {"https://warcraft.wiki.gg/wiki/The_War_of_the_Shifting_Sands", "https://warcraft.wiki.gg/wiki/The_War_of_the_Shifting_Sands_%28short_story%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8305 Long Forgotten Memories; 8519 A Pawn on the Eternal Board)", "https://warcraft.wiki.gg/wiki/The_Scepter_of_the_Shifting_Sands"},
        names = {"The War of the Shifting Sands", "Qiraji War"},
        related = {"npc:anachronos", "npc:valstann", "npc:fandral"},
        setting = "Classic / Forever"},
    W("npc:anachronos", "Anachronos", "Person",
        "Nozdormu's heir brought the bronze dragons into the War of the Shifting Sands after the Qiraji attacked their home. He helped seal Ahn'Qiraj and fashioned the scepter that could reopen its barrier.",
        SANDS, nil, {"event:shifting-sands", "faction:brood-nozdormu"}),
    W("npc:valstann", "Valstann Staghelm", "Person",
        "Fandral's son left the main army to defend Southwind Village during the Qiraji war. Captured and killed before his father's eyes, Valstann became the central loss behind Fandral's refusal to accept the sealing of Ahn'Qiraj as a true victory.",
        SANDS, {"Valstann"}, {"npc:fandral", "event:shifting-sands"}),
    {id = "faction:burning-legion",
        title = "Burning Legion",
        kind = "Faction",
        body = "The Burning Legion is a demonic army bent on consuming worlds. Sargeras's forces first invaded ancient Azeroth through the Well of Eternity, drawn in by Azshara and the Highborne's spellwork during the War of the Ancients.\n\nIts return uses conquest by other means before the demons march openly. The Lich King and his Scourge prepare Azeroth for invasion: plague ruins Lordaeron, undead armies destroy resistance, and dreadlords oversee the operation for the Legion. Kel'Thuzad explains this purpose to Arthas, revealing that the Scourge's victories serve masters beyond the undead themselves.\n\nArchimonde's arrival brings that plan into the open. Yet the advance ends at Mount Hyjal, where the combined resistance of humans, orcs and night elves gives Malfurion time to spring the World Tree's trap and destroy the invading commander.",
        sources = {"https://warcraft.wiki.gg/wiki/The_War_of_the_Ancients", "https://warcraft.wiki.gg/wiki/The_Revelation", "https://warcraft.wiki.gg/wiki/Twilight_of_the_Gods"},
        names = {"The Burning Legion", "Legion"},
        related = {"faction:shadow-council", "event:war-ancients", "npc:archimonde"},
        setting = "Classic / Forever"},
    {id = "npc:medivh",
        title = "Medivh",
        kind = "Person",
        body = "Medivh was the last Guardian of Tirisfal, heir to a line of mages empowered to defend Azeroth against the Burning Legion. The power meant to protect the world became its danger: possessed by Sargeras, he conspired with Gul'dan and the Shadow Council to open the Dark Portal, allowing the orcish Horde to cross from Draenor.\n\nDuring the First War, his apprentice Khadgar and Anduin Lothar confronted him in Karazhan. They killed the possessed Guardian, banishing Sargeras's spirit and freeing Medivh's own. His death did not close the war he had helped unleash; Stormwind still fell.\n\nMedivh returned before the Third War as the mysterious Prophet. He urged Thrall and Jaina to lead their people to Kalimdor, then brought them together with Tyrande and Malfurion against the Legion. Revealing his identity, he sought to repair the ruin he had caused by persuading former enemies to defend their world together. Their alliance stood against Archimonde at Mount Hyjal.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Guardians_of_Tirisfal", "https://warcraft.wiki.gg/wiki/The_Dark_Portal_and_the_Fall_of_Stormwind", "https://warcraft.wiki.gg/wiki/The_Last_Guardian_%28WC3_NightElf%29", "https://news.blizzard.com/en-us/article/16887806/jaina-hero-week"},
        names = {"The Last Guardian"},
        related = {"npc:guldan", "event:first-war", "event:third-war"},
        setting = "Classic / Forever",
        autoLink = true},
    W("npc:guldan", "Gul'dan", "Person",
        "Gul'dan taught demonic magic to the orcs and persuaded them to drink Mannoroth's blood. His bargain with Medivh linked that corrupted Horde to an invasion of Azeroth.",
        HISTORY, nil, {"npc:medivh", "faction:burning-legion"}),
    {id = "event:first-war",
        title = "First War",
        kind = "Event",
        body = "Sargeras, acting through the possessed Medivh, bargained with Gul'dan for the Horde's invasion; Medivh and the Shadow Council's warlocks then opened the Dark Portal.\n\nThe orcs' encampments in the eastern swamps became the base for raids on the human kingdom. As raids from the swamps grew more organized, Blackhand gathered the feuding orcs under one banner. The king sent footmen and archers to protect the Borderlands settlements; until then, the orcs' poor training and disorganization had been key to holding them at bay. The struggle brought the war to Stormwind itself.\n\nGarona killed Llane; Stormwind fell, and Lothar led its survivors across the sea to refuge in Lordaeron.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Dark_Portal_and_the_Fall_of_Stormwind", "https://warcraft.wiki.gg/wiki/Warcraft_I_manual", "https://warcraft.wiki.gg/wiki/Warcraft_II%3A_Tides_of_Darkness_manual"},
        names = {"the First War", "First Great War"},
        related = {"npc:medivh", "npc:guldan", "npc:lothar"},
        setting = "Classic / Forever"},
    {id = "event:second-war",
        title = "Second War",
        kind = "Event",
        body = "The Second War carried the conflict between the Horde and humanity into the northern kingdoms. After Stormwind's destruction, Lothar led its survivors to Lordaeron, where Terenas offered refuge. The threatened human nations gathered in an Alliance under Lothar's military command, joined by dwarven and high elven allies against Orgrim Doomhammer's advancing Horde.\n\nGul'dan weakened the invasion by abandoning it for the Tomb of Sargeras. Lothar died at Blackrock Spire, but Turalyon rallied the Alliance. The retreating Horde made its final stand around the Dark Portal; destroying that gateway became the decisive objective of the victorious army. Captured orcs were confined in camps, and Nethergarde was established to watch the portal's ruins. The victory ended the invasion while leaving the defeated orcs and their captors bound to a troubled settlement.",
        sources = {"https://wowwiki-archive.fandom.com/wiki/Warcraft_II_manual", "https://warcraft.wiki.gg/wiki/The_Alliance_of_Lordaeron", "https://warcraft.wiki.gg/wiki/The_Great_Portal_%28WC2_Human%29"},
        names = {"The Second War"},
        related = {"npc:orgrim", "book:alliance-lordaeron", "event:internment-liberation"},
        setting = "Classic / Forever"},
    {id = "npc:uther",
        title = "Uther the Lightbringer",
        kind = "Person",
        body = "Uther the Lightbringer was the first paladin and founder of the Order of the Silver Hand, devoted to defending Lordaeron. Arthas Menethil was his greatest student, loved by Uther like a son. At Stratholme he refused Arthas's order to slaughter its people; the prince dismissed him.\n\nEven after Arthas betrayed humanity, Uther fought to protect those the fallen prince threatened. His death devastated the Silver Hand: Tirion Fordring recalls how despair drove his son Taelan to abandon the order's standard. Uther's tomb in the Western Plaguelands remains a place of remembrance, where the Alliance brings offerings during the Harvest Festival to honor his sacrifice.",
        sources = {"https://warcraft.wiki.gg/wiki/Uther%27s_Tomb", "https://warcraft.wiki.gg/wiki/The_Culling_%28WC3_Human%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 8149, 5845)"},
        names = {"Uther Lightbringer", "Uther"},
        related = {"faction:silver-hand", "npc:arthas"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:arthas",
        title = "Arthas Menethil",
        kind = "Person",
        body = "Arthas Menethil was the prince of Lordaeron and a paladin trained by Uther the Lightbringer. His determination to stop the plague led him to order Stratholme's people killed before they could become undead. Uther refused, and Jaina abandoned him rather than join the slaughter.\n\nPursuing Mal'Ganis to Northrend, Arthas took the cursed sword Frostmourne despite warnings of its price. He killed the dreadlord, but the weapon subjected him to the Lich King's will. Returning home, he murdered his father, King Terenas, and became a champion of the Scourge. Uther made his final stand against the student he had loved.\n\nArthas later reached the Frozen Throne, broke Ner'zhul's icy prison and donned his helm, joining with him as the Lich King. From Northrend, this new ruler remains the power behind the Scourge. In Lordaeron, Sylvanas's hatred endures: she orders the Royal Apothecary Society to devise a plague capable of destroying Arthas and his army.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Defense_of_Strahnbrad_%28WC3_Human%29", "https://warcraft.wiki.gg/wiki/The_Culling_%28WC3_Human%29", "https://wowpedia.fandom.com/wiki/Frostmourne_%28WC3_Human%29", "https://warcraft.wiki.gg/wiki/Arthas%27_Betrayal_%28WC3_Human%29", "https://warcraft.wiki.gg/wiki/The_Ascension_%28WC3_Undead%29", "https://classicdb.ch/?quest=8149", "https://classicdb.ch/?quest=367"},
        names = {"Arthas", "Prince Arthas"},
        related = {"npc:uther", "npc:sylvanas", "faction:scourge"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:myranda", "Myranda the Hag", "Person",
        "Myranda was Tirion's trusted adviser when he ruled Mardenholde, and was banished after opposing his condemnation. Living near Uther's tomb, she uses illusion to carry his appeal through Hearthglen's hostile Scarlet guards.",
        {5861, 5862}, {"Myranda"}, {"npc:tirion", "npc:taelan"}),
    N("faction:stormpike", "Stormpike Guard", "Faction",
        "The Stormpike expedition seeks ore and relics in Alterac Valley and fights the Frostwolf for access. Alliance and Horde accounts sharply disagree about how hostilities began, even while acknowledging that the valley is Frostwolf territory.",
        {7241, 8369, 8375}, {"Stormpike Expedition", "Stormpike"}, {"faction:frostwolf"}),
    N("faction:silverwing", "Silverwing Sentinels", "Faction",
        "The Silverwing fight the Warsong Outriders over the destruction of Ashenvale's forest. Their account describes the trees as a defensive barrier for Astranaar as well as a living landscape worth protecting.",
        {8372, 8399}, {"Silverwing"}, {"faction:warsong-outriders"}),
    N("faction:warsong-outriders", "Warsong Outriders", "Faction",
        "The Warsong Outriders fight the Silverwing Sentinels in the struggle over Ashenvale's timber. Horde orders assert a right to harvest the forest, while Alliance defenders see the clearing as a direct threat to their settlements.",
        {7789, 8372}, {"Warsong"}, {"faction:silverwing"}),
    N("faction:arathor", "League of Arathor", "Faction",
        "The League battles the Defilers for the strategic resources of Arathi Basin. Its commanders seek control of the battlefield's bases both to secure supplies and to dislodge the Forsaken's competing occupation.",
        {8114, 8115}, {"The League of Arathor"}, {"faction:defilers"}),
    N("faction:defilers", "The Defilers", "Faction",
        "The Defilers are the Forsaken force opposing the League of Arathor in Arathi Basin. Their orders call for seizing strategic points to demonstrate how quickly the League's holdings can be taken away.",
        {8115, 8121}, {"Defilers"}, {"faction:arathor", "faction:forsaken"}),
    N("faction:royal-apothecaries", "Royal Apothecary Society", "Faction",
        "Sylvanas charges the Royal Apothecary Society with creating a plague that can ruin Arthas's Scourge army. Its research depends on field samples, experiments, and competing apothecaries pursuing their own methods.",
        {367, 232}, {"Apothecary Society"}, {"npc:sylvanas", "npc:faranell", "npc:johaan"}),
    N("faction:deathstalkers", "Deathstalkers", "Faction",
        "The Forsaken's scouts gather information in hostile territory, including northern Silverpine. The disappearance of Rane and Quinn Yorick shows the danger of their reconnaissance work, while another scout locates spellbooks linked to Arugal.",
        {422, 428}, {"The Deathstalkers"}, {"npc:rane", "npc:quinn", "faction:forsaken"}),
    {id = "faction:explorers-league",
        title = "Explorers' League",
        kind = "Faction",
        body = "The Explorers' League is a dwarven archaeological organization based in Ironforge's Assembly of Explorers. Its expeditions seek the ancient history of Azeroth and evidence of the dwarves' own beginnings. The Discs of Norgannon recovered from Uldaman are especially significant: their account of the earthen, troggs and dwarves may establish the enchanted creation that the League has long sought to prove.\n\nThe League supplies field expeditions such as Ironband's dig, where reports and requests for blastpowder pass through its headquarters. Its search also reaches Alterac Valley, where the desire to investigate artifacts becomes entangled with war against the Frostwolf. Scholarship can bring its explorers into conflict over the very ground they hope to study.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #301 Report to Ironforge; #7141 The Battle of Alterac", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #2278 and #2279 The Platinum Discs"},
        names = {"The Explorers' League"},
        related = {"faction:stormpike", "dungeon:uldaman", "relic:discs-norgannon"},
        setting = "Classic / Forever"},
    {id = "faction:si7",
        title = "SI:7",
        kind = "Faction",
        body = "Mathias Shaw heads SI:7 from Stormwind's Old Town barracks. His knowledge of assassins, criminal aliases, and the city's hidden dealings makes the organization central to investigations that ordinary military force cannot resolve.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 135)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 393)"},
        names = {},
        related = {"npc:mathias-shaw"},
        setting = "Classic / Forever",
        autoLink = true},
    N("faction:alliance", "The Alliance", "Faction",
        "The Alliance links kingdoms and peoples through shared military and diplomatic commitments. Magni's dealings with the Timbermaw show its leaders seeking common advantages in Kalimdor, while the Ahn'Qiraj war effort turns everyday supplies into the means to wage a major campaign.",
        {8484, 8492, 8493}, {"Alliance"}, {"npc:magni", "faction:timbermaw"}),
    {id = "faction:horde",
        title = "The Horde",
        kind = "Faction",
        body = "The Horde is a coalition of orcs, Darkspear trolls, tauren and Forsaken, peoples joined by the need to survive in a hostile world. Their reasons for belonging are different. The Darkspear pledged themselves after the orcs came to their aid; the Forsaken defend the freedom they recovered from the Lich King. The tauren bring their reverence for the Earth Mother into an alliance whose members do not all share their peaceful outlook.\n\nUnder Thrall, the Horde seeks a future guided by shamans and free from demonic control. Eitrigg returned to its service because he believed in that change. Yet freedom does not erase the older wars: captivity is remembered at Hammerfall, and the Horde honors Grom Hellscream's sacrifice at his monument in Ashenvale. Its new solidarity carries both the hope of independent peoples and the burden of their history.",
        sources = {"https://news.blizzard.com/en-us/article/23317716/taking-your-first-steps-in-world-of-warcraft-classic (The Horde section, Classic four-race description)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #787 The New Horde; #655 Hammerfall; #8150 Honoring a Hero"},
        names = {"Horde", "New Horde"},
        related = {"npc:thrall", "faction:darkspear", "npc:sylvanas"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "faction:dark-iron",
        title = "Dark Iron Clan",
        kind = "Faction",
        body = "The Dark Iron dwarves rule a kingdom beneath Blackrock Mountain, shaped by the destruction of their old city, Thaurissan, during the dwarven civil war. Relics in its ruins preserve visions of eight dwarves performing a ritual, followed by a survivor kneeling before a towering being of flame. The catastrophe that ruined their home also left the surviving nation under Ragnaros's power.\n\nFranclorn Forgewright describes Emperor Dagran Thaurissan's realm as corrupted by that elemental master. Its ambitions reach beyond the mountain: Dark Iron forces fortify the Searing Gorge and Badlands, strike at the dam near Loch Modan, and search Uldaman for ancient knowledge. Ragnaros even sends Ambassador Infernus to oversee the artifact hunters, turning their discoveries into a direct threat to Ironforge.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Smoldering_Ruins_of_Thaurissan", "https://warcraft.wiki.gg/wiki/The_Smoldering_Ruins_of_Thaurissan_%282%29", "https://warcraft.wiki.gg/wiki/Dark_Iron_Legacy", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quests 762)"},
        names = {"Dark Iron dwarves", "Dark Irons"},
        related = {"event:three-hammers", "npc:ragnaros", "faction:thorium-brotherhood"},
        setting = "Classic / Forever"},
    W("faction:bronzebeard", "Bronzebeard Clan", "Faction",
        "The Bronzebeards secured Ironforge in the War of the Three Hammers. Their dwarves later became a vital part of the Alliance, and King Magni rules the mountain city in this era.",
        HAMMERS, {"Bronzebeards"}, {"event:three-hammers", "npc:magni"}),
    N("npc:garrick-padfoot", "Garrick Padfoot", "Person",
        "Garrick leads a gang near the vineyards east of Northshire Abbey. His attacks on farmers and merchants bring a bounty from the local defenders, who warn that the thugs around him make reaching him dangerous.",
        {6}, {"Garrick"}),
    N("npc:hogger", "Hogger", "Person",
        "A huge gnoll roaming southwestern Elwynn, Hogger has defeated repeated efforts to capture him. Stormwind's army offers a bounty through Marshal Dughan, giving the countryside's scattered gnoll troubles a particularly feared name.",
        {176}, nil, {"npc:dughan"}),
    N("creature:princess", "Princess", "Creature",
        "The Brackwell family's enormous, prize-winning sow ranges from their pumpkin patch to raid neighboring vegetable fields. Her appetite makes her the subject of an exasperated farmer's bounty, with her collar requested as proof.",
        {88}),
    N("event:darkmoon-faire", "Darkmoon Faire", "Event",
        "A traveling carnival whose visits bring games of collection and reward to Goldshire and Mulgore. Gelvas Grimgate exchanges prize tickets for goods, while complete card decks have their own mysterious connection to the Faire.",
        {7905, 7907}, {"The Darkmoon Faire"}),
    W("npc:lich-king", "The Lich King", "Person",
        "The intelligence behind the Scourge first took shape when Kil'jaeden imprisoned Ner'zhul in the Frozen Throne. After defying the Legion, Ner'zhul joined with Arthas, who claimed the Lich King's power in Northrend.",
        KING, {"Lich King"}, {"npc:nerzhul", "npc:arthas", "faction:scourge"}),
    {id = "npc:nerzhul",
        title = "Ner'zhul",
        kind = "Person",
        body = "Ner'zhul was an orc shaman, chieftain of the Shadowmoon clan, and leader of the Horde that remained on Draenor after the Second War. He sought artifacts from Azeroth to open passages to other worlds. The portals offered new lands to conquer, but their energies tore Draenor apart. Ner'zhul escaped through one of them only to fall into Kil'jaeden's hands.\n\nKil'jaeden transformed Ner'zhul into the original Lich King and confined him in the Frozen Throne. From Northrend, Ner'zhul extended his undead dominion and enlisted Kel'Thuzad, eventually turning against his demonic master.",
        sources = {"https://warcraft.wiki.gg/wiki/Ner%27zhul (lead; Beyond the Dark Portal)", "https://warcraft.wiki.gg/wiki/Dark_Portal (The second opening, artifact mission)", "https://news.blizzard.com/en-us/article/24177510/challenge-the-lich-king-and-his-minions (existing retained paragraph attribution)"},
        names = {},
        related = {"npc:lich-king", "npc:kiljaeden", "event:creation-lich-king"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "faction:cult-damned",
        title = "Cult of the Damned",
        kind = "Faction",
        body = "The Cult of the Damned began as Kel'Thuzad's secret religion in Lordaeron, established in service to Ner'zhul, the Lich King. Kel'Thuzad approached people worn down by hardship and inequality, promising them a new order and eternal life in return for obedience. Its first strength was therefore among the living: willing converts could enter communities and serve a master whose undead armies were still far away.\n\nCultists protected plague cauldrons placed in villages throughout the north. The sickness killed inhabitants and returned them as undead bound to the Lich King's will, helping turn Lordaeron's own people into the Scourge. Even death held little terror for devoted converts who expected immortality. The cult's promises thus made its mortal followers active partners in the destruction of the society from which it recruited them.",
        sources = {"https://warcraft.wiki.gg/wiki/Kel%27Thuzad_and_the_Forming_of_the_Scourge"},
        names = {"The Cult of the Damned"},
        related = {"npc:kelthuzad", "npc:nerzhul", "faction:scourge"},
        setting = "Classic / Forever"},
    W("npc:sargeras", "Sargeras", "Person",
        "A fallen titan bent on destroying life, Sargeras worked through the possessed Medivh to reach Gul'dan. That hidden connection helped bring the corrupted orcish Horde through the Dark Portal and into Azeroth's First War.",
        FIRST, nil, {"npc:medivh", "npc:guldan", "event:first-war"}),
    {id = "npc:archimonde",
        title = "Archimonde",
        kind = "Person",
        body = "Archimonde is a commander of the Burning Legion whose invasion turns the Scourge's devastation of Lordaeron into an assault on the world itself. Kel'Thuzad summons him into Azeroth using the Book of Medivh. At Dalaran, Archimonde demonstrates his power by shaping a likeness of the city from sand and destroying it, bringing down the real towers with it.\n\nHe then advances on Mount Hyjal to seize the energies of Nordrassil, the World Tree. Humans, orcs and night elves unite to delay his army while Malfurion Stormrage prepares a trap. When Archimonde reaches the tree, gathered nature spirits unleash its power against him. His destruction ends the assault, but the victory costs the night elves their immortality and leaves the World Tree badly wounded.",
        sources = {"https://warcraft.wiki.gg/wiki/Under_the_Burning_Sky_%28WC3_Undead%29", "https://warcraft.wiki.gg/wiki/Fall_of_dalaran", "https://warcraft.wiki.gg/wiki/Twilight_of_the_Gods", "https://warcraft.wiki.gg/wiki/Eternity%27s_End_%28cinematic%29"},
        names = {},
        related = {"faction:burning-legion", "event:third-war", "npc:jaina"},
        setting = "Classic / Forever",
        autoLink = true},
    W("npc:kiljaeden", "Kil'jaeden", "Person",
        "An eredar commander in Sargeras's service, Kil'jaeden became one of the Burning Legion's great demon lords. His ambitions served a Legion that consumed worlds and bent other peoples to its cause.",
        "https://warcraft.wiki.gg/wiki/Sargeras_and_the_Betrayal (original in-game book: Legion champions and recruitment)", nil, {"npc:sargeras", "faction:burning-legion"}),
    {id = "npc:mannoroth",
        title = "Mannoroth",
        kind = "Person",
        body = "Mannoroth is the Burning Legion pit lord whose blood bound the orcs to demonic power. Their chieftains, including Grom Hellscream, drank willingly on Draenor. Years later, when Thrall's people reached Kalimdor, Mannoroth saw that the old bond could be used again.\n\nWith Tichondrius, he prepared a blood-tainted fountain in Ashenvale to lure the Warsong clan back into his service. The Legion wanted Cenarius destroyed, and Grom's warriors drank for the strength to defeat him. Their victory brought renewed enslavement: Mannoroth appeared and claimed them as his own.\n\nThrall and Jaina freed Grom from that immediate corruption, and Thrall accompanied him to confront the demon. Mannoroth overpowered Thrall, but Grom drove his axe into the demon's chest. The resulting blast killed Grom as well. With Mannoroth's death, the blood curse ended, a deliverance the Horde remembers at Grom's memorial in Demon Fall Canyon.",
        sources = {"https://warcraft.wiki.gg/wiki/The_Blood_of_Mannoroth_%28WC3_Orc%29", "https://warcraft.wiki.gg/wiki/The_Hunter_of_Shadows", "https://warcraft.wiki.gg/wiki/By_Demons_Be_Driven", "https://warcraft.wiki.gg/wiki/The_Death_of_Hellscream_%28WC3_Orc%29", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 8150)"},
        names = {},
        related = {"npc:grom", "npc:thrall", "faction:burning-legion"},
        setting = "Classic / Forever",
        autoLink = true},
    W("npc:illidan", "Illidan", "Person",
        "Illidan Stormrage pursued power to destroy the Burning Legion, even studying its magic from within during the War of the Ancients. Released by Tyrande during the Third War, he absorbed the Skull of Gul'dan's power and was banished by Malfurion after becoming demonic.",
        DEMONS, {"Illidan Stormrage"}, {"npc:malfurion", "npc:tyrande", "event:war-ancients"}),
    {id = "npc:lothar",
        title = "Anduin Lothar",
        kind = "Person",
        body = "Anduin Lothar was King Llane's champion and a friend of Medivh. During the First War, that friendship became a terrible duty: when Khadgar and Garona exposed Medivh's part in bringing the orcs to Azeroth, Lothar helped them enter Karazhan and confront the corrupted Guardian. He joined the assault that ended Medivh's life.\n\nAfter Stormwind fell, Lothar led its survivors north and commanded the newly formed Alliance. His campaign carried the war back toward the Horde's stronghold at Blackrock Spire, where he was killed. His lieutenant Turalyon survived him and carried the Alliance's struggle onward, but remembered his inability to save Lothar as a bitter failure.",
        sources = {"https://warcraft.wiki.gg/wiki/Medivh", "https://warcraft.wiki.gg/wiki/The_Alliance_of_Lordaeron", "https://warcraft.wiki.gg/wiki/Warcraft_II%3A_Beyond_the_Dark_Portal_manual", "https://warcraft.wiki.gg/wiki/Assault_on_Blackrock_Spire_%28WC2_Human%29"},
        names = {"Lothar", "Sir Lothar"},
        related = {"npc:turalyon", "npc:orgrim", "event:second-war"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:turalyon",
        title = "Turalyon",
        kind = "Person",
        body = "Turalyon is a human paladin and Alliance commander. After Lothar fell at Blackrock Spire, Turalyon raised his commander's bloodied shield and rallied the Alliance. He drove the retreating Horde toward the Dark Portal, where the Alliance won the closing battle of the Second War.\n\nHe later led the Alliance Expedition into Draenor. Stormwind's Valley of Heroes commemorates its High General as presumed dead.",
        sources = {"https://warcraft.wiki.gg/wiki/Turalyon_(Warcraft_II) (original game unit metadata only for added identity)", "https://ftp.blizzard.com/pub/misc/Warcraft%20III%20Manual.pdf (existing rally passage retained)", "https://warcraft.wiki.gg/wiki/Turalyon (Monuments: original Valley of Heroes plaque only)"},
        names = {},
        related = {"npc:lothar", "event:second-war", "book:invasion-draenor"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:khadgar",
        title = "Khadgar",
        kind = "Person",
        body = "Khadgar was Medivh's apprentice, a young mage whose discovery of his master's betrayal drew him into the First War. With Garona and Anduin Lothar he confronted the possessed Guardian at Karazhan. The struggle left Khadgar magically aged, but Medivh was defeated.\n\nHe studied the Dark Portal with the Kirin Tor and later watched over its ruined site. When the Alliance carried the war to Draenor, Khadgar sought the Book of Medivh and Skull of Gul'dan as the means to seal the passage between worlds. Ner'zhul's new portals began tearing Draenor apart; Khadgar closed the Dark Portal to spare Azeroth the catastrophe. With their return cut off, the expedition's survivors followed him toward another rift rather than remain on the dying world.\n\nStormwind's Valley of Heroes remembers him as the expedition's supreme commander, presumed dead beyond the portal.",
        sources = {"https://warcraft.wiki.gg/wiki/Archmage_Khadgar", "https://warcraft.wiki.gg/wiki/Warcraft_II%3A_Beyond_the_Dark_Portal_manual", "https://warcraft.wiki.gg/wiki/Beyond_the_Dark_Portal_missions", "https://warcraft.wiki.gg/wiki/Kadghar"},
        names = {"Archmage Khadgar"},
        related = {"npc:medivh", "npc:lothar", "relic:skull-guldan"},
        setting = "Classic / Forever",
        autoLink = true},
    W("npc:llane", "King Llane Wrynn", "Person",
        "Llane ruled Stormwind during the First War, when the invading Horde threatened his kingdom. Garona assassinated him as the conflict brought Stormwind to ruin, making the king's death part of the realm's founding catastrophe in its war against the orcs.",
        FIRST, {"Llane Wrynn", "King Llane"}, {"event:first-war", "npc:lothar"}),
    {id = "npc:deathwing",
        title = "Deathwing",
        kind = "Person",
        body = "Once Neltharion the Earth-Warder, the black Dragon Aspect fell under the Old Gods' influence. During the War of the Ancients he turned the Dragon Soul against his fellow dragons, devastating the blue flight and betraying the duty he had shared with the other Aspects.",
        sources = {"https://warcraft.wiki.gg/wiki/Deathwing (War of the Ancients, pre-Classic trilogy facts)", "https://warcraft.wiki.gg/wiki/Demon_Soul (War of the Ancients; original betrayal account)"},
        names = {"Neltharion", "Neltharion the Earth-Warder"},
        related = {"npc:malygos", "faction:old-gods", "event:war-ancients"},
        setting = "Classic / Forever",
        autoLink = true},
    N("npc:alexstrasza", "Alexstrasza", "Person",
        "Known as the Life-Binder, Alexstrasza was among the great dragons whose blessing the night elves sought for Teldrassil. She agreed with Nozdormu's refusal, leaving the new World Tree without the blessings its creators had hoped would restore their former condition.",
        {935, 7383}, {"Alexstrasza the Life-Binder"}, {"npc:nozdormu", "event:teldrassil-grown"}),
    N("npc:nozdormu", "Nozdormu", "Person",
        "The Lord of Time refused to bless Teldrassil, regarding Staghelm's demand for restored immortality as arrogance. His bronze brood's affairs also reach Silithus, where earning its trust draws outsiders into the legacy of the ancient war against the qiraji.",
        {7383, 8288}, {"Nozdormu the Timeless"}, {"faction:brood-nozdormu", "npc:fandral", "event:shifting-sands"}),
    {id = "npc:ysera",
        title = "Ysera",
        kind = "Person",
        body = "Ysera, called the Dreamer, is the green Dragon Aspect and guardian of the Emerald Dream. Her charge joins the care of that realm to the protection of nature in Azeroth. She leads the green dragonflight, whose work brings it into close alliance with the druids.\n\nThe druids sleeping in Ban'ethil fulfill a pact with Ysera, binding their service to the Dream. Her dragonflight also seeks the redemption of Eranikus, whose corrupted spirit makes that duty a struggle to recover a lost guardian.",
        sources = {"https://warcraft.wiki.gg/wiki/Ysera (lead, original identity)", "https://warcraft.wiki.gg/wiki/Green_dragonflight (lead, original charge and druid relationship)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 475)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt (quest 3374)"},
        names = {},
        related = {"place:emerald-dream", "faction:cenarion-circle", "npc:shade-eranikus"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "npc:malygos",
        title = "Malygos",
        kind = "Person",
        body = "Malygos, the Spellweaver, leads the blue dragonflight and guards magic, a charge bestowed on him by the titan Norgannon.\n\nDeathwing's betrayal devastated his flight and drove him into seclusion. Krasus later persuaded him to help rescue Alexstrasza after revealing that Deathwing survived. The Demon Soul's destruction restored the Aspects' stolen power, and Malygos recovered much of his former vitality.",
        sources = {"https://warcraft.wiki.gg/wiki/Charge_of_the_Dragonflights", "https://warcraft.wiki.gg/wiki/Malygos"},
        names = {},
        related = {"npc:deathwing", "faction:dragonflights", "book:charge-dragonflights"},
        setting = "Classic / Forever",
        autoLink = true},
    W("event:great-sundering", "The Great Sundering", "Event",
        "The destruction of the Well of Eternity broke the ancient world's landmass and left the Maelstrom in its place. This catastrophe ended the War of the Ancients at a terrible cost, destroying cities and dividing lands that had once belonged to a single continent.",
        ANCIENTS, {"Great Sundering", "The Sundering", "Sundering"}, {"event:war-ancients", "npc:azshara"}),
    {id = "event:culling-stratholme",
        title = "The Culling of Stratholme",
        kind = "Event",
        body = "Fearing the plague's spread, Arthas ordered Stratholme's people killed, including those who might not yet be infected. Jaina refused to take part and left him; when she returned, the burning city bore the evidence of his decision.",
        sources = {"https://news.blizzard.com/en-us/article/16887806/jaina-hero-week"},
        names = {"Culling of Stratholme", "Scourging of Stratholme", "The Culling", "The Purge of Stratholme", "Purge of Stratholme"},
        related = {"npc:arthas", "npc:jaina"},
        setting = "Classic / Forever",
        autoLink = true},
    N("faction:titans", "The Titans", "Faction",
        "The titans are the ancient makers whose works the Explorers' League studies in ruins and recovered texts. The legend of Uldaman's Tablet of Will claims they endowed their creations with life and free will; Ironforge's scholars seek the tablet to test that account.",
        {1050, 1139}, {"Titans"}, {"faction:explorers-league"}),
    N("faction:old-gods", "The Old Gods", "Faction",
        "Ancient powers remembered in a translated titan inscription as prisoners chained beneath the land. The Twilight's Hammer performs rites to bring these patrons back, making archaeological discoveries and the cult's present violence parts of the same threat.",
        {299, 1199}, {"Old Gods"}, {"group:twilights-hammer", "faction:titans"}),
    N("faction:highborne", "The Highborne", "Faction",
        "The Highborne served Queen Azshara and practiced the magic associated with the Well of Eternity. Darkshore preserves the wreckage of their world: Ameth'Aran's restless dead and Bashal'Aran's old magical prison outlast the civilization that created them.",
        {953, 957}, {"Highborne"}, {"npc:azshara", "event:great-sundering"}),
    W("faction:dragonflights", "The Dragonflights", "Faction",
        "The five Dragon Aspects received powers tied to time, nature, life, magic, and the earth. The dragons who followed Nozdormu, Ysera, Alexstrasza, Malygos, and Neltharion formed the great flights, each connected to its leader's charge over the world.",
        "https://worldofwarcraft.blizzard.com/en-us/news/23987094/", {"Dragonflights"}, {"npc:nozdormu", "npc:ysera", "npc:alexstrasza", "npc:malygos", "npc:deathwing"}),
})

-- Overnight notes pass 2026-11-05. Gaps found by comparing the catalogue with
-- Lore Forever's entries (its text is CC BY-SA, adapted from warcraft.wiki.gg).
-- Facts come from the vanilla quest corpus first; Lore Forever and the wiki only
-- confirm or locate. The wording is ours. Reference context, never player history.
local function LF(id, article)
    return "LoreForever " .. id .. " (wiki: https://warcraft.wiki.gg/wiki/" .. article .. ")"
end
local function Note(id, title, kind, body, sources, names, related, autoLink)
    return {id = id, title = title, kind = kind, body = body, sources = sources, names = names or {},
        related = related or {}, setting = "Classic / Forever", autoLink = autoLink or nil}
end
-- Batch 1: the Valley of Trials, Durotar and Red Cloud Mesa.
A.RegisterLoreNotes({
    Note("npc:gornek", "Gornek", "Person",
        "Gornek is the orc who takes charge of new recruits at the Den in the Valley of Trials. Kaltunk sends young orcs and trolls to him once they come of age, and Gornek decides what their first trials will be. He is sparing with praise and starts small, with the mottled boars north of the Den, on the grounds that a recruit is more useful to the Horde alive than lost on a kodo hunt.\n\nNews from the valley comes back to him as well. When the young hunter Hana'zua lies wounded in the hills and cannot walk back, it is Gornek who must hear of it.",
        {V .. " #4641 Your Place in the World; #787 The New Horde; #788 Cutting Teeth; #804 Sarkoth", LF("npc:gornek", "Gornek")},
        nil, {"place:the-den", "npc:kaltunk", "place:valley-trials"}, true),
    Note("npc:kaltunk", "Kaltunk", "Person",
        "Kaltunk greets young orcs in the Valley of Trials when they are of age to fight for the Horde. He looks each one over, laughs at anyone who imagines strangling a dragon or a demon barehanded, and sends them west to Gornek in the Den for work better suited to a beginner. Gornek is not always impressed with what Kaltunk sends him.",
        {V .. " #4641 Your Place in the World", LF("npc:kaltunk", "Kaltunk")},
        nil, {"npc:gornek", "place:the-den", "place:valley-trials"}, true),
    Note("npc:hana-zua", "Hana'zua", "Person",
        "Hana'zua is a young hunter who lies wounded under a tree in the hills of the Valley of Trials. Hunting scorpids on the plateau to the south, he threw himself at an unusually vicious one and struck its claw hard, but it caught his leg and drove its stinger into his chest. Too weak to reach the Den, he asks passers-by to kill the beast so that his honor is upheld, and to carry word of his plight to Gornek. He remembers his father saying he would never amount to much.",
        {V .. " #790 Sarkoth; #804 Sarkoth", LF("npc:hana-zua", "Hana'zua")},
        nil, {"npc:sarkoth", "npc:gornek", "place:valley-trials"}, true),
    Note("npc:sarkoth", "Sarkoth", "Creature",
        "Sarkoth is a large and vicious scorpid that hunts on a plateau at the southern end of the Valley of Trials. It nearly killed the young hunter Hana'zua, though not before he left a deep wound on its claw. Gornek knows the beast from a description and counts its death a feat worth some pride for a recruit.",
        {V .. " #790 Sarkoth; #804 Sarkoth"},
        nil, {"npc:hana-zua", "place:valley-trials"}, true),
    Note("npc:rhinag", "Rhinag", "Person",
        "Rhinag is a troll of Sen'jin Village who went after the venomtail scorpids near Orgrimmar's gates without carrying an antidote. One stung him deeply, and by his own reckoning the poison leaves him about an hour to live. Kor'ghan in Orgrimmar knows the cure. Rhinag is half glad he cannot go home in this state, since he expects the village to mock his carelessness.",
        {V .. " #812 Need for a Cure; #813 Finding the Antidote", LF("npc:rhinag", "Rhinag")},
        nil, {"npc:kor-ghan", "place:senjin", "faction:darkspear"}, true),
    Note("npc:kor-ghan", "Kor'ghan", "Person",
        "Kor'ghan works in the Cleft of Shadow in Orgrimmar and knows how to make an antidote for venomtail poison. The venomtails near the city's entrance are among the deadliest scorpids in Durotar, and their own poison sacs go into the cure. His advice to hunters is to study a creature's habits before hunting it. Young trolls of Sen'jin who answer to him can expect more rituals of hunting and gathering before he considers them proven.",
        {V .. " #812 Need for a Cure; #813 Finding the Antidote", LF("npc:kor-ghan", "Kor'ghan")},
        nil, {"place:cleft-of-shadow", "npc:rhinag", "region:4f726772696d6d6172"}, true),
    Note("npc:rezlak", "Rezlak", "Person",
        "Rezlak is a goblin who works for Gazlowe of Ratchet. His boss sent him to Durotar to help the orcs, and the work goes well except for the caravans. Dustwind harpies from Razorwind Canyon keep taking his shipments, and he wants their nests in Drygulch Ravine cleared so the routes are safe. He quotes Gazlowe's advice at every turn, most often that anything can be done for a price.",
        {V .. " #834 Winds in the Desert; #835 Securing the Lines", LF("npc:rezlak", "Rezlak")},
        nil, {"npc:gazlowe", "place:drygulch", "place:razorwind"}, true),
    Note("npc:orgnil", "Orgnil Soulscar", "Person",
        "Orgnil Soulscar is the orc at Razor Hill who polices Durotar against evils such as the Burning Blade, a demon-worshipping cult hiding in the region's caves. Reports of the cult from the Valley of Trials and Sen'jin Village are brought to him. His own investigations have found a Burning Blade warlock, the goblin Fizzle Darkstorm, camped in Thunder Ridge. He respects the counsel of the shaman Margoz about the cultists at Skull Rock, but still wants them crushed.",
        {V .. " #823 Report to Orgnil; #806 Dark Storms; #828 Margoz", LF("npc:orgnil-soulscar", "Orgnil_Soulscar")},
        {"Orgnil"}, {"faction:burning-blade", "place:razor-hill", "npc:margoz", "place:skull-rock"}),
    Note("npc:ukor", "Ukor", "Person",
        "Ukor is a peon who carried a load of food from Razor Hill to the Valley of Trials, past scorpids and spiders, because he thought the recruits would need it. They did not. Afraid of the beasts on the road back, he waits outside the valley for someone braver to return the food to Innkeeper Grosk at the Razor Hill inn. Grosk's guess is that the valley likes to keep its trainees hungry.",
        {V .. " #2161 A Peon's Burden", LF("npc:ukor", "Ukor")},
        nil, {"place:razor-hill", "place:valley-trials"}, true),
    Note("npc:gazlowe", "Gazlowe", "Person",
        "Gazlowe is the goblin who runs Ratchet, the port on the coast of the Barrens. He owns ships, warehouses and a fleet of privateers, and he keeps agents as far away as Durotar. His troubles are mostly at sea. Southsea Freebooters raid his shipping and have camped south of the town, and the guns of Northwatch Hold have sunk more than one of his vessels. He posts bounties on pirate captains such as Baron Longshore and thinks Undermine ought to do something about the raids.\n\nGazlowe pays well and says so. His observatory still waits for a lens lost with a ship, and his man Rezlak repeats Gazlowe's business sayings to anyone who will listen.",
        {V .. " #887 Southsea Freebooters; #888 Stolen Booty; #890 and #892 The Missing Shipment; #891 The Guns of Northwatch; #895 WANTED: Baron Longshore; #834 Winds in the Desert"},
        nil, {"place:ratchet", "npc:rezlak", "npc:dizzywig"}, true),
    Note("npc:telf-joolam", "Telf Joolam", "Person",
        "Telf Joolam keeps the Shrine of the Dormant Flame on a high peak above the Southfury River in Durotar. Treasure hunters and monster hunters who reach the summit find what looks like an empty shrine, and he sends them away. Shaman who arrive carrying the torch of a fire trial are welcome, because the shrine's purpose is known only to those versed in the shamanistic arts.",
        {V .. " #1524 Call of Fire", LF("npc:telf-joolam", "Telf_Joolam")},
        {"Telf"}, {"place:dormant-flame", "region:4475726f746172"}),
    Note("npc:chief-hawkwind", "Chief Hawkwind", "Person",
        "Chief Hawkwind leads Camp Narache on Red Cloud Mesa, where young tauren begin the Rites of the Earthmother. He teaches that the whole tribe shares its work, so newcomers start with humble tasks before he sends them to Seer Graytongue for the Rite of Strength. His mother is Greatmother Hawkwind, and his son Grull prepares the camp's young hunters. When a youth is ready to go on, the chief gives them a totem of his own carving to show his friend Baine Bloodhoof at Bloodhoof Village.",
        {V .. " #752 A Humble Task; #753 A Humble Task; #755 Rites of the Earthmother; #763 Rites of the Earthmother; #747 The Hunt Begins", LF("npc:chief-hawkwind", "Chief_Hawkwind")},
        nil, {"place:narache", "npc:greatmother-hawkwind", "npc:grull-hawkwind", "npc:baine"}),
    Note("npc:greatmother-hawkwind", "Greatmother Hawkwind", "Person",
        "Greatmother Hawkwind is the mother of Chief Hawkwind of Camp Narache. Her legs are slower than they once were, but she still does her share for the tribe, walking to the well southeast of the camp to fetch water. She holds that even the humblest task can earn the notice of the elders.",
        {V .. " #752 A Humble Task; #753 A Humble Task", LF("npc:greatmother-hawkwind", "Greatmother_Hawkwind")},
        nil, {"npc:chief-hawkwind", "place:narache"}),
    Note("npc:grull-hawkwind", "Grull Hawkwind", "Person",
        "Grull Hawkwind, son of Chief Hawkwind, prepares young hunters at Camp Narache. On Red Cloud Mesa the tauren hunt from need as well as for sport, and the camp relies on plainstrider meat and feathers and on mountain cougar pelts to feed its people, clothe its children and mend its tents. Grull passes word of promising youths to his father.",
        {V .. " #747 The Hunt Begins; #750 The Hunt Continues", LF("npc:grull-hawkwind", "Grull_Hawkwind")},
        {"Grull"}, {"npc:chief-hawkwind", "place:narache", "place:red-cloud"}),
    Note("npc:seer-graytongue", "Seer Graytongue", "Person",
        "Seer Graytongue lives in the hills just south of Camp Narache. Young tauren are sent to him to begin the Rite of Strength, the first of the three Rites of the Earthmother. The test is against the Bristleback quilboar of Brambleblade Ravine, who push onto tribal land, ambush hunting parties and steal from the camp by night.",
        {V .. " #755 Rites of the Earthmother; #757 Rite of Strength", LF("npc:seer-graytongue", "Seer_Graytongue")},
        {"Graytongue"}, {"place:brambleblade", "npc:chief-hawkwind", "faction:bristleback"}),
    Note("npc:zarlman-two-moons", "Zarlman Two-Moons", "Person",
        "Zarlman Two-Moons is the spiritual leader of Bloodhoof Village, where Baine Bloodhoof is chief. Young tauren come to him for the Rite of Vision. He has them gather well stones from Mulgore's water wells and ambercorn from beneath its great trees, and from these he brews the Water of the Seers.",
        {V .. " #767 Rite of Vision; #771 Rite of Vision; #772 Rite of Vision", LF("npc:zarlman-two-moons", "Zarlman_Two-Moons")},
        {"Zarlman"}, {"artifact:water-of-the-seers", "place:bloodhoof", "npc:baine"}),
    Note("npc:seer-ravenfeather", "Seer Ravenfeather", "Person",
        "Seer Ravenfeather guides young shaman at Camp Narache. She sends them to a shrine east of the camp to drink a sapta, a brew that binds the spirit to one of the elements. The spirit of earth met there gives each initiate a piece of rough quartz to bring back, and she makes it the heart of their first totem.",
        {V .. " #1519 Call of Earth; #1520 Call of Earth; #1521 Call of Earth", LF("npc:seer-ravenfeather", "Seer_Ravenfeather")},
        {"Ravenfeather"}, {"place:narache", "region:4d756c676f7265"}),
    Note("artifact:water-of-the-seers", "Water of the Seers", "Artifact",
        "The Water of the Seers is a holy draught brewed at Bloodhoof Village for the Rite of Vision, one of the Rites of the Earthmother. Zarlman Two-Moons makes it from well stones and ambercorn gathered in Mulgore. Drunk beside the tribal fire, it calls up a vision that leads the drinker to the next step of the rites. Only those who have drunk it can receive the blessing of the ancestral spirits at Red Rocks.",
        {V .. " #771 Rite of Vision; #772 Rite of Vision; #773 Rite of Wisdom", LF("item:water-of-the-seers", "Water_of_the_Seers")},
        nil, {"npc:zarlman-two-moons", "place:red-rocks", "place:bloodhoof"}),
})
-- Batch 2: Forever 1.60.1. The Riverglades' defenders and the foes of the two
-- new five-player instances. The wiki gives these foes little beyond a name and
-- a creature type, so the notes stay short rather than invent a history.
local RoL = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron_(instance) (boss list, added in patch 1.60.1)"
local HoT = "https://warcraft.wiki.gg/wiki/Hall_of_Thanes_(instance) (boss list, added in patch 1.60.1)"
local function ForeverNote(id, title, kind, body, sources, names, related, autoLink, explicitAliases)
    local entry = Note(id, title, kind, body, sources, names, related, autoLink)
    entry.setting, entry.explicitAliases = "Forever", explicitAliases
    return entry
end
A.RegisterLoreNotes({
    ForeverNote("faction:brotherhood-horse", "Brotherhood of the Horse", "Faction",
        "The Brotherhood of the Horse is an order of human fighters in the Riverglades. In the Second War they met the Twilight's Hammer ogres and Stormreaver orcs who came into the valley, then fell back south to strengthen Farholde and Meadowsbrook. Their counterattack broke the Horde's later siege of Farholde. Under Knight Commander Demar Brant they still fight to win back the land Stormwind gave up long ago.",
        {"https://warcraft.wiki.gg/wiki/Riverglades (Second War, siege of Farholde, Forever section)", LF("zone:riverglades", "Riverglades")},
        {"the Brotherhood of the Horse"}, {"place:farholde", "region:riverglades"}),
    ForeverNote("npc:the-baron", "The Baron", "Person",
        "The Baron is an abomination in the Ruins of Lordaeron, above the Undercity. Its head has been sewn back onto its body several times, and each new stitching holds a little less well than the last.\n\nThe head once belonged to Othmar, a Grand Marshal of the Alliance whom the Dark Lady killed herself. The apothecaries of the Undercity mean to wake it on a new body and bend it to her will.",
        {RoL, V .. " #97288 Unending Torment (description); #97289 Unending Torment (description)", LF("zone:ruinsoflordaeron", "Ruins_of_Lordaeron_(instance)")},
        {"the Baron"}, {"dungeon:lordaeron-ruins", "place:apothecarium", "npc:garithos"}, nil, {"The Baron", "the Baron"}),
    ForeverNote("npc:viktor-vile", "Viktor the Vile", "Person",
        "Viktor the Vile is a ghoul who haunts the Ruins of Lordaeron, the broken streets of the old human capital above the Undercity.",
        {RoL, LF("zone:ruinsoflordaeron", "Ruins_of_Lordaeron_(instance)")},
        {"Viktor"}, {"dungeon:lordaeron-ruins"}),
    ForeverNote("npc:the-abandoned", "The Abandoned", "Person",
        "The Abandoned is a wraith that roams the Ruins of Lordaeron above the Undercity, one of the restless dead left in the fallen capital.",
        {RoL, LF("zone:ruinsoflordaeron", "Ruins_of_Lordaeron_(instance)")},
        nil, {"dungeon:lordaeron-ruins"}, nil, {"The Abandoned"}),
    ForeverNote("npc:bjork", "Bjork", "Person",
        "Bjork is a wight that walks the Ruins of Lordaeron, among the undead that still hold the surface of the old capital.",
        {RoL, LF("zone:ruinsoflordaeron", "Ruins_of_Lordaeron_(instance)")},
        nil, {"dungeon:lordaeron-ruins"}, true),
    ForeverNote("npc:lordaeron-captain", "Lordaeron Captain", "Person",
        "The Lordaeron Captain is a rare foe in the Ruins of Lordaeron, the ghost of an officer of the fallen kingdom. With other spectral guards it still keeps watch over the upper ruins.",
        {RoL, LF("zone:ruinsoflordaeron", "Ruins_of_Lordaeron_(instance)")},
        nil, {"dungeon:lordaeron-ruins"}),
    ForeverNote("npc:faldrim-anvilmar", "Faldrim Anvilmar", "Person",
        "Faldrim Anvilmar is a thane of old whose ghost haunts the Hall of Thanes beneath Ironforge. An ancient grudge keeps him from rest. The spirit of one of his attendants, able to speak only in broken words, asks anyone who passes to help its master find peace.",
        {HoT, V .. " #96395 An Ancient Grudge", LF("quest:96395", "Hall_of_Thanes_(instance)")},
        {"Faldrim"}, {"dungeon:hall-thanes", "place:anvilmar"}),
    ForeverNote("npc:magmatus", "Magmatus", "Person",
        "Magmatus is a fiery brute in the lower vaults of the Hall of Thanes beneath Ironforge, one of the dangers that have reached the old halls since the Dark Iron incursion.",
        {HoT, LF("zone:hallofthanes", "Hall_of_Thanes_(instance)")},
        nil, {"dungeon:hall-thanes", "npc:durgen"}, true),
    ForeverNote("npc:plunder", "Plunder", "Person",
        "Plunder is an enchanted golem that guards the vaults of the Hall of Thanes beneath Ironforge, where the dwarves keep relics of their old bloodlines.",
        {HoT, LF("zone:hallofthanes", "Hall_of_Thanes_(instance)")},
        nil, {"dungeon:hall-thanes", "npc:durgen"}),
})

-- Batch 3: Shadowglen, Northshire, Deathknell and Brill, the capitals' errands.
A.RegisterLoreNotes({
    Note("npc:iverron", "Iverron", "Person",
        "Iverron is a young night elf of Shadowglen who likes to explore the spider cave close to the glade. There the spider Githyiss the Vile bit him badly, and the poison left him dizzy and weak. He asks for word to be taken to Dirania Silvershine, who knows an antidote made from hyacinth mushrooms, moonpetal lilies and ichor from the same webwood spiders. A friend who expects his visit at the same hour every day notices when he does not come.",
        {V .. " #3519 A Friend in Need; #3521 Iverron's Antidote; #4495 A Good Friend", LF("npc:iverron", "Iverron")},
        nil, {"place:shadowglen", "place:aldrassil"}, true),
    Note("npc:ilthalaine", "Conservator Ilthalaine", "Person",
        "Conservator Ilthalaine keeps the balance of nature in Shadowglen. Heavy spring rains let some of the forest's beasts flourish while others suffered, and the nightsabers and thistle boars have grown too many for the glade to feed. He asks young night elves to thin them so that the forest's harmony holds.",
        {V .. " #456 The Balance of Nature", LF("npc:ilthalaine", "Conservator_Ilthalaine")},
        {"Ilthalaine"}, {"place:shadowglen", "place:aldrassil"}),
    Note("npc:tenaron", "Tenaron Stormgrip", "Person",
        "Tenaron Stormgrip lives in the highest room of Aldrassil in Shadowglen. Before young night elves leave the glade, he teaches them their people's recent history, beginning with the cost of the Battle of Mount Hyjal. Nordrassil is a pale shadow of what it was, its power spent to defeat Archimonde, and Tenaron sends his pupils to the moonwells, whose waters come from the Well of Eternity.",
        {V .. " #920 Tenaron's Summons; #921 Crown of the Earth", "https://warcraft.wiki.gg/wiki/Tenaron_Stormgrip"},
        {"Tenaron"}, {"place:aldrassil", "place:nordrassil", "place:well-of-eternity"}),
    Note("npc:denalan", "Denalan", "Person",
        "Denalan keeps a camp at the eastern end of Lake Al'Ameth in Teldrassil, where he studies and experiments on the island's plant life. His work turns on the timberlings, whose seeds and hearts have begun to show a foul corruption, and he is searching for the cause of the tumors that plague them. Rellian Greenspyre, a druid of Darnassus, thinks Denalan may be the timberlings' only hope.",
        {V .. " #997 Denalan's Earth; #922 Rellian Greenspyre; #927 The Moss-twined Heart; #2498 Return to Denalan", LF("npc:denalan", "Denalan")},
        nil, {"region:54656c6472617373696c", "place:dolanaar"}, true),
    Note("npc:coleman-farthing", "Coleman Farthing", "Person",
        "Coleman Farthing worked for the Agamand family in life and blames them for his death. Now one of the Forsaken, he keeps to the Gallows' End Tavern in Brill and looks for fighters to carry out his revenge. The Agamands have become mindless servants of the Lich King at their mills in northern Tirisfal, and Coleman wants their family crypt stripped of its heirloom weapons so that nothing of their honor remains. He tells Magistrate Sevren about those who help him.",
        {V .. " #1820 Speak with Coleman; #1821 Agamand Heirlooms; #355 Speak with Sevren", LF("npc:coleman-farthing", "Coleman_Farthing")},
        {"Coleman"}, {"place:gallows-end", "place:agamand-mills", "npc:sevren"}),
    Note("npc:calvin-montague", "Calvin Montague", "Person",
        "Calvin Montague is a young Forsaken who lingers near Deathknell, where he has been fighting more than his share of mindless zombies and spiders. He has a letter for Renee, the innkeeper in Brill, and would rather someone else carried it, though he promises good pay. He does not much care what her last name is.",
        {V .. " #8 A Rogue's Deal", LF("npc:calvin-montague", "Calvin_Montague")},
        nil, {"place:deathknell", "place:gallows-end"}),
    Note("npc:linnea", "Deathguard Linnea", "Person",
        "Deathguard Linnea keeps the Deathguard waystation on the road east of Brill, toward the border with the Plaguelands. Magistrate Sevren relies on her reports to learn whether Scourge forces have slipped past the Bulwark. By her account the Bulwark holds most of them back, but some get through, and their activity gathers around the Balnir Farmstead.",
        {V .. " #359 Forsaken Duties", LF("npc:deathguard-linnea", "Deathguard_Linnea")},
        {"Linnea"}, {"npc:sevren", "place:bulwark", "place:balnir"}),
    Note("npc:arren", "Executor Arren", "Person",
        "Executor Arren commands the Forsaken at Deathknell. His scouts watch the Scarlet Crusade, which hunts every undead whether or not they serve the Lich King, and he would rather strike first. When reports from Brill say that a Scarlet messenger has been sent from the Scarlet Monastery to Deathknell, Arren wants the man's papers. The documents later credited to him, with the positions of the Crusade's field commanders, guide the Deathguard's fight against the Crusade around Brill.",
        {V .. " #381 The Scarlet Crusade; #382 The Red Messenger; #370 and #427 At War With The Scarlet Crusade", LF("npc:executor-arren", "Executor_Arren")},
        {"Arren"}, {"place:deathknell", "group:scarlet-crusade", "place:brill"}),
    {id = "npc:eleanor-shackleton", title = "Eleanor Shackleton", kind = "Person", setting = "Forever",
        body = "Eleanor Shackleton is a Forsaken who lives in the wilds of Tirisfal, camped in the hills west of the Brill road. She prides herself on surviving weather and monsters alike. Her best-known advice is to gather five times more firewood than seems enough.",
        sources = {V .. " #86784 Sticks and Bones (Forever)", LF("npc:eleanor-shackleton", "Eleanor_Shackleton")},
        names = {}, related = {"place:tirisfal"}},
    Note("npc:willem", "Deputy Willem", "Person",
        "Deputy Willem keeps watch at Northshire Abbey. He is brave and always ready to help, but his duties keep him at the abbey, so he sends dependable newcomers to friends in trouble, such as Milly Osworth with her wagon by the stables.",
        {V .. " #3903 Milly Osworth", LF("npc:willem", "Deputy_Willem")},
        {"Willem"}, {"place:northshire-abbey", "place:northshire"}),
    Note("npc:guard-thomas", "Guard Thomas", "Person",
        "Guard Thomas holds the bridge on the eastern edge of Elwynn Forest. Murlocs have settled in the streams around it, aggressive and at least semi-intelligent, and two of his guards, Rolf and Malakai, went north along the river to investigate and did not come back. Thomas wants to know what became of them.",
        {V .. " #35 Further Concerns; #37 Find the Lost Guards; #71 Report to Thomas", LF("npc:guard-thomas", "Guard_Thomas")},
        nil, {"region:456c77796e6e20466f72657374", "npc:dughan"}),
    Note("npc:bartleby", "Bartleby", "Person",
        "Bartleby is the drunk at the end of the bar in the Pig and Whistle tavern in Stormwind. He will not give up his mug to anyone who asks, and a warrior trainer there uses that fact as a test of a newcomer's skill.",
        {V .. " #1639 Bartleby the Drunk; #1640 Beat Bartleby", LF("npc:bartleby", "Bartleby")},
        nil, {"region:53746f726d77696e642043697479"}, true),
    Note("npc:bishop-farthing", "Bishop Farthing", "Person",
        "Bishop Farthing serves in the Cathedral of Light in Stormwind. Though Stormwind has turned its back on Darkshire, the Night Watch there counts him a kind and wise man, and sends him word when Duskwood's defenders need the Light's help against the necromancer Morbent Fel.",
        {V .. " #269 Seeking Wisdom", LF("npc:farthing", "Bishop_Farthing")},
        nil, {"place:cathedral-of-light", "place:darkshire"}),
    Note("npc:galgar", "Galgar", "Person",
        "Galgar is an orc of the Valley of Trials known for his cactus apple surprise, a treat he swears cools a recruit off faster than anything in the valley's heat. He trades portions of it for cactus apples gathered from the plants nearby.",
        {V .. " #4402 Galgar's Cactus Apple Surprise", LF("npc:galgar", "Galgar")},
        nil, {"place:valley-trials"}, true),
    Note("npc:ahanu", "Ahanu", "Person",
        "Ahanu is a leatherworker at Hewa's Armory in Thunder Bluff, at the foot of the wind rider tower. Hides from the Barrens reach him from colleagues at the Crossroads, and he turns them into leather goods.",
        {V .. " #6361 A Bundle of Hides; #6362 Ride to Thunder Bluff", LF("npc:ahanu", "Ahanu")},
        nil, {"region:5468756e64657220426c756666", "place:crossroads"}, true),
    Note("npc:gordon-wendham", "Gordon Wendham", "Person",
        "Gordon Wendham is a weapon dealer in the Trade Quarter of the Undercity. Orders for arms from the Forsaken's outposts come to him, among them the Sepulcher's requests to replace weapons its Deathguards have lost in Silverpine.",
        {V .. " #6321 Supplying the Sepulcher; #6323 Ride to the Undercity", LF("npc:gordon-wendham", "Gordon_Wendham")},
        nil, {"place:trade-quarter", "place:sepulcher"}),
})

-- Batch 4: quest givers the story prose names most often between levels 10 and 35.
A.RegisterLoreNotes({
    Note("npc:shael-dryn", "Shael'dryn", "Person",
        "Shael'dryn is a dryad who keeps to the moonwell east of Iris Lake in Ashenvale. Raene Wolfrunner of Astranaar sends people to her when matters are serious, because Shael'dryn knows how to remake the rod of the dead wizard Dartol, which the Sentinels hope can slow the furbolg attacks on their people.",
        {V .. " #1024 Raene's Cleansing; #991 Raene's Cleansing", LF("npc:shael-dryn", "Shael%27dryn")},
        nil, {"npc:raene", "place:astranaar", "region:417368656e76616c65"}, true),
    Note("npc:raene", "Raene Wolfrunner", "Person",
        "Raene Wolfrunner is a night elf of Astranaar who works with the Sentinels against the corruption spreading through Ashenvale. Darkshore sends her help through her servant Selarin. Her longtime friend Teronis went looking for the pieces of a rod made by the dead wizard Dartol, hoping it could slow the furbolg attacks, and has not come back from Lake Falathim.",
        {V .. " #990 Trek to Ashenvale; #991 Raene's Cleansing; #1024 Raene's Cleansing", LF("npc:raene-wolfrunner", "Raene_Wolfrunner")},
        {"Raene"}, {"place:astranaar", "npc:shael-dryn", "faction:sentinels"}),
    Note("npc:sputtervalve", "Sputtervalve", "Person",
        "Sputtervalve is a goblin engineer of the Tinkers' Union in Ratchet who works on shredders. The Venture Company's machines in the Barrens and Stonetalon are better than his, and he is not above stealing their plans, or their engineers. When the Venture Company hired a gnome, Gerenzo Wrenchwhistle, in Stonetalon, Sputtervalve took on the goblin engineers who left in disgust. One of them, Ziz Fizziks, calls him the cruelest slave driver of them all, though better than no job at all.",
        {V .. " #1483 Ziz Fizziks; #1093 Super Reaper 6000; #858 Ignition; #3924 Samophlange Manual", LF("npc:sputtervalve", "Sputtervalve")},
        nil, {"place:ratchet", "faction:venture-company", "npc:gazlowe"}, true),
    Note("npc:brine", "Brine", "Person",
        "Brine is a shaman who lives alone deep in the southern Barrens, with quilboar all around and no protection. Shaman seeking the water sapta are sent to her. She teaches that water means rebirth, healing when it is pure and devastating when it is polluted. Asked why she lives where she does, she answers that everyone has reasons.",
        {V .. " #1530 Call of Water; #63 Call of Water; #220 Call of Water", LF("npc:brine", "Brine")},
        nil, {"region:5468652042617272656e73", "faction:earthen-ring"}),
    Note("npc:doren", "Lieutenant Doren", "Person",
        "Lieutenant Doren leads the rebels camped northwest of the road where it enters Stranglethorn from Duskwood. He and his followers broke with Colonel Kurzen, whose expedition they once served, and they fight a losing war against him. Kurzen outnumbers them at least ten to one and is a brilliant tactician, so Doren uses Kurzen's own covert tactics against him. Supplies reach the rebels from Booty Bay by way of Private Thorsen.",
        {V .. " #198 Supplies to Private Thorsen; #203 The Second Rebellion; #202 Colonel Kurzen", LF("npc:doren", "Doren")},
        {"Doren"}, {"place:rebel-camp", "npc:kurzen", "region:537472616e676c6574686f726e2056616c65"}),
    Note("npc:kurzen", "Colonel Kurzen", "Person",
        "Colonel Kurzen commands soldiers in the jungles of northern Stranglethorn from the Stockpile, a cave behind his camp. Part of his command broke away under Lieutenant Doren and calls him an animal, but even the rebels grant him a cruel intellect and great skill as a tactician. His jungle fighters outnumber them many times over.",
        {V .. " #202 Colonel Kurzen; #203 The Second Rebellion; #198 Supplies to Private Thorsen", LF("npc:colonel-kurzen", "Colonel_Kurzen")},
        {"Kurzen"}, {"npc:doren", "place:rebel-camp", "region:537472616e676c6574686f726e2056616c65"}),
    Note("npc:madame-eva", "Madame Eva", "Person",
        "Madame Eva reads the cards in Darkshire, Duskwood's town under the Night Watch. She feels danger in her veins before she sees it on the table, and when a vision frightens her for her granddaughter Alyssa, she turns to the town's records and its visitors for help.",
        {V .. " #66 The Legend of Stalvan (opening only)", LF("npc:madame-eva", "Madame_Eva")},
        {"Eva"}, {"place:darkshire", "faction:night-watch"}),
    Note("npc:zargh", "Zargh", "Person",
        "Zargh is a butcher at the Crossroads in the Barrens. His fine cuts travel by wind rider to Gryshka, the innkeeper in Orgrimmar's Valley of Strength, who says that Zargh knows his way into a lady's heart.",
        {V .. " #6384 Ride to Orgrimmar; #6386 Return to the Crossroads", LF("npc:zargh", "Zargh")},
        nil, {"place:crossroads", "region:4f726772696d6d6172"}, true),
    Note("npc:thork", "Thork", "Person",
        "Thork is the orc who welcomes newcomers at the Crossroads, the Horde's fort in the Barrens. Tauren seers send their young to him, saying he has the Earthmother's blessing, since the lives of the tauren and the orcs have become intertwined. The quilboar raids on the Crossroads trouble him most, and a caged Razormane named Mangletooth offers to explain who is really behind them.",
        {V .. " #854 Journey to the Crossroads; #878 Tribes at War; #879 Betrayal from Within", LF("npc:thork", "Thork")},
        nil, {"place:crossroads", "faction:horde", "deity:earth-mother"}, true),
    Note("npc:devrak", "Devrak", "Person",
        "Devrak is the wind rider master at the Crossroads. For a small fee his wind riders carry couriers and goods from the Barrens to Orgrimmar and Thunder Bluff, among them hides for the leatherworkers and meat for the inns.",
        {V .. " #6361 A Bundle of Hides; #6365 Meats to Orgrimmar; #6363 Tal the Wind Rider Master", LF("npc:devrak", "Devrak")},
        nil, {"place:crossroads", "npc:zargh", "npc:ahanu"}, true),
    Note("npc:uzzek", "Uzzek", "Person",
        "Uzzek is a veteran of many battles who teaches young Horde warriors south of Far Watch Post, the orc garrison on the border between Durotar and the Barrens. Warriors are sent to him because, in the Horde's view, the truly great warriors are also great students.",
        {V .. " #1505 Veteran Uzzek", LF("npc:uzzek", "Uzzek")},
        nil, {"region:4475726f746172", "faction:horde"}, true),
    Note("npc:darcy", "Darcy", "Person",
        "Darcy works at the inn in Lakeshire. She makes lunch for Guard Parker, who patrols the road toward Duskwood, but thinks it far too dangerous for a townsperson to take it to him herself, so she trades a free meal to anyone who will.",
        {V .. " #129 A Free Lunch", LF("npc:darcy-parker", "Darcy_Parker")},
        nil, {"place:lakeshire"}, true),
    Note("npc:huldar", "Huldar", "Person",
        "Huldar is a dwarf who drives supplies from Thelsamar to Ironband's Excavation in southern Loch Modan, with Miran and Saean helping to haul the barrels. The route leaves town southward and follows the curve of the loch, and Dark Iron dwarves have been known to ambush the deliveries.",
        {V .. " #273 Resupplying the Excavation; #302 Powder to Ironband", LF("npc:huldar", "Huldar")},
        nil, {"place:thelsamar", "place:ironbands-excavation"}, true),
    {id = "deity:earth-mother", title = "Earth Mother", kind = "Deity", setting = "Classic / Forever",
        body = "The Earth Mother is the goddess of the tauren, who hold that she shaped the world and gave life to the land. Young tauren earn the respect of the elders of Thunder Bluff through the Rites of the Earthmother, and tauren speak of her blessing on those who serve well. In tauren belief the sun and the moon, An'she and Mu'sha, are her eyes.",
        sources = {"https://warcraft.wiki.gg/wiki/Earth_Mother", LF("topic:earth-mother", "Earth_Mother"), V .. " #755 Rites of the Earthmother; #854 Journey to the Crossroads; #1519 Call of Earth"},
        names = {"the Earth Mother", "Earthmother", "the Earthmother"}, related = {"people:tauren", "region:5468756e64657220426c756666", "deity:elune"}},
})

-- Batch 5: the supporting cast the rendered chapters name without a note.
-- Every fact is from the cited quest text; Lore Forever only where it has an entry.
A.RegisterLoreNotes({
    Note("npc:gryshka", "Innkeeper Gryshka", "Person",
        "Gryshka keeps the inn in Orgrimmar's Valley of Strength, not far from the wind rider tower. Zargh, the butcher at the Crossroads, sends her his best cuts by wind rider, and she is fond of him for it. She likes her meat served rare.",
        {V .. " #6365 Meats to Orgrimmar; #6384 Ride to Orgrimmar", LF("npc:innkeeper-gryshka", "Innkeeper_Gryshka")},
        {"Gryshka"}, {"place:valley-strength", "npc:zargh"}),
    Note("npc:mangletooth", "Mangletooth", "Person",
        "Mangletooth is a Razormane quilboar held in a cage at the Crossroads. His tribe turned its back on him and left him there, and he bargains with the Horde out of bitterness. He names the three Razormane who came out of the Kraul to lead the raids on the Horde, Nak, Kuz and their leader Lok Orcbane, and claims that Thork does not know the truth of who is behind them.",
        {V .. " #878 Tribes at War; #879 Betrayal from Within", LF("npc:mangletooth", "Mangletooth")},
        nil, {"place:crossroads", "npc:thork"}, true),
    Note("npc:wizzlecrank", "Wizzlecrank", "Person",
        "Wizzlecrank is a goblin who works for Sputtervalve of Ratchet. He climbed into one of the Venture Company's shredders at its drilling camp in the Barrens to steal it, only to find he needed a key to make it move. When another operator asked if all was well, he panicked and blamed a mechanical problem.",
        {V .. " #858 Ignition; #863 The Escape"},
        nil, {"npc:sputtervalve", "faction:venture-company"}, true),
    Note("npc:ziz-fizziks", "Ziz Fizziks", "Person",
        "Ziz Fizziks was an engineer for the Venture Company in the Stonetalon Mountains until the company hired a gnome, Gerenzo Wrenchwhistle, who took over the site and fired him. He asked Sputtervalve for work with the Tinkers' Union and now camps at the western edge of Windshear Crag, gathering what he can on Gerenzo's plans. He hopes to earn a place in a Union workshop in Gadgetzan or even Undermine.",
        {V .. " #1483 Ziz Fizziks; #1090 Gerenzo's Orders; #1096 Gerenzo Wrenchwhistle"},
        {"Ziz"}, {"npc:sputtervalve", "npc:gerenzo", "place:windshear-crag"}),
    Note("npc:gerenzo", "Gerenzo Wrenchwhistle", "Person",
        "Gerenzo Wrenchwhistle is a gnome who runs the Venture Company's operation at Windshear Crag in the Stonetalon Mountains, an appointment that scandalized the company's goblins. He watches over the site from high above Cragpool Lake, near the water wheel, and has ordered large amounts of a gold-green ore mined. His flesh looks to be rotting, and he has replaced some of his limbs with mechanical ones.",
        {V .. " #1090 Gerenzo's Orders; #1096 Gerenzo Wrenchwhistle; #1093 Super Reaper 6000"},
        {"Gerenzo"}, {"place:windshear-crag", "faction:venture-company", "npc:ziz-fizziks"}),
    Note("npc:guard-parker", "Guard Parker", "Person",
        "Guard Parker is a Stormwind guard who patrols the road from Lakeshire toward Duskwood. Darcy at the Lakeshire inn makes his lunch. When Parker sends her flowers, she suspects they came from Martie Jainrose, whom she calls a jealous rival.",
        {V .. " #129 A Free Lunch; #131 Delivering Daffodils"},
        {"Parker"}, {"npc:darcy", "place:lakeshire"}),
    Note("npc:teronis", "Teronis", "Person",
        "Teronis is a longtime friend of Raene Wolfrunner who aids the Sentinels in Ashenvale. He had leads on a rod made by Dartol, a dead and evil wizard, which he thought could slow the furbolg attacks, and went looking for a gem for it at the shrine in Lake Falathim. He has not returned.\n\nHis body lies on the island in the lake, cut down by murlocs. His notes on the search survived.",
        {V .. " #991 Raene's Cleansing; #1023 Raene's Cleansing"},
        nil, {"npc:raene", "relic:dartols-rod", "region:417368656e76616c65"}, true),
    Note("npc:elreth", "Novice Elreth", "Person",
        "Novice Elreth serves at Deathknell. She tends the wounded, tailors armor and clothing, and assists Shadow Priest Sarvis, and she trades armor for wolf paws and bat wings brought from the south of the village. She was a friend of Marla Fipps and wants Marla's last wish honored.",
        {V .. " #376 The Damned; #6395 Marla's Last Wish", LF("npc:novice-elreth", "Novice_Elreth")},
        {"Elreth"}, {"place:deathknell", "npc:sarvis", "npc:marla-fipps"}),
    Note("npc:marla-fipps", "Marla Fipps", "Person",
        "Marla Fipps lived with her husband Samuel in Tirisfal before the plague. Samuel joined the Scourge, and Marla, spared undeath, died at his hands. So strong was her love that her last wish was to be buried with him. Her grave lies in the first row of the graveyard at Deathknell.",
        {V .. " #6395 Marla's Last Wish"},
        {"Marla"}, {"npc:samuel-fipps", "npc:elreth", "place:deathknell"}),
    Note("npc:samuel-fipps", "Samuel Fipps", "Person",
        "Samuel Fipps succumbed to the plague and joined the mindless ranks of the Scourge, killing his wife Marla. He roams a ruined camp along the road northeast of Deathknell.",
        {V .. " #6395 Marla's Last Wish"},
        nil, {"npc:marla-fipps", "place:deathknell"}),
    Note("npc:dirania", "Dirania Silvershine", "Person",
        "Dirania Silvershine is a night elf of Shadowglen who knows an antidote for the poison of the webwood spiders. It takes hyacinth mushrooms, moonpetal lilies and ichor from the spiders themselves. She is a friend of Iverron and has always warned him about those spiders.",
        {V .. " #3519 A Friend in Need; #3521 Iverron's Antidote", LF("npc:dirania-silvershine", "Dirania_Silvershine")},
        {"Dirania"}, {"npc:iverron", "place:shadowglen"}),
    Note("npc:tallonkai", "Tallonkai Swiftroot", "Person",
        "Tallonkai Swiftroot is a night elf of Dolanaar who wants the satyr Lord Melenas dealt with. Melenas lives in Fel Rock, a cave just north of the village, and Tallonkai asks that the matter stay quiet, since the satyr are already an embarrassment to the night elves.",
        {V .. " #932 Twisted Hatred; #98403 Twisted Hatred (Forever)", LF("npc:tallonkai-swiftroot", "Tallonkai_Swiftroot")},
        {"Tallonkai"}, {"place:dolanaar", "npc:melenas", "place:fel-rock"}),
    Note("npc:melenas", "Lord Melenas", "Person",
        "Lord Melenas is a satyr who has made the cave of Fel Rock, north of Dolanaar, his lair and gathered grell warriors around him. To the night elves of Dolanaar his heart is black as night, and he plots something foul.",
        {V .. " #932 Twisted Hatred"},
        {"Melenas"}, {"place:fel-rock", "npc:tallonkai"}),
    Note("npc:rellian", "Rellian Greenspyre", "Person",
        "Rellian Greenspyre is a druid of Darnassus who walks the pathways of the Cenarion Enclave. He takes an interest in Denalan's work with the timberlings of Teldrassil, but he has found a corruption in many of them that their seeds carry on, beyond his talent to repair.",
        {V .. " #922 Rellian Greenspyre; #2498 Return to Denalan"},
        {"Rellian"}, {"npc:denalan", "region:4461726e6173737573"}),
    Note("npc:renee", "Innkeeper Renee", "Person",
        "Renee is the innkeeper at the Gallows' End Tavern in Brill. She offers the Forsaken rest and food, remarking on how large their appetites are, and waits on letters from her mother in Deathknell.",
        {V .. " #8 A Rogue's Deal", LF("npc:renee-lauer", "Innkeeper_Renee")},
        {"Renee"}, {"place:gallows-end", "place:brill"}),
    Note("npc:perrine", "Captain Perrine", "Person",
        "Captain Perrine commands a Scarlet Crusade brigade of zealots and missionaries at the ruined tower southwest of Brill. Among the things he has taken from the Forsaken is the grimoire of Egalin, who summoned the first voidwalker, though the warlocks of Brill doubt he understands what he stole.",
        {V .. " #370 At War With The Scarlet Crusade; #1473 Creature of the Void"},
        {"Perrine"}, {"group:scarlet-crusade", "place:brill"}),
    Note("npc:karos-razok", "Karos Razok", "Person",
        "Karos Razok is the bat handler at the Sepulcher in Silverpine Forest. For a small fee his bats carry riders to the Trade Quarter of the Undercity, and he counts it an honor to serve those who serve the Dark Lady.",
        {V .. " #6321 Supplying the Sepulcher; #6323 Ride to the Undercity", LF("npc:karos-razok", "Karos_Razok")},
        nil, {"place:sepulcher", "place:trade-quarter"}),
    Note("npc:farley", "Innkeeper Farley", "Person",
        "Innkeeper Farley runs the Lion's Pride Inn in Goldshire. His motto is rest and relaxation for the tired and cold, and friends who send travelers his way can promise them a discount on food and drink.",
        {V .. " #2158 Rest and Relaxation", LF("npc:innkeeper-farley", "Innkeeper_Farley")},
        {"Farley"}, {"place:lions-pride", "place:goldshire"}),
    Note("npc:william-pestle", "William Pestle", "Person",
        "William Pestle stays at the Lion's Pride Inn in Goldshire and is known for his potions. He sympathizes with Maybell Maclure and Tommy Joe Stonefield, young lovers kept apart because their families are bitter enemies. His brother Morgan keeps an apothecary in Stormwind's Trade District.",
        {V .. " #107 Note to William; #106 Young Lovers; #61 Shipment to Stormwind", LF("npc:william-pestle", "William_Pestle")},
        nil, {"place:lions-pride", "place:trade-district"}),
    Note("npc:milly-osworth", "Milly Osworth", "Person",
        "Milly Osworth keeps the Northshire Vineyards near the abbey. A gang of Defias brigands moved into the vineyards while she was harvesting, and she fears for her grapes whether the thieves take them or the guards trample them. Her harvest goes to Brother Neals, who manages the abbey's store of food and drink.",
        {V .. " #3903 Milly Osworth; #3904 Milly's Harvest; #3905 Grape Manifest"},
        {"Milly"}, {"place:northshire-abbey", "npc:brother-neals", "group:defias"}),
    Note("npc:brother-neals", "Brother Neals", "Person",
        "Brother Neals manages the store of food and drink at Northshire Abbey, and likes to taste the wine up in the bell tower. He counts on Milly Osworth's grapes for the abbey's wine.",
        {V .. " #3905 Grape Manifest", LF("npc:brother-neals", "Brother_Neals")},
        {"Neals"}, {"place:northshire-abbey", "npc:milly-osworth"}),
})

-- Batch 6: the world names the prose leans on most (Lordaeron, the Light) and the
-- quest givers still named without a note at levels 10 to 30, plus the paladin's charger.
A.RegisterLoreNotes({
    {id = "region:lordaeron", title = "Lordaeron", kind = "Region", setting = "Classic / Forever",
        body = "Lordaeron is the northern human kingdom of the Eastern Kingdoms, once the most powerful of the seven nations that grew from ancient Arathor and the heart of the Alliance that fought the Second War. The plague struck it first in the Third War. Prince Arthas Menethil killed his father, King Terenas, and the Scourge laid the kingdom waste.\n\nIts lands are now the Plaguelands, Tirisfal and the foothills to the south. The Forsaken rule from the Undercity beneath the ruined capital, the Scourge holds much of the east, and the Scarlet Crusade and the last Alliance holdouts fight over what remains.",
        sources = {"https://warcraft.wiki.gg/wiki/Kingdom_of_Lordaeron", LF("topic:lordaeron", "Lordaeron"), V .. " #363 Rude Awakening; #105 Alas, Andorhal"},
        names = {"Kingdom of Lordaeron"}, related = {"npc:arthas", "place:undercity", "book:alliance-lordaeron"}},
    {id = "belief:holy-light", title = "Holy Light", kind = "Belief", setting = "Classic / Forever",
        body = "The Holy Light is the power and faith at the heart of human and dwarven religion. Priests of the Church of the Holy Light and paladins of the Knights of the Silver Hand draw on it to heal, to shield and to strike at demons and the undead. In Stormwind the Cathedral of Light is its great church, and the faithful bless one another in its name.",
        sources = {"https://warcraft.wiki.gg/wiki/Holy_Light", LF("topic:light", "Light"), V .. " #5638 Desperate Prayer; #3905 Grape Manifest; #7638 Lord Grayson Shadowbreaker"},
        names = {"the Holy Light", "the Light"}, related = {"place:cathedral-of-light", "npc:grayson", "faction:silver-hand"}},
    {id = "npc:cenarius", title = "Cenarius", kind = "Person", setting = "Classic / Forever",
        body = "Cenarius is the demigod of the forests, son of Elune and the white stag Malorne. He taught Malfurion Stormrage the ways of the druid and fought in the War of the Ancients, and for ten thousand years after the Great Sundering he watched over Kalimdor with the Cenarion Circle. In the Third War he fell in Ashenvale to orcs maddened by demon blood. Druids still speak of the animal forms he blessed them with, and his children the dryads and the keepers of the grove guard the wild places.",
        sources = {"https://warcraft.wiki.gg/wiki/Cenarius", LF("topic:cenarius", "Cenarius"), V .. " #26 A Lesson to Learn; #1031 The Branch of Cenarius"},
        names = {}, related = {"faction:cenarion-circle", "deity:elune", "npc:malfurion"}, autoLink = true},
    {id = "region:kul-tiras", title = "Kul Tiras", kind = "Region", setting = "Classic / Forever",
        body = "Kul Tiras is the island kingdom of seafarers west of Lordaeron, whose navy carried the Alliance at sea in the Second War under Admiral Daelin Proudmoore. The kingdom has since drawn back into itself. Its Third Fleet was burned and sunk off the coast of the Wetlands by red dragons ridden by orcs, and Daelin's men have come to Kalimdor, where his daughter Jaina leads Theramore.",
        sources = {"https://warcraft.wiki.gg/wiki/Kul_Tiras", LF("topic:kul-tiras", "Kul_Tiras"), V .. " #288 The Third Fleet; #1285 Daelin's Men"},
        names = {}, related = {"npc:daelin-proudmoore", "npc:jaina", "place:theramore"}},
    {id = "place:karazhan", title = "Karazhan", kind = "Place", setting = "Classic / Forever",
        body = "Karazhan is the tower of the mage Medivh in Deadwind Pass, built above a meeting of ley lines that bends time and space. Possessed by Sargeras, Medivh helped open the Dark Portal from there. Anduin Lothar and Khadgar killed him in the tower, and its gates were sealed. Restless spirits haunt it still, and the Dark Riders search the lands around it for old relics.",
        sources = {"https://warcraft.wiki.gg/wiki/Karazhan", LF("subzone:karazhan", "Karazhan")},
        names = {}, related = {"npc:medivh", "npc:khadgar", "region:4465616477696e642050617373"}},
    {id = "npc:agamaggan", title = "Agamaggan", kind = "Person", setting = "Classic / Forever",
        body = "Agamaggan was the boar demigod who fell fighting the Burning Legion in the War of the Ancients. Where he died in the southern Barrens his blood soaked the earth, and the great thorns of the Razorfen grew from it. The quilboar revere him as their forefather and guard his resting place. Blood-red shards dug from the ground there are said to hold his power, and quilboar carry them as totems.",
        sources = {"https://warcraft.wiki.gg/wiki/Agamaggan", LF("topic:agamaggan", "Agamaggan"), V .. " #5052 Blood Shards of Agamaggan; #1101 The Crone of the Kraul"},
        names = {}, related = {"dungeon:razorfen-kraul", "npc:mangletooth"}, autoLink = true},
    Note("npc:calor", "Calor", "Person",
        "Calor works for the Carevin family of Darkshire, hunters of demons, undead and other monstrosities. He brings worgen heads back into town and watches the abandoned buildings of Raven Hill, where he has seen shadows moving and a light in a window.",
        {V .. " #163 Raven Hill; #1042 The Carevin Family", LF("npc:calor", "Calor")},
        nil, {"npc:jonathan-carevin", "place:raven-hill", "place:darkshire"}, true),
    Note("npc:kadrak", "Kadrak", "Person",
        "Kadrak leads the Horde's campaign into Ashenvale from the watch tower at the northern edge of the Barrens. New recruits report to him for duty at the Horde's fresh outposts in the forest, on the Zoram Strand and at Splintertree.",
        {V .. " #6541 Report to Kadrak; #6542 Report to Kadrak", LF("npc:kadrak", "Kadrak")},
        nil, {"place:splintertree", "place:zoram-strand", "region:417368656e76616c65"}, true),
    Note("npc:mull-thunderhorn", "Mull Thunderhorn", "Person",
        "Mull Thunderhorn is a tauren of Bloodhoof Village who tends Mulgore's sacred water wells. Goblins of the Venture Company have tainted the Winterhoof, Thunderhorn and Wildmane wells, and Mull makes cleansing totems from the gifts of the land so that each well can be purified in turn.",
        {V .. " #748 Poison Water; #754 Winterhoof Cleansing; #760 Wildmane Cleansing", LF("npc:mull-thunderhorn", "Mull_Thunderhorn")},
        {"Mull"}, {"place:bloodhoof", "faction:venture-company", "deity:earth-mother"}),
    Note("npc:morin-cloudstalker", "Morin Cloudstalker", "Person",
        "Morin Cloudstalker scouts the plains of Mulgore near Bloodhoof Village. His people burned a Venture Company caravan on the shore of Stonebull Lake after the goblins had killed two of their number, and he wants to know what the company was carrying and what it plans.",
        {V .. " #749 The Ravaged Caravan; #98424 Fizsprocket's Notes (Forever)", LF("npc:morin-cloudstalker", "Morin_Cloudstalker")},
        {"Morin"}, {"place:ravaged-caravan", "faction:venture-company", "place:bloodhoof"}),
    Note("npc:terenthis", "Terenthis", "Person",
        "Terenthis is a night elf druid in Auberdine. When the bear Grimclaw comes to him alone, he knows that Grimclaw's master Volcor is in trouble, and he makes a moonstalker cloak to help hide whoever goes to find him in the furbolg country to the south.",
        {V .. " #993 A Lost Master; #994 Escape Through Force", LF("npc:terenthis", "Terenthis")},
        nil, {"place:auberdine", "region:4461726b73686f7265"}, true),
    Note("npc:grayson", "Lord Grayson Shadowbreaker", "Person",
        "Lord Grayson Shadowbreaker is a paladin lord of the Silver Hand in Stormwind's Cathedral District. He guides paladins who are ready to win a charger, a trial of sacrifice and judgment that sends them to exorcise the restless spirits of Terrordale and to rescue the spirit of a charger held by the death knight Darkreaver.",
        {V .. " #7638 Lord Grayson Shadowbreaker; #7639 To Show Due Judgment; #7640 Exorcising Terrordale", LF("npc:lord-grayson-shadowbreaker", "Lord_Grayson_Shadowbreaker")},
        {"Grayson Shadowbreaker"}, {"place:cathedral-of-light", "place:terrordale", "faction:silver-hand"}),
    Note("npc:allister", "Shadow Priest Allister", "Person",
        "Shadow Priest Allister directs the Forsaken's watch over Silverpine from the Sepulcher. His chief worry is the wizards of Dalaran working at Ambermill, which the Kirin Tor have marked for a dormant ley energy node, and he decides with Dalar Dawnweaver how to stop them.",
        {V .. " #482 Dalaran's Intentions", LF("npc:shadow-priest-allister", "Shadow_Priest_Allister")},
        {"Allister"}, {"place:sepulcher", "place:ambermill", "npc:dalar"}),
    Note("npc:laird", "Laird", "Person",
        "Laird sells fish in Auberdine. A colleague at Rut'theran Village sends him bones and scales from Teldrassil's large catch to compare with the fish of the mainland.",
        {V .. " #6341 The Bounty of Teldrassil; #6343 Return to Nessa", LF("npc:laird", "Laird")},
        nil, {"place:auberdine", "place:ruttheran"}, true),
    Note("npc:gath-ilzogg", "Gath'Ilzogg", "Person",
        "Gath'Ilzogg leads the Blackrock orcs who took Stonewatch Keep in the Redridge Mountains and raid the township of Lakeshire. He keeps to the keep, plotting further attacks, and Magistrate Solomon has put a bounty on his head.",
        {V .. " #169 WANTED: Gath'Ilzogg", LF("npc:gath-ilzogg", "Gath%27Ilzogg")},
        nil, {"place:stonewatch", "place:lakeshire", "npc:solomon"}, true),
    Note("npc:gann-stonespire", "Gann Stonespire", "Person",
        "Gann Stonespire is a tauren who wanders the roads of the southern Barrens alone. His tribe's land was taken by the dwarves of the Bael Modan excavation, whose blasts and machines tear up the hills, and his attempts at a peaceful settlement have failed. He now means to drive them out by force.",
        {V .. " #843 Gann's Reclamation; #846 Revenge of Gann", LF("npc:gann-stonespire", "Gann_Stonespire")},
        {"Gann"}, {"place:bael-modan", "region:5468652042617272656e73"}),
    Note("npc:gazrog", "Gazrog", "Person",
        "Gazrog is one of the Horde's soldiers at the Crossroads. He worked with the grunt Dogran, whose mate waits for word of him in Orgrimmar.",
        {V .. " #1509 News of Dogran", LF("npc:gazrog", "Gazrog")},
        nil, {"place:crossroads"}, true),
    Note("npc:old-murk-eye", "Old Murk-Eye", "Person",
        "Old Murk-Eye is a murloc who leads raids along the Westfall coast. He drove off the family that kept the lighthouse there and, when they came back to relight the flame, led a second attack in which they died. The ghost of a sailor who died on the rocks there now keeps the light and wants the beast dead.",
        {V .. " #103 Keeper of the Flame; #104 The Coastal Menace", LF("npc:old-murk-eye", "Old_Murk-Eye")},
        {"Murk-Eye"}, {"region:5765737466616c6c"}),
})

-- Batch 9: people the horde lane's new scenes name (coordinator request).
local function ForeverPerson(id, title, body, sources, names, related)
    local entry = Note(id, title, "Person", body, sources, names, related)
    entry.setting = "Forever"
    return entry
end
A.RegisterLoreNotes({
    Note("group:agamand-family", "Agamand family", "Group",
        "The Agamands were the most prosperous family in Tirisfal Glades, owners of the Agamand Mills. When the Scourge came they fortified their home and persuaded the people in their employ to stay and defend it, and the plague took them all. The Agamands now roam their mills as servants of the Scourge, among them Gregor's younger son Devlin, weak and sharp-tongued in life, while his elder son Thurman was tall and gentle. Their former workers among the Forsaken, Coleman Farthing above all, blame the family's pride for their own undeath.",
        {V .. " #354 Deaths in the Family; #362 The Haunted Mills; #361 A Letter Undelivered; #1821 Agamand Heirlooms"},
        {"the Agamands", "Agamands", "the Agamand family"}, {"place:agamand-mills", "place:agamand-crypt", "npc:coleman-farthing"}),
    Note("npc:yvette-farthing", "Yvette Farthing", "Person",
        "Yvette Farthing is a Forsaken of Brill. In life she loved Thurman, the eldest son of Gregor Agamand, and begged him to leave Agamand Mills with her and her father when the plague came, but his loyalty to his family kept him there. As one of the Forsaken she says love is no longer among her goals.",
        {V .. " #361 A Letter Undelivered", LF("npc:yvette-farthing", "Yvette_Farthing")},
        {"Yvette"}, {"group:agamand-family", "npc:coleman-farthing", "place:brill"}),
    Note("npc:lillith-nefara", "Lillith Nefara", "Person",
        "Lillith Nefara is a powerful agent of the Scourge in Tirisfal. Her old, bloody altar stands just off the southern shore of Gunther Arcanus's island in Brightwater Lake, and a Candle of Beckoning lit upon it wakes her. Gunther asks anyone claiming to be free of the Lich King to destroy her as proof.",
        {V .. " #409 Proving Allegiance", LF("item:candle-of-beckoning", "Candle_of_Beckoning")},
        {"Lillith"}, {"npc:gunther", "place:brightwater", "faction:scourge"}),
    Note("npc:holland", "Junior Apothecary Holland", "Person",
        "Junior Apothecary Holland works in the graveyard of Brill. He needs doom weed, which grows near the mass graves to the north, and is exasperated that his abomination Gordo keeps bringing him gloom weed instead. He rubs his hands at the thought of what the weed will do for him, or rather for the Lady.",
        {V .. " #5481 Gordo's Task; #5482 Doom Weed"},
        {"Holland"}, {"npc:gordo", "place:brill", "place:mass-graves"}),
    Note("npc:gordo", "Gordo", "Person",
        "Gordo is an abomination who wanders the roads near Brill gathering weeds for his master, Junior Apothecary Holland. His hands are too big for picking, so he asks passers-by for help, and he gathers the wrong weed.",
        {V .. " #5481 Gordo's Task; #5482 Doom Weed"},
        nil, {"npc:holland", "place:brill"}, true),
    ForeverPerson("npc:heglan", "Heglan Shadeeye",
        "Heglan Shadeeye is a scout of the Shattered Hand, the Horde's group of more subtle fighters. She was set to watch Tiragarde Keep in Durotar from a distance until her reports stopped coming in.\n\nHer body lies in the wreckage of her hut. Naga, come down the coast from the north, killed her, and the banner and blade they left behind went to Orgnil Soulscar at Razor Hill.",
        {V .. " #99048 A Missing Hand (Forever); #99049 Threat from Below (Forever)"},
        {"Heglan"}, {"place:tiragarde", "npc:orgnil", "place:razor-hill"}),
    Note("npc:zureetha", "Zureetha Fargaze", "Person",
        "Zureetha Fargaze watches over the novices of the Valley of Trials. She sends them against the creatures in the cave near the valley, among them the vile familiars that serve the darker powers of the Burning Blade.",
        {V .. " #1499 Vile Familiars", LF("npc:zureetha-fargaze", "Zureetha_Fargaze")},
        {"Zureetha"}, {"place:valley-trials", "faction:burning-blade", "place:the-den"}),
    Note("npc:jorn-skyseer", "Jorn Skyseer", "Person",
        "Jorn Skyseer is a tauren hunter at Camp Taurajo in the Barrens who guides young hunters farther down their path. He holds that a true hunter can stalk prey anywhere, even at sea, and sends those who earn his respect to his sister Mahren.",
        {V .. " #3261 Jorn Skyseer; #874 Mahren Skyseer"},
        {"Jorn"}, {"place:camp-taurajo", "npc:mahren-skyseer"}),
    Note("npc:mahren-skyseer", "Mahren Skyseer", "Person",
        "Mahren Skyseer hunts the great water beasts along the coast of the Barrens, where the shore is held by humans. Her brother Jorn sends her the hunters he has come to respect, and she teaches them the ways of the creatures of the sea.",
        {V .. " #874 Mahren Skyseer"},
        {"Mahren"}, {"npc:jorn-skyseer", "region:5468652042617272656e73"}),
    Note("npc:wenikee", "Wenikee Boltbucket", "Person",
        "Wenikee Boltbucket is a clever and inquisitive tinkerer who lives just south of the Mor'shan Rampart, the Horde outpost between the Barrens and Ashenvale. Given a machine she does not understand, she wants nothing more than to fix it and see what it does.",
        {V .. " #3921 Wenikee Boltbucket"},
        {"Wenikee"}, {"region:5468652042617272656e73", "npc:rilli"}),
    Note("npc:rilli", "Rilli Greasygob", "Person",
        "Rilli Greasygob is a goblin engineer at Nogg's Machine Shop in Orgrimmar's Valley of Honor. He once worked for the Venture Company, where his rival Boss Copperplug kept the secrets of the samophlange from him, and he knows more about the company's machines than most.",
        {V .. " #3923 Rilli Greasygob; #3924 Samophlange Manual"},
        {"Rilli"}, {"place:valley-honor", "faction:venture-company", "npc:wenikee"}),
    ForeverPerson("npc:malah", "Longwalker Malah",
        "Longwalker Malah is one of the Longwalkers, the most trusted scouts of the tauren, loyal to the High Chieftain alone though Baine Bloodhoof sometimes asks for their help. She wears the headband and feathered staff of her order. She was sent to watch the eastern borders of Mulgore and has not come back.\n\nShe lies dead with arrows in her back, shot from a new centaur camp. A small raiding party has come into Mulgore.",
        {V .. " #99079 Longwalker Malah (Forever); #99081 Grim Tidings (Forever)"},
        {"Malah"}, {"npc:baine", "place:bloodhoof", "region:4d756c676f7265"}),
    ForeverPerson("npc:perith", "Perith Stormhoof",
        "Longwalker Perith Stormhoof is the most trusted scout of High Chieftain Cairne Bloodhoof. Cairne sent him to speak with the gnolls that have settled at Bleachmane Rock. They met his diplomacy with violence, and the rest of his mission is secret, as is all Longwalker business.",
        {V .. " #98430 The Longwalkers (Forever)"},
        {"Perith"}, {"npc:cairne", "region:5468756e64657220426c756666"}),
    Note("npc:ataeric", "Archmage Ataeric", "Person",
        "Archmage Ataeric is a wizard of Dalaran who oversees the Kirin Tor's work at Ambermill in Silverpine, where they mean to wake a dormant ley energy node. Mages and warders protect him, and the Forsaken at the Sepulcher see him as the one man whose death could stop the work.",
        {V .. " #480 The Weaver; #482 Dalaran's Intentions", "https://www.wowhead.com/classic/quest=480/the-weaver (Ataeric's Staff)"},
        {"Ataeric"}, {"place:ambermill", "npc:allister", "faction:kirin-tor"}),
    ForeverPerson("npc:aetheen", "Aetheen of the Gales",
        "Aetheen of the Gales sits on the Council of Elders of Zephras Isle. She comes to Thendal Grove to read the flow of the winds and to judge the young shen'dorei coming of age, and she sends those she finds ready to Constable Aonda in Shen'dar Village, which the Al'Aketh threaten.",
        {V .. " #92471 Aetheen of the Gales; #92472 The Next Step"},
        {"Aetheen"}, {"place:thendal", "place:shendar", "group:al-aketh"}),
})

-- Second overnight notes lane (notes2), 2026-11-05. Names the story prose still
-- used without a note, measured against every pack and weighted by use. Facts
-- from the vanilla quest corpus first; Lore Forever (CC BY-SA, adapted from
-- warcraft.wiki.gg) only confirms or locates. The wording is ours.
-- notes2 batch 1: Darkshore and Teldrassil, the Tower of Althalaxx and its watchers.
-- Athrikus Narassin's survival and leadership of the cult are discoveries
-- (LoreDiscoveryData.lua, "althalaxx"); the public notes never name him as master.
A.RegisterLoreNotes({
    Note("npc:athrikus", "Athrikus Narassin", "Person",
        "Athrikus Narassin was a sorcerer of the ancient Highborne. Queen Azshara gave him authority over the Highborne of Ameth'Aran and Bashal'Aran, and in time he withdrew from their affairs to the Tower of Althalaxx on the northern coast of Darkshore. The spirit freed at Bashal'Aran names him as the master who sealed it in its prison.\n\nAthrikus still lives. He leads the Cult of the Dark Strand from the top of the Tower of Althalaxx, among warlocks far more dangerous than those outside. Ilkrud Magthrull's writings show that he keeps two soulgems among the satyrs at Night Run and Satyrnaar, and Delgren the Purifier expects their loss to weaken him greatly.",
        {V .. " #957 Bashal'Aran; #1140 The Tower of Althalaxx; #1143 The Tower of Althalaxx", "https://warcraft.wiki.gg/wiki/Athrikus_Narassin", LF("subzone:tower-of-althalaxx", "Tower_of_Althalaxx")},
        {"Athrikus"}, {"place:tower-of-althalaxx", "group:dark-strand", "place:bashal-aran"}, true),
    Note("group:dark-strand", "Cult of the Dark Strand", "Group",
        "The Cult of the Dark Strand is a band of warlocks and cultists in northern Darkshore and Ashenvale. They have gathered in and around the Tower of Althalaxx, and more of them work at Ordil'Aran, northeast of Maestra's Post, where one of their number carries a soul gem that holds a secret of the cult's power. Balthule Shadowstrike learned the cult's name from scraps of parchment its members carry, and had never heard of it before. Delgren the Purifier calls the cult a thorn in his side.\n\nIts master is Athrikus Narassin, an ancient Highborne sorcerer who keeps to the top of the tower.",
        {V .. " #966 The Tower of Althalaxx; #970 The Tower of Althalaxx; #1140 The Tower of Althalaxx", LF("subzone:tower-of-althalaxx", "Tower_of_Althalaxx")},
        {"the Cult of the Dark Strand", "Dark Strand", "the Dark Strand"}, {"place:tower-of-althalaxx", "npc:balthule", "npc:delgren"}),
    Note("npc:balthule", "Balthule Shadowstrike", "Person",
        "Balthule Shadowstrike is a night elf who keeps watch on the Tower of Althalaxx in northern Darkshore. Sentinel Elissa Starbreeze of Auberdine sent him to observe the strange happenings there, and he stayed on rather than risk missing something while away. He gathers the scraps of parchment the tower's warlocks carry to piece together who they are. Balthule is a student of Delgren the Purifier, the human paladin at Maestra's Post, who has taught him about the Holy Light and the art of battle.",
        {V .. " #965 The Tower of Althalaxx; #966 The Tower of Althalaxx; #967 The Tower of Althalaxx", LF("npc:balthule-shadowstrike", "Balthule_Shadowstrike")},
        {"Balthule"}, {"place:tower-of-althalaxx", "npc:delgren", "npc:elissa-starbreeze"}),
    Note("npc:delgren", "Delgren the Purifier", "Person",
        "Delgren the Purifier is a human paladin at Maestra's Post in northern Ashenvale. Wherever undead or demons are found, he helps the Sentinels destroy them. The manners of the night elves took him time to get used to, but he has come to respect them greatly as allies, and he sends supplies and news north to the Sentinels at Auberdine. Balthule Shadowstrike is his student.\n\nDelgren learned the orcish tongue though many of his order scoffed at it, and finds it useful for understanding his enemies. He calls the Cult of the Dark Strand a thorn in his side.",
        {V .. " #967 The Tower of Althalaxx; #970 The Tower of Althalaxx; #1140 The Tower of Althalaxx; #976 Supplies to Auberdine", LF("npc:delgren-the-purifier", "Delgren_the_Purifier")},
        {"Delgren"}, {"place:maestras-post", "npc:balthule", "group:dark-strand"}),
    Note("npc:elissa-starbreeze", "Sentinel Elissa Starbreeze", "Person",
        "Sentinel Elissa Starbreeze is charged with protecting Auberdine. She follows the dangers in the Darkshore wilds from the town, and when strange happenings began around the Tower of Althalaxx she sent Balthule Shadowstrike to watch them. Delgren the Purifier sends supplies and messages to her from Ashenvale.",
        {V .. " #965 The Tower of Althalaxx; #976 Supplies to Auberdine; #1140 The Tower of Althalaxx", LF("npc:sentinel-elissa-starbreeze", "Sentinel_Elissa_Starbreeze")},
        {"Elissa Starbreeze", "Sentinel Starbreeze"}, {"place:auberdine", "npc:balthule", "faction:sentinels"}),
    Note("npc:grimclaw", "Grimclaw", "Creature",
        "Grimclaw is the bear companion of Volcor, a night elf of Darkshore. When furbolgs wounded Volcor and trapped him in a cave south of Auberdine, Grimclaw came to the druid Terenthis alone, and Terenthis understood that his master was in trouble. The bear waits beside the road near the cave to show the way in.",
        {V .. " #986 A Lost Master; #993 A Lost Master; #994 Escape Through Force", LF("subzone:blackwood-den", "Blackwood_Den")},
        nil, {"npc:volcor", "npc:terenthis", "place:blackwood-den"}, true),
    Note("npc:hollee", "Archaeologist Hollee", "Person",
        "Archaeologist Hollee is an Explorers' League scholar trained at the academy in Ironforge. Chief Archaeologist Greywhisker sent her to Darkshore to work under Prospector Remtravel, which she counted an honor. When golems sprang from the ground and overran their dig in the south, Remtravel did not seem to notice, and Hollee ran back to Auberdine for help. She will not leave Darkshore without him.\n\nIn Forever she also writes to Tarrel, a classmate from her school days who now digs in the Wetlands near Menethil Harbor. Tarrel, happily married to Merrin, thinks she has always been fond of him.",
        {V .. " #729 The Absent Minded Prospector; #731 The Absent Minded Prospector; #741 The Absent Minded Prospector; #98461 Unrequited Love (Forever)", LF("npc:archaeologist-hollee", "Archaeologist_Hollee")},
        {"Hollee"}, {"npc:remtravel", "npc:greywhisker", "place:auberdine"}),
    Note("npc:greywhisker", "Chief Archaeologist Greywhisker", "Person",
        "Chief Archaeologist Greywhisker directs the Explorers' League's work in Kalimdor from Darnassus. He finds that the Alliance often dismisses archaeology as a hobby, though recent discoveries in Khaz Modan show that a great and powerful force threatens all of Azeroth. He sent a crew under Prospector Remtravel to dig in Darkshore, and waits anxiously for word from them.",
        {V .. " #730 Trouble In Darkshore?; #729 The Absent Minded Prospector; #741 The Absent Minded Prospector", LF("npc:chief-archaeologist-greywhisker", "Chief_Archaeologist_Greywhisker")},
        {"Greywhisker"}, {"faction:explorers-league", "npc:remtravel", "npc:hollee"}),
    Note("npc:tharnariun", "Tharnariun Treetender", "Person",
        "Tharnariun Treetender is a night elf of Auberdine who studies the sickness spreading through Darkshore's animals. The thistle bears have been hit hardest, turning rabid and frenzied. He made a trap of soothing light, Tharnariun's Hope, to calm a sick bear long enough to lead it to him for a cure, but his healing could not save it. Since then he has asked for the sick animals to be put down, which grieves him, and his last request is the death of the Den Mother.",
        {V .. " #2118 Plagued Lands; #2139 Tharnariun's Hope", LF("npc:tharnariun-treetender", "Tharnariun_Treetender"), LF("item:tharnariun-s-hope", "Tharnariun%27s_Hope")},
        {"Tharnariun"}, {"place:auberdine", "npc:den-mother", "region:4461726b73686f7265"}),
    Note("npc:den-mother", "Den Mother", "Creature",
        "The Den Mother is a thistle bear that lairs in a cave northeast of Auberdine, near the ruins of Bashal'Aran. The sickness that turned Darkshore's bears rabid has taken her as well. Tharnariun Treetender, who first hoped to cure the bears, came to see her death as the last way to ease the forest's pain.",
        {V .. " #2139 Tharnariun's Hope; #2118 Plagued Lands", LF("quest:2139", "Tharnariun%27s_Hope_(quest)")},
        {"the Den Mother", "The Den Mother"}, {"npc:tharnariun", "place:bashal-aran", "place:auberdine"}),
    Note("npc:gilshalan", "Gilshalan Windwalker", "Person",
        "Gilshalan Windwalker is a night elf scholar who came to Shadowglen to study the webwood spiders of Shadowthread Cave. They are cousins of a much smaller spider, and he believes the growth of the new World Tree has changed them. He collects their venom and an unhatched egg to take back to Darnassus for comparison with their smaller kin.",
        {V .. " #916 Webwood Venom; #917 Webwood Egg", LF("npc:gilshalan-windwalker", "Gilshalan_Windwalker")},
        {"Gilshalan"}, {"place:shadowthread-cave", "place:shadowglen", "place:aldrassil"}),
    Note("npc:athridas", "Athridas Bearmantle", "Person",
        "Athridas Bearmantle is a night elf druid in Dolanaar. His brethren, the Druids of the Talon, sleep in the Ban'ethil Barrow Den under a pact with Ysera, guarded by the Great Warden Gaerolas Talvethren. When word from Gaerolas came late, Athridas sent help to Starbreeze Village and learned that the Gnarlpine furbolgs had turned on the forest's protectors. Their chieftain, Ursal the Mauler, has interfered with the sleepers, and Athridas prepares the Relics of Wakening to rouse them once Ursal is dead.",
        {V .. " #459 The Woodland Protector; #475 A Troubling Breeze; #476 Gnarlpine Corruption; #486 Ursal the Mauler", LF("npc:athridas-bearmantle", "Athridas_Bearmantle")},
        {"Athridas"}, {"place:dolanaar", "place:banethil", "npc:ursal"}),
    Note("npc:gaerolas", "Gaerolas Talvethren", "Person",
        "Gaerolas Talvethren is the Great Warden of the Druids of the Talon, chosen to keep them safe while they sleep in the Ban'ethil Barrow Den so that their pact with Ysera holds. Gnarlpine furbolgs ambushed him on his way to the den and went on to pillage Starbreeze Village. He is too badly wounded to carry the news back to Athridas Bearmantle in Dolanaar.",
        {V .. " #475 A Troubling Breeze; #476 Gnarlpine Corruption"},
        {"Gaerolas"}, {"place:starbreeze", "place:banethil", "npc:athridas"}),
    Note("npc:ursal", "Ursal the Mauler", "Person",
        "Ursal the Mauler is chieftain of the Gnarlpine furbolgs of Teldrassil, a tribe that lived peacefully until Fel Moss corrupted it. He uses the moss to drive his people mad. His furbolgs ambushed the Great Warden Gaerolas Talvethren and pillaged Starbreeze Village, and he has meddled with the sleeping Druids of the Talon. He lairs in Gnarlpine Hold in the southwest of the island.",
        {V .. " #459 The Woodland Protector; #476 Gnarlpine Corruption; #486 Ursal the Mauler", LF("quest:486", "Ursal_the_Mauler")},
        nil, {"place:gnarlpine-hold", "npc:athridas", "region:54656c6472617373696c"}),
})

-- notes2 batch 2: the Eastern Kingdoms names left over from the first lane, and two
-- secrets. Nathanos Marris is the Blightcaller only for readers who reached #6186;
-- Lescovar's employment of the assassin known as Maelik and Marzon is learned from
-- Shaw in #393 (LoreDiscoveryData.lua, "nathanos" and "lescovar" policies).
A.RegisterLoreNotes({
    Note("npc:tharil-zun", "Tharil'zun", "Person",
        "Tharil'zun is the orc who leads the Blackrock outrunners in the Redridge Mountains. His raiders and the renegades with them set ambushes on the roads between Lakeshire and Stonewatch Keep. Marshal Marris has put a price on his head and calls him vicious and crafty.",
        {V .. " #19 Tharil'zun", LF("quest:19", "Tharil%27zun_(quest)")},
        nil, {"place:stonewatch", "npc:marris", "place:lakeshire"}, true),
    Note("npc:captain-grayson", "Captain Grayson", "Person",
        "Captain Grayson is the ghost who keeps the flame of the Westfall Lighthouse. He died needlessly on the rocks of that coast, and after his death he watched Old Murk-Eye's murlocs drive off the lighthouse keeper's family and then kill them when they came back to light the fire again. Now he tends the light himself so that other ships are spared, and he wants Old Murk-Eye dead. Children of the Stormwind orphanage hear that he was a pirate captain whose ship was taken by other pirates.",
        {V .. " #103 Keeper of the Flame; #104 The Coastal Menace; #1687 Spooky Lighthouse", LF("npc:captain-grayson", "Captain_Grayson")},
        nil, {"npc:old-murk-eye", "region:5765737466616c6c"}),
    Note("npc:lars", "Lars", "Person",
        "Lars lives with Sven Yorgen at a lonely camp in western Duskwood. With the necromancer Morbent Fel to the east, the two of them hunt their own food, and starving dire wolves come out of the forest whenever Lars carries meat back to camp. Darkshire has donated flash bundles to Sven's cause, and Lars hands some of them on to those who help.",
        {V .. " #226 Wolves at Our Heels", LF("npc:lars", "Lars")},
        nil, {"npc:sven-yorgen", "npc:morbent-fel", "region:4475736b776f6f64"}),
    Note("npc:morbent-fel", "Morbent Fel", "Person",
        "Morbent Fel is a necromancer of Duskwood. He hides in a house on the hill east of Raven Hill, overlooking its cemetery, behind protective magic that ordinary weapons cannot break. Sven Yorgen wants him dead in revenge. Those who would face him seek Morbent's Bane, which renders his protections powerless, or a weapon of Lightforge Iron, a metal whose blows strike with holy truth.",
        {V .. " #55 Morbent Fel; #226 Wolves at Our Heels; #270 The Doomed Fleet", LF("quest:55", "Morbent_Fel_(quest)")},
        nil, {"place:raven-hill", "npc:sven-yorgen", "npc:lars"}, true),
    Note("npc:elaine-carevin", "Elaine Carevin", "Person",
        "Elaine Carevin of Darkshire belongs to the Carevin household, hunters of demons, undead and other monstrosities. She passes on Calor's reports of shadows and lights in the abandoned buildings of Raven Hill, and she has noticed that an old man who lives in a shack above the Raven Hill cemetery no longer comes to town for supplies. She sends supplies to Sven Yorgen's camp and calls him a man doing the work of the Light.",
        {V .. " #163 Raven Hill; #164 Deliveries to Sven; #165 The Hermit; #1042 The Carevin Family"},
        nil, {"npc:jonathan-carevin", "place:darkshire", "npc:calor"}),
    Note("npc:milton-sheaf", "Milton Sheaf", "Person",
        "Milton Sheaf is the head librarian of the Royal Library in Stormwind Keep, and knows every shelf of it. He works to fill the library and to save what knowledge he can, sending helpers as far as the Ruins of Alterac, where the fallen kingdom's large collection lies among ogres. Loremaster Dibbs of Southshore remembers him as a bookworm.",
        {V .. " #343 Speaking of Fortitude; #538 Southshore; #542 Return to Milton", LF("npc:milton-sheaf", "Milton_Sheaf")},
        {"Milton"}, {"place:stormwind-keep", "npc:kristoff", "region:53746f726d77696e642043697479"}),
    Note("npc:nathanos-marris", "Nathanos Marris", "Person",
        "Nathanos Marris was the first and last of the human ranger lords, a disciple of Sylvanas Windrunner before she became the Banshee Queen. He was thought killed defending Lordaeron five years ago, though his body was never found. His family's farm is the Marris Stead in the Eastern Plaguelands.\n\nHe did not die. He is Nathanos Blightcaller, champion of the Banshee Queen and an agent of the Forsaken. The Stormwind agents who went to look into Forsaken activity in the Plaguelands were killed. Highlord Bolvar Fordragon remembers him as a tactical genius behind a decade of Alliance victories, and has ordered him destroyed.",
        {V .. " #6182 The First and the Last; #6183 Honor the Dead; #6186 The Blightcaller Cometh; #6187 Order Must Be Restored", LF("subzone:marris-stead", "Marris_Stead")},
        nil, {"place:marris-stead", "npc:nathanos", "faction:si7"}),
    Note("npc:tyrion", "Tyrion", "Person",
        "Tyrion is a gnome in Stormwind City and an old friend of Elling Trias. He works with a helper he calls Spybot, and keeps his gear in a silk bag a tailor friend made for him. He is short-tempered when startled and anxious not to be noticed by the guards of Stormwind Keep.\n\nFor weeks he has watched Lord Gregor Lescovar from the bushes of the castle grounds. Trias has never trusted Lescovar, and Tyrion had been following leads that tied him to the Twilight's Hammer before his dealings with the Defias came to light.",
        {V .. " #2745 Infiltrating the Castle; #2746 Items of Some Consequence; #434 The Attack!", LF("npc:tyrion", "Tyrion")},
        nil, {"npc:elling", "place:stormwind-keep", "npc:lescovar"}),
    Note("npc:lescovar", "Lord Gregor Lescovar", "Person",
        "Lord Gregor Lescovar is one of the nobles of Stormwind. Mathias Shaw, who has his thumb on most of the city's underhanded dealings, calls him a lord of shady reputation, even given the corruption of the city's nobility. The assassin known as Marzon works for him, and under the name Maelik has been visiting the imprisoned Defias lieutenant Bazil Thredd. As a well-connected noble, Lescovar is effectively above the law, so Shaw has turned to Elling Trias for a justice that is not legal. Tyrion, who watches him for Trias, had first followed leads tying him to the Twilight's Hammer.",
        {V .. " #393 Shadow of the Past; #350 Look to an Old Friend; #2746 Items of Some Consequence", "https://warcraft.wiki.gg/wiki/Gregor_Lescovar"},
        {"Gregor Lescovar", "Lord Lescovar", "Lescovar"}, {"group:stormwind-nobles", "npc:marzon", "npc:mathias-shaw"}),
    Note("npc:marzon", "Marzon", "Person",
        "Marzon is an assassin in Stormwind, and the name is surely not his true one. As Maelik he visited the imprisoned Defias lieutenant Bazil Thredd in the Stockade once or twice a week, with papers that checked out. Mathias Shaw recognized him from Warden Thelwater's description and knows a good deal about him. He works for Lord Gregor Lescovar.",
        {V .. " #392 The Curious Visitor; #393 Shadow of the Past; #350 Look to an Old Friend", "https://warcraft.wiki.gg/wiki/Marzon_the_Silent_Blade"},
        {"Maelik"}, {"npc:lescovar", "npc:bazil-thredd", "npc:mathias-shaw"}, true),
    Note("npc:karna-remtravel", "Karna Remtravel", "Person",
        "Karna Remtravel is a gnome inventor who studies the apes of Un'Goro Crater. To get closer to them she built a mechanical ape, A-Me 01, with scrying gems for eyes, and lost contact with it at Fungal Rock, the apes' lair, when one of their alpha males rushed up to greet it.",
        {V .. " #4243 Chasing A-Me 01; #4245 Chasing A-Me 01"},
        {"Karna"}, {"region:556e27476f726f20437261746572", "npc:remtravel"}),
    Note("npc:sully-balloo", "Sully Balloo", "Person",
        "Sully Balloo was a dwarf who died fighting for the Alliance. His body lies pinned beneath icy water, and a war-torn letter he wrote to his wife, Sara Balloo of Ironforge, begins with the words My dear Sara. King Magni Bronzebeard, who feels the loss of every dwarf who falls in the Alliance's name, has commissioned a memorial to him from the Grand Mason of Ironforge.",
        {V .. " #637 Sully Balloo's Letter; #686 A King's Tribute; #700 A King's Tribute"},
        {"Sully"}, {"npc:sara-balloo", "npc:magni", "region:49726f6e666f726765"}),
    Note("npc:grimand-elmore", "Grimand Elmore", "Person",
        "Grimand Elmore is a dwarven weaponsmith with a shop in Stormwind's Dwarven District. He is fiercely proud of his skills and says he taught the armorer Furen Longbeard everything he knows, though he will still look at Furen's notes. He makes weapons for distant customers such as Mountaineer Stormpike, and he is the smith who can work Lightforge Iron into a weapon against the necromancer Morbent Fel.",
        {V .. " #1700 Grimand Elmore; #1097 Elmore's Task; #353 Stormpike's Delivery; #322 Blessed Arm"},
        {"Grimand"}, {"place:dwarven-district", "npc:mountaineer-stormpike", "npc:morbent-fel"}),
    Note("npc:glorin-steelbrow", "Glorin Steelbrow", "Person",
        "Glorin Steelbrow is a dwarf in Menethil Harbor and a colleague of Bishop Farthing. He knows where the wrecks of the Third Fleet of Kul Tiras lie along the Wetlands coast, and with them the Lightforge Iron one of its ships carried. If the iron is found, he knows who can make it into a weapon.",
        {V .. " #270 The Doomed Fleet; #290 Lifting the Curse; #292 The Eye of Paleth", LF("npc:glorin-steelbrow", "Glorin_Steelbrow")},
        {"Glorin"}, {"place:menethil", "npc:bishop-farthing", "npc:grimand-elmore"}),
    Note("npc:verner-osgood", "Verner Osgood", "Person",
        "Verner Osgood is the blacksmith of Lakeshire in the Redridge Mountains. Keeping the Stormwind guards outfitted uses up so much of his iron that he cannot shoe the stable's horses, and he has to ask Blacksmith Argus in Goldshire for horseshoes. He thinks the Stormwind Army is too busy with the orcs to protect Redridge from local dangers such as the gnolls.",
        {V .. " #118 The Price of Shoes; #119 Return to Verner", LF("npc:verner-osgood", "Verner_Osgood")},
        {"Verner"}, {"place:lakeshire", "place:goldshire", "faction:redridge-gnolls"}),
    Note("npc:morganth", "Morganth", "Person",
        "Morganth is a warlock and mage of great power who lives in the Tower of Ilgalar in the Redridge Mountains, an enemy of Stormwind. He has bent the Shadowhide gnolls to his will. His rival Theocritus spies on him with the Eye of Azora and fears that Morganth is searching for the Scythe of Elune, which would let him turn his dark might on Redridge and the kingdom.",
        {V .. " #94 A Watchful Eye; #249 Morganth; #91 Solomon's Law"},
        nil, {"npc:theocritus", "faction:shadowhide", "region:5265647269646765204d6f756e7461696e73"}, true),
})

-- notes2 batch 3: Forever's own people the new packs name (Zephras Isle, the Westfall
-- poison chain, the Forsaken paladins, Silverpine and Alterac), and the Horde names
-- the first lane left. Forever quest text from part1_corpus.txt and Lore Forever's
-- quest entries; outcomes of the Forever chains stay out of the public notes, and
-- Lorthuna's later moves are discoveries (LoreDiscoveryData.lua, "lorthuna").
local P1 = "StorageInvestigation/journal-voice/part1_corpus.txt"
A.RegisterLoreNotes({
    ForeverPerson("npc:lorthuna", "High Priestess Lorthuna",
        "High Priestess Lorthuna leads the Al'Aketh, the cult of Al'Akir on Zephras Isle, from the Shrine of Akir. Her orders send cult thugs to harass travelers and press recruits into the faith. The cult's leaders at Falaath Village in the Shen'dar Highlands have been heard planning moves on Shen'dar Village and the western watchtower, and Valennia Stormfist of the peacekeepers has long prepared a strike at the shrine to stop her. Pursued there, she fled through a portal to the Rohashi Spires above it.",
        {P1 .. " #92528 Among the Faithful; #92640 Desperate Times; #92646 Confront Lorthuna", LF("quest:92544", "World_of_Warcraft:_Forever"), LF("quest:92646", "World_of_Warcraft:_Forever")},
        {"Lorthuna"}, {"group:al-aketh", "npc:valennia", "region:5a6570687261732049736c65"}),
    ForeverPerson("npc:valennia", "Valennia Stormfist",
        "Valennia Stormfist leads the peacekeepers of Zephras Isle from Valanaar, on the island's southeastern edge. The peacekeepers long avoided open conflict with the Al'Aketh cult, but its rapid growth has ended that. Few of her peacekeepers are left at Valanaar, and she has been preparing a plan to strike the cult at the Shrine of Akir, one that needs both the Windshapers and the High Order despite the tension between them.",
        {P1 .. " #92579 To Valanaar; #92640 Desperate Times", LF("quest:92579", "World_of_Warcraft:_Forever"), LF("quest:92640", "World_of_Warcraft:_Forever")},
        {"Valennia"}, {"place:valanaar", "npc:aonda", "group:al-aketh"}),
    ForeverPerson("npc:aonda", "Constable Aonda",
        "Constable Aonda is a peacekeeper of the Shen'dar Highlands on Zephras Isle, a highlander whom Valennia Stormfist calls crafty. She sends her reports on the cult to Valennia in Valanaar, and she has put a peacekeeper bounty on Vulgara the Insatiable, a winged vuldren that terrorizes the highlands.",
        {P1 .. " #92579 To Valanaar; #93318 WANTED: Vulgara the Insatiable", LF("quest:93318", "World_of_Warcraft:_Forever")},
        {"Aonda"}, {"place:shendar", "npc:valennia", "region:5a6570687261732049736c65"}),
    ForeverPerson("npc:illaya", "Illaya Amberwind",
        "Illaya Amberwind is the Windshaper elder resident in Shen'dar Village on Zephras Isle. Newcomers touched by the spirits are sent to her first, and she welcomes recruits to the Windshapers' work of keeping Zephras and the shen'dorei alive. Tension runs high between the Windshapers and the High Order, but in Shen'dar the two keep things civil.",
        {P1 .. " #92514 Welcome to Shen'dar Village", LF("quest:92595", "World_of_Warcraft:_Forever")},
        {"Illaya"}, {"place:shendar", "faction:windshapers", "faction:high-order"}),
    ForeverPerson("npc:hanaa", "Hanaa Nightwind",
        "Hanaa Nightwind is a shen'dorei near Thendal Grove on Zephras Isle. Al'Aketh thugs from the Shrine of Akir have camped at the temple ruins southwest of the grove, harassing travelers and forcing recruits into the cult, and she wants their hold broken and their commander killed. She believes Lorthuna sent them.",
        {LF("quest:92544", "World_of_Warcraft:_Forever"), "LoreHordeStories.lua #92544 (from the same entry)"},
        {"Hanaa"}, {"place:thendal", "group:al-aketh", "npc:lorthuna"}),
    ForeverPerson("npc:elegael", "Elegael Thornpaw",
        "Elegael Thornpaw is one of the few shen'dorei druids of Zephras Isle, whose enclave in Shadowgale Forest has gone silent since Ban'aethal fell into ruin. Wounded herself, she makes poultices of Lady's Tear, an antiseptic moss from the forest's trees, for the druids trapped in the Nightclaw Den, and her mate Jorel Windsinger is among them. She fears the Al'Aketh will overwhelm the wounded before help comes from Valanaar.",
        {P1 .. " #94485 Tears of the Lady; #94489 The Wounds of Betrayal", LF("quest:94484", "World_of_Warcraft:_Forever"), LF("quest:94493", "World_of_Warcraft:_Forever")},
        {"Elegael"}, {"group:al-aketh", "place:valanaar", "region:5a6570687261732049736c65"}),
    ForeverPerson("npc:aamelia", "Aamelia Windfield",
        "Aamelia Windfield keeps her family's stormapple orchard in the Gustberry Lowlands west of Valanaar on Zephras Isle. Her husband Alvarion has gone to Valanaar for help, because the bandits of Ferauu mean to take their share of the Windfield harvest and camp in the hills to the north.",
        {LF("quest:92679", "World_of_Warcraft:_Forever"), LF("quest:92685", "World_of_Warcraft:_Forever"), LF("quest:92703", "World_of_Warcraft:_Forever")},
        {"Aamelia"}, {"place:valanaar", "region:5a6570687261732049736c65"}),
    ForeverPerson("npc:lumina", "Lumina Windsinger",
        "Lumina Windsinger is a shen'dorei of the Windshapers, and she is quick to say she is no quel'dorei. She came to the Eastern Kingdoms as a guest of the Earthen Ring and was crossing Silverpine Forest with her companion Banon, bound for the Arathi Highlands to study elemental convergences, when gnolls caged her.",
        {P1 .. " #91862 Lumina Windsinger", LF("quest:95140", "World_of_Warcraft:_Forever")},
        {"Lumina"}, {"faction:windshapers", "faction:earthen-ring", "place:silverpine"}),
    ForeverPerson("npc:father-gavin", "Father Gavin",
        "Father Gavin is a priest of the Argent Dawn in the Alterac Mountains. He has fixed up an old building in the peaks at Misty Pine Refuge as a rest for travelers, where he offers the Light's healing and comfort, and he keeps the hearth fed for anyone who needs warmth.",
        {LF("quest:99158", "World_of_Warcraft:_Forever"), LF("quest:99159", "World_of_Warcraft:_Forever"), "LoreForeverStories.lua #99158 Dawn in the Mountains"},
        nil, {"faction:argent-dawn", "region:416c7465726163204d6f756e7461696e73"}),
    ForeverPerson("npc:aramis-hammerhand", "Aramis Hammerhand",
        "Aramis Hammerhand is a Forsaken paladin in the chapel of Deathknell who welcomes newly risen paladins. The Light still answers them, but it burns their dead flesh, and he teaches them to push through the pain like an atrophied muscle and to take it as proof that they still serve the Light. Some who rise cannot accept what they have become. He hopes to show Executor Arren that Light-wielders serve the Forsaken faithfully, warns that the calling invites suspicion under the Dark Lady's banner, and sends his students on to Shari Stilwell in Brill.",
        {P1 .. " #90902 Rediscovering the Light; #91208 Coming to Terms", LF("npc:aramis-hammerhand", "World_of_Warcraft:_Forever"), LF("quest:98389", "World_of_Warcraft:_Forever")},
        {"Aramis"}, {"place:deathknell", "npc:shari-stilwell", "npc:arren"}),
    ForeverPerson("npc:shari-stilwell", "Shari Stilwell",
        "Shari Stilwell oversees the training of Forsaken paladins in Brill, those who follow the Light in undeath despite the pain it brings them. Paladins risen at Deathknell come to her from Aramis Hammerhand. Bareth Dawnstone of Bandarion Keep, a young monastic order of the Light on the bluffs northwest of the Solliden Farmstead, was sent to her with a message when zealots seized him on the road.",
        {P1 .. " #99144 Seeking Refuge", LF("npc:shari-stilwell", "World_of_Warcraft:_Forever"), LF("quest:91209", "World_of_Warcraft:_Forever")},
        {"Shari"}, {"place:brill", "npc:aramis-hammerhand", "place:bandarion"}),
    ForeverPerson("npc:alba-fairmoon", "Alba Fairmoon",
        "Alba Fairmoon is an elf who has come to Westfall to learn what is poisoning its land. She begins with the groundwater under the farms, testing the wells of the Jansen Stead and the Molsen Farm, and fears the taint could reach the sea and bring famine to Stormwind.",
        {P1 .. " #92742 Testing the Wells", LF("quest:92742", "World_of_Warcraft:_Forever"), "LoreForeverStories.lua #92744 Murloc Gills"},
        {"Alba"}, {"region:5765737466616c6c", "place:sentinel-hill"}),
    Note("npc:sprite-jumpsprocket", "Sprite Jumpsprocket", "Person",
        "Sprite Jumpsprocket is a gnome engineer in the Dwarven District of Stormwind, one of the gnomes who carried their craft there after Gnomeregan fell. In Forever she builds explosives for those who ask, greeting them with the question of what needs blowing up, and for parts she does not keep, such as a remote detonator, she sends to Stormwind Intelligence in Old Town.",
        {P1 .. " #92748 Explosive Consultation; #92750 Detonation at a Distance", LF("npc:sprite-jumpsprocket", "Sprite_Jumpsprocket")},
        {"Sprite"}, {"place:dwarven-district", "npc:jasper-fel", "event:fall-gnomeregan"}),
    Note("npc:jasper-fel", "Jasper Fel", "Person",
        "Jasper Fel serves Stormwind Intelligence at its headquarters in Old Town, supplying its agents with daggers and vials for poisons and warning visitors to mind their speech. In Forever he hands out a prototype remote detonator made by the service's own engineers, which keeps an explosion in the caves below Westfall at a safe distance.",
        {P1 .. " #92751 Detonation at a Distance", LF("npc:jasper-fel", "Jasper_Fel")},
        nil, {"faction:si7", "place:old-town", "npc:sprite-jumpsprocket"}),
    Note("npc:brewmaster-drohn", "Brewmaster Drohn", "Person",
        "Brewmaster Drohn is an orc who brews on the hill above Ratchet. His mentor learned the recipe for stormstout from the pandaren Chen Stormstout, who traveled with Rexxar long ago, and Drohn makes it still, from savannah lion tusks, plainstrider kidneys and thunder lizard horn. He recognizes Chen's empty kegs when travelers bring them to him, and remembers the trogg brew he once made.",
        {V .. " #819 Chen's Empty Keg; #821 Chen's Empty Keg; #822 Chen's Empty Keg", LF("npc:brewmaster-drohn", "Brewmaster_Drohn")},
        {"Drohn"}, {"npc:chen", "place:ratchet", "npc:rexxar"}),
    Note("npc:maur-raincaller", "Maur Raincaller", "Person",
        "Maur Raincaller is a tauren of Bloodhoof Village. His grandfather told him of battles with a strider named Mazzranache, a beast of red eyes, sharp talons and venomous bite, and when Maur met it on the plains it bit him deeply in the shoulder. Feverish from the infection, he needs a wolf heart, a cougar femur, a plainstrider scale and a swoop gizzard to make a remedy.",
        {V .. " #766 Mazzranache", LF("npc:maur-raincaller", "Maur_Raincaller")},
        nil, {"place:bloodhoof", "region:4d756c676f7265"}),
    Note("npc:thurman-agamand", "Thurman Agamand", "Person",
        "Thurman Agamand was the elder son of Gregor Agamand, tall and gentle in life. Yvette Farthing loved him and begged him to leave the Agamand Mills with her when the plague came, but he stayed with his family. He now roams the mills with the rest of the Agamands as a servant of the Scourge.",
        {V .. " #361 A Letter Undelivered; #362 The Haunted Mills", LF("item:thurman-s-remains", "Agamand_Mills")},
        nil, {"group:agamand-family", "npc:yvette-farthing", "place:agamand-mills"}),
    Note("npc:devlin-agamand", "Devlin Agamand", "Person",
        "Devlin Agamand was the younger son of Gregor Agamand, weak and sharp-tongued in life, and quick to fall when the plague took the Agamand Mills. His mad chattering can still be heard near the road leading to the mills.",
        {V .. " #362 The Haunted Mills", LF("item:devlin-s-remains", "Agamand_Mills")},
        nil, {"group:agamand-family", "npc:thurman-agamand", "place:agamand-mills"}),
})

-- notes2 batch 4: the 40-60 world prose (world lane request): the silithid
-- investigators of Tanaris and Feralas, the Stonemaul ogres, Winterspring's Kel'Theril,
-- the Plaguelands, Arathi and Azshara. Raschal's rescue is a discovery
-- (LoreDiscoveryData.lua, "raschal"); his public note leaves him missing.
A.RegisterLoreNotes({
    Note("npc:pestlezugg", "Alchemist Pestlezugg", "Person",
        "Alchemist Pestlezugg is a goblin of Gadgetzan who examines the strange insects of Tanaris for the Gadgetzan Water Company. The Centipaar parts brought to him from the Noxious Lair were unlike any insect he had seen, as if the creatures were being controlled by an outside force and changed into pure ravagers. He judged the finding serious enough to share with anyone who can read. Scholars on both sides who study the silithid send their theories to him.",
        {V .. " #82 Noxious Lair Investigation; #110 Insect Part Analysis; #113 Insect Part Analysis; #4493 March of the Silithid"},
        {"Pestlezugg"}, {"place:gadgetzan", "group:silithid", "npc:fizzledowser"}),
    Note("npc:fizzledowser", "Senior Surveyor Fizzledowser", "Person",
        "Senior Surveyor Fizzledowser runs surveys in Tanaris for the Gadgetzan Water Company. Insects have been draining the pools where the Noxious Lair now lies, and he sends his junior surveyors to gather their parts for Alchemist Pestlezugg. He mourns the surveyor Scrimshank, lost to the bugs in the Gaping Chasm. Though the company does not usually give its information away, he has the silithid report copied for anyone who will carry a warning to the Horde or the Alliance.",
        {V .. " #82 Noxious Lair Investigation; #110 Insect Part Analysis; #113 Insect Part Analysis; #32 Rise of the Silithid", LF("npc:senior-surveyor-fizzledowser", "Senior_Surveyor_Fizzledowser")},
        {"Fizzledowser"}, {"group:gadgetzan-water-company", "npc:pestlezugg", "group:silithid"}),
    Note("npc:zilzibin", "Zilzibin Drumlore", "Person",
        "Zilzibin Drumlore is a troll scholar who lives on the upper tier of the Drag in Orgrimmar. He studies the life forms unique to Azeroth and is a historian as well. He identifies the Zukk'ash as silithid and believes their strength comes from deeper in Kalimdor, perhaps from Un'Goro Crater. He has friends high in the Horde, and is furious that its leaders, blinded by hatred of the Alliance, will not see the greater threat.",
        {V .. " #32 Rise of the Silithid; #4494 March of the Silithid; #4509 Calm Before the Storm; #7732 Zukk'ash Report"},
        {"Zilzibin"}, {"place:drag", "group:silithid", "npc:pestlezugg"}),
    Note("npc:gracina", "Gracina Spiritmight", "Person",
        "Gracina Spiritmight is a night elf priestess and scholar in the Temple of the Moon in Darnassus, learned in the life forms of Azeroth and in history. Her people know the silithid of old. She holds that they exist to devour everything that is not of their own kind, that what has been seen so far is only the first stage, and that their strength comes from deeper in Kalimdor.",
        {V .. " #162 Rise of the Silithid; #4267 Rise of the Silithid; #4493 March of the Silithid"},
        {"Gracina"}, {"place:temple-of-the-moon", "group:silithid", "npc:pestlezugg"}),
    Note("npc:raschal", "Raschal", "Person",
        "Raschal is a courier of Feathermoon Stronghold who has served there since General Feathermoon led the expedition to Feralas, and he knows the land well. He set out for Thalanaar meaning to row down the coast and cross southern Feralas away from the Horde camp, and went missing. His boat was found wrecked, with his knife in the mud beside it.\n\nInvestigating insect creatures in the Writhing Deep, south of the Woodpaw gnoll camps, he was overwhelmed and sealed alive in a pod. Freed, he wrote the report on the infestation of southeastern Feralas that General Feathermoon has sent to Darnassus.",
        {V .. " #4125 The Missing Courier; #4127 Boat Wreckage; #4135 The Writhing Deep; #4265 Freed from the Hive; #4267 Rise of the Silithid"},
        nil, {"place:feathermoon", "npc:ginro", "group:silithid"}, true),
    Note("npc:ginro", "Ginro Hearthkindle", "Person",
        "Ginro Hearthkindle of Feathermoon Stronghold searches the wilds of Feralas every day for the missing courier Raschal, and comes back with nothing but gnoll teeth. He calls it a lost cause but will take any help offered. He plays cards with the druid Quintis Jonespyre, who owes him money.",
        {V .. " #4124 The Missing Courier; #4129 The Knife Revealed; #4130 Psychometric Reading"},
        {"Ginro"}, {"place:feathermoon", "npc:raschal", "npc:quintis"}),
    Note("npc:draz-zilb", "Draz'Zilb", "Person",
        "Draz'Zilb is an ogre of the Stonemaul clan in Dustwallow Marsh who speaks with unexpected polish and dislikes being taken for a ruffian. While Overlord Mok'Morokk wallows in power and Tharg grieves, he is the one trying to learn which dragon drove the clan out of its old home. He wants Onyxia's eggs in the Wyrmbog destroyed, because the Stonemaul can never reclaim their village while the bog breeds whelps, and he thinks Mok'Morokk unfit to lead.",
        {V .. " #1169 Identifying the Brood; #1171 The Brood of Onyxia; #1172 The Brood of Onyxia"},
        nil, {"faction:stonemaul", "npc:mokmorokk", "place:wyrmbog"}, true),
    Note("npc:tharg", "Tharg", "Person",
        "Tharg is an ogre of the Stonemaul clan. Black dragons killed many ogres and his wife, and when Overlord Mok'Morokk told the clan to run he obeyed, though he believes ogres should fight. He wants revenge on the black dragon army and wants to go home to the Stonemaul Ruins in the south. Draz'Zilb thinks he would make a fine leader, were it not for his injuries and age.",
        {V .. " #1168 Army of the Black Dragon; #1169 Identifying the Brood; #1172 The Brood of Onyxia"},
        nil, {"faction:stonemaul", "npc:mokmorokk", "npc:draz-zilb"}, true),
    Note("npc:smokey-larue", "Smokey LaRue", "Person",
        "Smokey LaRue is a demolitions man in the Eastern Plaguelands who calls himself ol' Smokey. The Argent Dawn has commissioned him to blow up Scourge buildings in Plaguewood, and his services go to whoever slaps gold on the table. He also loves a good stogie, and mourns the famous tobacco of Fras Siabi, who meant to burn every leaf rather than leave his stock behind when his town was sacked.",
        {V .. " #5214 The Great Fras Siabi; #6026 That's Asking A Lot; #6041 When Smokey Sings, I Get Violent"},
        {"Smokey"}, {"faction:argent-dawn", "place:plaguewood", "region:4561737465726e20506c616775656c616e6473"}),
    Note("npc:aurora-skycaller", "Aurora Skycaller", "Person",
        "Aurora Skycaller is a high elf who lives near the Northpass Tower in the northern Eastern Plaguelands. She does not like to speak of the past of the high elves, and grieves that her race, like a shattered crystal, may never be whole again. She knows the Crystal of Zin-Malor, the relic whose theft cursed the highborne of Kel'Theril, and the sacred writings about it kept in the Temple of Zin-Malor in Azshara.",
        {V .. " #5245 Troubled Spirits of Kel'Theril; #5246 Fragments of the Past; #5248 Tormented By the Past"},
        {"Aurora"}, {"artifact:crystal-zin-malor", "place:kel-theril", "faction:highborne"}),
    {id = "artifact:crystal-zin-malor", title = "Crystal of Zin-Malor", kind = "Artifact", setting = "Classic / Forever",
        body = "The Crystal of Zin-Malor is an ancient artifact able to contain and control strong arcane forces. Highborne stole it, meaning to siphon its power for themselves at Kel'Theril in Winterspring, and it shattered in a great explosion that drove its pieces under the ice of the lake. The spirits of those highborne are bound there still, searching for the fragments. Aurora Skycaller holds that it could have been used for good.",
        sources = {V .. " #5244 The Ruins of Kel'Theril; #5245 Troubled Spirits of Kel'Theril; #5246 Fragments of the Past"},
        names = {"the Crystal of Zin-Malor"}, related = {"place:kel-theril", "npc:aurora-skycaller", "region:417a7368617261"}},
    Note("npc:kim-jael", "Kim'jael", "Person",
        "Kim'jael is a goblin in Azshara who took work scouting for treasure with a band of blood elves, until they turned on him and kept his equipment. He says his name means little rat in their tongue, warns that no blood elf can be trusted, and pays those who recover his gear, though he likes to haggle over what was agreed.",
        {V .. " #3601 Kim'jael Indeed!; #5534 Kim'jael's \"Missing\" Equipment"},
        nil, {"region:417a7368617261"}, true),
    Note("npc:lar-korwi", "Lar'korwi", "Creature",
        "Lar'korwi is a great beast that hunts in Un'Goro Crater. When one of Torwa Pathfinder's brothers took meat from one of its kills, Lar'korwi followed him for days, destroying everything he touched, and killed him as he fled the crater. Torwa holds that the only way to provoke it is to take meat from a fresh kill.",
        {V .. " #4290 The Fare of Lar'korwi; #4289 The Apes of Un'Goro"},
        nil, {"npc:torwa", "region:556e27476f726f20437261746572"}, true),
    Note("npc:trelane", "Archmage Trelane", "Person",
        "Archmage Trelane fled Stromgarde in the Arathi Highlands when the city fell under siege, after trying and failing to hold the Tower of Arathor. He left items behind there, and his former apprentice Archmage Malin has sent agents to recover them. One of them, a wand, has fallen to the ogre Kor'gresh in Boulderfist Hall.",
        {V .. " #690 Malin's Request; #693 Wand over Fist; #695 An Apprentice's Enchantment"},
        {"Trelane"}, {"npc:archmage-malin", "place:stromgarde", "faction:boulderfist"}),
    Note("npc:skuerto", "Skuerto", "Person",
        "Skuerto is one of the agents Archmage Malin sent to the Arathi Highlands to recover the items Archmage Trelane left in Stromgarde. He works from the camp near Refuge Pointe and traces where each item has ended up.",
        {V .. " #691 Worth Its Weight in Gold; #693 Wand over Fist; #695 An Apprentice's Enchantment", LF("npc:skuerto", "Skuerto")},
        nil, {"npc:trelane", "npc:archmage-malin", "region:41726174686920486967686c616e6473"}, true),
    Note("npc:loramus", "Loramus Thalipedes", "Person",
        "Loramus Thalipedes is a demon hunter who lives among the islands off Azshara. Those who would battle demons are sent to him, and he insists they listen to his account first without interrupting. He knows how to strike at the servants of the demon Razelikh in the Blasted Lands.",
        {V .. " #2744 The Demon Hunter; #3141 Loramus", LF("npc:loramus-thalipedes", "Loramus_Thalipedes")},
        {"Loramus"}, {"region:417a7368617261", "region:426c6173746564204c616e6473"}),
    Note("npc:brother-paxton", "Brother Paxton", "Person",
        "Brother Paxton keeps the small library of Northshire Abbey. Months ago he borrowed The Stresses of Iron from the Royal Library of Stormwind to copy it for his own shelves, and is a little embarrassed that he still has it. Kobolds keep stealing his books, apparently to eat them.",
        {V .. " #344 Brother Paxton; #91741 Nibbled-On Book (Forever)"},
        {"Paxton"}, {"place:northshire-abbey", "npc:milton-sheaf", "npc:kristoff"}),
    Note("npc:vimes", "Captain Garran Vimes", "Person",
        "Captain Garran Vimes commands the guard at Theramore from the barracks on the northeastern side of the isle. He reads orcish better than most, so reports taken from Horde spies go to him. He also knows the sad history of Smiling Jim, the innkeeper whose inn in the marsh was lost to the ogres when Theramore lost control of the roads.",
        {V .. " #1220 Captain Vimes; #1282 They Call Him Smiling Jim"},
        {"Garran Vimes", "Captain Vimes", "Vimes"}, {"place:theramore", "faction:theramore-guard", "region:4475737477616c6c6f77204d61727368"}),
})

-- notes2 batch 5: Dun Morogh and Ironforge, the thinnest starting coverage the first
-- lane reported. Coldridge, Kharanos, Brewnall and the halls of Ironforge.
A.RegisterLoreNotes({
    Note("npc:grelin-whitebeard", "Grelin Whitebeard", "Person",
        "Grelin Whitebeard is a dwarf sent with his brother Senir to look into the threat of the Frostmane trolls in Dun Morogh, while the Senate of Ironforge has its hands full with the troggs. Camped in Coldridge Valley, he judges that the trolls there are poorly placed and that a few strong arms will do instead of the army. He has authority to pay for help in the King's name, and uses it more freely than his brother advises. Trolls stole his notebook in the night, and he blames a good-for-nothing apprentice.",
        {V .. " #182 The Troll Cave; #218 The Stolen Journal; #282 Senir's Observations; #420 Senir's Observations", LF("npc:grelin-whitebeard", "Grelin_Whitebeard")},
        {"Grelin"}, {"npc:senir-whitebeard", "place:coldridge", "faction:frostmane"}),
    Note("npc:senir-whitebeard", "Senir Whitebeard", "Person",
        "Senir Whitebeard is Grelin Whitebeard's brother, sent to Kharanos to study the Frostmane trolls of Dun Morogh. He found their hold southwest of Brewnall Village but saw so many that he would not go in, and his reports to the Senate of Ironforge run late in the cold. He would rather nobody mentioned who helped him with them. He thinks a few feathers in the Senate needed ruffling.",
        {V .. " #420 Senir's Observations; #287 Frostmane Hold; #291 The Reports", LF("npc:senir-whitebeard", "Senir_Whitebeard")},
        {"Senir"}, {"npc:grelin-whitebeard", "place:kharanos", "place:frostmane-hold"}),
    Note("npc:redstone", "Senator Barin Redstone", "Person",
        "Senator Barin Redstone sits in the Senate of Ironforge and keeps his chamber where King Magni holds court. He is a sour man with little patience for petitioners. When he learned that Grelin Whitebeard had acted on the King's authority, he was outraged at Magni and promised that the Senate would not be pleased.",
        {V .. " #291 The Reports"},
        {"Barin Redstone", "Redstone"}, {"group:ironforge-senate", "npc:magni", "region:49726f6e666f726765"}),
    {id = "group:ironforge-senate", title = "Senate of Ironforge", kind = "Group", setting = "Classic / Forever",
        body = "The Senate of Ironforge is the body of dwarven senators who sit with King Magni Bronzebeard's court. It sends investigators across Dun Morogh, and its hands are full with the troggs. Some of its members, such as Senator Barin Redstone, resent the King acting on his own authority, and the brothers Grelin and Senir Whitebeard know that using the King's name ruffles feathers there.",
        sources = {V .. " #182 The Troll Cave; #291 The Reports; #420 Senir's Observations"},
        names = {"the Senate", "the Senate of Ironforge", "Ironforge Senate"}, related = {"npc:magni", "npc:redstone", "region:49726f6e666f726765"}},
    Note("npc:talin-keeneye", "Talin Keeneye", "Person",
        "Talin Keeneye is a dwarf hunter camped beside the frozen lake to the west of Coldridge Valley, where letters from the pass are brought to him. Boars have grown so numerous there that even his daily hunt has become dangerous.",
        {V .. " #233 Coldridge Valley Mail Delivery; #183 The Boar Hunter"},
        {"Talin"}, {"place:coldridge", "region:44756e204d6f726f6768"}),
    Note("npc:belia-thundergranite", "Belia Thundergranite", "Person",
        "Belia Thundergranite is one of the most respected animal trainers of the Hall of Arms in Ironforge, and a friendly sort. Hunters who have learned to tame a beast are sent to her to learn to train and care for it.",
        {V .. " #6086 Training the Beast"},
        {"Belia"}, {"region:49726f6e666f726765"}),
    Note("npc:maxan-anvol", "Maxan Anvol", "Person",
        "Maxan Anvol teaches young priests in Kharanos. Branstock sends them to him to learn more of the path of the Light and, if they prove worthy, to receive their first robes. He will set aside a formal test when a wounded mountaineer outside town needs healing.",
        {V .. " #5626 In Favor of the Light; #5625 Garments of the Light", LF("npc:maxan-anvol", "Maxan_Anvol")},
        {"Maxan"}, {"place:kharanos", "belief:holy-light"}),
    Note("npc:bellowfiz", "Pilot Bellowfiz", "Person",
        "Pilot Bellowfiz is a siege engine pilot of Dun Morogh, and Jetsteam is his machine. He likes Rejold Barleybrew's Evershine to keep him warm on the cold road, and throws it into Jetsteam's furnace for a burst of power when he is in a tight spot.",
        {V .. " #318 Evershine; #320 Return to Bellowfiz", LF("npc:pilot-bellowfiz", "Pilot_Bellowfiz")},
        {"Pilot Bellowfiz", "Bellowfiz"}, {"npc:rejold-barleybrew", "place:steelgrills-depot", "region:44756e204d6f726f6768"}),
    Note("npc:rejold-barleybrew", "Rejold Barleybrew", "Person",
        "Rejold Barleybrew lives at Brewnall Village, west of Kharanos, and experiments with his brews. Some taste good, some bad, and some will lay all but the stoutest dwarf flat. His Evershine burns hot enough to fuel a steam tank.",
        {V .. " #318 Evershine; #320 Return to Bellowfiz", LF("npc:rejold-barleybrew", "Rejold_Barleybrew")},
        {"Rejold"}, {"place:brewnall", "npc:bellowfiz", "place:kharanos"}),
    Note("npc:beldin-steelgrill", "Beldin Steelgrill", "Person",
        "Beldin Steelgrill owns Steelgrill's Depot, the mechanic shop northeast of Kharanos and a haunt of veteran siege engine pilots. He is the best siege engine mechanic there is, and so hard on his tools that he nearly breaks arclight spanners faster than they can be supplied.",
        {V .. " #400 Tools for Steelgrill", LF("npc:beldin-steelgrill", "Beldin_Steelgrill")},
        {"Beldin"}, {"place:steelgrills-depot", "place:kharanos", "npc:bellowfiz"}),
    Note("npc:mountaineer-thalos", "Mountaineer Thalos", "Person",
        "Mountaineer Thalos guards the tunnel that leads from Coldridge Valley to Kharanos. The tunnel is overrun with hostile troggs that attack travelers, and he warns those passing through.",
        {V .. " #282 Senir's Observations; #420 Senir's Observations", LF("npc:mountaineer-thalos", "Mountaineer_Thalos")},
        nil, {"place:coldridge", "place:kharanos", "place:anvilmar"}),
    Note("npc:macgrann", "Tundra MacGrann", "Person",
        "Tundra MacGrann is a dwarf hunter of Dun Morogh. He kept a month's worth of salted meat in a thorium locker for the cold season, but while he was out hunting deer the beast Old Icebeard made off with it to his cave, and without it he will starve.",
        {V .. " #312 Tundra MacGrann's Stolen Stash", LF("item:macgrann-s-dried-meats", "Tundra_MacGrann")},
        {"MacGrann"}, {"region:44756e204d6f726f6768"}),
    Note("npc:golnir-bouldertoe", "Golnir Bouldertoe", "Person",
        "Golnir Bouldertoe works in the Deep Mountain Mining Guild in the Great Forge District of Ironforge. He keeps honorary picks ready for the best mining students of Brock Stoneseeker in Thelsamar.",
        {V .. " #6387 Honor Students; #6391 Ride to Ironforge", LF("npc:golnir-bouldertoe", "Golnir_Bouldertoe")},
        {"Golnir"}, {"place:great-forge", "npc:brock-stoneseeker", "region:49726f6e666f726765"}),
    Note("npc:brock-stoneseeker", "Brock Stoneseeker", "Person",
        "Brock Stoneseeker teaches mining in Thelsamar in Loch Modan, where many young dwarves come to learn the trade. Those who score highest in his lessons earn an honorary pick, and he sends their names to Golnir Bouldertoe in Ironforge.",
        {V .. " #6387 Honor Students; #6391 Ride to Ironforge", LF("npc:brock-stoneseeker", "Brock_Stoneseeker")},
        {"Brock"}, {"place:thelsamar", "npc:golnir-bouldertoe", "region:4c6f6368204d6f64616e"}),
    Note("npc:rohan", "High Priest Rohan", "Person",
        "High Priest Rohan teaches in the Hall of Mysteries in Ironforge, where promising priests are called back for further training. Paladins seeking a charger come to him for his exorcism censer, and he asks a donation for it that also feeds the needy of the city.",
        {V .. " #5634 Desperate Prayer; #5635 Desperate Prayer; #7637 Emphasis on Sacrifice", LF("npc:high-priest-rohan", "High_Priest_Rohan")},
        {"Rohan"}, {"region:49726f6e666f726765", "npc:grayson", "belief:holy-light"}),
    Note("npc:nori-pridedrift", "Nori Pridedrift", "Person",
        "Nori Pridedrift carries scalding mornbrew around Coldridge Valley, to Grelin Whitebeard's camp and to Durnan Furcutter in Anvilmar, and minds the mugs, since many couriers forget to bring them back.",
        {V .. " #3364 Scalding Mornbrew Delivery; #3365 Bring Back the Mug", LF("npc:nori-pridedrift", "Nori_Pridedrift")},
        {"Nori"}, {"place:coldridge", "place:anvilmar", "npc:grelin-whitebeard"}),
})

-- notes2 batch 6: Thunder Bluff and Bloodhoof people the Horde prose names.
A.RegisterLoreNotes({
    Note("npc:magatha", "Magatha Grimtotem", "Person",
        "Magatha Grimtotem is the matriarch of the Grimtotem tribe and lives on Elder Rise in Thunder Bluff. She is very old and a powerful shaman, and those seeking the spiritual aid of the tauren elders are sent to her. Though she has little regard for other races, she works with the Forsaken emissary Apothecary Zamah, and her enchantments can light the sacred fire of life that summons the vengeful Arikara.",
        {V .. " #1063 The Elder Crone; #1064 Forsaken Aid; #5062 Sacred Fire", LF("npc:magatha-grimtotem", "Magatha_Grimtotem")},
        {"Magatha"}, {"place:elder-rise", "faction:grimtotem", "npc:zamah"}),
    Note("npc:turak-runetotem", "Turak Runetotem", "Person",
        "Turak Runetotem trains young druids in Thunder Bluff and is one of the assistants of Arch Druid Hamuul Runetotem. He is known as wise and patient, and teaches the aquatic form and the cure for poison to those who have done their trials.",
        {V .. " #5926 Heeding the Call; #31 Aquatic Form; #6130 Power over Poison", LF("npc:turak-runetotem", "Turak_Runetotem")},
        {"Turak"}, {"npc:hamuul", "faction:cenarion-circle", "region:5468756e64657220426c756666"}),
    Note("npc:holt-thunderhorn", "Holt Thunderhorn", "Person",
        "Holt Thunderhorn is one of the most revered hunters of Thunder Bluff. He has bested the most feared beasts of Azeroth and commands many strong creatures of his own, and young hunters who have learned to tame a beast come to him to learn to train it.",
        {V .. " #6089 Training the Beast", LF("npc:holt-thunderhorn", "Holt_Thunderhorn")},
        {"Holt"}, {"place:hunter-rise", "region:5468756e64657220426c756666"}),
    Note("npc:ruul-eagletalon", "Ruul Eagletalon", "Person",
        "Ruul Eagletalon is a warrior and teacher at Bloodhoof Village. Young tauren who must prepare for their trials before going far from Mulgore come to him, and he sends them first against the Windfury harpies on the mountain edges to the southeast.",
        {V .. " #743 Dangers of the Windfury", LF("npc:ruul-eagletalon", "Ruul_Eagletalon")},
        nil, {"place:bloodhoof", "region:4d756c676f7265"}),
    Note("npc:harken-windtotem", "Harken Windtotem", "Person",
        "Harken Windtotem guides young hunters at Bloodhoof Village. He holds that a collection of swoop quills is a badge of cleverness and determination, because the swoop is a cunning bird and hard to find on the plains of Mulgore.",
        {V .. " #761 Swoop Hunting", LF("npc:harken-windtotem", "Harken_Windtotem")},
        {"Harken"}, {"place:bloodhoof", "region:4d756c676f7265"}),
    Note("npc:bena-winterhoof", "Bena Winterhoof", "Person",
        "Bena Winterhoof is the alchemy trainer of Thunder Bluff. Those who serve the elders well may be sent to her with a voucher for potions and a special reward.",
        {V .. " #2440 The Platinum Discs"},
        {"Bena"}, {"region:5468756e64657220426c756666"}),
})

-- notes2 batch 7: Hillsbrad, Alterac, Arathi and Desolace names the 30-40 prose uses
-- most often without a note, measured after batches 1-6.
A.RegisterLoreNotes({
    Note("npc:mug-thol", "Mug'Thol", "Person",
        "Mug'Thol is the ogre who leads the Crushridge in the ruins of Alterac. He and his warband were sent to recover the Crown of Will for Lady Sylvanas, but he put the crown on instead, and it lets him resist the possession that bound him to her service. The Dark Lady wants an example made of him, and her agents in Tarren Mill mean to thin his ogres first.",
        {V .. " #495 The Crown of Will; #518 The Crown of Will"},
        nil, {"faction:crushridge", "place:ruins-alterac", "artifact:crown-of-will"}, true),
    {id = "artifact:crown-of-will", title = "Crown of Will", kind = "Artifact", setting = "Classic / Forever",
        body = "The Crown of Will is a crown from the ruins of Alterac that lets its wearer resist possession. The ogre Mug'Thol was sent to fetch it for Lady Sylvanas, put it on himself, and so threw off her hold on him.",
        sources = {V .. " #495 The Crown of Will"},
        names = {"the Crown of Will"}, related = {"npc:mug-thol", "place:ruins-alterac", "npc:sylvanas"}},
    Note("npc:melisara", "Melisara", "Person",
        "Melisara is a Forsaken in Tarren Mill and the lieutenant of Sharlindra in the Undercity. She wastes little time on idle chatter, and she has charge of the Dark Lady's punishment of the ogre Mug'Thol.",
        {V .. " #495 The Crown of Will; #518 The Crown of Will"},
        nil, {"place:tarren-mill", "npc:mug-thol", "npc:sylvanas"}, true),
    Note("npc:phin-odelic", "Phin Odelic", "Person",
        "Phin Odelic leads a band of adventurers at Refuge Pointe who look into strange happenings in the area. His cousin in Hillsbrad had to put down his dog, Stanley, after it grew to an immense size and attacked anyone who came near, and Phin believes the undead are behind it. His companions say he has done much for them since the plague.",
        {V .. " #659 Hints of a New Plague?; #657 Hints of a New Plague?"},
        {"Phin"}, {"npc:quae", "npc:kinelory", "place:refuge-pointe"}),
    Note("npc:quae", "Quae", "Person",
        "Quae is one of Phin Odelic's companions. With Kinelory she went to watch the Go'Shek Farm in the Arathi Highlands, where orcs work for the Forsaken, and found that Apothecary Jorell is running deadly experiments there. She would destroy every Forsaken herself if it brought Phin peace.",
        {V .. " #659 Hints of a New Plague?; #657 Hints of a New Plague?"},
        nil, {"npc:phin-odelic", "npc:kinelory", "place:goshek"}, true),
    Note("npc:kinelory", "Kinelory", "Person",
        "Kinelory is one of Phin Odelic's companions, sent with Quae to watch the Go'Shek Farm in the Arathi Highlands. She means to go down to the farm and steal whatever research of Apothecary Jorell's has not yet been sent to Tarren Mill.",
        {V .. " #659 Hints of a New Plague?; #657 Hints of a New Plague?"},
        nil, {"npc:phin-odelic", "npc:quae", "place:goshek"}, true),
    Note("npc:karnitol", "Karnitol", "Person",
        "Karnitol is a mage and a noble of Stormwind. When sea giants attacked his ship off the northwest coast of Desolace, he and his servants tried to bring his most valuable chest ashore, then abandoned it and teleported to safety. He has hired Kreldig Ungor of the Reclaimers to recover it, and Kreldig warns that he is impatient.",
        {V .. " #1454 The Karnitol Shipwreck", "LoreAllianceStories.lua #1457 (Kreldig's warning)"},
        nil, {"npc:kreldig-ungor", "region:4465736f6c616365", "region:53746f726d77696e642043697479"}, true),
    Note("npc:maurin", "Maurin Bonesplitter", "Person",
        "Maurin Bonesplitter is a Horde agent at Ghost Walker Post in Desolace, sent by Keldran because he knows the Burning Blade and their warlock ways. He runs the Horde's plots against the cult there on behalf of the Warchief, and he can read the old demonic writing the cult uses.",
        {V .. " #1433 Alliance Relations; #1480 The Corrupter"},
        {"Maurin"}, {"place:ghost-walker", "faction:burning-blade", "region:4465736f6c616365"}),
    Note("npc:helcular", "Helcular", "Person",
        "Helcular was a wizard of the Hillsbrad Foothills who was nearly transformed into a lich when a mob from Southshore found his ritual lair in the hills and killed him. They buried him in the Southshore cemetery. His apprentice wants revenge on the town, and means to use Helcular's Rod, charged at the three ceremonial pyres the wizard made in the caves of the foothills.",
        {V .. " #552 Helcular's Revenge; #553 Helcular's Revenge"},
        nil, {"place:southshore", "region:48696c6c736272616420466f6f7468696c6c73"}, true),
    Note("npc:farren-orinelle", "Lieutenant Farren Orinelle", "Person",
        "Lieutenant Farren Orinelle was moved from the Stormwind city guard to Southshore, and dislikes the smell of the harbor. Marshal Redpath has him clear murlocs from the coast, and Farren cannot stand touching their heads.",
        {V .. " #559 Farren's Proof; #560 Farren's Proof"},
        {"Farren Orinelle", "Farren"}, {"place:southshore", "region:48696c6c736272616420466f6f7468696c6c73"}),
    Note("npc:lydon", "Apothecary Lydon", "Person",
        "Apothecary Lydon works for the Royal Apothecary Society in Tarren Mill. Under pressure from the Dark Lady to develop a New Plague, the Society's apothecaries share their findings with one another, and Lydon receives reports from as far as the Sepulcher in Silverpine.",
        {V .. " #493 Journey to Hillsbrad Foothills; #513 Elixir of Agony"},
        {"Lydon"}, {"place:tarren-mill", "faction:royal-apothecaries", "npc:renferrel"}),
    Note("npc:gol-dir", "Gol'dir", "Person",
        "Gol'dir led an expedition of orc warriors sent from Durotar by the Warchief to recover an object from Durnholde Keep and to look into the Syndicate. The humans there overwhelmed them, and Gol'dir is held captive at a Syndicate base in the Alterac Mountains.",
        {V .. " #498 The Rescue; #503 Gol'dir"},
        nil, {"place:durnholde", "faction:syndicate", "region:416c7465726163204d6f756e7461696e73"}, true),
    Note("npc:jarl", "Jarl", "Person",
        "Jarl lives alone in Dustwallow Marsh, east of the Darkmist Cavern. He has cutting to do that he will not explain, and wants a moonsteel broadsword for it, which he calls a swing blade. He also likes to drink the juice of spider eyes.",
        {V .. " #1203 Jarl Needs a Blade; #1206 Jarl Needs Eyes"},
        nil, {"region:4475737477616c6c6f77204d61727368"}),
})

-- notes3 2026-11-05, batch 1: names the story prose used with no note. Five of
-- them carry secrets and have discovery policies in LoreDiscoveryData.lua
-- ("notes3" blocks): Gerrig Bonegrip and Keeper Bel'dugur (Yagyin's Digest),
-- Paval Reethe (the Shady Rest Inn), Myzrael (the Arathi shards) and the Rot Hides.
A.RegisterLoreNotes({
    Note("npc:gorzeeki", "Gorzeeki Wildeyes", "Person",
        "Gorzeeki Wildeyes is the servant of the warlock Mor'zul Bloodbringer in the Burning Steppes, and an alchemist of some skill. He prepares the blood ink for the parchment that summons a dreadsteed, and he knows the ritual needs far more than blood. He keeps a jar holding a clever imp, J'eevee, which he sends to the alchemy lab of Scholomance to infuse the parchment with Xorothian stardust. He would rather keep blood in a living rodent, where it stays warm.",
        {V .. " #7564 Wildeyes; #7629 Imp Delivery"},
        {"Gorzeeki"}, {"npc:morzul", "region:4275726e696e672053746570706573", "dungeon:scholomance"}, true),
    Note("npc:morzul", "Mor'zul Bloodbringer", "Person",
        "Mor'zul Bloodbringer is a warlock camped near the Altar of Storms in the Burning Steppes, where he studies the altar's energy. Warlock trainers send their most accomplished students to him when they are ready to master a dreadsteed of Xoroth. He warns that the summoning ritual costs blood, sweat and gold, and his servant Gorzeeki prepares its parchment.",
        {V .. " #7562 Mor'zul Bloodbringer; #7564 Wildeyes"},
        {"Mor'zul"}, {"npc:gorzeeki", "region:4275726e696e672053746570706573"}, true),
    Note("npc:impsy", "Impsy", "Person",
        "Impsy is an imp in Felwood, north of the Bloodvenom Falls, and the servant of Niby the Almighty. Niby lets Impsy set warlocks on the way to the infernal Kroshius, whose burned-out remains must be rekindled before he can be destroyed. Impsy also summons warlocks of his own and asks for a piece of satyr felcloth as a sign of good faith, which he loves for the way it burns the skin.",
        {V .. " #7601 What Niby Commands; #8419 An Imp's Request"},
        nil, {"region:46656c776f6f64"}, true),
    Note("npc:rethiel", "Rethiel the Greenwarden", "Person",
        "Rethiel the Greenwarden is a guardian of the Wetlands who lives in the marsh east of the fork in the road to Dun Modr, among the crocolisks. Rumor in Menethil Harbor calls him a beast who bites travelers in half. He says he has many names but answers to few, and he asks those he trusts to heal the wounds of the land, which he says is weeping.",
        {V .. " #463 The Greenwarden", LF("npc:rethiel-the-greenwarden", "Rethiel_the_Greenwarden")},
        {"Rethiel", "the Greenwarden", "Greenwarden"}, {"region:5765746c616e6473"}, true),
    Note("npc:ormer", "Ormer Ironbraid", "Person",
        "Ormer Ironbraid is a dwarf of the Whelgar Excavation team in the Wetlands. The bones the team uncovered drew raptors, which killed several of the diggers and trapped Ormer, Merrin and Prospector Whelgar on a bluff above the site. Ormer stays to guard the other two and wants the raptors killed, from the smaller mottled ones to the fiercest.",
        {V .. " #294 Ormer's Revenge; #295 Ormer's Revenge; #296 Ormer's Revenge", LF("npc:ormer-ironbraid", "Ormer_Ironbraid")},
        {"Ormer"}, {"place:whelgars-excavation-site", "npc:merrin", "region:5765746c616e6473"}, true),
    Note("npc:merrin", "Merrin Rockweaver", "Person",
        "Merrin Rockweaver works on the Whelgar Excavation in the Wetlands for the Explorers' League. Her husband Tarrel waits for the letters she sends every week, and when they stopped for two weeks, Longbraid promised to send a scout. Raptors overran the dig after it uncovered large bones, and Merrin is trapped on a bluff above it with Ormer Ironbraid and Prospector Whelgar.",
        {V .. " #305 In Search of the Excavation Team; #294 Ormer's Revenge", LF("npc:merrin-rockweaver", "Merrin_Rockweaver")},
        {"Merrin"}, {"place:whelgars-excavation-site", "npc:ormer", "faction:explorers-league"}),
    Note("npc:bathrah", "Bath'rah the Windwatcher", "Person",
        "Bath'rah the Windwatcher is a troll hermit camped by ruins on the eastern bank of the river that runs north from Tarren Mill, between the Alterac Mountains and the Western Plaguelands. He is a powerful shaman and a skilled weaponsmith. Warriors who have learned the berserker stance come to him for a weapon, and he asks their help in return. He also summons shamans of great wisdom and asks them for a sample of each element.",
        {V .. " #1791 The Windwatcher; #8410 Elemental Mastery", LF("npc:bath-rah-the-windwatcher", "Bath%27rah_the_Windwatcher")},
        {"Bath'rah"}, {"region:416c7465726163204d6f756e7461696e73", "place:tarren-mill"}, true),
    Note("npc:mokthardin", "Far Seer Mok'thardin", "Person",
        "Far Seer Mok'thardin is a troll shaman at Grom'gol Base Camp in Stranglethorn Vale. He means to harness the magic of the jungle for the Horde, and his rituals have worked so far. He makes enchanted items from the claws and fangs of the jungle's great cats and thanks the spirits for each beast taken.",
        {V .. " #570 Mok'thardin's Enchantment; #571 Mok'thardin's Enchantment", "LoreForever quest:570 (wiki: https://warcraft.wiki.gg/wiki/Mok%27thardin%27s_Enchantment)"},
        {"Mok'thardin"}, {"place:gromgol", "region:537472616e676c6574686f726e2056616c65"}, true),
    Note("npc:torgan", "Tor'gan", "Person",
        "Tor'gan is a troll shaman at Hammerfall in the Arathi Highlands. He can rebind the broken sigil of Thoradin, which Galen Trollbane split into eleven pieces among Stromgarde's defenders. He also pities the old orc Gor'mul, who was denied a death beside his Warchief, and hopes that the shamans' power can restore Gor'mul's pride.",
        {V .. " #640 The Broken Sigil; #675 Raising Spirits"},
        nil, {"place:hammerfall", "npc:gormul", "region:41726174686920486967686c616e6473"}, true),
    Note("npc:erlgadin", "Sir S. J. Erlgadin", "Person",
        "Sir S. J. Erlgadin is a member of Hemet Nesingwary's hunting expedition in Stranglethorn Vale. He is the camp's master of panther tracking, and those who want to join the great hunt must first prove themselves against Stranglethorn's panthers under him.",
        {V .. " #583 Welcome to the Jungle"},
        {"Sir Erlgadin", "Erlgadin"}, {"npc:hemet-nesingwary", "region:537472616e676c6574686f726e2056616c65"}, true),
    Note("npc:wizbang", "Wizbang Cranktoggle", "Person",
        "Wizbang Cranktoggle is a gnome inventor in Auberdine. He came to Darkshore for quiet to invent in, and lost his box of gaffer jacks after drinking too much on the voyage. His Buzzboxes stand along the Darkshore coast, and each one speaks with his voice, asks for parts and pays whoever repairs it. He is fond of crawler wine.",
        {V .. " #1001 Buzzbox 411; #1002 Buzzbox 323; #1003 Buzzbox 525", LF("npc:wizbang-cranktoggle", "Wizbang_Cranktoggle")},
        {"Wizbang"}, {"place:auberdine", "region:4461726b73686f7265"}, true),
    Note("npc:derrington", "High Executor Derrington", "Person",
        "High Executor Derrington commands the Forsaken base camp at the Bulwark, east of Tirisfal Glades, at the edge of the Plaguelands. He issued the Horde's call to arms against the Scourge there. With his second, Shadow Priestess Vandis, he plans to turn the Scourge's plague cauldrons against their makers, since Kel'Thuzad's power is too strong to shut them down.",
        {V .. " #5093 A Call to Arms: The Plaguelands!; #5228 The Scourge Cauldrons", LF("npc:high-executor-derrington", "High_Executor_Derrington")},
        {"Derrington"}, {"place:bulwark", "npc:vandis", "region:5765737465726e20506c616775656c616e6473"}, true),
    Note("npc:vandis", "Shadow Priestess Vandis", "Person",
        "Shadow Priestess Vandis is High Executor Derrington's second at the Bulwark. She coordinates the plan to change the plague brewed in the Scourge's cauldrons into something that harms the Scourge, starting with the four cauldrons of the Western Plaguelands.",
        {V .. " #5228 The Scourge Cauldrons; #5229 Target: Felstone Field"},
        {"Vandis"}, {"npc:derrington", "place:bulwark", "region:5765737465726e20506c616775656c616e6473"}, true),
    Note("npc:darthalia", "High Executor Darthalia", "Person",
        "High Executor Darthalia commands the Forsaken at Tarren Mill in the Hillsbrad Foothills. By the authority of Lady Sylvanas she pays bounties on the Syndicate, whose members gather in the ruins of Durnholde Keep. Her deathstalkers scout Hillsbrad, and she prepares an attack on the town in the expectation that Varimathras will be pleased.",
        {V .. " #549 WANTED: Syndicate Personnel; #494 Time To Strike", LF("npc:high-executor-darthalia", "High_Executor_Darthalia")},
        {"Darthalia"}, {"place:tarren-mill", "faction:syndicate", "region:48696c6c736272616420466f6f7468696c6c73"}, true),
    Note("npc:krog", "Krog", "Person",
        "Krog is an orc of Brackenwall Village in Dustwallow Marsh who looks into the burning of the Shady Rest Inn for the Horde. He knows many people and sends his trackers after what the ruins turn up.",
        {V .. " #1269 Lieutenant Paval Reethe; #1323 The Black Shield"},
        nil, {"place:brackenwall", "region:4475737477616c6c6f77204d61727368"}),
    Note("npc:nazeer", "Nazeer Bloodpike", "Person",
        "Nazeer Bloodpike is an officer of Brackenwall Village in Dustwallow Marsh. Horde and Alliance keep an uneasy truce in the marsh, but he wants the Theramore infiltrators who watch the village from the east hunted down.",
        {V .. " #1201 Theramore Spies"},
        nil, {"place:brackenwall", "region:4475737477616c6c6f77204d61727368"}),
    Note("npc:remy", "Remy \"Two Times\"", "Person",
        "Remy \"Two Times\" is a merchant in Goldshire. He warned Marshal Dughan that murlocs were coming up the streams of eastern Elwynn and attacking people there, and Dughan, though he respects Remy as a merchant, wants a military report before he sends troops. Remy also buys the gold dust that Elwynn's kobolds carry.",
        {V .. " #40 A Fishy Peril", LF("npc:remy-two-times", "Remy_%22Two_Times%22")},
        {"Remy Two Times"}, {"place:goldshire", "npc:dughan", "region:456c77796e6e20466f72657374"}),
    {id = "group:rot-hides", title = "Rot Hide Gnolls", kind = "Group", setting = "Classic / Forever",
        body = "The Rot Hides are gnolls given a kind of life by an embalming ichor. They serve the Scourge in Tirisfal Glades, carrying corpses from the Mass Graves near Garren's Haunt to swell the undead armies, and the Forsaken hunt them there. The apothecaries of the Undercity study their ichor, which carries warlock and necromantic magic.\n\nThe ichor is the work of Thule Ravenclaw, once a promising mage, who betrayed his brethren to the Scourge and leads the Rot Hides from Fenris Isle.",
        sources = {V .. " #358 Graverobbers; #443 Rot Hide Ichor; #444 Rot Hide Origins; #446 Thule Ravenclaw"},
        names = {"Rot Hides", "the Rot Hides", "Rot Hide gnolls", "Rot Hide Gnolls"}, related = {"npc:thule", "place:fenris-isle", "npc:sevren"}},
    Note("npc:gerrig-bonegrip", "Gerrig Bonegrip", "Person",
        "Gerrig Bonegrip keeps Bonegrip's Runes and Dooms, a shop in Ironforge's Forlorn Cavern. He sells old tomes, among them The Powers Below, a book of foreboding names, rites of worship and sacrifices, and warns his visitors that knowledge can be deadly.\n\nHe belongs to the Twilight's Hammer. He serves Myzrael, whom he calls the Lady, knows how to summon her, and greets his fellows as brothers in praise of the dwellers beneath. He keeps a copy of Yagyin's Digest, which the order's most learned study.",
        {V .. " #968 The Powers Below; #653 Myzrael's Allies; #687 Theldurin the Lost; #727 To Ironforge for Yagyin's Digest; #735 The Star, the Hand and the Heart", "LoreForever npc:gerrig-bonegrip (wiki: https://warcraft.wiki.gg/wiki/Gerrig_Bonegrip)"},
        {"Gerrig"}, {"place:forlorn-cavern", "group:twilights-hammer", "npc:myzrael"}),
    Note("npc:beldugur", "Keeper Bel'dugur", "Person",
        "Keeper Bel'dugur is a Forsaken scholar of the Undercity who collects works of forbidden magic. He wants the Book of Ur from Shadowfang Keep, both for his collection and for certain parties among the Forsaken, and he praises Ur's knowledge while scorning the conscience that held Ur back.\n\nHe secretly belongs to the order that Theldurin the Lost fled, and keeps its copies of Yagyin's Digest. He warns his fellows to be discreet, since some would see them fail if they knew of them.",
        {V .. " #1013 The Book of Ur; #728 To the Undercity for Yagyin's Digest; #736 The Star, the Hand and the Heart", "LoreForever npc:keeper-bel-dugur (wiki: https://warcraft.wiki.gg/wiki/Keeper_Bel%27dugur)"},
        {"Bel'dugur", "Keeper Bel'Dugur"}, {"place:undercity", "book:ur", "npc:theldurin-the-lost"}, true),
    Note("npc:reethe", "Lieutenant Paval Reethe", "Person",
        "Lieutenant Paval Reethe is an officer of the Theramore guard. His badge lies in the ashes of the burned Shady Rest Inn in Dustwallow Marsh. Theramore's records list him as a former Kul Tiras marine who came across the sea with Lady Proudmoore and is now missing, and Captain Garran Vimes reads that as desertion. The deserters at Lost Point say they threw him out for raiding the supplies of the Brackenwall ogres.\n\nThe Horde found him hiding in the woods, suspected of stealing supplies, and he died of an arrow wound after he was questioned. The fire at the inn is still unexplained.",
        {V .. " #1252 Lieutenant Paval Reethe; #1285 Daelin's Men; #1287 The Deserters; #1269 Lieutenant Paval Reethe; #1273 Questioning Reethe"},
        {"Paval Reethe", "Reethe"}, {"place:theramore", "npc:vimes", "region:4475737477616c6c6f77204d61727368"}),
    Note("npc:myzrael", "Myzrael", "Person",
        "Myzrael speaks through crystal shards in the Arathi Highlands. She calls herself a princess of the earth held captive beneath the Highlands by giants, and asks for help reaching the surface.\n\nOnce the Stones of Binding and the Keystone are opened, she is free but hides to gather strength, meaning to confront the giants who held her. The Twilight's Hammer serve her and know how to summon her. Theldurin the Lost, who fled that order, warns that she endangers the surface world and must be summoned, defeated and bound again with her Eldritch Shackles.",
        {V .. " #642 The Princess Trapped; #651 Stones of Binding; #653 Myzrael's Allies; #692 The Lost Fragments; #656 Summoning the Princess"},
        nil, {"relic:pendant-myzrael", "region:41726174686920486967686c616e6473", "group:twilights-hammer"}, true),
})

-- notes3 2026-11-05, batch 2: more names the prose uses, including the starters3
-- lane's Forever prose (Shadowvale, the Tarnished, Vrang, the Longwalkers, Bleachmane
-- Rock, Thatog's family). Velinde Starsong's fate has a discovery policy.
A.RegisterLoreNotes({
    Note("npc:velinde", "Velinde Starsong", "Person",
        "Velinde Starsong is a priestess of Elune who led the struggle against Felwood's corruption from Ashenvale. At first she seemed to have the trouble in Felwood under control, but her efforts faltered, and one day she disappeared. The Sentinels keep her belongings in their bunkhouse in Astranaar and believe she had her own reasons for leaving. The papers among her belongings tell of the Scythe of Elune, through which she summoned worgen against the demons of Felwood.\n\nThe search for her ends at Roland's Doom in Duskwood, where her specter laments the worgen running loose and the loss of the Scythe.",
        {V .. " #1037 Velinde Starsong; #1038 Velinde's Effects; #1044 Answered Questions"},
        {"Velinde"}, {"relic:scythe-elune", "npc:thyntel-bladeweaver", "region:417368656e76616c65"}, true),
    Note("place:oracle-tree", "Oracle Tree", "Place",
        "The Oracle Tree stands in the Oracle Glade in northwestern Teldrassil. Beneath its boughs lies the first and most powerful of the island's moonwells, the last that Corithras Moonrage's students visit when they gather water from the moonwells of Teldrassil.",
        {V .. " #934 Crown of the Earth; #7383 Crown of the Earth"},
        {"the Oracle Tree"}, {"place:oracle-glade", "region:54656c6472617373696c"}),
    {id = "place:shadowvale", title = "Shadowvale", kind = "Place", setting = "Forever",
        body = "Shadowvale is a ruined village deep in the Whispering Forest of western Tirisfal Glades. Before the Scourge came, its insular villagers distilled Whispering Elixir from herbs found only in Tyr's Fall. The elixir was banned in the capital, yet apothecaries, mystics and poisoners still sought it, and some say the forest is cursed and its roots carry the curse into the brew.\n\nThe Tarnished, risen paladins hostile to their fellow Forsaken, have taken up residence in its ruins, and the Scourge gather in the cellars beneath it.",
        sources = {V .. " #95314 That Shadowvale Green Elixir (Forever); #91316 Making Repairs (Forever); #91317 The Tarnished (Forever); #99152 As Above, So Below (Forever)",
            "LoreForever quest:95314 (wiki: https://warcraft.wiki.gg/wiki/That_Shadowvale_Green_Elixir)"},
        names = {"Shadowvale"}, related = {"group:tarnished", "place:tirisfal"}, autoLink = true},
    {id = "group:tarnished", title = "The Tarnished", kind = "Group", setting = "Forever",
        body = "The Tarnished are risen paladins who carried their prejudices from life into undeath and turn violence on their fellow Forsaken. They have gathered at Shadowvale in the Whispering Forest. Their attacks feed the mistrust that the Forsaken already hold for the order of risen paladins seeking a place among them.",
        sources = {V .. " #91317 The Tarnished (Forever)", "LoreForever quest:91317 (wiki: https://warcraft.wiki.gg/wiki/World_of_Warcraft:_Forever)"},
        names = {"the Tarnished", "Tarnished"}, related = {"place:shadowvale", "faction:forsaken"}},
    {id = "npc:vrang", title = "Vrang", kind = "Person", setting = "Forever",
        body = "Vrang is a trader in the Barrens with a wounded leg. He trades raw hides with a hermit tanner who lives alone on the ridge above the Dry Hills and warns visitors that the tanner's looks are worse than his nature. He keeps traps across the valley below for small game.",
        sources = {V .. " #95495 The Hermit Tanner (Forever); #95507 Vrang's Game (Forever)", "LoreForever quest:95495 (wiki: https://warcraft.wiki.gg/wiki/World_of_Warcraft:_Forever)"},
        names = {}, related = {"region:5468652042617272656e73"}, autoLink = true},
    {id = "group:longwalkers", title = "Longwalkers", kind = "Group", setting = "Forever",
        body = "The Longwalkers are the most trusted scouts of the tauren, loyal to the High Chieftain, and their missions are kept secret. Cairne Bloodhoof sent Longwalker Perith Stormhoof to speak with the gnolls at Bleachmane Rock, and Longwalker Malah to watch the eastern borders of Mulgore.",
        sources = {V .. " #98430 The Longwalkers (Forever); #99079 Longwalker Malah (Forever)", "LoreForever quest:98430 (wiki: https://warcraft.wiki.gg/wiki/World_of_Warcraft:_Forever)"},
        names = {"the Longwalkers"}, related = {"npc:cairne", "npc:malah", "place:bleachmane-rock"}, autoLink = true},
    {id = "place:bleachmane-rock", title = "Bleachmane Rock", kind = "Place", setting = "Forever",
        body = "Bleachmane Rock is a gnoll den in Mulgore. Cairne Bloodhoof sent Longwalker Perith Stormhoof there to speak with the gnolls who had settled it, and they answered his diplomacy with violence.",
        sources = {V .. " #98430 The Longwalkers (Forever)", "LoreForever quest:98430 (wiki: https://warcraft.wiki.gg/wiki/World_of_Warcraft:_Forever)"},
        names = {}, related = {"group:longwalkers", "region:4d756c676f7265"}, autoLink = true},
    {id = "npc:thatog", title = "Thatog", kind = "Person", setting = "Forever",
        body = "Thatog is an orc of Orgrimmar whose duties keep him at his post all day. His young son Migi plays behind Grommash Hold with the neighborhood children from morning to dusk and forgets to eat, so Thatog has lunch sent from Borstan's Firepit.",
        sources = {V .. " #97246 Meal Appeal (Forever); #97249 Favorite Food (Forever)", "LoreForever quest:97246 (wiki: https://warcraft.wiki.gg/wiki/World_of_Warcraft:_Forever)"},
        names = {}, related = {"npc:migi", "region:4f726772696d6d6172"}},
    {id = "npc:migi", title = "Migi", kind = "Person", setting = "Forever",
        body = "Migi is Thatog's young son in Orgrimmar. He races through the city with his friends and plays in the yard behind Grommash Hold, and would rather keep playing than stop to eat.",
        sources = {V .. " #97246 Meal Appeal (Forever)"}, names = {}, related = {"npc:thatog", "region:4f726772696d6d6172"}},
    {id = "npc:borstan", title = "Borstan", kind = "Person", setting = "Forever",
        body = "Borstan keeps Borstan's Firepit in Orgrimmar, where Thatog orders hot meals for his son Migi.",
        sources = {V .. " #97246 Meal Appeal (Forever)"}, names = {"Borstan's Firepit"}, related = {"npc:thatog", "region:4f726772696d6d6172"}},
    Note("npc:pozzik", "Pozzik", "Person",
        "Pozzik is the mechanic of the goblin racing team at the Shimmering Flats in Thousand Needles. He was one of the most respected tinkerers in Undermine before he left the Tinkers' Union for the races, and he designed the team's two-engine racers. Gazlowe of Ratchet finds parts for him from around the world. The gnomish team is his rival.",
        {V .. " #1178 Goblin Sponsorship; #1186 The Eighteenth Pilot", LF("npc:pozzik", "Pozzik")},
        nil, {"npc:razzeric", "npc:gazlowe", "region:54686f7573616e64204e6565646c6573"}, true),
    Note("npc:razzeric", "Razzeric", "Person",
        "Razzeric is the goblin racing team's pilot at the Shimmering Flats, its eighteenth. After Pozzik finishes a racer, Razzeric adds his own changes, loosening the controls, cutting away parts of the frame and adding power, such as a seaforium booster ordered from Shreev in Gadgetzan.",
        {V .. " #1186 The Eighteenth Pilot; #1187 Razzeric's Tweaking"},
        nil, {"npc:pozzik", "region:54686f7573616e64204e6565646c6573"}, true),
    Note("npc:lotwil", "Lotwil Veriatus", "Person",
        "Lotwil Veriatus is a gnome scholar working on dangerous experiments with the elementals of the Badlands, east of Kargath. He is easily distracted by his contraptions, promises that each project is his top priority, and offers good helpers work in Kharanos.",
        {V .. " #714 Gyro... What?; #715 Liquid Stone", LF("npc:lotwil-veriatus", "Lotwil_Veriatus")},
        {"Lotwil"}, {"region:4261646c616e6473"}, true),
    Note("npc:gwennyth", "Gwennyth Bly'Leggonde", "Person",
        "Gwennyth Bly'Leggonde is a night elf scholar in Auberdine. She collects samples from the sea turtles and other creatures that wash up dead on the Darkshore coast, where murlocs often scavenge the remains, and sends them to Darnassus for study.",
        {V .. " #4722 Beached Sea Turtle; #4723 Beached Sea Creature", LF("npc:gwennyth-bly-leggonde", "Gwennyth_Bly%27Leggonde")},
        {"Gwennyth"}, {"place:auberdine", "region:4461726b73686f7265"}, true),
    Note("npc:menara", "Menara Voidrender", "Person",
        "Menara Voidrender is a warlock staying in Strahad Farsan's tower above Ratchet. Warlock trainers of both factions send her their promising students. She is not friendly, but believes warlocks must band together whatever their race, and she helps them make tools for their craft, sending them to the mage Tabetha in Dustwallow Marsh to cleanse the Orb of Orahil.",
        {V .. " #4736 In Search of Menara Voidrender; #1799 Fragments of the Orb of Orahil", LF("npc:menara-voidrender", "Menara_Voidrender")},
        {"Menara"}, {"place:ratchet", "npc:tabetha"}, true),
    Note("npc:ridgewell", "Count Remington Ridgewell", "Person",
        "Count Remington Ridgewell is a Stormwind noble and a collector of relics, trophies and art. His agents send adventurers as far as Blackrock Spire for pieces such as Doomrigger's Clasp, a Dark Iron relic so encrusted with gems that it was said to make any dwarf weep.",
        {V .. " #4764 Doomrigger's Clasp; #4765 Delivery to Ridgewell", LF("npc:count-remington-ridgewell", "Count_Remington_Ridgewell")},
        {"Count Ridgewell", "Ridgewell"}, {"group:stormwind-nobles", "dungeon:blackrock-spire"}, true),
    Note("npc:wrenix", "Wrenix the Wretched", "Person",
        "Wrenix the Wretched is a goblin of Ratchet. The troll seer Zando'zan sends him helpers, and Wrenix remarks that the last five ended up as shark food.",
        {V .. " #2382 Wrenix of Ratchet", LF("npc:wrenix-the-wretched", "Wrenix_the_Wretched")},
        {"Wrenix"}, {"place:ratchet"}, true),
    Note("npc:rynthariel", "Rynthariel the Keymaster", "Person",
        "Rynthariel is a dryad, the Keymaster of the Talon Den on Stonetalon Peak. Her outrunners carry messages through the Barrens, and the Horde treat them as a threat on their ground.",
        {V .. " #3514 Horde Presence"},
        {"Rynthariel"}, {"region:53746f6e6574616c6f6e204d6f756e7461696e73"}, true),
    Note("npc:tonga", "Tonga Runetotem", "Person",
        "Tonga Runetotem is a tauren druid at the Crossroads in the Barrens. The druids of Thunder Bluff sent him to find the source of a strange power leaking into the Barrens and its oases, a mystery he says he cannot unravel alone.",
        {V .. " #886 The Barrens Oases", LF("npc:tonga-runetotem", "Tonga_Runetotem")},
        {"Tonga"}, {"place:crossroads", "region:5468652042617272656e73"}, true),
    Note("npc:cyrus", "Cyrus Therepentous", "Person",
        "Cyrus Therepentous serves the black dragonflight. He tests mortals who have worked in the Searing Gorge, scorns them as useless, and admits only grudgingly that some are not.",
        {V .. " #4022 A Taste of Flame; #4023 A Taste of Flame", LF("npc:cyrus-therepentous", "Cyrus_Therepentous")},
        {"Cyrus"}, {"region:4275726e696e672053746570706573"}, true),
    Note("npc:fitzsimmons", "Fitzsimmons", "Person",
        "Fitzsimmons is the only survivor of the Third Fleet of Kul Tiras, wrecked off the northern coast of the Wetlands. One of its ships carried a hidden and terrible treasure whose power keeps the souls of his drowned comrades trapped in the rotting hulls, and he hopes their curse can be broken.",
        {V .. " #289 The Cursed Crew; #292 The Eye of Paleth"},
        nil, {"region:5765746c616e6473"}, true),
})

-- Fourth notes lane (notes4), 2026-11-06. People the new 20-30 scenes name without a
-- note. Batch 1: Sun Rock Retreat, Malaka'jin and the Grimtotem raid. Kaya Flathoof's
-- survival and the Earthen under Boulderslide Ravine are discoveries
-- (LoreDiscoveryData.lua, "kaya" and "goggeroc"); Goggeroc's note stays hidden until then.
do
    local STM, ASH = "region:53746f6e6574616c6f6e204d6f756e7461696e73", "region:417368656e76616c65"
    A.RegisterLoreNotes({
        Note("npc:makaba-flathoof", "Makaba Flathoof", "Person",
            "Makaba Flathoof is a tauren of the eastern Stonetalon Mountains. The Grimtotem raided his village near the Barrens border and killed nearly everyone in it, and he fought until he barely escaped with his life. He asks the Horde for Grimtotem blood, above all that of Grundig Darkcloud, who led the raid from Grimtotem Post. He will never forget, he says, what the clan did to his village.\n\nHis daughter Kaya survived the raid as a Grimtotem captive. She escaped and made her way out through Camp Aparaje, and her aunt Tammra Windfield at Sun Rock Retreat has the news.",
            {V .. " #6548 Avenge My Village; #6629 Kill Grundig Darkcloud; #6523 Protect Kaya; #6401 Kaya's Alive", LF("npc:makaba-flathoof", "Makaba_Flathoof")},
            {"Makaba"}, {"place:grimtotem-post", "faction:grimtotem", "npc:tammra-windfield"}),
        Note("npc:tammra-windfield", "Tammra Windfield", "Person",
            "Tammra Windfield is a tauren shaman at Sun Rock Retreat. War and the greed of the lumber trade have wrecked Stonetalon, and she believes only the Earthmother's blessing can heal it. She blesses Gaea seeds from the shore of Mirkfallon Lake to speed their growth and has them planted at the center of the destruction in the Charred Vale, where she hopes a forest will one day stand again. She is the aunt of Kaya Flathoof, the daughter of Makaba Flathoof, whose village the Grimtotem destroyed.",
            {V .. " #6301 Cycle of Rebirth; #6381 New Life; #6401 Kaya's Alive", LF("npc:tammra-windfield", "Tammra_Windfield")},
            nil, {"place:sun-rock", "place:mirkfallon-lake", "npc:makaba-flathoof"}),
        Note("npc:morrogal", "Mor'rogal", "Person",
            "Mor'rogal is a tauren of Sun Rock Retreat who watches over the caves and crevices of the Stonetalon Mountains. He feels a tension in the land and sends adventurers into the kobold cave of Boulderslide Ravine, where the kobolds frantically mine a rare crystal called Resonite. He also has a use for the golden sunstones that the Bloodfury harpies hoard.\n\nIn the Resonite he finds a trace of Earthen magic. Earthen, he says, are creatures of the Titans who shaped the land, and he enchants the ore against the one the kobolds have uncovered.",
            {V .. " #6421 Boulderslide Ravine; #6481 Earthen Arise; #86576 Bloodfury Trinkets (Forever)", LF("npc:mor-rogal", "Mor%27rogal")},
            nil, {"place:sun-rock", "place:boulderslide-ravine", STM}, true),
        Note("npc:goggeroc", "Goggeroc", "Person",
            "Goggeroc is an Earthen, one of the beings the Titans made to shape the land. He lies asleep in a Resonite cask deep in the kobold cave of Boulderslide Ravine, where the kobolds have dug down to him. Mor'rogal of Sun Rock Retreat fears what an Earthen would mean for Kalimdor, and he knows that Goggeroc would be weak for a time after so long a sleep.",
            {V .. " #6421 Boulderslide Ravine; #6481 Earthen Arise"},
            nil, {"npc:morrogal", "place:boulderslide-ravine", "faction:titans"}, true),
        Note("npc:maggran", "Maggran Earthbinder", "Person",
            "Maggran Earthbinder leads Sun Rock Retreat, the Horde's camp in the Stonetalon Mountains. He holds that the tauren are the protectors of the land, and he is alarmed by the Bloodfury harpies who spread from the Charred Vale; he wants the flock culled and its leader, Bloodfury Ripper, killed. He has also put a bounty on the spider Besseleth of Sishir Canyon, whose fang he once survived. The fighting has filled his thoughts for so long that he wonders what he would do with himself in peace. He keeps the Horde's guards rested as well, sending a reserve warrior to relieve Grish Longrunner at the Great Lift.",
            {V .. " #6282 Harpies Threaten; #6283 Bloodfury Bloodline; #6284 Arachnophobia; #5881 Calling in the Reserves", LF("npc:maggran-earthbinder", "Maggran_Earthbinder")},
            {"Maggran"}, {"place:sun-rock", "place:charred-vale", "place:sishir-canyon"}),
        Note("npc:braelyn-firehand", "Braelyn Firehand", "Person",
            "Braelyn Firehand is a magic-user who lives among the Horde at Sun Rock Retreat. She hates Stonetalon. The keepers and druids of Stonetalon Peak stifle the flow of magic, and channeling there, she complains, is like drawing water with a bucket full of holes. Her master has sent her to the peak and will not let her return to Jaedenar until her work is done, and she pays Horde mercenaries to thin the druids, to raid the hoard of the Talon Den and to kill Keeper Ordanus, whom she knew long ago and remembers as arrogant.",
            {V .. " #1087 Cenarius' Legacy; #1088 Ordanus; #1089 The Den", LF("npc:braelyn-firehand", "Braelyn_Firehand")},
            nil, {"place:sun-rock", "npc:ordanus", "place:talon-den"}),
        Note("npc:ordanus", "Keeper Ordanus", "Person",
            "Keeper Ordanus is one of the eldest sons of Cenarius. The druids of Stonetalon Peak moved him from the peak to the top of the great tree at Raynewood Retreat in Ashenvale, out of the reach of Braelyn Firehand, but her scrying has found him there. She knew him long ago and says he held himself above even the Highborne.",
            {V .. " #1088 Ordanus", LF("item:ordanus-head", "Ordanus%27_Head")},
            {"Ordanus"}, {"npc:cenarius", "place:raynewood-retreat", "npc:braelyn-firehand"}),
        Note("npc:xenzilla", "Xen'Zilla", "Person",
            "Xen'Zilla is a troll hunter of Malaka'jin. The camp has prospered on Stonetalon's hunting, but lately spiders from the mountains raid it at night to steal the kill. Xen'Zilla fears nothing in Stonetalon, he says, yet he does not walk about after dark, and he asks travelers to thin the blood feeders north of the camp.",
            {V .. " #6461 Blood Feeders", LF("quest:6461", "Blood_Feeders")},
            nil, {"place:malakajin", STM}, true),
        Note("npc:jinzil", "Witch Doctor Jin'Zil", "Person",
            "Jin'Zil is a troll witch doctor who lives at Malaka'jin in the Stonetalon Mountains. He keeps three night elves in cages and gathers sap, whiskers, eyes and a fey dragon's scale to brew them what he calls forest magic. He is an old friend of Darsok Swiftdagger of the Crossroads, and he remembers the days when his friend Rokhan went with Rexxar to kill Bloodfeather, the harpy matriarch whose younger sister Serena led the Witchwing harpies of the Barrens.",
            {V .. " #1058 Jin'Zil's Forest Magic; #1060 Letter to Jin'Zil", LF("npc:witch-doctor-jin-zil", "Witch_Doctor_Jin%27Zil"), LF("quest:876", "Serena_Bloodfeather")},
            {"Jin'Zil"}, {"place:malakajin", "npc:rexxar", STM}),
    })
end

-- notes4 batch 2: Thousand Needles and the Battle of Hillsbrad. "Lakota" alone stays
-- unlinked: the Barrens kodo Lakota'mani shares the word.
do
    local TN, HB = "region:54686f7573616e64204e6565646c6573", "region:48696c6c736272616420466f6f7468696c6c73"
    A.RegisterLoreNotes({
        Note("npc:motega-firemane", "Motega Firemane", "Person",
            "Motega Firemane is a tauren who studies the creatures of Thousand Needles from Whitereach Post, on the road northwest of Freewind Post. Young Pao'ka Swiftmountain came with him as his assistant, though the boy's father was reluctant to let him go. Motega knows the old tauren legend of Arikara, a serpent of vengeance, and when Hagar Lightninghoof of Freewind finds signs he cannot explain, it is Motega he sends for.",
            {V .. " #4770 Homeward Bound; #4865 Serpent Wild; #5088 Arikara", LF("npc:motega-firemane", "Motega_Firemane")},
            {"Motega"}, {"place:whitereach-post", "npc:paoka", TN}),
        Note("npc:paoka", "Pao'ka Swiftmountain", "Person",
            "Pao'ka Swiftmountain is a young tauren who came to Thousand Needles with Motega Firemane to study its creatures. He went alone into Highperch to watch the wyverns, came too close to a nest and was chased off and lost, and he has hidden among the cliffs for days without a friendly face. He fears what Motega will say when he learns where Pao'ka went.",
            {V .. " #4770 Homeward Bound", LF("npc:pao-ka-swiftmountain", "Pao%27ka_Swiftmountain")},
            {"Pao'ka"}, {"npc:motega-firemane", "place:highperch", TN}),
        Note("npc:lakota-windsong", "Lakota Windsong", "Person",
            "Lakota Windsong is a tauren woman held by the Grimtotem on Darkcloud Pinnacle. Arnak Grimtotem wanted to marry her, and when she refused him he came back that night and carried her off. Her brother tried to stop him and was killed. She wants only to get back to her friend Thalia Amberhide at Freewind Post, who will be sick with worry.",
            {V .. " #4904 Free at Last; #5147 Wanted - Arnak Grimtotem", LF("npc:lakota-windsong", "Lakota_Windsong")},
            nil, {"place:darkcloud-pinnacle", "npc:thalia-amberhide", "faction:grimtotem"}),
        Note("npc:thalia-amberhide", "Thalia Amberhide", "Person",
            "Thalia Amberhide is a tauren of Freewind Post in Thousand Needles. Her friend Lakota Windsong was carried off by Arnak Grimtotem, who killed Lakota's brother when he tried to stop him, and Thalia waits at Freewind for word of her.",
            {V .. " #4904 Free at Last", LF("npc:thalia-amberhide", "Thalia_Amberhide")},
            nil, {"place:freewind", "npc:lakota-windsong", TN}),
        Note("npc:grish-longrunner", "Grish Longrunner", "Person",
            "Grish Longrunner is a tauren who guards the Great Lift at the southern edge of the Barrens. He asked some time ago for leave to visit his family, and Maggran Earthbinder, who keeps the Horde's troops rested, sends him word that a reserve warrior is coming to take his place. He feels he has sat guarding the lift long enough.",
            {V .. " #5881 Calling in the Reserves", LF("npc:grish-longrunner", "Grish_Longrunner")},
            nil, {"place:great-lift", "npc:maggran", "region:5468652042617272656e73"}),
        Note("npc:moonhorn", "Brave Moonhorn", "Person",
            "Brave Moonhorn is a tauren who watches the western approaches of Thousand Needles near the Great Lift. The centaurs have stepped up their attacks there, and he sends urgent word to Cliffwatcher Longhorn at Freewind Post. He warns travelers away from the nearby Grimtotem, who have been acting strangely toward the other tauren.",
            {V .. " #4542 Message to Freewind Post", LF("npc:brave-moonhorn", "Brave_Moonhorn")},
            nil, {"place:great-lift", "place:freewind", TN}),
        Note("npc:wizlo", "Wizlo Bearingshiner", "Person",
            "Wizlo Bearingshiner is a goblin tinkerer waiting at Whitereach Post in Thousand Needles, the only survivor of a caravan that the centaurs attacked just to the north. The raiders took everything except a rare panther in a cage, and the panther wears Wizlo's best gizmo, a hypercapacitor, around its neck. Even the centaurs, he says, tremble before the beast.",
            {V .. " #5151 Hypercapacitor Gizmo", LF("npc:wizlo-bearingshiner", "Wizlo_Bearingshiner")},
            {"Wizlo"}, {"place:whitereach-post", TN}),
        Note("npc:korran", "Korran", "Person",
            "Korran is a troll posted at the Crossroads in the Barrens to watch the land and report on it to his masters in Orgrimmar. He studies the insect creatures of the Field of Giants, which seem cleverer than any normal animal, and collects their eggs. What the travelers who help him report has convinced him that the insects are a far greater threat than Orgrimmar first thought, and he sends word to Belgrom Rockmaul in the city.",
            {V .. " #868 Egg Hunt; #1145 The Swarm Grows", LF("npc:korran", "Korran")},
            nil, {"place:field-of-giants", "place:crossroads", "group:silithid"}, true),
        Note("npc:verringtan", "Blacksmith Verringtan", "Person",
            "Verringtan is the blacksmith of the town of Hillsbrad. He and his apprentices arm the townsfolk, which is why the humans resist the Forsaken so stubbornly, and the town keeps a stockpile of iron at his smithy. To the Forsaken commanders at Tarren Mill he is a supply line to be cut.",
            {V .. " #529 Battle of Hillsbrad", "LoreForever quest:529 (wiki: https://warcraft.wiki.gg/wiki/Battle_of_Hillsbrad)"},
            {"Verringtan"}, {"place:hillsbrad-fields", "place:tarren-mill", HB}),
        Note("npc:burnside", "Magistrate Burnside", "Person",
            "Magistrate Burnside leads the human town of Hillsbrad with its town council. Despite heavy losses to the Forsaken, the townsfolk rally around him and keep fighting. The town reveres a political document, the Hillsbrad Proclamation, and its council keeps the town registry.",
            {V .. " #532 Battle of Hillsbrad; #539 Battle of Hillsbrad", "LoreForever quest:532 (wiki: https://warcraft.wiki.gg/wiki/Battle_of_Hillsbrad)"},
            {"Burnside"}, {"place:hillsbrad-fields", "place:southshore", HB}),
        Note("npc:ironhill", "Captain Ironhill", "Person",
            "Captain Ironhill commands Dun Garok, the dwarven barracks along Thoradin's Wall in southeastern Hillsbrad. His dwarves aid the humans of the foothills against the Forsaken, and the Forsaken at Tarren Mill mean to test the Alliance by laying siege to his barracks.",
            {V .. " #541 Battle of Hillsbrad", "LoreForever quest:541 (wiki: https://warcraft.wiki.gg/wiki/Battle_of_Hillsbrad)"},
            {"Ironhill"}, {"place:dun-garok", "npc:thoradin", HB}),
    })
end

-- notes4 batch 3: Ashenvale for the Alliance. Anilia's fate ("anilia"), the Dor'Danil
-- vision ("dordanil") and the summoner behind Mystral Lake's elementals ("sarilus") are
-- discoveries (LoreDiscoveryData.lua); Geltharis stays hidden until Anilia names him.
do
    local ASH, BAR = "region:417368656e76616c65", "region:5468652042617272656e73"
    A.RegisterLoreNotes({
        Note("npc:illiyana", "Illiyana", "Person",
            "Illiyana is a dryad of Ashenvale, one of the daughters of Cenarius, who keeps to the woods near the Shrine of Aessina. Her sisters, led by Anilia, went to the satyr ruins of Xavian to take back the Branch of Cenarius, and after two days without word she began asking travelers to find them.\n\nAnilia did not come back. Illiyana can hardly believe that her sister is gone, since they were playing together in the woods only the day before, and she asks that the satyrs who took Anilia be slain.",
            {V .. " #1021 Vile Satyr! Dryads in Danger!; #1031 The Branch of Cenarius; #1032 Satyr Slaying!", LF("npc:illiyana", "Illiyana")},
            nil, {"npc:anilia", "place:xavian", ASH}, true),
        Note("npc:anilia", "Anilia", "Person",
            "Anilia is a dryad of Ashenvale and a sister of Illiyana. She led the dryads who went into the satyr ruins of Xavian to take back the Branch of Cenarius.\n\nShe was found in Xavian near death from a wound in her side. With her last breath she pointed to an arch to the north and named Geltharis as the one who took the Branch.",
            {V .. " #1021 Vile Satyr! Dryads in Danger!; #1031 The Branch of Cenarius"},
            nil, {"npc:illiyana", "place:xavian", "npc:geltharis"}, true),
        Note("npc:geltharis", "Geltharis", "Person",
            "Geltharis holds the Branch of Cenarius among the satyr ruins of Xavian in eastern Ashenvale, beyond an arch to the north. The dryad Anilia, dying of her wound, named him as the one who had taken it, and her sister Illiyana waits for the Branch to come back to dryad hands.",
            {V .. " #1031 The Branch of Cenarius", LF("quest:1031", "The_Branch_of_Cenarius")},
            nil, {"place:xavian", "npc:anilia", "npc:illiyana"}, true),
        Note("npc:melyria", "Melyria Frostshadow", "Person",
            "Sentinel Melyria Frostshadow serves in Ashenvale, where the Sentinels have spent much effort driving the remaining demons out of Felwood with few successes, though they have kept most of the demonic presence out of Ashenvale. She seeks the reason the wolf-men have overrun the shrine of Mel'Thandris in the Howling Vale, and she asks after Velinde Starsong, the priestess who led the fight against Felwood's corruption before her.",
            {V .. " #1022 The Howling Vale; #1037 Velinde Starsong", LF("quest:1022", "The_Howling_Vale")},
            {"Sentinel Melyria Frostshadow", "Melyria"}, {"place:howling-vale", "npc:velinde", ASH}),
        Note("npc:kayneth", "Kayneth Stillwind", "Person",
            "Kayneth Stillwind is a night elf druid who keeps the shrine of Forest Song in eastern Ashenvale. He fears that a corruption is moving through the forest and reads the Sentinels' reports for signs of it. The Forsaken who have crept into Ashenvale's ruins and barrows worry him most. He believes they mean to spread disease through the night elves' lands, and he wants a bottle from their camp near the Dor'Danil Barrow Den to test. Spirits freed from Felwood's suffering are sent to him.\n\nWhile he struggled with the Forsaken's poisons, Kayneth saw in a vision that the druids of Dor'Danil had been poisoned and murdered by the undead and driven mad as ghosts.",
            {V .. " #4581 Kayneth Stillwind; #1011 Forsaken Diseases; #1012 Insane Druids; #4261 Ancient Spirit", LF("quest:1011", "Forsaken_Diseases")},
            {"Kayneth"}, {"place:forest-song", "place:dordanil", "npc:shindrell-swiftfire"}),
        Note("npc:velene", "Sentinel Velene Starstrike", "Person",
            "Velene Starstrike is a Sentinel at Silverwind Refuge in Ashenvale. Water elementals have been filling the pools near Mystral Lake with corruption, and she has a divining scroll that can name their creator once it is focused through bracers taken from the elementals themselves.\n\nThe divination points to Sarilus Foulborne, the only undead mage in the Barrens able to defile so many elementals, and she wants his head brought back from Dreadmist Peak.",
            {V .. " #1016 Elemental Bracers; #1017 Mage Summoner", LF("npc:sentinel-velene-starstrike", "Sentinel_Velene_Starstrike")},
            {"Velene Starstrike", "Velene"}, {"place:silverwind-refuge", "place:mystral-lake", "npc:sarilus"}),
        Note("npc:sarilus", "Sarilus Foulborne", "Person",
            "Sarilus Foulborne is an undead mage who has made his camp at the top of Dreadmist Peak in the Barrens.\n\nHe is the summoner who fills the pools of Ashenvale near Mystral Lake with corrupt water elementals, and Sentinel Velene Starstrike of Silverwind Refuge wants him dead.",
            {V .. " #1017 Mage Summoner", LF("item:sarilus-foulborne-s-head", "Sarilus_Foulborne")},
            {"Sarilus"}, {"place:dreadmist-peak", "npc:velene", BAR}),
        Note("npc:pelturas", "Pelturas Whitemoon", "Person",
            "Pelturas Whitemoon is a night elf of Astranaar whose young daughter, Relara, is deathly ill. The herbalist Orendil Broadleaf sends him a cure and tells him of further remedies to try should the first fail, each found in one of Ashenvale's sacred places. Elune's Tear rests on the isle in Iris Lake, a frosted dust lies among the Ruins of Stardust, and moonstones used to be gathered at Fallen Sky Lake before the Shadethicket bog beasts came.",
            {V .. " #1020 Orendil's Cure; #1033 Elune's Tear; #1034 The Ruins of Stardust; #1035 Fallen Sky Lake", LF("npc:pelturas-whitemoon", "Pelturas_Whitemoon")},
            {"Pelturas"}, {"npc:relara", "place:astranaar", "place:iris-lake"}),
        Note("npc:relara", "Relara", "Person",
            "Relara is the young daughter of Pelturas Whitemoon of Astranaar. She is deathly ill, and ordinary medicine has not been enough, so her father and the herbalist Orendil Broadleaf look to the sacred places of Ashenvale for remedies strong enough to save her.",
            {V .. " #1020 Orendil's Cure; #1033 Elune's Tear", LF("npc:pelturas-whitemoon", "Pelturas_Whitemoon")},
            nil, {"npc:pelturas", "place:astranaar", ASH}, true),
        Note("npc:therysil", "Therysil", "Person",
            "Therysil is a dryad at the Shrine of Aessina in Ashenvale. Her sister Therylune does not mind getting dirty and wanders far from home, as far as the Master's Glaive in Darkshore, a place Therysil thinks unwholesome.",
            {V .. " #945 Therylune's Escape", LF("npc:therysil", "Therysil")},
            nil, {"place:masters-glaive", "region:4461726b73686f7265", ASH}, true),
        Note("npc:dal-bloodclaw", "Dal Bloodclaw", "Person",
            "Dal Bloodclaw is the chieftain of the Thistlefur furbolgs, who live directly north of Astranaar. Their numbers have grown greatly in recent months, and the town's defenders fear that the tribe will soon find the courage to attack Astranaar itself.",
            {V .. " #1054 Culling the Threat", LF("item:dal-bloodclaw-s-skull", "Dal_Bloodclaw")},
            nil, {"place:astranaar", "race:furbolgs", ASH}),
    })
end

-- notes4 batch 4: Zoram'gar, Splintertree and the Warsong camp; Kaela Shadowspear and
-- Gaxim Rustfizzle's campaign against the Venture Company in Windshear Crag. "Tara"
-- and "Torek" alone stay unlinked (an ordinary given name; a short word).
do
    local ASH, STM = "region:417368656e76616c65", "region:53746f6e6574616c6f6e204d6f756e7461696e73"
    A.RegisterLoreNotes({
        Note("npc:muglash", "Muglash", "Person",
            "Muglash is a member of the Horde at Zoram'gar Outpost on the coast of Ashenvale, who has seen many naga attacks since he came there. The hydra Vorsha the Lasher has struck the outpost again and again, and he has a plan to end it. The naga keep a brazier lit in her honor on an island off the coast, and he believes that putting it out will bring her out in anger.",
            {V .. " #6641 Vorsha the Lasher", LF("quest:6641", "Vorsha_the_Lasher")},
            nil, {"place:zoramgar", "npc:vorsha", "people:naga"}, true),
        Note("npc:vorsha", "Vorsha the Lasher", "Person",
            "Vorsha the Lasher is a hydra of the seas off the Zoram Strand in Ashenvale. She has attacked Zoram'gar Outpost many times, unprovoked, laying waste to anything in her path. The naga honor her wicked nature with a brazier that burns on an island just off the coast.",
            {V .. " #6641 Vorsha the Lasher", LF("quest:6641", "Vorsha_the_Lasher")},
            {"Vorsha"}, {"place:zoram-strand", "place:zoramgar", "people:naga"}),
        Note("npc:mitsuwa", "Mitsuwa", "Person",
            "Mitsuwa is a troll at Zoram'gar Outpost in Ashenvale. His kinfolk were bringing many sacred troll charms there when the Thistlefur furbolgs attacked and killed them, and the charms now lie in chests in Thistlefur Hold. He believes he will meet his dead brothers and sisters again in the afterlife, but he cannot bear that furbolgs hold the charms. A troll without his charm, he says, is worthless.",
            {V .. " #6462 Troll Charm", LF("npc:mitsuwa", "Mitsuwa")},
            nil, {"place:zoramgar", "place:thistlefur-hold", ASH}, true),
        Note("npc:kuraybin", "Kuray'bin", "Person",
            "Kuray'bin is a troll scout of Splintertree Post in Ashenvale. Night elf outrunners from Silverwing Outpost sneak through the forest south of the post to gather word of the Horde's defenses, and Kuray'bin has them hunted down, since an Alliance without that knowledge is less likely to attack.",
            {V .. " #6503 Ashenvale Outrunners", LF("npc:kuray-bin", "Kuray%27bin")},
            nil, {"place:splintertree", "place:silverwing-outpost", ASH}, true),
        Note("npc:ertog", "Ertog Ragetusk", "Person",
            "Ertog Ragetusk is an officer at Splintertree Post in Ashenvale and the superior of the raider Torek, who leads attacks on Silverwing Outpost and its leader, Duriel Moonfire. Ertog thinks the night elves decent foes, a little skinny but strong and fierce, and he hopes those who fight them come back with a scar or two.",
            {V .. " #6544 Torek's Assault", LF("quest:6544", "Torek%27s_Assault")},
            {"Ertog"}, {"place:splintertree", "npc:torek", ASH}),
        Note("npc:torek", "Torek", "Person",
            "Torek is an orc raider of the Horde in Ashenvale who answers to Ertog Ragetusk at Splintertree Post. He and his raiders mean to attack Silverwing Outpost to the west and kill its leader, Duriel Moonfire, though scouts report that it is heavily defended by Sentinels and warriors. He calls the coming battle glorious.",
            {V .. " #6544 Torek's Assault", LF("quest:6544", "Torek%27s_Assault")},
            nil, {"npc:ertog", "place:silverwing-outpost", "npc:duriel-moonfire"}),
        Note("npc:duriel-moonfire", "Duriel Moonfire", "Person",
            "Duriel Moonfire leads Silverwing Outpost, the night elf post on the Falfarren River in Ashenvale. The Horde raiders of Splintertree Post make the outpost's leader the chief target of their attacks.",
            {V .. " #6544 Torek's Assault", LF("subzone:silverwing-outpost", "Silverwing_Outpost")},
            {"Duriel"}, {"place:silverwing-outpost", "npc:torek", ASH}),
        Note("npc:locke-okarr", "Locke Okarr", "Person",
            "Locke Okarr supplies the Warsong lumber camp in Ashenvale and is in big trouble if its shipments do not arrive soon. The saw blades wait with Pixel at Splintertree Post and a crate of axes with Wharfmaster Lozgil in Booty Bay. Thistlefur and Foulweald furbolgs have stolen the rope, and satyrs took the oil for their rites in Night Run, Satyrnaar and Xavian.",
            {V .. " #6571 Warsong Supplies", LF("quest:6571", "Warsong_Supplies")},
            nil, {"place:warsong-lumber-camp", "place:splintertree", ASH}),
        Note("npc:gurda-ragescar", "Gurda Ragescar", "Person",
            "Gurda Ragescar works at the Warsong Lumber Camp in Ashenvale. She picked up a shredder in Ratchet and was on her way back to duty when a gust of wind tore its operating manual from her hands and scattered it through the forest, leaving her only the cover. Reading is not her strong point, and without the manual she cannot work the machine.",
            {V .. " #6504 The Lost Pages", LF("npc:gurda-ragescar", "Gurda_Ragescar")},
            nil, {"place:warsong-lumber-camp", "place:ratchet", ASH}),
        Note("npc:karang", "Karang Amakkar", "Person",
            "Karang Amakkar is a Horde commander at Zoram'gar Outpost in western Ashenvale who means to see the Horde claim the whole forest. Thistlefur Village blocks the road east to Splintertree Post that would let the Horde skirt Astranaar, and he wants the furbolgs there thinned so that no Alliance expansion path opens. He has also challenged the Foulweald furbolgs southeast of Astranaar, whose chief, Murgut, must answer a Horde banner on their totem mound.",
            {V .. " #216 Between a Rock and a Thistlefur; #6621 King of the Foulweald", LF("npc:karang-amakkar", "Karang_Amakkar")},
            {"Karang"}, {"place:zoramgar", "npc:murgut", ASH}),
        Note("npc:murgut", "Chief Murgut", "Person",
            "Murgut is the chief of the Foulweald furbolgs, who live southeast of Astranaar in Ashenvale. The tribe is smaller than the Thistlefur but fierce. When an enemy banner is planted on its totem mound, the tribe tries to destroy it, and Murgut comes out to save face, carrying the Foulweald totem.",
            {V .. " #6621 King of the Foulweald", LF("quest:6621", "King_of_the_Foulweald")},
            {"Murgut"}, {"npc:karang", "race:furbolgs", ASH}),
        Note("npc:kaela", "Kaela Shadowspear", "Person",
            "Kaela Shadowspear is a night elf Sentinel sent into the Stonetalon Mountains by Raene Wolfrunner to learn what is happening to the land. She has spent most of her time there fighting the Venture Company's destruction of the forest around Windshear Crag. The situation is grave enough that she works beside a gnome mage, Gaxim Rustfizzle, and she asks others not to judge him too soon. Her friend Tara Thenysil waits for news of her in Astranaar.",
            {V .. " #1070 On Guard in Stonetalon; #1085 On Guard in Stonetalon; #1082 Update for Sentinel Thenysil", LF("npc:kaela-shadowspear", "Kaela_Shadowspear")},
            {"Kaela"}, {"npc:gaxim", "npc:raene", "place:windshear-crag"}),
        Note("npc:gaxim", "Gaxim Rustfizzle", "Person",
            "Gaxim Rustfizzle is a gnome mage of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences who works beside Kaela Shadowspear in the Stonetalon Mountains. He holds it his duty to show the night elves that a blend of magic, mixtures and mechanisms can help save their forests, since swearing off magic, he says, will not help them. He herds the Venture Company's goblins with well-placed explosives and plans bigger devices, drawing on his old friends Lomac Gearstrip of Tinker Town for the explosive NG-5 and Collin Mauren of Stormwind for spells.",
            {V .. " #1071 A Gnome's Respite; #1072 An Old Colleague; #1075 A Scroll from Mauren; #1085 On Guard in Stonetalon", LF("npc:gaxim-rustfizzle", "Gaxim_Rustfizzle")},
            {"Gaxim"}, {"npc:kaela", "faction:venture-company", "place:windshear-crag"}, true),
        Note("npc:collin-mauren", "Collin Mauren", "Person",
            "Collin Mauren is a human mage in the Mage Quarter of Stormwind and a friend of the gnome Gaxim Rustfizzle. He works out the spells Gaxim's inventions need and impresses them on scrolls, among them a messaging spell from which Gaxim makes a way to set off explosives from afar.",
            {V .. " #1075 A Scroll from Mauren; #1076 Devils in Westfall; #1077 Special Delivery for Gaxim", LF("npc:collin-mauren", "Collin_Mauren")},
            {"Mauren"}, {"place:mage-quarter", "npc:gaxim", "region:53746f726d77696e642043697479"}),
        Note("npc:lomac-gearstrip", "Lomac Gearstrip", "Person",
            "Lomac Gearstrip is a gnome alchemist in Tinker Town in Ironforge and the only one who can make Nitromirglyceronium, the volatile explosive called NG-5. He is an old colleague of Gaxim Rustfizzle, though he does not take anyone's word for that, and he thinks the world is not all about swords and sorcery.",
            {V .. " #1072 An Old Colleague; #1073 Ineptitude + Chemicals = Fun; #1074 Ineptitude + Chemicals = Fun", LF("npc:lomac-gearstrip", "Lomac_Gearstrip")},
            {"Lomac"}, {"place:tinker-town", "npc:gaxim", "region:49726f6e666f726765"}),
    })
end

-- notes4 batch 5: Booty Bay, Nesingwary's camp, the Hinterlands and the Mirage Raceway,
-- names last night's notes3 lane left over. Who holds Yenniku is a discovery
-- ("yenniku", LoreDiscoveryData.lua), which now also covers the older Yenniku and
-- Nimboya notes. Sharpbeak's note tells only that he is missing.
do
    local STV = "region:537472616e676c6574686f726e2056616c65"
    A.RegisterLoreNotes({
        Note("npc:revilgaz", "Baron Revilgaz", "Person",
            "Baron Revilgaz is the goblin lord of Booty Bay and leader of the Blackwater Raiders, who keep the port open to Alliance and Horde alike for the Steamwheedle Cartel. He keeps agents across Stranglethorn and has them listen for rumors of the strange and the out-of-place. When Gelriz pushes aside moguls appointed by the trade princes and tries to cut in on Revilgaz himself, the baron has his people answer with theft. He also collects ancient artifacts and relics, and a troll legend of the Stone of the Tides has caught his eye.",
            {V .. " #616 The Haunted Isle; #213 Hostile Takeover; #189 Bloodscalp Ears; #601 Water Elementals", LF("npc:baron-revilgaz", "Baron_Revilgaz")},
            {"Revilgaz"}, {"place:booty-bay", "faction:blackwater-raiders", "relic:stone-tides"}),
        Note("npc:krazek", "Krazek", "Person",
            "Krazek is a goblin merchant and inventor in Booty Bay, maker of Krazek's Crock Pot, a mechanical cooking pot that saves its owners hours of work but now and then breaks a spring or throws a gear. Nothing he fixes comes without a price, and he likes to be paid in bloodstone from the caves of the Arathi Highlands. He also keeps an ear out for rumors for Baron Revilgaz and sends supplies north to Lieutenant Doren's camp.",
            {V .. " #210 Krazek's Cookery; #627 Favor for Krazek; #616 The Haunted Isle; #198 Supplies to Private Thorsen", LF("quest:210", "Krazek%27s_Cookery")},
            nil, {"place:booty-bay", "npc:revilgaz", STV}, true),
        Note("npc:kebok", "Kebok", "Person",
            "Kebok is an agent of Booty Bay who answers to Baron Revilgaz. The Bloodscalp trolls have been killing his agents in the jungle, and he must explain the mounting costs to the baron. He also runs a quiet trade in tiger fangs for the South Seas, filling it with forgeries carved from the tusks of Skullsplitter trolls, on the grounds that what the buyer does not know cannot hurt him.",
            {V .. " #189 Bloodscalp Ears; #209 Skullsplitter Tusks", LF("quest:189", "Bloodscalp_Ears")},
            nil, {"place:booty-bay", "npc:revilgaz", "faction:skullsplitter"}, true),
        Note("npc:zanzil", "Zanzil the Outcast", "Person",
            "Zanzil the Outcast is a troll witch doctor who dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay. His own tribe exiled him because his leaders fear him. He bends the minds of others with a mixture of jungle plants that suppresses the will and strengthens the body, and those who would control others will pay well for it.\n\nZanzil holds Yenniku, the young son of the Darkspear chief, at the Ruins of Aboraz and controls him body and soul.",
            {V .. " #621 Zanzil's Secret; #588 The Fate of Yenniku; #592 Saving Yenniku", LF("item:sample-of-zanzil-s-altered-mixture", "Zanzil_the_Outcast")},
            {"Zanzil"}, {"npc:yenniku", "faction:darkspear", STV}),
        Note("npc:ajeck", "Ajeck Rouack", "Person",
            "Ajeck Rouack is a hunter at Nesingwary's Expedition in northern Stranglethorn. Her father trained her in tiger hunting when she was a young girl, and she teaches the hunters who want a place in Hemet Nesingwary's great hunt, starting them on the young tigers near the camp. She has a name for the wily raptor that even Nesingwary has failed to kill, Tethis.",
            {V .. " #185 Tiger Mastery; #583 Welcome to the Jungle; #197 Raptor Mastery", LF("quest:185", "Tiger_Mastery")},
            {"Ajeck"}, {"place:nesingwarys-expedition", "npc:hemet-nesingwary", "npc:erlgadin"}),
        Note("npc:drizzlik", "Drizzlik", "Person",
            "Drizzlik is a leathercrafter of Booty Bay who calls himself the finest of the South Seas. His Excelsior line of boots is his best seller, and Director Riddlevox, chief inventor of the Tinkers' Union, has ordered a dozen pairs, made from the skins of Stranglethorn's crocolisks with tiger blood to soften them.",
            {V .. " #575 Supply and Demand; #577 Some Assembly Required; #628 Excelsior", LF("quest:575", "Supply_and_Demand")},
            nil, {"place:booty-bay", STV}, true),
        Note("npc:thorsen", "Private Thorsen", "Person",
            "Private Thorsen serves with Lieutenant Doren's rebel camp in northern Stranglethorn, northwest of the road from Duskwood. He takes in the camp's regular supplies from Booty Bay and patrols south of it when he is not there. The camp needs its supplies, land mines among them, to defend itself against Colonel Kurzen and his men.",
            {V .. " #198 Supplies to Private Thorsen", LF("quest:198", "Supplies_to_Private_Thorsen")},
            {"Thorsen"}, {"npc:doren", "npc:kurzen", STV}),
        Note("npc:oglethorpe", "Oglethorpe Obnoticus", "Person",
            "Oglethorpe Obnoticus is a gnome inventor in Booty Bay who builds homing robots shaped like chickens. Each carries a distress beacon in a metal egg, and his voice crackles from the egg when a traveler finds one. His robots keep crashing in far places, from the Gaping Chasm in Tanaris to the Hinterlands and Feralas, and he rewards anyone who helps them home for repairs.",
            {V .. " #351 Find OOX-17/TN!; #485 Find OOX-09/HL!; #648 Rescue OOX-17/TN!", LF("quest:485", "Find_OOX-09/HL!")},
            {"Oglethorpe"}, {"place:booty-bay", "region:54616e61726973"}),
        Note("npc:sharpbeak", "Sharpbeak", "Person",
            "Sharpbeak is the young son of Swiftwing, the mightiest gryphon of the Wildhammer at Aerie Peak, and is destined to lead the next generation of gryphons. He was lost while hunting with his parents, and the Wildhammer believe that trolls took him.",
            {V .. " #2988 Witherbark Cages", LF("quest:2988", "Witherbark_Cages")},
            nil, {"place:aerie-peak", "faction:wildhammer", "npc:talonaxe"}, true),
        Note("npc:talonaxe", "Gryphon Master Talonaxe", "Person",
            "Gryphon Master Talonaxe keeps the gryphons and flight assignments of Aerie Peak in the Hinterlands. He has a soft spot for the Explorers' League, since his father helped the first team that excavated Uldaman, and he once sent his best rider, Rhapsody Shindigger, with Brohann Caskbelly. The loss of Sharpbeak, son of the mightiest gryphon, is his trouble now.",
            {V .. " #1450 Gryphon Master Talonaxe; #2988 Witherbark Cages", LF("quest:1450", "Gryphon_Master_Talonaxe")},
            {"Talonaxe"}, {"place:aerie-peak", "npc:sharpbeak", "faction:wildhammer"}),
        Note("npc:zengu", "Zengu", "Person",
            "Zengu is a troll of Hammerfall in the Arathi Highlands. His people fought the Arathorian Empire long ago, and their most capable enemy was Lord Ignaeus of Strom, called Trollbane, who rode into battle with the sword Trol'kalar. Now that Stromgarde is in ruins, Zengu means to take the sword from Trollbane's tomb, and he seeks the sigils that guard it, divided among Stromgarde's survivors.",
            {V .. " #639 Sigil of Strom", LF("quest:639", "Sigil_of_Strom")},
            nil, {"place:hammerfall", "relic:trolkalar", "place:stromgarde"}, true),
        Note("npc:kravel", "Kravel Koalbeard", "Person",
            "Kravel Koalbeard makes it his job to get people at the Mirage Raceway in Thousand Needles what they need, filling parts orders for the gnome and goblin racers through Wharfmaster Dizzywig in Ratchet, though he does not always pay his tab. He trades in rumors as well, and he is brewing a risky scheme with Crank Fizzlebub of Booty Bay that he expects to make them both a bundle.",
            {V .. " #1111 Wharfmaster Dizzywig; #1112 Parts for Kravel; #1117 Rumors for Kravel; #1118 Back to Booty Bay", LF("npc:kravel-koalbeard", "Kravel_Koalbeard")},
            {"Kravel"}, {"place:mirage-raceway", "place:shimmering-flats", "region:54686f7573616e64204e6565646c6573"}),
    })
end

-- notes4 batch 6: names left from notes3's list and the band3050 lane's request.
-- Deliah's note is a discovery from the first clue on ("deliah", LoreDiscoveryData.lua):
-- the ring, then her husband, then her murder.
do
    local STV = "region:537472616e676c6574686f726e2056616c65"
    A.RegisterLoreNotes({
        Note("npc:deliah", "Deliah", "Person",
            "Deliah is the name engraved on a ring found on a woman's hand among the corpse piles of the Rot Hide gnolls in Silverpine Forest. The body bore the marks of the plague but was not long dead, and the Forsaken of the Sepulcher believe the gnolls took it from the mass graves of Tirisfal Glades.\n\nA Deliah lived in Brill not long ago and was buried in its mass grave. Her husband, Raleigh, now dwells in the Trade Quarter of the Undercity, and the ring was hers. He feels nothing for her death any more, he says.\n\nShe was murdered. Raleigh names her killer as Valdred, once his good friend, who was last heard of at the Greymane Wall in southern Silverpine, trying to flee into Gilneas.",
            {V .. " #439 Rot Hide Clues; #440 The Engraved Ring; #441 Raleigh and the Undercity; #530 A Husband's Revenge", LF("item:deliah-s-ring", "Deliah%27s_Ring")},
            nil, {"group:rot-hides", "place:brill", "place:undercity"}, true),
        Note("npc:islen", "Islen Waterseer", "Person",
            "Islen Waterseer is a tauren shaman of the Barrens who guides young shamans of the Horde through the trials of water. Her students travel far for the pure water she asks for, from a plague-tainted shrine on the coast of Silverpine to the fountain of the Ruins of Stardust in Ashenvale, before she rewards them with their next totem.",
            {V .. " #220 Call of Water; #63 Call of Water; #1534 Call of Water", LF("npc:islen-waterseer", "Islen_Waterseer")},
            {"Islen"}, {"place:ruins-of-stardust", "region:5468652042617272656e73"}),
        Note("npc:zalazane", "Zalazane", "Person",
            "Zalazane is a troll witch doctor and warlock who holds the Echo Isles off the coast of Durotar, the isles the Darkspear once called home. Trolls who were once Darkspear now serve him. He sends them to the mainland to hex the tribe and drag more of its people under his sway, traps the souls of those he kills in their own skulls, and corrupts the land's magic with ju-ju heaps among his huts.",
            {V .. " #826 Zalazane; #808 Minshina's Skull; #1884 Ju-Ju Heaps", LF("item:zalazane-s-head", "Zalazane")},
            nil, {"faction:darkspear", "place:echo-isles"}, true),
        Note("npc:hinderweir", "Chief Engineer Hinderweir VII", "Person",
            "Chief Engineer Hinderweir the Seventh keeps the Stonewrought Dam in Loch Modan and its defenses. After the Dark Iron dwarves destroyed the Thandol Span and pillaged Dun Modr, he has no doubt that the dam is their next target, and a strange powder found near it has him sending for an explosives expert.",
            {V .. " #161 A Dark Threat Looms", LF("npc:chief-engineer-hinderweir-vii", "Chief_Engineer_Hinderweir_VII")},
            {"Hinderweir", "Chief Engineer Hinderweir", "Hinderweir VII"}, {"faction:dark-iron", "region:4c6f6368204d6f64616e"}, true),
        Note("npc:longbraid", "Longbraid the Grim", "Person",
            "Longbraid the Grim leads the dwarven regiment that guarded Dun Modr and the Thandol Span in the northern Wetlands. The Dark Iron dwarves ambushed the regiment at the Span and then took Dun Modr before it could regroup. Most of his soldiers were killed, he lost his kin in the attack on the Span, and he sounded the retreat. He keeps watch outside the fallen town and still sends scouts to the excavation teams of the Wetlands.",
            {V .. " #472 Fall of Dun Modr; #305 In Search of the Excavation Team; #378 The Fury Runs Deep", LF("npc:longbraid-the-grim", "Longbraid_the_Grim")},
            {"Longbraid"}, {"place:thandol-span", "faction:dark-iron", "region:5765746c616e6473"}, true),
        Note("npc:hadoken", "Hadoken Swiftstrider", "Person",
            "Hadoken Swiftstrider is a Horde officer at Camp Mojache in Feralas. The Woodpaw gnolls have grown worked up and their attacks too coordinated to be planned without help, so he wants their battle plans found. He also gathers what the Horde learns about the Zukk'ash insects that threaten the camp and sends it to Zilzibin Drumlore in Orgrimmar.",
            {V .. " #2902 Woodpaw Investigation; #2903 The Battle Plans; #7732 Zukk'ash Report", LF("quest:2862", "War_on_the_Woodpaw")},
            {"Hadoken"}, {"place:camp-mojache", "npc:zilzibin", "region:466572616c6173"}),
        Note("npc:belgrom", "Belgrom Rockmaul", "Person",
            "Belgrom Rockmaul is a member of the Horde in Orgrimmar to whom Korran at the Crossroads reports on the insect creatures of the Barrens. Belgrom also hears that more of them erupted from a cave at a dwarven dig site in the Shimmering Flats and nearly killed a Horde raiding party, and he wants them pushed back into whatever depths they crawled from.",
            {V .. " #1145 The Swarm Grows; #1146 The Swarm Grows; #1147 The Swarm Grows", LF("quest:1145", "The_Swarm_Grows")},
            {"Belgrom"}, {"npc:korran", "group:silithid", "region:4f726772696d6d6172"}),
        Note("npc:nazz", "Nazz Steamboil", "Person",
            "Nazz Steamboil is a goblin racing pilot at the Mirage Raceway in Thousand Needles. Rumor at the raceway says that he did not always go by that name, and Kravel Koalbeard wonders why he changed it and how much he would pay to keep the reason quiet.",
            {V .. " #1115 The Rumormonger; #1117 Rumors for Kravel", LF("quest:1115", "The_Rumormonger")},
            {"Nazz"}, {"place:mirage-raceway", "npc:kravel"}),
        Note("npc:crank-fizzlebub", "Crank Fizzlebub", "Person",
            "Crank Fizzlebub is a goblin of Booty Bay with an interest in the races of the Mirage Raceway. He likes Kravel Koalbeard's sinister mind and joins his risky scheme, which calls for something powerful enough to addle the wits of a racing crew before the next race.",
            {V .. " #1118 Back to Booty Bay; #1122 Report Back to Fizzlebub", LF("quest:1118", "Back_to_Booty_Bay")},
            {"Fizzlebub"}, {"place:booty-bay", "npc:kravel", "place:mirage-raceway"}),
        Note("npc:mukla", "King Mukla", "Person",
            "King Mukla is the great Skymane king of an island off the coast of Stranglethorn. He commands the island's beasts, and with their help he keeps a captive chained there against her will.",
            {V .. " #630 Message in a Bottle", LF("quest:630", "Message_in_a_Bottle")},
            {"Mukla"}, {STV}),
    })
end

-- Fifth notes lane (notes5), 2026-11-06. People the 40-60 and end-game scenes name most
-- often without a note. Batch 1: Tanaris, Felwood, Silithus, the Plaguelands' key to
-- Scholomance, the Burning Steppes and Searing Gorge, the Blasted Lands. The Fallen Hero's
-- account, Kalaran's true form and Bijou's double dealing are discoveries
-- (LoreDiscoveryData.lua, "fallenhero", "kalaran", "bijou"). "Fizzle" alone names two
-- people and stays unlinked; Greta, Aurel, Bijou, Katar and Viktori stay out as words or
-- given names a player could carry.
do
    local BL, SOS = "region:426c6173746564204c616e6473", "region:5377616d70206f6620536f72726f7773"
    local WPL = "region:5765737465726e20506c616775656c616e6473"
    A.RegisterLoreNotes({
        Note("npc:bilgewhizzle", "Chief Engineer Bilgewhizzle", "Person",
            "Chief Engineer Bilgewhizzle is a goblin of the Gadgetzan Water Company in Tanaris. The Wastewander nomads have seized nearly every water well in the desert, and without them the company's supply would soon run dry. He pays for the deaths of their bandits, thieves, rogues and shadow mages, and the company's wanted notice puts a high bounty on their leader, Caliph Scorpidsting.\n\nHe keeps Gadgetzan's model 4711-FTZ power sources, which normally run the water wells, and parts with one only for a price paid in water. His cherished divino-matic rod shows him where to dig new water holes. Sergeant Bly said he would only borrow it, then took it treasure hunting in Zul'Farrak.",
            {V .. " #1690 Wastewander Justice; #1691 More Wastewander Justice; #2781 WANTED: Caliph Scorpidsting; #243 Into the Field; #379 Slake That Thirst; #2768 Divino-matic Rod", LF("quest:1690", "Chief_Engineer_Bilgewhizzle")},
            {"Bilgewhizzle"}, {"place:gadgetzan", "group:gadgetzan-water-company", "npc:sergeant-bly"}),
        Note("npc:greta-mosshoof", "Greta Mosshoof", "Person",
            "Greta Mosshoof is a tauren druid of the Emerald Circle at the Emerald Sanctuary in southern Felwood, where she works against the corruption eating the forest. She holds the Shadow Council in Jaedenar responsible for many of its evils. A newcomer must first strike at the Council in its barrow dens before she offers her trust, since the blood shed both weakens the cult and earns respect.\n\nShe looks for clean water as well as enemies. She sends scouts north to Shatter Scar Vale to learn whether its craters still hold the foul water left by the infernals of the last great war. Water taken from the moonwell of Jaedenar goes to her old friend Islen Waterseer on the coast of the Barrens to be purified, and she means to use it against the braziers that shield Shadow Hold from her scrying. The parts of a cure for the corruption, gathered with the help of the Cenarion Circle, are brought to her as well.",
            {V .. " #5155 Forces of Jaedenar; #5156 Verifying the Corruption; #5157 Collection of the Corrupt Water; #5158 Seeking Spiritual Aid; #5165 Dousing the Flames of Protection; #8257 Blood of Morphaz", LF("npc:greta-mosshoof", "Greta_Mosshoof")},
            nil, {"place:jaedenar", "faction:shadow-council", "npc:islen", "region:46656c776f6f64"}),
        Note("npc:marvon", "Marvon Rivetseeker", "Person",
            "Marvon Rivetseeker is a goblin scientist and treasure hunter who has studied many ancient places. He left his workshop in Ratchet long ago to study the troll ruins of Tanaris and has not been heard from in some time. In the desert he gathers Gahz'ridian, the material of ornaments the trolls once carved in honor of the hydra Gahz'rilla, and he lends a detector helmet of his own making to find them.\n\nMarvon has seen the Sunken Temple with his own eyes and barely came out of it. His memory of the place is cloudy, but a serpent-marked stone in his workshop brings it back, and he speaks of a round chamber of serpent statues around an altar that holds the key to a guarded treasure. In Ratchet his apprentice has been left to carry on with experiments alone.",
            {V .. " #3161 Gahz'ridian; #3380 The Sunken Temple; #3445 The Sunken Temple; #3444 The Stone Circle; #3446 Into the Depths; #3447 Secret of the Circle; #4147 Marvon's Workshop; #4502 Volcanic Activity", LF("quest:3445", "Marvon_Rivetseeker")},
            {"Marvon"}, {"place:ratchet", "dungeon:atalhakkar", "npc:gahzrilla", "region:54616e61726973"}),
        Note("npc:bijou", "Operative Bijou", "Person",
            "Operative Bijou is a goblin agent of the Kargath Expeditionary Force, the Horde's force at Kargath in the Badlands. She works inside Blackrock Spire, sneaking through the orc city at night while the guard is light and writing down anything of strategic value to the K.E.F. Her reports go to Grandmaster Lexlort, head of its reconnaissance division.\n\nLexlort has learned that she also works for Kibler, a dealer in exotic pets from the Burning Steppes, and pays for her operations with Horde funds. Bijou admits that she needed the money and that Kibler pays far better than the K.E.F., but she insists that her loyalty never wavered, and she means to redeem her name with her reconnaissance report.",
            {V .. " #4981 Operative Bijou; #4982 Bijou's Belongings; #4983 Bijou's Reconnaissance Report"},
            {"Operative Bijou"}, {"npc:lexlort", "dungeon:blackrock-spire", "place:kargath", "npc:kibler"}),
        Note("npc:lexlort", "Grandmaster Lexlort", "Person",
            "Grandmaster Lexlort heads the reconnaissance division of the Kargath Expeditionary Force, which Warlord Goretooth commands from Kargath in the Badlands. He has found where the high-ranking officials of the Dark Iron dwarves train their forces, behind a locked gate near the heart of their city in Blackrock Depths. His agents inside Blackrock Spire report on the Blackrock orcs, and in his view a goblin is never to be trusted.",
            {V .. " #4082 KILL ON SIGHT: High Ranking Dark Iron Officials; #4981 Operative Bijou; #4983 Bijou's Reconnaissance Report"},
            {"Lexlort"}, {"place:kargath", "npc:bijou", "dungeon:blackrock-spire"}),
        Note("npc:kalaran", "Kalaran Windblade", "Person",
            "Kalaran Windblade keeps a camp in the Searing Gorge, southeast of Thorium Point. By his own account he seeks vengeance on the Dark Iron dwarves for the death of his father, and Stormwind would not hear his plea. He means to strike where it will hurt most, at the four sentry towers of the Dark Irons. To set them ablaze he has a torch made from hearts of flame, golem oil, the thorium of Dark Iron daggers and the magic of a Twilight's Hammer symbol of Ragnaros. His envoy, Squire Maltrake, explains its use.\n\nKalaran is not what he claims. The account of his father was a lie. Once the towers burn, he takes his true form, a black drake, and flies off toward Blackrock Mountain, leaving Squire Maltrake to hand out his reward.",
            {V .. " #3441 Divine Retribution; #3442 The Flawless Flame; #3443 Forging the Shaft; #3452 The Flame's Casing; #3453 The Torch of Retribution; #3462 Squire Maltrake", LF("quest:3441", "Kalaran_Windblade"), "https://warcraft.wiki.gg/wiki/Kalaran_Windblade (the false account and his true form after #3463)"},
            {"Kalaran"}, {"npc:maltrake", "faction:dark-iron", "region:53656172696e6720476f726765"}),
        Note("npc:maltrake", "Squire Maltrake", "Person",
            "Squire Maltrake is Kalaran Windblade's envoy in the Searing Gorge. He explains the use of the torch of retribution. The four Dark Iron sentry towers can never be destroyed, he says, but the torch sets them burning with a fire no element or force can put out, and while they burn no guard can hold the watch posts.",
            {V .. " #3462 Squire Maltrake; #3463 Set Them Ablaze!", LF("quest:3462", "Squire_Maltrake")},
            {"Maltrake"}, {"npc:kalaran", "faction:dark-iron", "region:53656172696e6720476f726765"}),
        Note("npc:aurel-goldleaf", "Aurel Goldleaf", "Person",
            "Aurel Goldleaf is a craftswoman in the eastern part of Cenarion Hold in Silithus. The Cenarion Circle has learned that the Abyssal Council controls the Twilight's Hammer through the wind stones in the cult's camps, and her skill serves the effort to strike at it. From brilliant shards and the crests and signets of the cult's own officers she makes copies of its insignia, a medallion of station and a ring of lordship, so that the wearer can pass for a ranking member of the Twilight's Hammer at the stones. She also makes the colors of a twilight emissary, in the hope that the stones can carry someone to the place where the cult's plans are made.",
            {V .. " #8331 Aurel Goldleaf; #8332 Dukes of the Council; #8341 Lords of the Council; #8343 Goldleaf's Discovery; #8829 The Ultimate Deception"},
            {"Goldleaf"}, {"place:cenarion-hold", "group:twilights-hammer", "npc:bor-wildmane", "region:53696c6974687573"}),
        Note("npc:dithers", "Apothecary Dithers", "Person",
            "Apothecary Dithers is a Forsaken apothecary at the Bulwark, the Forsaken line at the edge of the Western Plaguelands. Shadow Priestess Vandis sends him samples of the Scourge's cauldron poisons, from which he makes counteragents to weaken the undead. He has also made a study of Scholomance, the Scourge school on Caer Darrow, whose door no one can pass without a key. His plan is a skeleton key forged from the bones of many skeletons in a mold made by Krinkle Goodsteel of Gadgetzan and finished with the signet of a being who can open the way. He admits he is no banker.",
            {V .. " #838 Scholomance; #964 Skeletal Fragments; #5514 Mold Rhymes With...; #5802 Fire Plume Forged; #5804 Araj's Scarab; #5230 Return to the Bulwark", LF("quest:5802", "Apothecary_Dithers")},
            {"Dithers"}, {"place:bulwark", "npc:vandis", "dungeon:scholomance", WPL}),
        Note("npc:arbington", "Alchemist Arbington", "Person",
            "Alchemist Arbington is an alchemist at Chillwind Camp, the Alliance base in the Western Plaguelands. He has made a study of Scholomance, the Scourge school on Caer Darrow, and of the key needed to pass its door. The key is to be forged from the bones of many skeletons and hardened with thorium in a mold from Krinkle Goodsteel of Gadgetzan, and it works only once a signet is set in it, the scarab of Araj the Summoner. He also works out the reagents that High Priestess MacDonnell's campaign against the Scourge's plague cauldrons needs.",
            {V .. " #5533 Scholomance; #5537 Skeletal Fragments; #5538 Mold Rhymes With...; #5801 Fire Plume Forged; #5803 Araj's Scarab", LF("quest:5801", "Alchemist_Arbington")},
            {"Arbington"}, {"place:chillwind", "dungeon:scholomance", "npc:araj", WPL}),
        Note("npc:araj", "Araj the Summoner", "Person",
            "Araj the Summoner is a lich who rules the ruined city of Andorhal from its center. He once led Scholomance, the Scourge school on Caer Darrow, before he claimed the city as his own. Ranks of Scourge ring the heart of Andorhal, and a retinue of guardians attends him. His signet, a scarab, is the piece that the makers of a key to Scholomance need most.",
            {V .. " #211 Alas, Andorhal; #105 Alas, Andorhal; #5803 Araj's Scarab; #5804 Araj's Scarab"},
            {"Araj"}, {"place:andorhal", "dungeon:scholomance", "faction:scourge", WPL}),
        Note("npc:valorfist", "Commander Ashlam Valorfist", "Person",
            "Commander Ashlam Valorfist leads Chillwind Camp, the Alliance base in the Western Plaguelands north of the Alterac Mountains. Stormwind's call to arms against the Scourge sends volunteers to him. He means to take Andorhal, whose western and northern roads are well fortified, by the weaker eastern road through Sorrow Hill, and he wants the lich who rules the city, Araj the Summoner, destroyed.",
            {V .. " #5066 A Call to Arms: The Plaguelands!; #5090 A Call to Arms: The Plaguelands!; #5092 Clear the Way; #211 Alas, Andorhal"},
            {"Valorfist", "Ashlam Valorfist", "Commander Valorfist"}, {"place:chillwind", "place:andorhal", "npc:araj", WPL}),
        Note("npc:oralius", "Oralius", "Person",
            "Oralius is an Alliance officer at Morgan's Vigil in the Burning Steppes. He wages his own campaign against the Firegut ogres, allies of the Blackrock orcs who guard Dreadmaul Rock and keep its supply lines open. For the third phase of his attack he had the head of their brute lord, Gor'tesh, set on a pike at the top of the rock.\n\nOralius collects ogre ears and orc badges, insists that he is the only sane one in camp, and confides in Captain Winky, a pal he grabs at in the empty air.",
            {V .. " #3823 Extinguish the Firegut; #3824 Gor'tesh the Brute Lord; #3825 Ogre Head On A Stick = Party; #4283 FIFTY! YEP!; #4286 The Good Stuff"},
            nil, {"place:morgans-vigil", "faction:firegut", "region:4275726e696e672053746570706573"}, true),
        Note("npc:duthorian-rall", "Duthorian Rall", "Person",
            "Duthorian Rall is a paladin of the Silver Hand and one of the most influential in Stormwind. He spends most of his time in the Cathedral of Light, where he trains paladins through the Tomes of Divinity, Valor and Nobility, and paladins in the field send promising students to him. He warns that a test of valor can cost a life. One such test sends the petitioner to the Longshore of Westfall, where Daphne Stilwell lives alone while her husband Jordan, a smith, works with the dwarves of Ironforge.",
            {V .. " #2998 Tome of Divinity; #3681 Tome of Divinity; #1649 The Tome of Valor; #1650 The Tome of Valor; #4485 The Tome of Nobility; #4486 The Tome of Nobility", LF("npc:duthorian-rall", "Duthorian_Rall")},
            {"Rall"}, {"place:cathedral-of-light", "faction:silver-hand"}),
        Note("npc:fizzle-darkstorm", "Fizzle Darkstorm", "Person",
            "Fizzle Darkstorm is a goblin warlock of the Burning Blade who has camped in Thunder Ridge in northwestern Durotar. He and his cultists spread chaos there, and the Horde will not allow the cult a foothold in its lands.",
            {V .. " #806 Dark Storms"},
            nil, {"faction:burning-blade", "place:thunder-ridge", "region:4475726f746172"}),
        Note("npc:fizzle-brassbolts", "Fizzle Brassbolts", "Person",
            "Fizzle Brassbolts is the gnome engineer of the gnomish racing team at the Mirage Raceway in Thousand Needles. He has more designs for the team's rocket car than he can try. He wants a fuel that burns hot enough to make the car fly, brewed from the salty venom of the scorpids of the Shimmering Flats, and pistons strong enough for a new engine, for which he seeks the advice of the smith Martek the Exiled in the Badlands. Parts he orders have a way of coming up a little short. His brother Wizzle works on the car with him.",
            {V .. " #1104 Salt Flat Venom; #1105 Hardened Shells; #1106 Martek the Exiled; #1114 Delivery to the Gnomes", LF("npc:fizzle-brassbolts", "Fizzle_Brassbolts")},
            nil, {"place:mirage-raceway", "npc:pozzik", "region:54686f7573616e64204e6565646c6573"}),
        Note("npc:krusk", "Krusk", "Person",
            "Krusk is an orc warrior at Tarren Mill in the Hillsbrad Foothills. The Warchief sent him with others to Durnholde to recover an object and look into the Syndicate. A large force of humans overwhelmed them there. Krusk escaped, but Drull and Tog'thar were taken captive, and Gol'dir, who led the expedition, was carried off to another Syndicate camp. From Tarren Mill he searches for the missing and watches the Syndicate's leaders, among them Lord Aliden Perenolde, who means to make slaves of the orcs.",
            {V .. " #498 The Rescue; #533 Infiltration; #503 Gol'dir; #506 Blackmoore's Legacy; #507 Lord Aliden Perenolde", LF("npc:krusk", "Krusk")},
            nil, {"place:tarren-mill", "place:durnholde", "npc:gol-dir", "faction:syndicate"}, true),
        Note("npc:maleb", "Magistrate Henry Maleb", "Person",
            "Magistrate Henry Maleb governs Southshore in the Hillsbrad Foothills. He took office after his predecessor was assassinated. The killers were never found, but his investigations point to the Syndicate, a band of thieves led by nobles of the fallen kingdom of Alterac, and he sends Southshore's allies against its camps north of Tarren Mill and in the ruins of Strahnbrad. He expects the Syndicate to come for him as it came for the last magistrate.",
            {V .. " #505 Syndicate Assassins; #510 Foreboding Plans; #512 Noble Deaths; #522 Assassin's Contract", LF("npc:magistrate-henry-maleb", "Magistrate_Henry_Maleb")},
            {"Maleb", "Henry Maleb", "Magistrate Maleb"}, {"place:southshore", "faction:syndicate", "region:48696c6c736272616420466f6f7468696c6c73"}),
        Note("npc:latronicus", "Latronicus Moonspear", "Person",
            "Latronicus Moonspear is a night elf officer at Feathermoon Stronghold in Feralas and second in command to General Shandris Feathermoon. He watches the Hatecrest naga on Sardor Isle and expects them to try to take the island for their own, so he means to weaken them first. Scouts have shown him their chain of command, headed by naga royalty. His wife, Vestia Moonspear, is a priestess of the stronghold and one of its most learned scholars. He also seeks the web that the blood elf Lethtendris made in Dire Maul to snare the magic of that place.",
            {V .. " #3130 Against the Hatecrest; #2869 Against the Hatecrest; #2870 Against Lord Shalzaru; #2871 Delivering the Relic; #4124 The Missing Courier; #7488 Lethtendris's Web", LF("quest:2869", "Latronicus_Moonspear")},
            {"Latronicus"}, {"place:feathermoon", "npc:shandris", "npc:lethtendris", "region:466572616c6173"}),
        Note("npc:strahad", "Strahad Farsan", "Person",
            "Strahad Farsan is a human warlock who keeps a tower with his acolytes on the bluff above Ratchet in the Barrens. Warlock teachers of both Horde and Alliance count him among their inner circle and send him their students when the time comes for greater summonings, the felhunter and the felsteed. The orb maker Menara Voidrender stays at his tower. He is powerful and should be respected, one of them warns, and he is no enemy, at least for now.",
            {V .. " #1798 Seeking Strahad; #3001 Seeking Strahad; #3631 Summon Felsteed; #4487 Summon Felsteed; #4490 Summon Felsteed; #4736 In Search of Menara Voidrender", LF("npc:strahad-farsan", "Strahad_Farsan")},
            {"Strahad"}, {"place:ratchet", "npc:menara", "region:5468652042617272656e73"}),
        Note("npc:viktori", "Viktori Prism'Antras", "Person",
            "Viktori Prism'Antras lives above Darkshire in Duskwood. He believes that a truth beyond magic can explain the strange change in the forest, and he is building a device to look at the stars from a blueprint by his gnome friend Cog. It needs a bronze tube from a skilled engineer, the looking glass of a woman named Mary who once lived in southern Duskwood, and a lens as large as the monocle of the ogre Zzarc'Vul.",
            {V .. " #174 Look to the Stars; #175 Look to the Stars; #177 Look to the Stars; #181 Look to the Stars", LF("npc:viktori-prism-antras", "Viktori_Prism%27Antras")},
            nil, {"place:darkshire", "region:4475736b776f6f64"}),
        Note("npc:katar", "Katar", "Person",
            "Katar keeps Stonard's watch on the coast of the Swamp of Sorrows, where he patrols the beach against the murlocs. He has no love for the sea or anything that comes out of it, and he takes pleasure in seeing the fish men die at the hands of those who serve the Horde.",
            {V .. " #1422 Threat From the Sea; #1426 Threat From the Sea; #1428 Continued Threat", LF("quest:1426", "Katar")},
            nil, {"npc:tokkar", "place:stonard", SOS}),
        Note("npc:tokkar", "Tok'Kar", "Person",
            "Tok'Kar is a weaponsmith of Stonard's watch on the coast of the Swamp of Sorrows. He forges weapons for the fight against the murlocs of the beach and would rather see the Horde's helpers keep their wits sharp than drink with the louses of the camp.",
            {V .. " #1422 Threat From the Sea; #1427 Threat From the Sea", LF("quest:1422", "Tok%27Kar")},
            nil, {"npc:katar", "place:stonard", SOS}, true),
        Note("npc:kumisha", "Kum'isha the Collector", "Person",
            "Kum'isha the Collector is a draenei in the Blasted Lands. Draenei have spent lifetimes searching for a flawless sphere of draenethyst, and many met terrible ends without finding one. Kum'isha hopes such a sphere could take him home and promises riches to whoever brings one. Flawed fragments are of less use to that purpose, but he trades his own junk for them all the same, and he makes no secret of his disgust at the greed of those who bring them.",
            {V .. " #2521 To Serve Kum'isha; #3501 Everything Counts In Large Amounts; #3502 One Draenei's Junk..."},
            {"Kum'isha"}, {BL}),
        Note("npc:razelikh", "Razelikh the Defiler", "Person",
            "Razelikh the Defiler is the demon lord who rules the Blasted Lands. Three lieutenants serve him there, Archmage Allistarj, Lady Sevine and Grol the Destroyer of the Dreadmaul ogres, and in return for their service he has given them great power within his lands. His lair stands atop the highest mountain of the Blasted Lands and can be reached only by teleport runes near its foot. Some of the Alliance who fight there warn that this power keeps growing while Horde and Alliance squabble over scorched earth.",
            {V .. " #2743 The Cover of Darkness; #2744 The Demon Hunter; #3627 Uniting the Shattered Amulet; #3628 You Are Rakh'likh, Demon; #2783 Petty Squabbles", LF("quest:3625", "Razelikh_the_Defiler")},
            {"Razelikh", "the Defiler"}, {"faction:dreadmaul", "faction:burning-legion", BL}),
        Note("npc:fallen-hero", "Fallen Hero of the Horde", "Person",
            "The Fallen Hero of the Horde is a spirit who keeps watch on the southern road of the Swamp of Sorrows, at the threshold of the Blasted Lands. He is bound there by regret over one bad decision and by the orders he never received, and he waits for word of them still. He knows the truth of the Blasted Lands, and some of the Alliance who fight there urge their own to set old enmity aside and hear him.\n\nIn life he commanded a Horde regiment, Thrall's Grasp, sent into the Blasted Lands. He led it south without waiting for the orders, which never reached him because the Swamp Talker's murlocs ambushed the soldiers carrying them. The regiment was destroyed. He and his lieutenant, Kirith, were imprisoned and tortured by Archmage Allistarj, and the souls of his men were bound in stones held by Razelikh and his servants. As a spirit he is powerless, and he asks others to free his men and win back his honor.\n\nHis name is Trebor. Kirith knows him by it.",
            {V .. " #2621 The Disgraced One; #2622 The Missing Orders; #2623 The Swamp Talker; #2784 Fall From Grace; #2801 A Tale of Sorrow; #2681 The Stones That Bind Us; #2721 Kirith; #2743 The Cover of Darkness; #2783 Petty Squabbles", LF("npc:fallen-hero-of-the-horde", "Fallen_Hero_of_the_Horde")},
            {"the Fallen Hero", "Fallen Hero", "the Fallen Hero of the Horde"}, {"region:5377616d70206f6620536f72726f7773", "place:stonard", BL}),
    })
end

-- notes5 batch 2: Gadgetzan and Booty Bay, Stranglethorn's rebels and hunters, Arathi,
-- the Badlands and Kargath, the Hinterlands, Feralas, Dire Maul and two craftsmen of the
-- dwarven cities. Hammertoe's survival stays out of Ryedol's and Karnik's notes; Itharius
-- and the Atal'ai exile are told only as far as the first quest that names them.
do
    local TAN, STV = "region:54616e61726973", "region:537472616e676c6574686f726e2056616c65"
    local BAD = "region:4261646c616e6473"
    A.RegisterLoreNotes({
        Note("npc:marin", "Marin Noggenfogger", "Person",
            "Marin Noggenfogger is a goblin of Gadgetzan in Tanaris who suffers from a terrible thirst. He heard that the dew collectors of the cactus garden southwest of town store water in special glands, and he set out to brew a drink from their dew. It tasted awful until his friend Sprinkle, the town's chef, added her secret ingredient, a powder of the Violet Tragan mushroom. The result is the Noggenfogger Elixir, which he means to sell by the million.",
            {V .. " #2605 The Thirsty Goblin; #2606 In Good Taste; #2641 Sprinkle's Secret Ingredient; #2661 Delivery for Marin; #2662 Noggenfogger Elixir", LF("quest:2605", "Marin_Noggenfogger")},
            {"Noggenfogger", "Marin"}, {"place:gadgetzan", "npc:sprinkle", TAN}),
        Note("npc:sprinkle", "Sprinkle", "Person",
            "Sprinkle is a goblin chef in Gadgetzan. Her sister did all the cooking when she was a child, and it was so bad that Sprinkle found a secret ingredient to make anything taste good, the Violet Tragan mushroom. Her powder of it turned Marin Noggenfogger's dew into his elixir, and she expects a favor in return.",
            {V .. " #2606 In Good Taste; #2641 Sprinkle's Secret Ingredient; #2661 Delivery for Marin", LF("quest:2606", "Sprinkle")},
            nil, {"place:gadgetzan", "npc:marin", TAN}, true),
        Note("npc:krinkle", "Krinkle Goodsteel", "Person",
            "Krinkle Goodsteel is a goblin smith in Gadgetzan who sells his skills to the highest bidder. He keeps a ledger of goods he wants from the Searing Gorge and other distant places, and he is the one smith able to make the mold for a skeleton key to Scholomance, for a steep fee. The mold must be dipped in the lava lake atop Fire Plume Ridge in Un'Goro Crater, which is hot enough to fuse thorium and bone.",
            {V .. " #4450 Ledger from Tanaris; #5514 Mold Rhymes With...; #5538 Mold Rhymes With...; #5801 Fire Plume Forged; #5802 Fire Plume Forged", LF("quest:4450", "Krinkle_Goodsteel")},
            {"Krinkle", "Goodsteel"}, {"place:gadgetzan", "dungeon:scholomance", "place:fire-plume", TAN}),
        Note("npc:tranrek", "Tran'rek", "Person",
            "Tran'rek is a goblin in Gadgetzan who trades in the shells of the Tanaris scarabs. They are hard enough to build with, so useful that the scarabs were hunted nearly to extinction, and he knows where more of them live. He owes a cousin across the sea a load of the shells, weeks overdue. He also wants to get into Thistleshrub Valley, though he does not trust its gnarled thistleshrubs and rootshapers for a minute.",
            {V .. " #2864 Tran'rek; #2865 Scarab Shells; #3362 Thistleshrub Valley", LF("quest:3362", "Tran%27rek")},
            nil, {"place:gadgetzan", TAN}, true),
        Note("npc:stoley", "Stoley", "Person",
            "Stoley tends the bar at Steamwheedle Port in Tanaris. He bet Sea Wolf MacKinley of Booty Bay a special bottle of rum that the port's rum is stronger than anything found in Booty Bay, and promised to double the money he owes if MacKinley disagreed. Captain Cuergo's pirates stole his last shipment and took it to their walled town to the south.",
            {V .. " #2872 Stoley's Debt; #2873 Stoley's Shipment; #2874 Deliver to MacKinley", LF("quest:2872", "Stoley")},
            nil, {"place:steamwheedle-port", "npc:mackinley", TAN}),
        Note("npc:mackinley", "Sea Wolf MacKinley", "Person",
            "Sea Wolf MacKinley is a gambler of Booty Bay who cannot stand people who do not pay their debts, and many owe him. Shaky Phillipe on the docks is one of them. Another is Stoley, the barkeep of Steamwheedle Port in Tanaris, who owes him a bottle of rum over a bet about whose port pours the stronger drink.",
            {V .. " #606 Scaring Shaky; #607 Return to MacKinley; #2872 Stoley's Debt; #2874 Deliver to MacKinley", LF("quest:607", "Sea_Wolf_MacKinley")},
            {"MacKinley"}, {"place:booty-bay", "npc:stoley", STV}),
        Note("npc:smotts", "Captain Hecklebury Smotts", "Person",
            "Captain Hecklebury Smotts once sailed a ship between Booty Bay and Ratchet and had a sterling reputation. Three sea giants of the Stranglethorn coast, Gorlash, Mok'rash and Negolash, ruined him. They smashed his first ship and killed its crew, and when he set out after them in a second ship, Smotts' Revenge, they smashed that too. He came back to Booty Bay in a lifeboat both times, and each giant kept something of his, his chest, his monogrammed sash and his cutlass.",
            {V .. " #8551 The Captain's Chest; #8552 The Monogrammed Sash; #8553 The Captain's Cutlass", LF("quest:8551", "Captain_Hecklebury_Smotts")},
            {"Smotts", "Hecklebury Smotts", "Captain Smotts"}, {"place:booty-bay", STV}),
        Note("npc:barnil", "Barnil Stonepot", "Person",
            "Barnil Stonepot is a dwarf of Hemet Nesingwary's hunting camp in Stranglethorn and one of the companions named in Nesingwary's novel, The Green Hills of Stranglethorn. He greets newcomers to the camp, and Nesingwary trusted him to proofread the manuscript until a gust of wind scattered it across the jungle. He expects the finished book to stand in libraries throughout the world.",
            {V .. " #583 Welcome to the Jungle; #338 The Green Hills of Stranglethorn; #339 Chapter I; #342 Chapter IV", LF("quest:338", "Barnil_Stonepot")},
            {"Barnil"}, {"npc:hemet-nesingwary", "place:nesingwarys-expedition", STV}),
        Note("npc:nimetz", "Brother Nimetz", "Person",
            "Brother Nimetz is a priest at the Rebel Camp in northern Stranglethorn. He remembers Colonel Kurzen as a great and noble man and wants to learn what drove him to depravity. Suspecting troll magic, he studies the legends on the tablets of Stranglethorn's troll ruins and the fetishes of the Skullsplitter witchdoctors.",
            {V .. " #207 Kurzen's Mystery; #205 Troll Witchery", LF("quest:207", "Brother_Nimetz")},
            {"Nimetz"}, {"place:rebel-camp", "npc:kurzen", STV}),
        Note("npc:yohwa", "Sergeant Yohwa", "Person",
            "Sergeant Yohwa leads the fighting at the Rebel Camp in northern Stranglethorn against Colonel Kurzen, who outnumbers the rebels at least ten to one and is a brilliant tactician. Yohwa turns Kurzen's own covert tactics against him, striking at his camp, his medicine men and finally the trained forces he keeps in the Stockpile at the back of the Kurzen Compound. He knows many of those soldiers personally.",
            {V .. " #203 The Second Rebellion; #204 Bad Medicine; #574 Special Forces", LF("quest:203", "Sergeant_Yohwa")},
            {"Yohwa"}, {"place:rebel-camp", "npc:kurzen", STV}),
        Note("npc:obreen", "Shakes O'Breen", "Person",
            "Shakes O'Breen is the captain of a Blackwater Raiders crew that has put in at Faldir's Cove on the coast of the Arathi Highlands. They came for a lost elven treasure sunk in the dark sea and meant to stay only a few hours, but two ships of their formation, the Spirit of Silverpine and the Maiden's Folly, went down, and the Daggerspine naga gather to attack. The crew cannot sail back to Booty Bay without his knowledge of the seas.",
            {V .. " #663 Land Ho!; #665 Sunken Treasure; #667 Death From Below; #669 Sunken Treasure", LF("quest:663", "Shakes_O%27Breen")},
            {"O'Breen", "Captain O'Breen"}, {"place:faldirs-cove", "faction:blackwater-raiders", "npc:seahorn"}),
        Note("npc:kryten", "Apprentice Kryten", "Person",
            "Apprentice Kryten works at Refuge Pointe in the Arathi Highlands for Archmage Malin of Stormwind, who sent him and Skuerto to collect reagents. Malin's old master, Archmage Trelane, defended the Tower of Arathor when Stromgarde fell and left items there, and Kryten gathers what is needed to reach them, starting with Witherbark tusks, medicine pouches and a shadow hunter's knife.",
            {V .. " #691 Worth Its Weight in Gold; #690 Malin's Request; #694 Trelane's Defenses; #697 Malin's Request", LF("quest:691", "Apprentice_Kryten")},
            {"Kryten"}, {"place:refuge-pointe", "npc:archmage-malin", "place:stromgarde"}),
        Note("npc:zardeth", "Zardeth of the Black Claw", "Person",
            "Zardeth of the Black Claw is a warlock who keeps a hidden establishment beneath the Slaughtered Lamb in Stormwind's Mage Quarter, where the city's warlocks practice their arts. Lord Wishock has learned of it and lobbies the House of Nobles for an investigation, though he spends his own nights upstairs drinking on credit he never pays. Zardeth means to keep him busy with a special brew, Black Claw stout. His servant Zggi hands out his rewards.",
            {V .. " #335 A Noble Brew; #336 A Noble Brew; #397 You Have Served Us Well", LF("npc:zardeth-of-the-black-claw", "Zardeth_of_the_Black_Claw")},
            {"Zardeth"}, {"place:mage-quarter", "region:53746f726d77696e642043697479"}),
        Note("npc:furen", "Furen Longbeard", "Person",
            "Furen Longbeard is a dwarven armorsmith in Stormwind's Dwarven District whose skill other dwarves admire, enough that Mountaineer Stormpike wants a shield of his making and wonders why he lives so far from Ironforge. He knows the secrets of fire-hardened mail and shares the techniques he learns with other smiths, among them Grimand Elmore in the district's weapon shop and Klockmort Spannerspan in Ironforge.",
            {V .. " #1338 Stormpike's Order; #1700 Grimand Elmore; #1701 Fire Hardened Mail; #1704 Klockmort Spannerspan", LF("npc:furen-longbeard", "Furen_Longbeard")},
            {"Furen"}, {"place:dwarven-district", "npc:grimand-elmore", "npc:klockmort"}),
        Note("npc:klockmort", "Klockmort Spannerspan", "Person",
            "Klockmort Spannerspan is a gnome blacksmith who works deep in Ironforge among the gnomes who fled Gnomeregan. He is keen on new smithing techniques, and Furen Longbeard of Stormwind sends him what he has learned. His experiments also need parts that can only be found in Gnomeregan.",
            {V .. " #1704 Klockmort Spannerspan; #2924 Essential Artificials", LF("quest:2924", "Klockmort_Spannerspan")},
            {"Klockmort"}, {"place:tinker-town", "npc:furen", "dungeon:gnomeregan"}),
        Note("npc:felzerul", "Fel'Zerul", "Person",
            "Fel'Zerul leads the Horde's investigation of the Temple of Atal'Hakkar from Stonard in the Swamp of Sorrows. The Warchief sent him to look into strange happenings at the temple of the Atal'ai, a tribe of dark casters who practice forbidden magic. His party found the temple sunk and the green dragons guarding the site, and from Atal'ai artifacts found around the Pool of Tears he tries to learn what the trolls meant to do and what went wrong.",
            {V .. " #1424 Pool of Tears; #1444 Return to Fel'Zerul; #1445 The Temple of Atal'Hakkar", LF("quest:1424", "Fel%27Zerul")},
            {"Fel'zerul"}, {"place:stonard", "dungeon:atalhakkar", "group:atalai"}, true),
        Note("npc:ryedol", "Prospector Ryedol", "Person",
            "Prospector Ryedol works for the Explorers' League in the Badlands, south of Hammertoe's Digsite. He escaped an attack on his dig site by Dark Iron dwarves who look like the Shadowforge clan, and lost his lucky pick there. His partner, Prospector Hammertoe, was searching Uldaman for the origins of the dwarves and set himself against the Shadowforge as well.",
            {V .. " #719 A Dwarf and His Tools; #723 Prospect of Faith", LF("npc:prospector-ryedol", "Prospector_Ryedol")},
            {"Ryedol"}, {"place:hammertoes-digsite", "dungeon:uldaman", BAD}),
        Note("npc:karnik", "Historian Karnik", "Person",
            "Historian Karnik is a scholar of the Explorers' League in Ironforge who worked with Prospector Hammertoe to find the lost artifacts of Uldaman. The Shadowforge clan of the Dark Iron dwarves seeks the same artifacts to use against Ironforge, and Karnik sends word of that threat to Advisor Belgrum, who answers on the king's authority.",
            {V .. " #724 Prospect of Faith; #725 Passing Word of a Threat; #726 Passing Word of a Threat; #762 An Ambassador of Evil"},
            {"Karnik"}, {"dungeon:uldaman", "npc:ryedol", "region:49726f6e666f726765"}),
        Note("npc:goretooth", "Warlord Goretooth", "Person",
            "Warlord Goretooth commands the Kargath Expeditionary Force from Kargath in the Badlands, where he keeps watch on the Dark Iron dwarves and Blackrock Mountain. His orders call for the destruction of General Angerforge's forces in Blackrock Depths, who slaughtered the K.E.F.'s 109th division, and of the masters of Blackrock Spire, Highlord Omokk, War Master Voone and Overlord Wyrmthalak.",
            {V .. " #4081 KILL ON SIGHT: Dark Iron Dwarves; #4082 KILL ON SIGHT: High Ranking Dark Iron Officials; #4132 Operation: Death to Angerforge; #4903 Warlord's Command", LF("npc:warlord-goretooth", "Warlord_Goretooth")},
            {"Goretooth"}, {"place:kargath", "npc:lexlort", "dungeon:blackrock-depths"}),
        Note("npc:jarkal", "Jarkal Mossmeld", "Person",
            "Jarkal Mossmeld is an alchemist of Kargath in the Badlands, one of some note by his own account. He buys Badlands reagents to restock his supplies. Droffers and Son Salvage cannot restore the magic of an old necklace, he says, but he can, and he would study it to learn to make such things himself.",
            {V .. " #2258 Badlands Reagent Run; #2338 Translating the Journal", LF("quest:2258", "Jarkal_Mossmeld")},
            {"Jarkal"}, {"place:kargath", BAD}),
        Note("npc:martek", "Martek the Exiled", "Person",
            "Martek the Exiled is a smith who lives in a camp in the Badlands with a goblin. He knows more about metal than anyone, by Fizzle Brassbolts's account, and he is not out there only to stay away from people. The Badlands hold indurium, a metal with great resistance to heat and stress, and its true ore is mined deep within Uldaman.",
            {V .. " #1106 Martek the Exiled; #1108 Indurium; #1137 News for Fizzle", LF("quest:1106", "Martek_the_Exiled")},
            {"Martek"}, {"npc:fizzle-brassbolts", "dungeon:uldaman", BAD}),
        Note("npc:primal-torntusk", "Primal Torntusk", "Person",
            "Primal Torntusk is a leader of the Revantusk trolls of Revantusk Village in the Hinterlands. The Vilebranch took her mate, Elder Torntusk, in a midnight raid, and her spies say the Vile Priestess Hexx holds him atop Jintha'Alor to sacrifice to Hakkar. She has put a price on Hexx and her guards, and she wants the dark vessels of tainted blood that drive the Vilebranch to madness taken from them.",
            {V .. " #7845 Kidnapped Elder Torntusk!; #7850 Dark Vessels; #7861 Wanted: Vile Priestess Hexx and Her Minions", LF("quest:7845", "Primal_Torntusk")},
            nil, {"place:revantusk", "place:jinthaalor", "faction:vilebranch"}),
        Note("npc:itharius", "Itharius", "Person",
            "Itharius is a dragon of Ysera's flight who keeps watch from a cave in the southwestern cliffs of the Swamp of Sorrows, near the sunken Temple of Atal'Hakkar. He speaks through an Oathstone to those who carry the gem of Eranikus and asks their help in redeeming Eranikus's corrupted soul. Eranikus lies between sleep and death, caught in a weave of nightmares.",
            {V .. " #3374 The Essence of Eranikus; #3512 In Eranikus' Own Words", "LoreForever subzone:itharius-s-cave (wiki: https://warcraft.wiki.gg/wiki/Itharius%27s_Cave)"},
            nil, {"npc:shade-eranikus", "npc:ysera", "dungeon:atalhakkar"}, true),
        Note("npc:lydros", "Lorekeeper Lydros", "Person",
            "Lorekeeper Lydros keeps the books of the Shen'dralar in Dire Maul. One of their greatest works, Foror's Compendium of Dragon Slaying, was missing for ages. He knows how to forge the sword Quel'Serrar, which must be heated in a dragon's breath and tempered in her blood. He tells one visiting mage that he has not seen one of that people in five hundred years, then sets the mage to catalogue a water elemental in the Warpwood Quarter.",
            {V .. " #7507 Foror's Compendium; #7508 The Forging of Quel'Serrar; #7463 Arcane Refreshment"},
            {"Lydros"}, {"faction:shendralar", "dungeon:dire-maul", "relic:quel-serrar"}),
        Note("npc:talo", "Talo Thornhoof", "Person",
            "Talo Thornhoof is a tauren of Camp Mojache in Feralas. He wants the heart of Edana Hatetalon, queen of the Northspring harpies, said to be made of crystal and empty of everything but hate. He also seeks the web of the blood elf Lethtendris, who defied her own kind to siphon the tainted magic of Dire Maul and means to loose it on her enemies.",
            {V .. " #3062 Dark Heart; #7489 Lethtendris's Web", LF("quest:3062", "Talo_Thornhoof")},
            {"Thornhoof"}, {"place:camp-mojache", "npc:lethtendris", "region:466572616c6173"}),
        Note("npc:leftwitch", "Leftwitch", "Person",
            "Leftwitch is a gnome mage in Kharanos who buys reagents through Reclaimers Inc. of Ironforge. His list for the company's crew in Desolace runs from satyr horns and scorpashi venom to the brains and wings of demons, and his directions are explicit about which creatures each part must come from.",
            {V .. " #1458 Reagents for Reclaimers Inc.; #1459 Reagents for Reclaimers Inc.; #1466 Reagents for Reclaimers Inc.; #1467 Reagents for Reclaimers Inc.", LF("quest:1458", "Leftwitch")},
            nil, {"place:kharanos", "npc:kreldig-ungor", "region:4465736f6c616365"}, true),
    })
end

-- notes5 batch 3: the names the 50-60 and end-game lane asked for. Light's Hope and the
-- Plaguelands, Silithus and the Abyssal Council, Felwood and Winterspring, Kargath and
-- Blackrock Spire, Dire Maul, Tarren Mill. Guarded here (LoreDiscoveryData.lua): Kirith's
-- fate ("kirith"), Trey Lightforge's death ("trey"), and who stands behind the Twilight's
-- Hammer ("abyssal"). The Grand Crusader's true nature stays out of Zverenhoff's note,
-- Ramaladni's fate out of Korfax's and Kariel Winthalus's fate out of his own.
do
    local EPL, WPL = "region:4561737465726e20506c616775656c616e6473", "region:5765737465726e20506c616775656c616e6473"
    local SIL, WS = "region:53696c6974687573", "region:57696e746572737072696e67"
    A.RegisterLoreNotes({
        Note("npc:marduke", "Magistrate Marduke", "Person",
            "Magistrate Marduke is the ghost of a magistrate of Caer Darrow, the town on the island in Darrowmere Lake that fell when Scholomance overran it. Unlike most of the town's dead he keeps his memories, and he is seen only by those who carry a spectral essence. He seeks revenge on Ras Frostwhisper, the lich who leads the school. The undead fear life as the living fear death, he says, and many destroy every remnant of their former lives, so his plan needs a keepsake from Ras's years as a living man in Stromgarde. Bound to the lich's soul, it can make Ras mortal again long enough to be killed.",
            {V .. " #5461 The Human, Ras Frostwhisper; #5465 Soulbound Keepsake; #5466 The Lich, Ras Frostwhisper", "https://warcraft.wiki.gg/wiki/Magistrate_Marduke (a ghost of Caer Darrow who keeps his memories; seen with the spectral essence)"},
            {"Marduke"}, {"place:caer-darrow", "npc:ras", "dungeon:scholomance"}),
        Note("npc:zverenhoff", "Duke Nicholas Zverenhoff", "Person",
            "Duke Nicholas Zverenhoff is one of the most respected leaders of the Argent Dawn and a brilliant linguist. He works from Light's Hope Chapel in the far east of the Eastern Plaguelands. He chooses champions for the Dawn from those who both destroy and follow orders, and he would see Baron Rivendare, who rules Stratholme for Kel'Thuzad, destroyed. It is Zverenhoff who brings a chosen champion before Lord Maxwell Tyrosus, who has granted no outsider an audience in years.",
            {V .. " #6030 Duke Nicholas Zverenhoff; #5263 Above and Beyond; #5264 Lord Maxwell Tyrosus"},
            {"Zverenhoff", "Nicholas Zverenhoff"}, {"place:lights-hope", "faction:argent-dawn", "npc:maxwell-tyrosus", EPL}),
        Note("npc:maxwell-tyrosus", "Lord Maxwell Tyrosus", "Person",
            "Lord Maxwell Tyrosus directs the Argent Dawn's defense against the Scourge from Light's Hope Chapel in the Eastern Plaguelands. He is a veteran paladin of the Silver Hand. For years he granted no audience to outsiders, and he keeps the Argent Hold, the Dawn's locked store of power, for those he judges worthy. He also studies husks of the Colossi of Silithus in the hope that their secrets can help in the war against the Scourge.",
            {V .. " #5264 Lord Maxwell Tyrosus; #5265 The Argent Hold; #8859 Secrets of the Colossus - Zora", "LoreForever npc:lord-maxwell-tyrosus (wiki: https://warcraft.wiki.gg/wiki/Lord_Maxwell_Tyrosus)"},
            {"Maxwell Tyrosus", "Lord Maxwell"}, {"place:lights-hope", "faction:argent-dawn", "place:argent-hold", "faction:silver-hand"}),
        Note("npc:korfax", "Korfax", "Person",
            "Korfax serves the Argent Dawn at Light's Hope Chapel. He keeps the memory of Ramaladni, an old warrior of the Brotherhood who went into Naxxramas for vengeance and never came out, and he wants to know what became of him.",
            {V .. " #9229 The Fate of Ramaladni (description)"},
            nil, {"place:lights-hope", "npc:ramaladni", "dungeon:naxxramas"}, true),
        Note("npc:ramaladni", "Ramaladni", "Person",
            "Ramaladni was a warrior of the Brotherhood and a pupil of Highlord Mograine, before the Argent Dawn existed. When news of Mograine's death reached him, hatred and anger took him over, and Korfax of the Argent Dawn calls him the spirit of retribution. He went into Naxxramas for vengeance and never returned.",
            {V .. " #9229 The Fate of Ramaladni (description)"},
            nil, {"npc:highlord-mograine", "dungeon:naxxramas", "npc:korfax"}, true),
        Note("npc:huum", "Huum Wildmane", "Person",
            "Huum Wildmane is a tauren of the Cenarion Circle at Cenarion Hold in Silithus who directs its effort against the Twilight's Hammer. Forays against the cult have shown him that a darker power commands it through the wind stones in its camps, the Abyssal Council, and he sends the Hold's champions to Aurel Goldleaf, whose disguises can lure its Dukes and Lords out, and to Bor Wildmane, who pays for their defeat.",
            {V .. " #8331 Aurel Goldleaf; #8343 Goldleaf's Discovery; #8348 Signet of the Dukes; #8352 Scepter of the Council"},
            {"Huum"}, {"place:cenarion-hold", "npc:bor-wildmane", "npc:aurel-goldleaf", SIL}),
        Note("group:abyssal-council", "Abyssal Council", "Faction",
            "The Abyssal Council is a hierarchy of elemental nobles who command the Twilight's Hammer in Silithus. Its Templars serve under the Abyssal Dukes, who are among the main forces organizing the cultists, and above them stand the Abyssal Lords. They speak to the cult through wind stones in its camps, and only the highest ranks of the Twilight's Hammer may address the Lords through the greater stones. The Cenarion Circle at Cenarion Hold works to lure the Dukes and Lords into the world and destroy them.",
            {V .. " #8331 Aurel Goldleaf; #8332 Dukes of the Council; #8341 Lords of the Council; #8538 The Four Dukes; #8352 Scepter of the Council"},
            {"the Abyssal Council", "Abyssal Dukes", "Abyssal Lords"}, {"group:twilights-hammer", "place:cenarion-hold", "npc:huum", SIL}),
        Note("npc:ortell", "Hermit Ortell", "Person",
            "Hermit Ortell is a deserter of the Twilight's Hammer who hides as a hermit in a cave in the mountains of southeastern Silithus, south of Southwind Village. The cult does not forgive those who leave it and still hunts him like a beast, so any enemy of theirs is a friend of his. He can read the cult's coded writing with the Twilight Lexicon, the book of its scribes, whose three parts its Twilight Keepers guard in separate camps, and what he deciphers goes to Commander Mar'alith of Cenarion Hold.",
            {V .. " #8285 The Deserter; #8279 The Twilight Lexicon; #8287 A Terrible Purpose", "LoreForever subzone:ortell-s-hideout (wiki: https://warcraft.wiki.gg/wiki/Ortell%27s_Hideout)"},
            {"Ortell"}, {"group:twilights-hammer", "place:southwind", "npc:maralith", SIL}),
        Note("npc:kirith", "Lieutenant Kirith", "Person",
            "Lieutenant Kirith served under the Fallen Hero of the Horde in the regiment Thrall's Grasp. When the regiment was destroyed in the Blasted Lands, Kirith and his commander were imprisoned and tortured by Archmage Allistarj in a cave of the Serpent's Coil, and Kirith's strength of will faltered. His commander heard the experiments from his own cage and never saw him again.\n\nKirith did not survive Allistarj. His soul was twisted into a demon, Kirith the Damned, which haunts the Serpent's Coil. When that form is destroyed his spirit lingers for a short time, long enough to tell how Razelikh's three lieutenants are protected by the amulet each of them wears.",
            {V .. " #2721 Kirith; #2743 The Cover of Darkness", "https://warcraft.wiki.gg/wiki/Kirith_the_Damned (the felhound at the Serpent's Coil; his soul twisted under Allistarj's torture)"},
            {"Kirith", "Kirith the Damned"}, {"npc:fallen-hero", "npc:razelikh", "region:426c6173746564204c616e6473"}),
        Note("npc:arkonarin", "Arko'narin", "Person",
            "Arko'narin is a night elf who went into Jaedenar in Felwood with the paladin Trey Lightforge. The Shadow Council caught her and kept her caged in Shadow Hold, where she feared she would be sacrificed to the demons the cult worships. A strange red key carried by one of its members opens her cage. Once free she means to recover Trey's sword, Lightforge, escape the hold and carry word of what is happening there to her superiors in Darnassus, and her friend Jessir Moonbow waits for her near the Ashenvale border.",
            {V .. " #5202 A Strange Red Key; #5203 Rescue From Jaedenar"},
            {"Arko"}, {"place:shadow-hold", "npc:jessir", "npc:trey-lightforge", "region:46656c776f6f64"}, true),
        Note("npc:trey-lightforge", "Trey Lightforge", "Person",
            "Trey Lightforge was a paladin who went into Jaedenar in Felwood with Arko'narin, one of her best friends. His sword, named Lightforge, lies with their confiscated gear in Shadow Hold.\n\nTrey died in Shadow Hold, tortured by the Shadow Council. Arko'narin escaped with his sword, and his remains were carried out to their friend Jessir Moonbow so that he could be given proper respect.",
            {V .. " #5203 Rescue From Jaedenar; #5204 Retribution of the Light; #5385 The Remains of Trey Lightforge"},
            nil, {"npc:arkonarin", "npc:jessir", "place:shadow-hold"}),
        Note("npc:jessir", "Jessir Moonbow", "Person",
            "Jessir Moonbow waits on the border of Felwood and Ashenvale, at the camp of the Emerald Circle there. She is a friend of Arko'narin and the paladin Trey Lightforge and was to meet them there after their mission into Jaedenar.",
            {V .. " #5203 Rescue From Jaedenar; #5204 Retribution of the Light"},
            {"Jessir"}, {"npc:arkonarin", "npc:trey-lightforge", "region:46656c776f6f64"}),
        Note("npc:mauari", "Mau'ari", "Person",
            "Mau'ari is a troll of Winterspring who makes lucky charms. She can tell at a glance who wants one, she says, and she makes it from the reflective frostmaul shards of the ice giants' canyon south of her. Whoever carries her charm finds special items called E'ko on the creatures of the wilds, and she trades help for them.",
            {V .. " #969 Luck Be With You; #975 Cache of Mau'ari"},
            nil, {"place:frostwhisper-gorge", WS}, true),
        Note("npc:trull-failbane", "Trull Failbane", "Person",
            "Trull Failbane is an orc of Bloodvenom Post in Felwood who knows a great deal about the wildkin of Winterspring, though not about the magic they wield. For that he sends what is found among them to Nara Wildmane in Thunder Bluff.",
            {V .. " #4882 Guarding Secrets; #4883 Guarding Secrets", "https://warcraft.wiki.gg/wiki/Trull_Failbane (Bloodvenom Post; orc)"},
            {"Failbane"}, {"place:bloodvenom", WS, "region:46656c776f6f64"}),
        Note("npc:mayara", "Mayara Brightwing", "Person",
            "Mayara Brightwing is an agent of Count Remington Ridgewell of Stormwind, sent to the Burning Steppes to scout the ruined Dark Iron city of Thaurissan for objects for the Ridgewell family museum. She seeks a relic in Blackrock Spire, Doomrigger's clasp, so encrusted with gems that it was said to make any dwarf who saw it weep. It lay in a chamber once called the Hall of Fortune, where the Dark Irons kept their relics, trophies and art, and which has since collapsed and been put to less savory use.",
            {V .. " #4766 Mayara Brightwing; #4764 Doomrigger's Clasp"},
            {"Mayara"}, {"npc:ridgewell", "dungeon:blackrock-spire", "region:4275726e696e672053746570706573"}),
        Note("npc:vivian-lagrave", "Shadowmaster Vivian Lagrave", "Person",
            "Shadowmaster Vivian Lagrave is an agent of the Apothecarium of the Undercity who works at Kargath in the Badlands. She follows rumors of a brew made by the Dark Iron dwarves of Blackrock Depths, and she believes that Blackrock Spire holds the Darkstone Tablet, a tablet of old alchemical recipes that would serve the apothecaries' research. Kargath lacks the amenities of the Apothecarium, she finds.",
            {V .. " #4133 Vivian Lagrave; #4769 Vivian Lagrave and the Darkstone Tablet; #4768 The Darkstone Tablet"},
            {"Vivian Lagrave"}, {"place:kargath", "place:apothecarium", "item:darkstone-tablet", "faction:royal-apothecaries"}),
        Note("item:darkstone-tablet", "Darkstone Tablet", "Relic",
            "The Darkstone Tablet carries the writings of Urheld Darkstone, a long-dead dwarf and a skilled alchemist. His contemporaries thought him insane, so he shared his research with no one and etched it onto tablets instead. One of them is believed to lie in Blackrock Spire, in the chamber the Dark Irons once called the Hall of Fortune.",
            {V .. " #4768 The Darkstone Tablet; #4769 Vivian Lagrave and the Darkstone Tablet"},
            {"the Darkstone Tablet"}, {"npc:vivian-lagrave", "dungeon:blackrock-spire"}),
        Note("item:gauntlet-gordok-might", "Gauntlet of Gordok Might", "Relic",
            "The Gauntlet of Gordok Might is the prized artifact of the Gordok ogres of Dire Maul. Prince Tortheldrin, whom the ogres call the creepy elf, stole it from an old Gordok king, and every king since has failed to recover it. The old stories of the ogres say that only the one true king of the Gordok can take it back.",
            {V .. " #7703 Unfinished Gordok Business; #1318 Unfinished Gordok Business"},
            {"the Gauntlet of Gordok Might"}, {"npc:kromcrush", "npc:tortheldrin", "dungeon:dire-maul"}),
        Note("item:felvine", "Felvine", "Relic",
            "The Felvine is the Fruit of Fertility of Eldre'Thalas, now corrupted. It grows close to Alzzin the Wildshaper, who rules the eastern part of the ruined city of Dire Maul. Its essence is so vile that only a Reliquary of Purity can hold it without harming its bearer, and few such reliquaries were ever made. One lay in the night elf village of Southwind in Silithus many years ago.",
            {V .. " #5526 Shards of the Felvine; #5527 A Reliquary of Purity"},
            {"the Felvine", "Fruit of Fertility"}, {"npc:alzzin", "dungeon:dire-maul", "place:southwind"}),
        Note("npc:kariel", "Kariel Winthalus", "Person",
            "Kariel Winthalus is an elven master who fled the devastation of his homeland years ago, carrying several ancient elven artifacts. Scholars of both Horde and Alliance have followed his trail from the ruins of Quel'Thalas through the Burning Steppes and across the sea to Feralas, and they suspect he sought sanctuary in the halls of Eldre'Thalas, now called Dire Maul. They want the knowledge he carried, whether he is found alive or dead.",
            {V .. " #7481 Elven Legends; #7482 Elven Legends"},
            {"Kariel", "Winthalus"}, {"dungeon:dire-maul", "region:466572616c6173"}),
        Note("npc:serge-hinott", "Serge Hinott", "Person",
            "Serge Hinott is a Forsaken apothecary at Tarren Mill in the Hillsbrad Foothills who brews for the Royal Apothecary Society and knows the ways of making and using poison. Those poisoned beyond other help are sent to him. He admires a poison of the troll Zanzil that he had never seen before, cures its creeping madness, and teaches its use, though he can do nothing about the smell.",
            {V .. " #2479 Hinott's Assistance; #2480 Hinott's Assistance", "LoreForever npc:serge-hinott (wiki: https://warcraft.wiki.gg/wiki/Serge_Hinott)"},
            {"Hinott"}, {"place:tarren-mill", "faction:royal-apothecaries", "npc:zanzil"}),
    })
end

-- notes5 batch 5: the groups and smaller people of the 40-60 scenes. Tanaris's nomads and
-- pirates, Stranglethorn's sea giants, Feralas's naga and insects, the Shadowforge clan,
-- the Reclaimers, Cenarion Hold's quartermaster of the roads, Dire Maul's library and the
-- Skeleton Key, and four helpers of Kalimdor and the Hinterlands. "Shaky" alone and the
-- sea giants' shared kind stay unlinked.
do
    local TAN, STV, FER = "region:54616e61726973", "region:537472616e676c6574686f726e2056616c65", "region:466572616c6173"
    A.RegisterLoreNotes({
        Note("faction:wastewander", "Wastewander", "Faction",
            "The Wastewander are desert nomads of Tanaris, outlaws in the eyes of Gadgetzan. They have seized nearly every water well in the desert, and the Gadgetzan Water Company says the water in their pouches was stolen from it in the first place. Their bandits, thieves, rogues, assassins and shadow mages camp east and southeast of the town, and their leader is Caliph Scorpidsting.",
            {V .. " #1690 Wastewander Justice; #1691 More Wastewander Justice; #1707 Water Pouch Bounty; #2781 WANTED: Caliph Scorpidsting", LF("quest:1690", "Wastewander_Nomads")},
            {"Wastewander nomads", "the Wastewander"}, {"npc:scorpidsting", "group:gadgetzan-water-company", TAN}),
        Note("npc:scorpidsting", "Caliph Scorpidsting", "Person",
            "Caliph Scorpidsting leads the Wastewander outlaws of Tanaris. The Gadgetzan Water Company's wanted notice charges him with the murder of its employees and with stealing its resources and seizing its property, and it pays a high bounty for his head.",
            {V .. " #2781 WANTED: Caliph Scorpidsting", LF("quest:2781", "Caliph_Scorpidsting")},
            {"Scorpidsting"}, {"faction:wastewander", "npc:bilgewhizzle", TAN}),
        Note("npc:andre-firebeard", "Andre Firebeard", "Person",
            "Andre Firebeard is a pirate wanted for crimes against Steamwheedle and Gadgetzan. By decree of the governing council, those who read the notice may use lethal force against him and his abettors, and if he is dead by the time of his hearing his head may stand in for him.",
            {V .. " #2875 WANTED: Andre Firebeard"},
            nil, {"npc:security-chief-bilgewhizzle", "place:steamwheedle-port", TAN}),
        Note("npc:cuergo", "Captain Cuergo", "Person",
            "Captain Cuergo is a pirate captain of Lost Rigger Cove, the walled pirate town on the southern coast of Tanaris. His crew stole the last shipment of rum bound for Stoley's bar at Steamwheedle Port and stowed it in the town.",
            {V .. " #2873 Stoley's Shipment", LF("quest:2873", "Captain_Cuergo")},
            {"Cuergo"}, {"place:lost-rigger", "npc:stoley", TAN}),
        Note("npc:shaky-phillipe", "Shaky Phillipe", "Person",
            "Shaky Phillipe is a gambler on the docks of Booty Bay who owes Sea Wolf MacKinley plenty after a game. He swears he meant to pay all along, and blames a little too much drink for losing his way.",
            {V .. " #606 Scaring Shaky; #607 Return to MacKinley"},
            {"Phillipe"}, {"npc:mackinley", "place:booty-bay"}),
        Note("npc:gorlash", "Gorlash", "Person",
            "Gorlash is one of three sea giants of the Stranglethorn coast who smashed the ships of Captain Hecklebury Smotts and killed his crews. He took the captain's chest, saying he wanted it for a snuffbox.",
            {V .. " #8551 The Captain's Chest"},
            nil, {"npc:smotts", "npc:mokrash", "npc:negolash", STV}, true),
        Note("npc:mokrash", "Mok'rash", "Person",
            "Mok'rash is one of three sea giants of the Stranglethorn coast who smashed the ships of Captain Hecklebury Smotts three times and killed his crews. He carries the captain's monogrammed sash.",
            {V .. " #8552 The Monogrammed Sash"},
            nil, {"npc:smotts", "npc:gorlash", "npc:negolash", STV}, true),
        Note("npc:negolash", "Negolash", "Person",
            "Negolash is one of three sea giants of the Stranglethorn coast who wrecked Captain Hecklebury Smotts's second ship, Smotts' Revenge, and took his cutlass. When the giants smashed the ship he went straight for the galley, hungry not for the crew but for wine and the cook's barbecued buzzard wings, and Sprogger the cook knows how to lure him with them.",
            {V .. " #8553 The Captain's Cutlass; #618 Facing Negolash", LF("quest:618", "Negolash")},
            nil, {"npc:smotts", "npc:sprogger", STV}, true),
        Note("npc:sprogger", "Sprogger", "Person",
            "Sprogger was the cook of Captain Hecklebury Smotts's ship and survived when the sea giants destroyed it. His specialty is barbecued buzzard wings, made to a recipe he fetched from the Badlands, and the giant Negolash is fond of them and of wine.",
            {V .. " #618 Facing Negolash; #8553 The Captain's Cutlass", LF("quest:618", "Sprogger")},
            nil, {"npc:smotts", "npc:negolash", STV}, true),
        Note("faction:hatecrest", "Hatecrest", "Faction",
            "The Hatecrest are naga of the Feralas coast. They have occupied the ancient Ruins of Solarsal south of Feathermoon Stronghold in alarming numbers and hold much of Sardor Isle, and the officers of the stronghold expect them to try to take the island for their own. Royalty heads their chain of command, and one of their crueler lords, Shalzaru, has dug up an odd relic in a cave on the Isle of Dread.",
            {V .. " #2866 The Ruins of Solarsal; #2867 Return to Feathermoon Stronghold; #2869 Against the Hatecrest; #2870 Against Lord Shalzaru", LF("quest:2866", "Hatecrest")},
            {"Hatecrest naga", "the Hatecrest"}, {"place:feathermoon", "npc:latronicus", FER}),
        Note("group:zukkash", "Zukk'ash", "Faction",
            "The Zukk'ash are insects of southern Feralas who dwell in the Writhing Deep, south of the Woodpaw gnolls. The Horde at Camp Mojache suspects that they drive the gnolls to frenzy, and whether or not they are sentient it counts them as great a threat as the gnolls. Feathermoon Stronghold has met them too. What the Horde learns of them goes to Zilzibin Drumlore in Orgrimmar, an expert on strange creatures.",
            {V .. " #7730 Zukk'ash Infestation; #7732 Zukk'ash Report; #4266 A Hero's Welcome", LF("quest:4135", "Zukk%27ash")},
            {"the Zukk'ash", "Zukk'ash insects"}, {"place:writhing-deep", "faction:woodpaw", "npc:zilzibin", FER}),
        Note("group:shadowforge", "Shadowforge clan", "Faction",
            "The Shadowforge are a clan of the Dark Iron dwarves, and Shadowforge City, the Dark Iron city, lies deep in Blackrock Depths. In the Badlands they search Uldaman for lost artifacts that could be turned against Ironforge, and they have attacked the dig sites of the Explorers' League there. Ragnaros himself sent Ambassador Infernus to Angor Fortress to watch over their search.",
            {V .. " #719 A Dwarf and His Tools; #724 Prospect of Faith; #726 Passing Word of a Threat; #762 An Ambassador of Evil"},
            {"Shadowforge", "the Shadowforge", "Shadowforge City"}, {"faction:dark-iron", "dungeon:uldaman", "dungeon:blackrock-depths", "place:angor-fortress"}),
        Note("group:reclaimers", "Reclaimers Inc.", "Faction",
            "Reclaimers Inc. is a salvage company run from Ironforge by Roetten. It takes jobs from paying clients, and its short-handed crew under Kreldig Ungor works out of Nijel's Point in Desolace. Its work there ranges from the chest that the mage Karnitol abandoned when sea giants attacked his ship to the reagents the gnome mage Leftwitch of Kharanos wants from the satyrs, beasts and demons of Desolace.",
            {V .. " #1453 Reclaimers' Business in Desolace; #1454 The Karnitol Shipwreck; #1457 The Karnitol Shipwreck; #1458 Reagents for Reclaimers Inc.; #1467 Reagents for Reclaimers Inc.", LF("quest:1454", "Reclaimers_Inc.")},
            {"Reclaimers", "the Reclaimers"}, {"npc:kreldig-ungor", "place:nijels-point", "npc:leftwitch", "region:4465736f6c616365"}),
        Note("npc:proudhorn", "Windcaller Proudhorn", "Person",
            "Windcaller Proudhorn keeps the supply lines of Cenarion Hold in Silithus, which he holds to be of the utmost strategic importance. As long as the Hold stands, he is convinced, victory over the silithid is assured, but only if its supplies keep coming. Desert worms such as the dredge strikers and crushers threaten the caravans more than the silithid do, and mounted Twilight's Hammer marauders under a warrior named Morna pick off the Hold's smaller patrols.",
            {V .. " #8280 Securing the Supply Lines; #8281 Stepping Up Security; #8740 Twilight Marauders"},
            {"Proudhorn"}, {"place:cenarion-hold", "group:twilights-hammer", "region:53696c6974687573"}),
        Note("place:athenaeum", "Athenaeum", "Place",
            "The Athenaeum is the library of the Shen'dralar in Dire Maul. An ancient chest of the Shen'dralar lies hidden beneath its stairway.",
            {V .. " #7877 The Treasure of the Shen'dralar; #7462 The Treasure of the Shen'dralar; #7507 Foror's Compendium"},
            {"the Athenaeum"}, {"faction:shendralar", "npc:lydros", "dungeon:dire-maul"}),
        Note("item:skeleton-key", "Skeleton Key", "Relic",
            "The Skeleton Key opens the barred door of Scholomance on Caer Darrow. It is forged from the bones of several skeletons, from Andorhal or the land around it, hardened with thorium in a mold from Krinkle Goodsteel of Gadgetzan that is dipped in the lava lake of Fire Plume Ridge. It works only once it carries the signet of a being who can open the way, the scarab of Araj the Summoner.",
            {V .. " #964 Skeletal Fragments; #5537 Skeletal Fragments; #5801 Fire Plume Forged; #5802 Fire Plume Forged; #5803 Araj's Scarab; #5804 Araj's Scarab"},
            {"the Skeleton Key", "Skeleton Key to Scholomance"}, {"dungeon:scholomance", "npc:dithers", "npc:arbington", "npc:araj"}),
        Note("npc:nara-wildmane", "Nara Wildmane", "Person",
            "Nara Wildmane is a tauren druid of Thunder Bluff. Hamuul Runetotem calls her young and fierce of spirit. Hamuul dreamed of a cult of druids in the Wailing Caverns whose goals were once noble but who now serve the taint spreading through the Barrens, and Nara wants the four leaders of these Druids of the Fang defeated. She also knows the magic of the wildkin.",
            {V .. " #1490 Nara Wildmane; #914 Leaders of the Fang; #4883 Guarding Secrets"},
            nil, {"npc:hamuul", "group:druids-fang", "dungeon:wailing-caverns", "region:5468756e64657220426c756666"}),
        Note("npc:gilveradin", "Gilveradin Sunchaser", "Person",
            "Gilveradin Sunchaser keeps the original packaging of Hinterlands Honey Ripple and will wrap a bottle properly for a fee of two more bottles. The ripple lies in crates in the abandoned Horde base near Skulk Rock, among foul slimes and oozes.",
            {V .. " #77 A Sticky Situation", LF("quest:77", "Gilveradin_Sunchaser")},
            {"Gilveradin"}, {"place:skulk-rock", "region:5468652048696e7465726c616e6473"}),
        Note("npc:falfindel", "Falfindel Waywarder", "Person",
            "Falfindel Waywarder is a night elf druid at Thalanaar on the border of Feralas and Thousand Needles. He works to heal corrupted lands and can call forth great forest spirits to help restore them, and those who would reclaim the Charred Vale in Stonetalon seek his aid. Goods meant for him travel by courier to the way-station.",
            {V .. " #1059 Reclaiming the Charred Vale; #4281 Thalanaar Delivery", LF("npc:falfindel-waywarder", "Falfindel_Waywarder")},
            {"Falfindel"}, {"place:charred-vale", FER, "region:54686f7573616e64204e6565646c6573"}),
        Note("npc:agnar", "Agnar Beastamer", "Person",
            "Agnar Beastamer is a dwarf of Aerie Peak in the Hinterlands and a master animal handler. Those who would raise a sprite darter hatchling from its egg go to him for the final steps of incubation, and he knows what the young darters eat.",
            {V .. " #3843 The Newest Member of the Family; #4297 Food for Baby; #4298 Becoming a Parent", LF("quest:3843", "Agnar_Beastamer")},
            {"Agnar"}, {"place:aerie-peak", "region:5468652048696e7465726c616e6473"}),
    })
end

-- Sixth notes lane (notes6), 2026-11-06. Batch 1: the people the 30-60 scenes name most
-- often without a note. Mai'Zoth's part in Kurzen's fall (Nimetz's finding in #206) and
-- what Vaelan is (#4743) are discoveries (LoreDiscoveryData.lua, "maizoth", "vaelan");
-- Raleigh of the Undercity waits for the Deliah chain. Jaron, Daltry and Biggs stay out as
-- given names or surnames a player could carry; "Raleigh" alone names two men.
do
    local STV, DUSK = "region:537472616e676c6574686f726e2056616c65", "region:4475736b776f6f64"
    A.RegisterLoreNotes({
        Note("npc:mebok", "Mebok Mizzyrix", "Person",
            "Mebok Mizzyrix is a goblin entrepreneur in Ratchet who pays travelers to bring him strange finds from the wilds of Kalimdor, sure that each one will make him a fortune. His favorite venture is the smart drink. He believes the raptors of the Barrens owe their cunning to their horns, and he has had the horns of sunscale scytheclaws ground and mixed with wine. When that did not work he turned to the wailing essence of the ectoplasmic creatures in the Wailing Caverns, which he takes for the cause of the strange plants and animals of the Barrens.\n\nHe trades in food as well. Spider egg omelettes are a fad in Booty Bay, and he ships deepmoss spider eggs from the Stonetalon Mountains there through Wharfmaster Dizzywig. He also pays well for Blueleaf and Redleaf tubers from the quilboar of Razorfen Kraul and for bogbean leaves from Dustwallow Marsh, and the treasure hunters who work for him do not always come back easily.",
            {V .. " #865 Raptor Horns; #1491 Smart Drinks; #1069 Deepmoss Spider Eggs; #1221 Blueleaf Tubers; #1144 Willix the Importer; #1270 Stinky's Escape", LF("npc:mebok-mizzyrix", "Mebok_Mizzyrix")},
            {"Mebok"}, {"place:ratchet", "region:5468652042617272656e73", "dungeon:wailing-caverns", "npc:dizzywig"}),
        Note("npc:smitts", "Tavernkeep Smitts", "Person",
            "Tavernkeep Smitts runs the Scarlet Raven Tavern in Darkshire. The inn does not see the business it used to, but travelers still pass through, and Smitts makes a point of remembering them.\n\nSmitts brews Zombie Juice, a liquor strong enough that few ask for it. Its rot blossoms grow inside the skulls of the skeletal horrors and fiends of the Raven Hill Cemetery and the Tranquil Gardens, and those who bring them help keep Darkshire safe, news he passes on to Althea Ebonlocke of the Night Watch.",
            {V .. " #156 Gather Rot Blossoms; #158 Zombie Juice; #159 Juice Delivery; #266 Inquire at the Inn", LF("npc:tavernkeep-smitts", "Tavernkeep_Smitts")},
            {"Smitts"}, {"place:scarlet-raven", "place:darkshire", "npc:abercrombie", DUSK}),
        Note("npc:niby", "Niby the Almighty", "Person",
            "Niby the Almighty lives in Felwood, north of the Bloodvenom Falls, and teaches warlocks to summon an infernal servant. His price is the infernal core of Kroshius, an infernal that lies burned out in the rubble of Shatter Scar Vale and must be rekindled with fel fire before it can be destroyed. His imp Impsy sets students on the way, and does not hold his master's wits in high regard.",
            {V .. " #7601 What Niby Commands; #7602 Flawless Fel Essence; #7603 Kroshius' Infernal Core; #8420 Hot and Itchy"},
            {"Niby"}, {"npc:impsy", "place:shatter-scar", "region:46656c776f6f64"}),
        Note("npc:daio", "Daio the Decrepit", "Person",
            "Daio the Decrepit is an aged human warlock who lives by a ruined demonic altar above the Tainted Scar in the Blasted Lands, drawn by its fel energies. He teaches seasoned warlocks to conjure and control a Doomguard. The demon must first be caught in a crystal prison, whose walls are made from the Tears of the Hederine, anti-magic crystals taken from the demons of Darkwhisper Gorge in Winterspring, bound with the coagulated blood of the Wildspawn satyrs of Dire Maul. A Doomguard Commander of the Tainted Scar is then captured in it, and Daio warns that the demon fights the one performing the ritual with all its fury.",
            {V .. " #7581 The Prison's Bindings; #7582 The Prison's Casing; #7583 Suppression", LF("subzone:tainted-scar", "Tainted_Scar")},
            {"Daio"}, {"region:426c6173746564204c616e6473", "place:darkwhisper", "dungeon:dire-maul"}),
        Note("npc:jaron", "Jaron Stoneshaper", "Person",
            "Jaron Stoneshaper works a dig site in southern Winterspring. Bloodthirsty wildkin chased him from his camp, where he thinks he came too close to something they were guarding, and a friend of his did not get away. He wants back his supplies and an amulet he unearthed the day before.\n\nJaron has also been among the ruins of Kel'Theril, though he calls himself no historian. He knows that the highborne spirits there still search the frozen lake for pieces of the relic whose theft cursed them, and he sends those curious about the pieces to Aurora Skycaller in the Eastern Plaguelands. The past of the high elves pains him to speak of.",
            {V .. " #4861 Enraged Wildkin; #4863 Enraged Wildkin; #4864 Enraged Wildkin; #5244 The Ruins of Kel'Theril; #5245 Troubled Spirits of Kel'Theril"},
            nil, {"place:kel-theril", "npc:aurora-skycaller", "region:57696e746572737072696e67"}),
        Note("npc:vaelan", "Vaelan", "Person",
            "Vaelan waits in Lower Blackrock Spire and shows those who would enter the upper citadel how to make the Seal of Ascension. The unadorned seal has three sockets, each for a gemstone that stands for the command of one of the three generals of the lower citadel, and the generals seldom carry them. The seal must then be forged in the flame of a black dragon. Overlord Wyrmthalak could do it, but his will cannot be broken, so Vaelan sends the seekers to Emberstrife, an ancient drake in the Wyrmbog of Dustwallow Marsh, with an orb that holds the drake's mind for a few seconds once his will is broken. Nefarian, he warns, works feverishly to unleash his evil.\n\nWhen the seal is finished, Vaelan's eyes turn to twin orbs of flame. He sets protective wards in it and promises that in the darkest hour the might of the red flight will be at its bearer's disposal.",
            {V .. " #4742 Seal of Ascension; #4743 Seal of Ascension"},
            nil, {"dungeon:blackrock-spire", "npc:wyrmthalak", "npc:emberstrife", "npc:nefarian"}),
        Note("npc:maizoth", "Mai'Zoth", "Person",
            "Mai'Zoth is an ogre mage who dwells deep in the Mosh'Ogg Ogre Mound in the eastern mountains of Stranglethorn. The Darkspear witch doctor Kin'weelay knows him from the years when his tribe lived in the jungle and calls him vicious, with strong magic made stronger by the artifact he holds, the Mind's Eye.\n\nBrother Nimetz of the Rebel Camp has found that Mai'Zoth is said to use mind-controlling magic, and he is certain the ogre corrupted Colonel Kurzen with the Mind's Eye. While Mai'Zoth lives, Nimetz fears, his evil may raise another Kurzen.\n\nKin'weelay needs the jewel to free Yenniku, and calls it the only hope of saving him.",
            {V .. " #591 The Mind's Eye; #206 Mai'Zoth"},
            nil, {"place:moshogg", "npc:kinweelay", "npc:nimetz", "npc:kurzen", "npc:yenniku"}),
        Note("npc:rau", "Rau Cliffrunner", "Person",
            "Rau Cliffrunner is a tauren at Freewind Post in Thousand Needles. He wants an artifact the Galak centaur protect at Splithoof Hold, a relic from the time of the centaurs' creation guarded by an eternal flame. Water from a night elf moonwell can pierce that flame for a short time, he explains, because the dryads share their ancestry with the centaurs. The relic is the Cloven Hoof, whose strange energy he cannot yet explain.",
            {V .. " #1195 The Sacred Flame; #1196 The Sacred Flame; #1197 The Sacred Flame", LF("npc:rau-cliffrunner", "Rau_Cliffrunner")},
            {"Rau"}, {"place:freewind", "faction:galak", "region:54686f7573616e64204e6565646c6573"}),
        Note("npc:nezzliok", "Nezzliok the Dire", "Person",
            "Nezzliok the Dire is the witch doctor of the Bloodscalp trolls of Stranglethorn, who keep to the Ruins of Zul'Kunda. The Bloodscalps are enemies of the Darkspear and at war with the Skullsplitters. When Yenniku, son of the Darkspear chieftain, went missing, Nimboya at Grom'gol judged that only Nezzliok and his chief, Gan'zulah, knew the truth, and that they would never speak it freely while they lived.",
            {V .. " #584 Bloodscalp Clan Heads; #585 Speaking with Nezzliok"},
            {"Nezzliok"}, {"faction:bloodscalp", "npc:ganzulah", "npc:nimboya", STV}),
        Note("npc:ganzulah", "Gan'zulah", "Person",
            "Gan'zulah is the chief of the Bloodscalp trolls of Stranglethorn, with Nezzliok the Dire as his witch doctor in the Ruins of Zul'Kunda. His tribe are enemies of the Darkspear, and their headhunters take shrunken heads. When the Darkspear searched those heads for Yenniku, Nimboya swore that if the Bloodscalps had killed the boy, a curse of six hundred years would fall on Gan'zulah's spirit.",
            {V .. " #582 Headhunting; #584 Bloodscalp Clan Heads; #586 Speaking with Gan'zulah"},
            {"Gan'zulah"}, {"faction:bloodscalp", "npc:nezzliok", "faction:skullsplitter", STV}),
        Note("npc:daltry", "Clerk Daltry", "Person",
            "Clerk Daltry keeps the Town Registry in Darkshire Town Hall. With the strange happenings of recent years he keeps track of strangers as well as he can, though he admits that the knowledge is usually wanted for unpleasant business. He also sells books, and remembers who buys them.\n\nHe also hears the town's news. When Calor came into Darkshire with a string of worgen heads, Daltry knew him as a hunter who works with the Carevin family, hunters of demons and undead.",
            {V .. " #265 The Shadowy Search Continues; #266 Inquire at the Inn; #1041 The Caravan Road; #1042 The Carevin Family", LF("npc:clerk-daltry", "Clerk_Daltry")},
            nil, {"place:darkshire", "npc:calor", DUSK}),
        Note("npc:biggs", "Watcher Biggs", "Person",
            "Watcher Biggs was carrying a caravan of supplies through the Swamp of Sorrows to Nethergarde Keep when the Lost Ones attacked it. The guards were killed, he alone survived, and one wagon was dragged north to the Fallow Sanctuary with a chest of reagents the wizards of Nethergarde need for their work at the Dark Portal. Biggs camps beside his broken wagon, defends what is left from the swamp's beasts, and needs sun-dried driftwood from the coast to mend it. Nethergarde's quartermaster had given the caravan and Biggs up for lost.",
            {V .. " #1396 Encroaching Wildlife; #1398 Driftwood; #1421 The Lost Caravan; #1425 Deliver the Shipment"},
            nil, {"region:5377616d70206f6620536f72726f7773", "place:fallow-sanctuary", "place:nethergarde"}),
        Note("npc:raleigh-devout", "Raleigh the Devout", "Person",
            "Raleigh the Devout lives in Southshore. He once served the Scarlet Crusade with honor and pride, believing in its cause of ridding Azeroth of the undead, but at the Scarlet Monastery in Tirisfal he saw its grasp on reality slip. The Crusade, he says, now thinks everyone who does not wear its tabard is plagued, and innocent men and women have been tortured for it. He wants its highest officers in the monastery slain, High Inquisitor Whitemane, Scarlet Commander Mograine, Herod and Houndmaster Loksey, in the hope that the true cause can be rekindled. Brother Anton of the Crusade still sends recruits to him, believing him one of their own.",
            {V .. " #1052 Down the Scarlet Path; #1053 In the Name of the Light"},
            nil, {"dungeon:scarlet-monastery", "place:southshore", "npc:whitemane", "npc:scarlet-mograine"}),
        Note("npc:raleigh", "Raleigh", "Person",
            "Raleigh is one of the Forsaken and lives in the Trade Quarter of the Undercity. His wife, Deliah, lived in Brill and was buried in the town's mass grave. When her engraved ring was brought to him he knew it, but he says he feels nothing for her death or for the theft of her body.\n\nHe still wants revenge. Raleigh names Valdred, once his good friend, as Deliah's murderer, and wants his hands. Valdred was last heard of at the Greymane Wall in southern Silverpine, trying to flee into Gilneas.",
            {V .. " #441 Raleigh and the Undercity; #530 A Husband's Revenge"},
            nil, {"npc:deliah", "place:trade-quarter", "place:brill"}),
        Note("npc:emberstrife", "Emberstrife", "Person",
            "Emberstrife is an ancient black drake who keeps his lair in the Wyrmbog of Dustwallow Marsh. He is an old gatekeeper of Nefarian, charged with testing the dragonspawn who would rise to the rank of elite guard to Onyxia, and he holds the skull-shaped medallion that marks that rank until General Drakkisath of Blackrock Spire places its final enchantment. He speaks with contempt of the whelps sent to him.\n\nFew of the black dragonkin outside the upper citadel of Blackrock Spire can forge the Seal of Ascension with their breath, and Emberstrife is one of them. Vaelan sends the seal's makers to him, since his will, unlike Overlord Wyrmthalak's, can be broken long enough to turn his flame to the work.",
            {V .. " #6570 Emberstrife; #6601 Ascension...; #4743 Seal of Ascension"},
            nil, {"place:wyrmbog", "npc:onyxia", "npc:drakkisath", "npc:vaelan"}),
    })
end

-- notes6 batch 2: Forever's own people (Zephras, Teldrassil, Loch Modan, Dun Morogh,
-- Orgrimmar, the Barrens, Hillsbrad) and the Ironforge, Wetlands, Winterspring and Un'Goro
-- names the scenes use. Whose head the Baron wears stays with the existing "baron.othmar"
-- discovery; Walton's past and Blazerunner's part in Linken's journey are discoveries too
-- (LoreDiscoveryData.lua). Ott and Walton stay out as an ordinary surname; Jemma stays out
-- as a given name.
do
    local ZEP, TEL = "region:5a6570687261732049736c65", "region:54656c6472617373696c"
    local IF, ORG = "region:49726f6e666f726765", "region:4f726772696d6d6172"
    A.RegisterLoreNotes({
        Note("npc:garithos", "Othmar Garithos", "Person",
            "Garithos was a Grand Marshal of the Alliance who commanded its remaining forces in Lordaeron after the Third War. He held the high elves in contempt and turned on Prince Kael'thas and his people when they took help from the naga. Later he allied himself with Sylvanas Windrunner to take back the capital of Lordaeron from the dreadlords. Once the city had fallen she broke the alliance and had him put to death.\n\nOthmar Garithos's head is now that of the Baron, the abomination of the Ruins of Lordaeron, sewn back onto it many times. The apothecaries of the Undercity remember him as a particularly unpleasant Grand Marshal whom the Dark Lady dispatched herself, and they believe the head could tell many secrets if it could talk.\n\nSet beside a new body, the head brings it twitching to life, and Othmar relives his final moments. He refuses to serve his keepers. Master Apothecary Faranell welcomes the challenge and means to bind him to the Dark Lady's will with a serum fed into the workings above the body, and he speaks of many plans for Othmar's future.",
            {"https://warcraft.wiki.gg/wiki/Othmar_Garithos (Third War and Lordaeron sections)", P1 .. " #97289 Unending Torment; #97290 Unending Torment; #97291 Unending Torment; #97292 Unending Torment", LF("quest:97289", "Othmar_Garithos")},
            {"Grand Marshal Garithos", "Garithos", "Othmar", "Grand Marshal Othmar Garithos"}, {"npc:sylvanas", "npc:the-baron", "npc:faranell", "place:apothecarium"}),
        ForeverPerson("npc:ott", "Ott",
            "Ott is an orc weaponsmith in Tarren Mill who sells plain, functional blades to travelers. Yet smiths in the Undercity who saw one of his swords took it for the work of a known master. The paladin Trevan Rol, who bought that sword, has given him the first custom commission of his life, a blade to be forged from fine materials, and Ott calls the result his finest work.",
            {P1 .. " #95111 An Underrated Talent; #95125 Ott's Masterwork; #95126 The Moonsilver Blade", LF("quest:95111", "World_of_Warcraft:_Forever")},
            nil, {"place:tarren-mill", "npc:lumina", "place:undercity"}),
        ForeverPerson("npc:norric", "Norric Lochthane", "Norric Lochthane is an aging dwarf shaman in Loch Modan. He calls shaman who have found harmony with earth, wind and fire to the rites of water. The rites take them to Hervdana Saegrund in the Wetlands, to the waters of Stonewatch Falls in Redridge and of the lake beside Astranaar, and to a corrupted spring at Stendel's Pond in Westfall where the water spirits have gone silent. He grants the water totem to those who bring back a shard of water from that shrine. Norric was the mentor of the shaman Grenhild, who learned long ago not to question his ways with magic, and he would rather she visited than sent him the snow he asked for.",
            {P1 .. " #94494 Call of Water; #94501 Call of Water; #94505 Call of Water; #86667 Snowbound", LF("quest:94494", "World_of_Warcraft:_Forever"), LF("quest:94499", "World_of_Warcraft:_Forever"), LF("quest:86667", "World_of_Warcraft:_Forever")},
            {"Norric"}, {"region:4c6f6368204d6f64616e"}),
        ForeverPerson("npc:byancie", "Byancie",
            "Byancie lives in Dolanaar on Teldrassil and teaches travelers to make a first aid kit for the camp. She believes that the foulness spreading through the forest has touched its harpies, and through them the Sentinels they wound. To hold such an affliction back she makes a salve from the fronds of dewy lashers, which grow around Lake Al'Ameth and Wellspring Lake, with a vial of spring water, though she cannot say whether it cures, since the rot festers quickly and grows stronger as it spreads.",
            {P1 .. " #97942 Camping 101: First Aid; #99047 Not Dead Yet; #99050 The Great Tree Provides; #99073 Easing Suffering", LF("quest:99050", "World_of_Warcraft:_Forever")},
            {}, {"place:dolanaar", TEL}),
        ForeverPerson("npc:yorana", "Yorana Windyreed",
            "Yorana Windyreed is a lieutenant of Valennia Stormfist among the peacekeepers of Zephras Isle. When the Al'Aketh cult attacked the pylon watchtower east of Valanaar, she led the relief force that broke through to its defenders. The cult outnumbers them there, its healers keep its attackers coming, and its commander is Belguilos the Breaker, once a peacekeeper herself and, in Yorana's words, a little off even then.",
            {P1 .. " #93320 Tower Defense; #92642 Disrupting Logistics; #92645 Breaking the Breaker", LF("quest:93320", "World_of_Warcraft:_Forever")},
            {"Yorana"}, {"npc:valennia", "place:valanaar", "group:al-aketh", ZEP}),
        ForeverPerson("npc:elaadrin", "Elaadrin Evengale",
            "Elaadrin Evengale is the Supreme Magister of the High Order, the arcane faction of the Skyborne, and leads it from a lodge in the southeast of Valanaar. Promising students are sent to him by Rathiril. When the Al'Aketh cult began its violence he argued for dialogue while the peacekeepers and Windshapers postured, and sent his friend Belathaan Brightwish to the Shrine of Akir to open talks. The cult sent back Belathaan's tongue dipped in silver pigment, and Elaadrin now holds that there is no reasoning with it. Ayessa Dawnsinger blames him for sending Belathaan alone.\n\nThe High Order looks beyond the island for an arcane answer to the instability that has troubled Zephras for years, and Elaadrin prepares an expedition to Azeroth with allies from the Kirin Tor.",
            {P1 .. " #92699 The Supreme Magister; #92834 Avenged Tenfold; #93746 A Firm Response; #93089 What Comes Next", LF("quest:92699", "World_of_Warcraft:_Forever"), LF("quest:92834", "World_of_Warcraft:_Forever")},
            {"Elaadrin", "Supreme Magister Elaadrin Evengale"}, {"faction:high-order", "place:valanaar", "npc:ayessa", ZEP}),
        ForeverPerson("npc:yelmak", "Yelmak",
            "Yelmak is a master alchemist who keeps a shop of alchemy and potions in the Valley of Honor in Orgrimmar. His apprentice Whuut is a prodigy who burns through the rarest reagents without learning the basics, and is too proud to ask for help. Yelmak means to teach him with remedies of the city's own cattail and speargrass, which grow around the water of the valley and are found nowhere else.",
            {P1 .. " #97242 Yelmak's Medley; #97275 Whuut's the Rush", LF("quest:97242", "World_of_Warcraft:_Forever")},
            {}, {"place:valley-honor", ORG}),
        ForeverPerson("npc:thra", "Thra",
            "Thra is one of the young orcs who play behind Grommash Hold in Orgrimmar, setting up their figures in a clear patch of dirt where the fortress guards leave them be. The children have nothing to sit on there, and Thra wants smooth boulders with a flat side for chairs and tables.",
            {P1 .. " #97326 Rocks to Rests", LF("quest:97326", "World_of_Warcraft:_Forever")},
            {}, {ORG}),
        ForeverPerson("npc:walton", "Walton",
            "Walton keeps watch over a valley of the Barrens from his ridge, with a rifle and its scope. He has seen soldiers in the livery of Kul Tiras searching the valley and camping by a wrecked caravan to the south. The remnants of Daelin Proudmoore's fleet who still fly his banner, he says, are as rotten and barbaric as the admiral was before he died.\n\nThe soldiers are hunting a deserter, and Walton knows that it is him. He served in the Kul Tiras navy, and when the Lord Admiral took Theramore and began his campaign in Durotar he objected to his methods, above all the executing of civilians.",
            {P1 .. " #95621 Trouble in the Valley; #95508 Unwelcome Guests", LF("quest:95621", "World_of_Warcraft:_Forever")},
            {}, {"region:5468652042617272656e73", "region:kul-tiras", "npc:daelin-proudmoore"}),
        ForeverPerson("npc:jemma-quikswitch", "Jemma Quikswitch",
            "Jemma Quikswitch is a gnome of Gnomeregan, now an exile in Ironforge. Before her people fled the city she copied her family's archives onto punch cards, among them arcanotechnical field equations, submarine hull designs from the Second War and her grandmother's chili recipe. On the way to Ironforge a hole in her pack let several cards fall into the snow outside Gnomeregan, and without them the rest is too scrambled to recover.",
            {P1 .. " #95041 Data Hoarders", LF("quest:95041", "World_of_Warcraft:_Forever")},
            {}, {"dungeon:gnomeregan", IF, "region:44756e204d6f726f6768"}),
        ForeverPerson("npc:thesten", "Quarrymaster Thesten",
            "Quarrymaster Thesten runs the Gol'Bolar Quarry in Dun Morogh, where the dwarves keep stores of blasting powder. Troggs have stolen a keg holding enough, by his account, to turn King Magni's throne room into an open-air courtyard, and he wants it back before they learn how to set it off. He would rather nobody spoke of the breach.",
            {P1 .. " #95213 Stolen Blasting Powder; #95214 Stolen Blasting Powder", LF("quest:95214", "World_of_Warcraft:_Forever")},
            {"Thesten"}, {"place:golbolar", "region:44756e204d6f726f6768"}),
        Note("npc:belgrum", "Advisor Belgrum", "Person",
            "Advisor Belgrum serves King Magni Bronzebeard in Ironforge and speaks with the king's authority. Reports of the Shadowforge clan's work in the Badlands reach him from Historian Karnik, and he orders it stopped. He holds that the Shadowforge's digging in Uldaman can be slowed by striking at their base, Angor Fortress, where Ragnaros himself sent Ambassador Infernus to mind their search for lost artifacts.",
            {V .. " #725 Passing Word of a Threat; #726 Passing Word of a Threat; #762 An Ambassador of Evil", LF("quest:725", "Advisor_Belgrum")},
            {"Belgrum"}, {"npc:karnik", "group:shadowforge", "place:angor-fortress", IF}),
        Note("npc:stoutfist", "Captain Stoutfist", "Person",
            "Captain Stoutfist commands the defense of Menethil Harbor from the war room of Menethil Keep. His enemy is the Dragonmaw clan. Nearly destroyed after the Second War, when its red dragons turned on their masters, the Dragonmaw fled Grim Batol into the mountains of the Wetlands and has regained its strength. Stoutfist counts them less of a threat without dragons but fierce still. Their leader, Nek'rosh, has built catapults to lay siege to the harbor, and the fighting in Dun Algaz cuts the port off from reinforcements.",
            {V .. " #473 Report to Captain Stoutfist; #464 War Banners; #465 Nek'rosh's Gambit", LF("npc:captain-stoutfist", "Captain_Stoutfist")},
            {"Stoutfist"}, {"place:menethil-keep", "place:menethil", "faction:dragonmaw", "place:dun-algaz"}),
        Note("npc:prospector-stormpike", "Prospector Stormpike", "Person",
            "Prospector Stormpike works for the Explorers' League in Ironforge, in the Hall of Explorers. Requests for supplies from the League's digs come to him, and Jern Hornhelm warns that he is hotheaded and will not like news of slow progress. He is also a master of decryption. Loremaster Dibbs of Southshore sends him the coded letters and enchanted parchments that no one else can read, and holds that there is no one north of Blackrock Spire better at it.",
            {V .. " #301 Report to Ironforge; #302 Powder to Ironband; #514 Letter to Stormpike; #554 Stormpike's Deciphering", LF("npc:prospector-stormpike", "Prospector_Stormpike")},
            nil, {"faction:explorers-league", "place:hall-explorers", "place:ironbands-excavation", IF}),
        Note("npc:roetten", "Roetten Stonehammer", "Person",
            "Roetten Stonehammer runs the business of Reclaimers Inc. from Ironforge. He sends adventurers across the sea to Kreldig Ungor at Nijel's Point in Desolace, takes in what the Reclaimers salvage there, and pays for the work in person. His men in the field say he gives orders as if the jobs were easy coin, short-handed as they are, such as gathering reagents from Desolace's demons and beasts for Leftwitch, the gnome mage of Kharanos.",
            {V .. " #1453 Reclaimers' Business in Desolace; #1457 The Karnitol Shipwreck; #1458 Reagents for Reclaimers Inc.; #1467 Reagents for Reclaimers Inc.", LF("npc:roetten-stonehammer", "Roetten_Stonehammer")},
            {"Roetten"}, {"group:reclaimers", "npc:kreldig-ungor", "place:nijels-point", IF}),
        Note("npc:salfa", "Salfa", "Person",
            "Salfa is a Timbermaw furbolg who stands guard at the Winterspring entrance of Timbermaw Hold, both a speaker for the tribe in Winterspring and its defender. The Winterfall of that frigid land have fallen under the same corruption as the furbolgs of Felwood, and their rage and fear of anything they do not understand have turned them against the Timbermaw. Salfa wants their numbers thinned at Winterfall Village, far to the east, since the Timbermaw have very few allies.",
            {V .. " #8465 Speak to Salfa; #8464 Winterfall Activity"},
            {}, {"faction:timbermaw", "place:timbermaw-hold", "faction:winterfall", "region:57696e746572737072696e67"}),
        Note("npc:erelas", "Erelas Ambersky", "Person",
            "Erelas Ambersky is a druid of Rut'theran Village on Teldrassil. He hatches the hippogryph eggs sent to him and trains the young hippogryphs, and without that work, he says, their numbers would not flourish. Curgle Cranklehop in Tanaris sends him crates of eggs. Erelas also studies the magic of the wildkin, which seems part of the creatures' very essence rather than something they wield, and compares the feathers of the wildkin of the Hinterlands with those of Winterspring.",
            {V .. " #3022 Handle With Care; #978 Moontouched Wildkin", LF("quest:3022", "Erelas_Ambersky")},
            {"Erelas"}, {"place:ruttheran", TEL, "npc:ranshalla"}),
        Note("npc:gnoarn", "Gnoarn", "Person",
            "Gnoarn is a gnome of Gnomeregan who lives among the exiles in Tinker Town in Ironforge. Since the radiation leak that cost his people their city, and by his own account cost him the only gnomefro in Azeroth, he thinks and talks of little but cleansing Gnomeregan of its troggs and curing the sickness there. He sends helpers to Ozzie Togglevolt in Kharanos, and he worries over Bingles Blastenheimer, whose reconnaissance flight over Gnomeregan has gone silent.",
            {V .. " #2927 The Day After; #2926 Gnogaine; #2039 Find Bingles", LF("npc:gnoarn", "Gnoarn")},
            {}, {"place:tinker-town", "dungeon:gnomeregan", "npc:ozzie", IF}),
        Note("npc:ozzie", "Ozzie Togglevolt", "Person",
            "Ozzie Togglevolt is a gnome of Gnomeregan who works in Kharanos with his partner Razzle Sprysprocket on a cure for the sickness of their city. By Razzle's account the gnomes failed to wipe out the troggs and instead turned most of their own people into mindless leper gnomes, and the two mean to reverse it with an invention of theirs, the Recombobulator. For their cure, or perhaps a very powerful rum, Ozzie needs radioactive fallout from Gnomeregan, the purest from its irradiated slimes, lurkers and horrors.\n\nOzzie was standing beside Gnoarn when a radiation bolt took his hair, and he still tells of it with relish.",
            {V .. " #412 Operation Recombobulation; #2926 Gnogaine; #2962 The Only Cure is More Green Glow; #2927 The Day After", LF("npc:ozzie-togglevolt", "Ozzie_Togglevolt")},
            {"Ozzie"}, {"place:kharanos", "dungeon:gnomeregan", "npc:gnoarn", "region:44756e204d6f726f6768"}),
        Note("npc:blazerunner", "Blazerunner", "Person",
            "Blazerunner is a fire elemental who dwells in the heart of Un'Goro Crater, an evil, in the words of those who know of it, of the purest form. An aura that no one can dispel protects it, except those given the power to do so.\n\nBlazerunner guards the Golden Flame, an artifact of vast power that is dangerous in the hands of one with an evil heart. Linken came to Un'Goro to destroy it, as the last step of a long journey, before he lost his memory. Its aura is broken with a totem shaped by the water spirit Aquementas, called up from a circle of stones on the coast of Tanaris.",
            {V .. " #4084 Silver Heart; #3961 Linken's Adventure; #3962 It's Dangerous to Go Alone; #4005 Aquementas"},
            {}, {"region:556e27476f726f20437261746572", "place:fire-plume", "npc:linken"}),
    })
end

-- notes6 batch 3: the smaller people of the 20-50 Alliance and Horde scenes, Gnomeregan's
-- exiles and the machine in its Clean Zone. Mulgris is named only when his branch reaches
-- Elder Rise (#4987 completion), so his note waits for it ("mulgris", LoreDiscoveryData.lua).
-- Willix, Shoni, Ruzzgot, Treshala and Feegly link by their distinctive names; "Mary",
-- "Flint" and "Red Jack" stay plain.
do
    local IF, TB = "region:49726f6e666f726765", "region:5468756e64657220426c756666"
    local BAR = "region:5468652042617272656e73"
    A.RegisterLoreNotes({
        Note("npc:ruzzgot", "Caravaneer Ruzzgot", "Person",
            "Caravaneer Ruzzgot is a goblin caravan driver based in Booty Bay who carries goods overland through Stranglethorn Vale. He has no jobs to offer and little patience for anyone without goods to ship, but he keeps a memory of his passengers. A night elf priestess, Velinde Starsong, once traveled north with his caravan until they parted on the way, and she was bound for Darkshire.",
            {V .. " #1040 Passage to Booty Bay; #1041 The Caravan Road", LF("quest:1041", "Caravaneer_Ruzzgot")},
            {"Ruzzgot"}, {"place:booty-bay", "npc:velinde", "region:537472616e676c6574686f726e2056616c65"}),
        Note("npc:red-jack-flint", "Red Jack Flint", "Person",
            "Red Jack Flint is a mariner on the docks of Menethil Harbor who longs to be at sea again. His job is to tell eager newcomers of Kalimdor, the land of opportunity, and to send those willing to try their luck across the sea to Theramore, where his partner Fiora Longears starts them on their way.",
            {V .. " #1132 Fiora Longears", LF("npc:red-jack-flint", "Red_Jack_Flint")},
            nil, {"place:menethil", "npc:fiora-longears", "place:theramore"}),
        Note("npc:fiora-longears", "Fiora Longears", "Person",
            "Fiora Longears is an elf in Theramore who meets the newcomers Red Jack Flint sends from Menethil Harbor. She advises them to go first to Astranaar and offer their services to Shindrell Swiftfire, though Shindrell does not know her. She also buys wyvern venom from the Highperch wyverns of Thousand Needles, which in some circles is worth more than the beasts.",
            {V .. " #1132 Fiora Longears; #1133 Journey to Astranaar; #1135 Highperch Venom", LF("quest:1132", "Fiora_Longears")},
            {"Fiora"}, {"place:theramore", "npc:red-jack-flint", "npc:shindrell-swiftfire", "place:astranaar"}),
        Note("npc:heralath", "Heralath Fallowbrook", "Person",
            "Heralath Fallowbrook, whose wife waits for him in Darnassus, was sent into Razorfen Kraul and lies dying there in the hands of the quilboar. The dwarf Lonebrow has gone to warn Falfindel. Heralath's last wish is that the pendant of bonding between him and his wife, Treshala, which one of the quilboar tore from him, be returned to her in Darnassus with word of his death.",
            {V .. " #1142 Mortality Wanes", LF("npc:heralath-fallowbrook", "Heralath_Fallowbrook")},
            {"Heralath"}, {"dungeon:razorfen-kraul", "npc:treshala", "npc:falfindel"}),
        Note("npc:treshala", "Treshala Fallowbrook", "Person",
            "Treshala Fallowbrook waits in Darnassus for word of her husband, Heralath, who went south into Razorfen Kraul. The pendant of bonding that ties them was taken from him by the quilboar.",
            {V .. " #1142 Mortality Wanes", LF("npc:treshala-fallowbrook", "Treshala_Fallowbrook")},
            {"Treshala"}, {"npc:heralath", "region:4461726e6173737573", "dungeon:razorfen-kraul"}),
        Note("npc:castpipe", "Master Mechanic Castpipe", "Person",
            "Master Mechanic Castpipe is a gnome in Ironforge who organizes bands to go back into Gnomeregan for its lost data. When the gnomes fled their city they left vital data behind, along with the security punch cards needed to reach them. The most important lie on a prismatic punch card in a Matrix Punchograph 3005-D high security terminal deep in the city, reached only through the lower terminals, models A, B and C, one card at a time.",
            {V .. " #2931 Castpipe's Task; #2930 Data Rescue", LF("quest:2930", "Master_Mechanic_Castpipe")},
            {"Castpipe"}, {"dungeon:gnomeregan", "place:tinker-town", IF}),
        Note("npc:kernobee", "Kernobee", "Person",
            "Kernobee has learned that Dark Iron dwarves are involved in the making of a great new rig at Gnomeregan, and he means to warn Tinkerwiz in Ratchet. His word of the rig had already set Scooty of Booty Bay building the Transpolyporter, a quick way into the city. The Dark Irons caught Kernobee, beat him within an inch of his life and threw him among the troggs of Gnomeregan.",
            {V .. " #2904 A Fine Mess; #2842 Chief Engineer Scooty", LF("npc:kernobee", "Kernobee")},
            {}, {"dungeon:gnomeregan", "faction:dark-iron", "place:booty-bay", "place:ratchet"}),
        Note("npc:shoni", "Shoni the Shilent", "Person",
            "Shoni the Shilent commands the gnomes' underground assault crew from among the dwarves of Stormwind. Her gyrodrillmatic excavationators are meant to bore through the rock around Gnomeregan and open the way for an assault on the troggs who hold it. The machines need the power supply of a working goblin shredder from the Deadmines and spare parts torn from the robots of Gnomeregan, and by her count, after the first repair, three hundred and ninety-eight are left to fix.",
            {V .. " #2041 Speak with Shoni; #2040 Underground Assault; #2928 Gyrodrillmatic Excavationators", LF("npc:shoni-the-shilent", "Shoni_the_Shilent")},
            {"Shoni"}, {"place:dwarven-district", "dungeon:gnomeregan", "dungeon:deadmines", "region:53746f726d77696e642043697479"}),
        Note("npc:tsunaman", "Tsunaman", "Person",
            "Tsunaman is an envoy at Sun Rock Retreat in the Stonetalon Mountains, sent by the Tribunal of the Tides to wage war on the fire elementals of the Charred Vale. Neptulon the Tidehunter, lord of the water elementals, takes a personal interest in seeing them put out. Tsunaman also sends Horde travelers to Je'neu Sancrea at Zoram'gar Outpost on the coast of Ashenvale.",
            {V .. " #6393 Elemental War; #6562 Trouble in the Deeps", LF("npc:tsunaman", "Tsunaman")},
            {}, {"place:sun-rock", "place:charred-vale", "npc:jeneu"}),
        Note("npc:willix", "Willix the Importer", "Person",
            "Willix the Importer is an entrepreneur, always out for a copper, held prisoner by the quilboar of Razorfen Kraul for longer than he can remember. He had heard that Mebok Mizzyrix of Ratchet paid well for Redleaf Tuber from the kraul and expected an easy job.",
            {V .. " #1144 Willix the Importer"},
            {"Willix"}, {"dungeon:razorfen-kraul", "npc:mebok"}),
        Note("npc:veren", "Veren Tallstrider", "Person",
            "Veren Tallstrider is a tauren leatherworker in Thunder Bluff who makes clothes and armor for its people from the skins of beasts. He trades his goods for hides brought from the hunt, and teaches young leatherworkers to make a bag of hide from the strong kodo of Mulgore.",
            {V .. " #768 Gathering Leather; #769 Kodo Hide Bag", LF("quest:768", "Veren_Tallstrider")},
            {"Veren"}, {TB}),
        Note("npc:feegly", "Feegly the Exiled", "Person",
            "Feegly the Exiled once dug at Bael Modan in the southern Barrens and held its first great find, a relic called the Tear of the Moons. General Twinbraid called it cursed, locked it away in the keep and drove Feegly off. Feegly says Twinbraid grew jealous of the power it gave him, and he wants it back.",
            {V .. " #857 The Tear of the Moons", LF("npc:feegly-the-exiled", "Feegly_the_Exiled")},
            {"Feegly"}, {"place:bael-modan", BAR}),
        Note("npc:tatternack", "Tatternack Steelforge", "Person",
            "Tatternack Steelforge is a smith of the Horde at Camp Taurajo in the Barrens who studies the weapons of its enemies for the warchief. He found the Razormane quilboar beyond the Field of Giants making sturdier weapons than anyone expected without a skilled smith among them, and warns that the Horde may have underestimated them. He also wants to test an unusual ore that travelers took from a kobold in Thousand Needles.",
            {V .. " #893 Weapons of Choice; #1153 A New Ore Sample", LF("npc:tatternack-steelforge", "Tatternack_Steelforge")},
            {"Tatternack"}, {"place:camp-taurajo", "faction:razormane", BAR}),
        Note("npc:bellygrub", "Bellygrub", "Creature",
            "Bellygrub is a boar that tramples and plunders the garden of Martie Jainrose in Lakeshire, ruining her daffodils for a season. Marshal Marris gave him the name. He forages in the hills of Redridge, and Martie offers a reward for his tusk.",
            {V .. " #34 An Unwelcome Guest", LF("quest:34", "Bellygrub")},
            {}, {"place:lakeshire", "npc:marris", "region:5265647269646765204d6f756e7461696e73"}),
        Note("npc:blind-mary", "Blind Mary", "Person",
            "Blind Mary is a sad spirit who haunts an old farmhouse in the hills south of Darkshire, where dark things now lurk. She cannot bear to be looked at and calls herself hideous; she tore out her own eyes, she says, yet still feels every gaze. Madame Eva spins thread from her ghostly hair, gathered with a spectral comb.",
            {V .. " #149 Ghost Hair Thread; #154 Return the Comb", LF("npc:blind-mary", "Blind_Mary")},
            {}, {"npc:madame-eva", "npc:abercrombie", "region:4475736b776f6f64"}),
        Note("artifact:sparklematic", "Sparklematic 5200", "Artifact",
            "The Sparklematic 5200 is a cleaning machine in the Clean Zone of Gnomeregan's dormitories. Items caked in the city's filth and hardened residue, such as the rings taken from Dark Iron dwarves, go in, and a box with the item scoured clean comes out. Some of the rings carry the seal of Ironforge or of Orgrimmar and a maker's initials.",
            {V .. " #2945 Grime-Encrusted Ring; #2947 Return of the Ring; #2949 Return of the Ring", LF("quest:2945", "Sparklematic_5200")},
            {"the Sparklematic 5200", "Sparklematic"}, {"dungeon:gnomeregan", "npc:nogg"}),
        Note("npc:laris", "Laris Geardawdle", "Person",
            "Laris Geardawdle is a gnome scholar in Ironforge who has studied oozes above all else. He has seen members of the Royal Apothecary Society collecting them and wants to know why. His samples from Felwood showed him that oozes adapt and take on the nature of the place they live in, and he looks for pure ones that the land has not polluted.",
            {V .. " #4512 A Little Slime Goes a Long Way; #4513 A Little Slime Goes a Long Way", LF("npc:laris-geardawdle", "Laris_Geardawdle")},
            {"Geardawdle"}, {IF, "faction:royal-apothecaries", "region:46656c776f6f64"}),
        Note("npc:mulgris", "Mulgris", "Person",
            "Mulgris was a tauren druid of the Cenarion Circle and a good friend of the druids at Elder Rise in Thunder Bluff. He went to minister to the creatures suffering in the Plaguelands and died there. The healthy, warm oaken branch found in his hand is carved with druidic glyphs and holds much lore about the plague the Scourge spreads, which the druids of Elder Rise mean to study.",
            {V .. " #4987 Glyphed Oaken Branch"},
            {}, {"place:elder-rise", "faction:cenarion-circle", "faction:scourge"}),
    })
end

-- notes6 batch 4: the 30-50 lane's people of Stranglethorn, Arathi, the Badlands, Feralas,
-- Desolace and Tanaris. Requests and premises only; what each errand achieves stays with
-- the scenes. Sigrun, Shay, Korin, Roon and Fin stay out as given names; "Nials" has a
-- second bearer in Lore Forever.
do
    local STV, ARA, BAD = "region:537472616e676c6574686f726e2056616c65", "region:41726174686920486967686c616e6473", "region:4261646c616e6473"
    A.RegisterLoreNotes({
        Note("npc:fin-fizracket", "Fin Fizracket", "Person",
            "Fin Fizracket has contracted Stranglethorn Fever, a deadly sickness, and can barely speak. The only cure he knows is to eat the heart of Mokk the Savage, an elusive white beast of the jungle, and only Witch Doctor Unbagwa, in a hidden cave on the southern cape of Stranglethorn, can summon it.",
            {V .. " #348 Stranglethorn Fever", LF("quest:348", "Fin_Fizracket")},
            nil, {"npc:unbagwa", "npc:mokk", STV}),
        Note("npc:unbagwa", "Witch Doctor Unbagwa", "Person",
            "Witch Doctor Unbagwa lives in a hidden cave on the southern cape of Stranglethorn Vale. He knows what Mokk the Savage likes and can call the white beast with his spirit talk, though the jungle's other gorillas answer the calling too, and he wants gorilla fangs before he begins.",
            {V .. " #348 Stranglethorn Fever; #349 Stranglethorn Fever", LF("quest:349", "Witch_Doctor_Unbagwa")},
            {"Unbagwa"}, {"npc:mokk", "npc:fin-fizracket", STV}),
        Note("npc:mokk", "Mokk the Savage", "Creature",
            "Mokk the Savage is an elusive white gorilla of the Stranglethorn jungle. Those who have caught Stranglethorn Fever believe that eating his heart is the only cure, and Witch Doctor Unbagwa can lure him out by speaking with the spirits.",
            {V .. " #348 Stranglethorn Fever; #349 Stranglethorn Fever", LF("quest:349", "Mokk_the_Savage")},
            {"Mokk"}, {"npc:unbagwa", "npc:fin-fizracket", STV}),
        Note("npc:whiskey-slim", "Whiskey Slim", "Person",
            "Whiskey Slim is a sailor of Booty Bay who knows all about liquid courage. When a storm caught his ship off the Overlook Cliffs, within sight of the Hinterlands, he broke into the captain's crate of Pupellyverbos Port, taken from a privateer bound for Stormwind, and a wave washed the bottles overboard. He fears a taste of the cat if the captain finds them missing.",
            {V .. " #580 Whiskey Slim's Lost Grog", LF("quest:580", "Whiskey_Slim")},
            nil, {"place:booty-bay", "region:5468652048696e7465726c616e6473"}),
        Note("npc:poobah", "Princess Poobah", "Person",
            "Princess Poobah is held captive on an island in the South Seas, off the coast of Stranglethorn, by the great Skymane King Mukla, who commands the island's beasts. A chain keeps her there. She sent word of her plight in a bottle that washed ashore, writing that on the clearest days she can see the Wild Shore to the northwest and large sailing ships to the southwest.",
            {V .. " #594 Message in a Bottle; #630 Message in a Bottle", LF("quest:630", "Princess_Poobah")},
            {"Poobah"}, {"npc:mukla", STV}),
        Note("npc:bloads", "Privateer Bloads", "Person",
            "Privateer Bloads works out of Booty Bay. His friend Privateer Groy makes a killing selling akiris reed, a valuable ocean reed taken from the naga, and Bloads gathers bundles of it and ships them to Groy in Theramore, though neither seems sure what the reed is for.",
            {V .. " #617 Akiris by the Bundle; #623 Akiris by the Bundle", LF("quest:617", "Privateer_Bloads")},
            {"Bloads"}, {"npc:groy", "place:booty-bay", STV}),
        Note("npc:groy", "Privateer Groy", "Person",
            "Privateer Groy sells akiris reed, an ocean reed the naga gather, from Theramore Isle, and pays his friend Privateer Bloads of Booty Bay well for bundles of it. He has clients who want more of it right away.",
            {V .. " #617 Akiris by the Bundle; #623 Akiris by the Bundle", LF("quest:623", "Privateer_Groy")},
            {"Groy"}, {"npc:bloads", "place:theramore"}),
        Note("npc:nials", "Captain Nials", "Person",
            "Captain Nials commands the Alliance camp at Refuge Pointe in the Arathi Highlands. The fight for Stromgarde has split the city between its defenders, the ogres and the Syndicate, and the defenders are losing. Supplies from Southshore must pass the Syndicate base at Northfold Manor, and Nials pays the bounties set on the Syndicate's leaders in Arathi, among them Lord Falconcrest, his bodyguard Otto, and the warlock Marez Cowl.",
            {V .. " #681 Northfold Manor; #634 Plea To The Alliance; #684 Wanted! Marez Cowl; #685 Wanted! Otto and Falconcrest", LF("quest:681", "Captain_Nials")},
            nil, {"place:refuge-pointe", "place:stromgarde", "faction:syndicate", ARA}),
        Note("npc:korin-fel", "Korin Fel", "Person",
            "Korin Fel is the wife of Drum Fel of Hammerfall in the Arathi Highlands. Her auguries show her what threatens her husband. The ogre Or'Kalar hates him for a defeat years ago and has laid a trap for him, and she has hidden the signs of the ogre from Drum, who would rush off to face him.",
            {V .. " #680 The Real Threat"},
            nil, {"place:hammerfall", "npc:orkalar", ARA}),
        Note("npc:orkalar", "Or'Kalar", "Person",
            "Or'Kalar is an ogre in Stromgarde, a pawn of Mug'thol. He has hated Drum Fel of Hammerfall ever since Drum defeated him years ago, and he wants nothing more than his death.",
            {V .. " #680 The Real Threat"},
            {}, {"npc:mug-thol", "place:stromgarde", "place:hammerfall", ARA}),
        Note("npc:phizzlethorpe", "Professor Phizzlethorpe", "Person",
            "Professor Phizzlethorpe is a gnome scientist at Faldir's Cove in the Arathi Highlands who, with Doctor Draxlegauge, has joined the Blackwater Raiders. Their job is to help Captain O'Breen find the lost elven treasure on the sea floor, and they have built goggles that must be charged with the energy of an enchanted stone in a cursed cave above the cove.",
            {V .. " #665 Sunken Treasure; #666 Sunken Treasure; #668 Sunken Treasure"},
            {"Phizzlethorpe"}, {"npc:draxlegauge", "place:faldirs-cove", "faction:blackwater-raiders", "npc:obreen"}),
        Note("npc:draxlegauge", "Doctor Draxlegauge", "Person",
            "Doctor Draxlegauge is a gnome of Faldir's Cove in the Arathi Highlands who, with Professor Phizzlethorpe, works for the Blackwater Raiders. He made the Goggles of Gem Hunting to find the elven gems on the sea floor, calcified into stone after so long in the water, and lends them to divers, since his own business keeps him on dry land. A few weeks among pirates have taught the two gnomes that holding on to pirate treasure is bad for their health.",
            {V .. " #666 Sunken Treasure; #668 Sunken Treasure"},
            {"Draxlegauge"}, {"npc:phizzlethorpe", "place:faldirs-cove", "faction:blackwater-raiders", "npc:obreen"}),
        Note("npc:sigrun", "Sigrun Ironhew", "Person",
            "Sigrun Ironhew is a dwarf smith of the expedition that left the Uldaman excavation in a hurry and now camps in the Badlands, waiting for word from Ironforge and the Explorers' League. Ogres from Camp Kosh stripped the wagons the dwarves abandoned, and with them the cart that carried their weapons, so the camp has gone hungry. Sigrun scrounges scrap metal from the ogres of Dustbelch Grotto for defenses. He learned a technique for fiery weapon enchantments as the apprentice of Feranor Steeltoe, and it needs the blood of a still-beating black drake whelp's heart from Lethlor Ravine.",
            {V .. " #718 Mirages; #733 Scrounging; #706 Fiery Blaze Enchantments", LF("quest:706", "Sigrun_Ironhew")},
            nil, {"npc:ryedol", "dungeon:uldaman", "place:lethlor-ravine", BAD}),
        Note("npc:lucien", "Lucien Tosselwrench", "Person",
            "Lucien Tosselwrench works beside the inventor Lotwil Veriatus in the Badlands and keeps the parts for his machines, cog number five among them. He knows how cheap Lotwil can be, and makes enchanted bracers from the extra stones gathered for Lotwil's newest invention, which he calls a coming atrocity.",
            {V .. " #716 Stone Is Better than Cloth; #734 This Is Going to Be Hard", LF("quest:716", "Lucien_Tosselwrench")},
            {"Tosselwrench"}, {"npc:lotwil", BAD}),
        Note("npc:thogrun", "Boss Tho'grun", "Person",
            "Boss Tho'grun leads a band of ogre mercenaries in the Badlands. The orcs of Kargath hired him to obtain the Sign of the Earth, the key to the drakes' prison in Lethlor Ravine, but he betrayed them and kept it.",
            {V .. " #782 Broken Alliances", LF("quest:782", "Boss_Tho%27grun")},
            {"Tho'grun"}, {"place:kargath", "place:lethlor-ravine", BAD}),
        Note("npc:rockbiter", "Rockbiter", "Person",
            "Rockbiter is a giant in Feralas who was meant to watch over his little friend Shay Leafrunner. While they walked through the ruins north of his spot she slipped away from him, and he is awfully worried, too slow of leg to go looking himself.",
            {V .. " #2844 The Giant Guardian; #2845 Wandering Shay"},
            {}, {"npc:shay", "region:466572616c6173"}),
        Note("npc:shay", "Shay Leafrunner", "Person",
            "Shay Leafrunner is a young night elf of Feralas and the friend of the giant Rockbiter, who is supposed to keep an eye on her. She wanders off whenever something catches her eye, and there are many things to see. Only the sound of a precious bell of hers will always call her back.",
            {V .. " #2845 Wandering Shay; #2844 The Giant Guardian", LF("quest:2845", "Shay_Leafrunner")},
            {}, {"npc:rockbiter", "region:466572616c6173"}),
        Note("npc:roon-wildmane", "Roon Wildmane", "Person",
            "Roon Wildmane is a tauren hunter of Desolace. Long ago the dwarf Hemet Nesingwary came there to hunt great beasts, and the two hunted together for many days, the enmity between their peoples forgotten. When Hemet left for Stranglethorn, Roon vowed to welcome him back one day, and he sends a kodo horn that Hemet will know.",
            {V .. " #5763 Hunting in Stranglethorn", LF("quest:5763", "Roon_Wildmane")},
            nil, {"npc:hemet-nesingwary", "region:4465736f6c616365", "place:nesingwarys-expedition"}),
        Note("npc:luglunket", "Spigot Operator Luglunket", "Person",
            "Spigot Operator Luglunket works for the Gadgetzan Water Company in Tanaris. The water in the Wastewander nomads' pouches is the company's own, he says, stolen like the wells, and for every five pouches brought back from the desert the company gives an official care package.",
            {V .. " #1707 Water Pouch Bounty", LF("quest:1707", "Spigot_Operator_Luglunket")},
            {"Luglunket"}, {"group:gadgetzan-water-company", "faction:wastewander", "place:gadgetzan", "region:54616e61726973"}),
    })
end

-- notes6 batch 5: the rest of the 30-50 lane's names, Tanaris to Azshara, Desolace, the
-- Swamp of Sorrows, the Hinterlands and the Searing Gorge, and the Harborage. Premises and
-- requests only. Galen, Andi, Tooga and Torta stay out as given names or short words.
do
    local TAN, SOS, DES = "region:54616e61726973", "region:5377616d70206f6620536f72726f7773", "region:4465736f6c616365"
    local HIN, SG = "region:5468652048696e7465726c616e6473", "region:53656172696e6720476f726765"
    A.RegisterLoreNotes({
        Note("npc:curgle", "Curgle Cranklehop", "Person",
            "Curgle Cranklehop is an inventor in Tanaris whose devices serve the worthwhile causes of her friends. Her Super Snapper FX takes pictures, and Daryn Lightwind of Rut'theran Village, who longs to see the giant snapjaw Gammerita of the Hinterlands beach, has one sent there. Curgle also sends crates of hippogryph eggs to the druid Erelas Ambersky in Rut'theran, who hatches them.",
            {V .. " #2941 The Borrower; #2944 The Super Snapper FX; #3022 Handle With Care", LF("quest:2944", "Curgle_Cranklehop")},
            {"Curgle"}, {"npc:erelas", "place:ruttheran", TAN}),
        Note("npc:andi-lynn", "Andi Lynn", "Person",
            "Andi Lynn of Tanaris is afraid of the Dunemaul ogres, a large band of nomads who have lately come into the desert and built a compound south of Gadgetzan. Smaller bands wander the sands, and some have taken over the old troll ruins. She wants the compound destroyed before the ogres build up a force, and believes that ending the rule of their leader, Gor'marok the Ravager, will be the beginning of the end for them.",
            {V .. " #5863 The Dunemaul Compound", LF("quest:5863", "Andi_Lynn")},
            nil, {"npc:gormarok", "place:gadgetzan", TAN}),
        Note("npc:gormarok", "Gor'marok the Ravager", "Person",
            "Gor'marok the Ravager leads the Dunemaul ogres, nomads who have recently arrived in Tanaris and taken a wide stretch of desert south of Gadgetzan for their compound.",
            {V .. " #5863 The Dunemaul Compound", LF("quest:5863", "Gor%27marok_the_Ravager")},
            {"Gor'marok"}, {"npc:andi-lynn", TAN}),
        Note("npc:tooga", "Tooga", "Person",
            "Tooga is lost in the Tanaris desert. His wife Torta sent him out to fetch dinner, and he took a wrong turn somewhere on the way back to her.",
            {V .. " #1560 Tooga's Quest", LF("quest:1560", "Tooga")},
            {}, {"npc:torta", "place:steamwheedle-port", TAN}),
        Note("npc:torta", "Torta", "Person",
            "Torta waits just south of Steamwheedle Port in Tanaris for her husband Tooga, whom she sent out to fetch dinner. She is not surprised when he cannot find his way back alone.",
            {V .. " #1560 Tooga's Quest", LF("quest:1560", "Tooga")},
            {}, {"npc:tooga", "place:steamwheedle-port", TAN}),
        Note("npc:malcin", "Ambassador Malcin", "Person",
            "Ambassador Malcin is an envoy of the Scourge who waits outside Razorfen Downs in the Barrens. Before Lordaeron fell he was a human diplomat of that kingdom, and now he is one of the Scourge's plagued servants. His letter to Charlga Razorflank of Razorfen Kraul offers her the Barrens and the lands beyond in return for the freedom to act there, and some of the quilboar have grown frightfully powerful while showing signs of the plague. Varimathras of the Forsaken wants the ambassador slain so that the Scourge gains no foothold in Kalimdor.",
            {V .. " #6522 An Unholy Alliance; #6521 An Unholy Alliance"},
            {"Malcin"}, {"faction:scourge", "dungeon:razorfen-downs", "npc:charlga", "npc:varimathras"}),
        Note("npc:rimtori", "Magus Rimtori", "Person",
            "Magus Rimtori is a blood elf who leads a band of workers among the ruins of Azshara. She persuaded Belgrom Rockmaul of Orgrimmar that the land held great riches and powerful items, and that a guard of his warriors would be well rewarded. She killed them all. She spends her days searching Azshara with her bodyguards, while her workers dig along the southern bluffs of its northern peninsula, and the goblin Kim'jael has worked for her as well.",
            {V .. " #3504 Betrayed; #3505 Betrayed; #5534 Kim'jael's \"Missing\" Equipment", LF("npc:magus-rimtori", "Magus_Rimtori")},
            {"Rimtori"}, {"npc:belgrom", "npc:agtor", "npc:kim-jael", "region:417a7368617261"}),
        Note("npc:agtor", "Ag'tor Bloodfist", "Person",
            "Ag'tor Bloodfist commands at Valormok in Azshara, north of the Haldarr Encampment. Belgrom Rockmaul sends him those who would avenge the warriors Magus Rimtori betrayed. Ag'tor's crusade starts with her blood elf workers on the northern peninsula, killed with bloody rage so that they know they betrayed the wrong allies, and then a search for her own camp.",
            {V .. " #3504 Betrayed; #3505 Betrayed"},
            {"Ag'tor"}, {"place:valormok", "npc:rimtori", "npc:belgrom", "region:417a7368617261"}),
        Note("npc:zamael", "Zamael Lunthistle", "Person",
            "Zamael Lunthistle is kept in a cage in the Searing Gorge, where no one has visited him for many years, and he has accepted his fate there. By his own account he has done countless malevolent deeds against the world and its peoples, yet his faith in Elune has been rekindled. His prayer to her is etched on a golden tablet that the idol worshippers of the Gorge took from him, and he wants it carried to Astarii Starseeker in Darnassus. He expects no absolution.",
            {V .. " #3377 Prayer to Elune; #3378 Prayer to Elune", LF("quest:3378", "Zamael_Lunthistle")},
            {"Zamael"}, {SG, "deity:elune", "region:4461726e6173737573"}),
        Note("npc:azore", "Azore Aldamort", "Person",
            "Azore Aldamort works from the tower of Ethel Rethor in Desolace, against the naga and the Burning Blade. He wants the Sceptre of Light, which legend says can sink whole cities beneath the sea, out of the hands of the Burning Blade seer who studies it at Thunder Axe Fortress. He also seeks the Book of the Ancients, which holds the secrets the naga have kept for centuries, guarded on Ranazjar Isle and summoned by setting the Gem of the Serpent in the hand of its serpent statue. What he learns goes to the high council.",
            {V .. " #5741 Sceptre of Light; #6027 Book of the Ancients", LF("quest:6027", "Azore_Aldamort")},
            {"Aldamort"}, {"faction:burning-blade", DES}),
        Note("npc:gurda-wildmane", "Gurda Wildmane", "Person",
            "Gurda Wildmane works against the centaur of Desolace by turning their hatred against them. Her plan is to ally with one clan and learn from it how to defeat them all. Whoever sides with the Magram must kill the Gelkis and then meet the Magram spokesman Warug, and whoever sides with the Gelkis must kill the Magram and then meet the Gelkis shaman Uthek the Wise.",
            {V .. " #1367 Magram Alliance; #1368 Gelkis Alliance", LF("quest:1367", "Gurda_Wildmane")},
            nil, {"faction:magram", "faction:gelkis", "npc:uthek", DES}),
        Note("npc:magtoor", "Magtoor", "Person",
            "Magtoor is one of the draenei of the Harborage in the Swamp of Sorrows. The lost ones of the Fallow Sanctuary to the east look as his people look, he says, but they are monsters, once their brethren and driven mad by the journey to Azeroth. They catch or kill any who wander near and have stolen the draenethyst crystals sacred to the Harborage, without which its people fear they too may lose their way. Noboru the Cudgel and his gang have terrorized the draenei of the swamp for months.",
            {V .. " #1389 Draenethyst Crystals; #1392 Noboru the Cudgel", LF("quest:1389", "Magtoor")},
            {"Magtoor"}, {"place:harborage", "place:fallow-sanctuary", SOS}),
        Note("npc:galen", "Galen Goodward", "Person",
            "Galen Goodward is trapped among the creatures of the Fallow Sanctuary in the Swamp of Sorrows, sure that they mean to eat him. He promises a great treasure for his rescue, kept in his camp in the swamp north of Stonard in a strongbox whose keyhole is filled with black resin. Only he knows the trick that opens it, a hidden latch on the bottom of the box.",
            {V .. " #1393 Galen's Escape", LF("quest:1393", "Galen_Goodward")},
            {"Goodward"}, {"place:fallow-sanctuary", "place:stonard", SOS}),
        Note("npc:lungertz", "Quartermaster Lungertz", "Person",
            "Quartermaster Lungertz keeps the stores of Nethergarde Keep in the Blasted Lands, where the keep watches over the Dark Portal. Its mages depend on powerstones from Darkshire, which lose their power if they are not carried quickly, and on the reagent called Azoran Crystals, whose stock runs low. Supplies come to him by caravan through the Swamp of Sorrows, and Watcher Biggs's caravan never arrived.",
            {V .. " #1395 Supplies for Nethergarde; #1425 Deliver the Shipment", LF("quest:1425", "Quartermaster_Lungertz")},
            {"Lungertz"}, {"place:nethergarde", "npc:biggs", "region:426c6173746564204c616e6473"}),
        Note("npc:orwin", "Orwin Gizzmick", "Person",
            "Orwin Gizzmick is a traveler newly arrived in Feralas, near Camp Mojache, who has heard that the Gordunni ogres keep interesting minerals. They bury their cobalt to keep it from people like him, so he lends out his shovel and means to sell what is found for a pretty penny on his travels.",
            {V .. " #2987 Gordunni Cobalt", LF("quest:2987", "Orwin_Gizzmick")},
            {"Gizzmick"}, {"faction:gordunni", "place:camp-mojache", "region:466572616c6173"}),
        Note("npc:slagtree", "Smith Slagtree", "Person",
            "Smith Slagtree is the orc smith of Revantusk Village in the Hinterlands. When the Vilebranch trolls raided the village they stole his tools, a set given to him by a kind-hearted gnome who saved his life when he was young, and they mean the world to him. Markhor saw them near the Agol'watha and Shaol'watha temples in the northeast of the Hinterlands.",
            {V .. " #7839 Vilebranch Hooligans", LF("quest:7839", "Smith_Slagtree")},
            {"Slagtree"}, {"place:revantusk", "faction:vilebranch", HIN}),
        Note("npc:fraggar", "Fraggar Thundermantle", "Person",
            "Fraggar Thundermantle is a Wildhammer dwarf of Aerie Peak in the Hinterlands, and he is quick to say that the Wildhammers are not part of the Alliance. They remember the past more than their brothers in Ironforge and judge outsiders by deeds rather than talk. He pays for the tribal necklaces of the hillside trolls, and wants the sludges and oozes cleared from the Horde's abandoned positions around Skulk Rock, where the Wildhammers have plans of their own.",
            {V .. " #2880 Troll Necklace Bounty; #2877 Skulk Rock Clean-up", LF("quest:2880", "Fraggar_Thundermantle")},
            {"Fraggar"}, {"place:aerie-peak", "faction:wildhammer", "place:skulk-rock", HIN}),
        Note("npc:burninate", "Master Smith Burninate", "Person",
            "Master Smith Burninate is a smith of the Thorium Brotherhood in the Searing Gorge. Overseer Maltorius left the Brotherhood for a promotion among the Dark Iron dwarves, taking its recipe for fiery flux with him, a secret Burninate values above a pristine arcane crystal, and Maltorius now commands the Dark Iron crew in the Slag Pit. Burninate wants the plans back, and with Scrange he wants the incendosaurs of the Slag Pit's lava pools cleared for expedition teams.",
            {V .. " #7722 What the Flux?; #7727 Incendosaurs? Whateverosaur is More Like It; #7701 WANTED: Overseer Maltorius", LF("quest:7722", "Master_Smith_Burninate")},
            {"Burninate"}, {"faction:thorium-brotherhood", "place:thorium-point", SG}),
    })
end

-- notes6 batch 6: Security Chief Bilgewhizzle of Steamwheedle Port, a second goblin of that
-- name (the short "Bilgewhizzle" stays with the chief engineer of Gadgetzan, as the scenes
-- use it), and names the scan still ranks high: Lethlor Ravine's drakes and those who want
-- them dead, Timbermaw's road guard, Un'Goro's hot springs, the Flame Crest, Stonetalon Peak
-- and Brackenwall. Nothing here says how the drakes or the shield's story end.
do
    local BAD = "region:4261646c616e6473"
    A.RegisterLoreNotes({
        Note("npc:security-chief-bilgewhizzle", "Security Chief Bilgewhizzle", "Person",
            "Security Chief Bilgewhizzle keeps the law at Steamwheedle Port in Tanaris. Wanted notices for pirates such as Andre Firebeard, whose crimes are against both Steamwheedle and Gadgetzan, name him as the one to receive their heads, which by decree may stand in for the accused at a hearing, and his payment comes with a contract and small print no one could read. Stolen ship schedules between Steamwheedle Port and Booty Bay, marked up by pirates with notes of loot and hard fights, also come to him.",
            {V .. " #2875 WANTED: Andre Firebeard; #2876 Ship Schedules", LF("quest:2875", "Security_Chief_Bilgewhizzle")},
            nil, {"place:steamwheedle-port", "npc:andre-firebeard", "npc:bilgewhizzle", "region:54616e61726973"}),
        Note("npc:garek", "Garek", "Person",
            "Garek has come to the Badlands at the bidding of his master, Krasus of the Kirin Tor, to end the trouble brewing in Lethlor Ravine. He keeps the exact nature of his task to himself. He holds that the black drakes Blacklash and Hematus can no longer be trusted to stay imprisoned there, now that black dragons have settled in the ravine and ogres have stolen the Sign of the Earth, and he wants their dreams made eternal.",
            {V .. " #732 Tremors of the Earth; #717 Tremors of the Earth"},
            {"Garek"}, {"place:lethlor-ravine", "npc:blacklash", "faction:kirin-tor", BAD}),
        Note("npc:gorn", "Gorn", "Person",
            "Gorn of Kargath in the Badlands wants the Horde's honor restored. In the Second War the Horde was allied with Deathwing, and two of his lieutenants, the black drakes Blacklash and Hematus, were imprisoned in Lethlor Ravine. Gorn wants those depraved allies of old silenced. The ogre Tho'grun, hired to get the Sign of the Earth that opens their prison, kept it for himself. In Gorn's eyes the black dragonflight still stands with the renegade Blackrock orcs.",
            {V .. " #782 Broken Alliances; #793 Broken Alliances"},
            {"Gorn"}, {"place:kargath", "npc:blacklash", "npc:thogrun", BAD}),
        Note("npc:blacklash", "Blacklash", "Person",
            "Blacklash is a black drake, one of the two lieutenants of Deathwing who were imprisoned in Lethlor Ravine in the Badlands after the Second War, with Hematus. Their prison is the Seal of the Earth, held by three runestones in the Pillars of Diamond, Opal and Amethyst, and only the Sign of the Earth can draw the runestones out.",
            {V .. " #782 Broken Alliances; #793 Broken Alliances; #717 Tremors of the Earth"},
            {"Blacklash"}, {"npc:hematus", "place:lethlor-ravine", "npc:deathwing"}),
        Note("npc:hematus", "Hematus", "Person",
            "Hematus is a black drake, one of the two lieutenants of Deathwing who were imprisoned in Lethlor Ravine in the Badlands after the Second War, with Blacklash. The Horde of Kargath and the Kirin Tor's agent Garek both want the pair dead before they can escape.",
            {V .. " #782 Broken Alliances; #793 Broken Alliances; #717 Tremors of the Earth"},
            {"Hematus"}, {"npc:blacklash", "place:lethlor-ravine", "npc:deathwing"}),
        Note("npc:nafien", "Nafien", "Person",
            "Nafien is a Timbermaw furbolg who stands guard outside the Felwood entrance of Timbermaw Hold. He may look like a feral beast, but he seeks help against the forces that threaten his tribe's home. A camp of Deadwood furbolgs lies southwest of his post, thick with corruption. The Deadwood are evil, he says, but it is the fel that pollutes their minds, and it saddens him to fight his own kin; he would rather not hear the details. He sends further help across the Hold to Salfa at the Winterspring entrance.",
            {V .. " #8462 Speak to Nafien; #8461 Deadwood of the North; #8465 Speak to Salfa"},
            {"Nafien"}, {"faction:timbermaw", "place:timbermaw-hold", "npc:salfa", "region:46656c776f6f64"}),
        Note("npc:krakle", "Krakle", "Person",
            "Krakle studies the hot springs of Un'Goro Crater near Fire Plume Ridge and wonders where their heat comes from, suspecting the volcano. He built a thermometer that reads in degrees Kraklenheit to find the ridge's hottest spots. Hearing of hot springs in Winterspring with no volcano near them, he sends those curious to his friend Donova Snowden, who stays beside them.",
            {V .. " #974 Finding the Source; #980 The New Springs"},
            {"Krakle"}, {"place:fire-plume", "npc:donova", "region:556e27476f726f20437261746572"}),
        Note("npc:tinkee", "Tinkee Steamboil", "Person",
            "Tinkee Steamboil studies the dragons of Blackrock Mountain from the Flame Crest in the Burning Steppes. Her inventions include the Draco Incarcinatrix 900, which captures the essence of dragon whelp broodlings, and the eggscilloscope, meant to freeze the eggs of black dragons in the rookery high in Blackrock Spire. Frozen eggs should be harmless, she says, and it is the unfrozen ones to worry about. Felnok Steelspring in Winterspring is a friend of hers.",
            {V .. " #4726 Broodling Essence; #4734 Egg Freezing; #4735 Egg Collection; #4907 Tinkee Steamboil"},
            {"Tinkee"}, {"place:flame-crest", "dungeon:blackrock-spire", "npc:felnok", "region:4275726e696e672053746570706573"}),
        Note("npc:albagorm", "Keeper Albagorm", "Person",
            "Keeper Albagorm waits on Stonetalon Peak as a protector of the forest spirits. The Charred Vale to the south was set afire by a greedy mechanized army of industrialists, and the Bloodfury harpies who have moved into it refuse the druids passage to begin its regrowth. Albagorm wants the harpies driven out, and sends word south to the druid Falfindel Waywarder, who can call the great forest spirits to restore the vale.",
            {V .. " #1056 Journey to Stonetalon Peak; #1057 Reclaiming the Charred Vale; #1059 Reclaiming the Charred Vale", LF("npc:keeper-albagorm", "Keeper_Albagorm")},
            {"Albagorm"}, {"place:stonetalon-peak", "place:charred-vale", "npc:falfindel", "region:53746f6e6574616c6f6e204d6f756e7461696e73"}),
        Note("npc:dogol", "Do'gol", "Person",
            "Do'gol is the blacksmith of Brackenwall Village in Dustwallow Marsh. Krog sends him a blackened iron shield whose writing is hidden under burned residue, and Do'gol, who calls it a good, strong shield, cleans it with the acid of the marsh's Darkfang spiders.",
            {V .. " #1321 The Black Shield; #1322 The Black Shield; #1323 The Black Shield"},
            {"Do'gol"}, {"place:brackenwall", "npc:krog", "region:4475737477616c6c6f77204d61727368"}),
    })
end

-- Seventh notes lane (notes7), 2026-11-06. Batch 1: the people the scan still ranked
-- highest. Talen of the Zoram Strand, Piznik of Windshear Crag, Drum Fel of Hammerfall,
-- Booty Bay's Scooty, Seereth Stonebreak and Marukai of Stonetalon and Ashenvale, Daryn
-- Lightwind of Rut'theran and Forever's Trevan Rol. "Trevan" and "Daryn" stay out as given
-- names; their full names link. Nothing here says how Natalia, Tyranis or Anilia fare.
do
    local ASH, HIN = "region:417368656e76616c65", "region:5468652048696e7465726c616e6473"
    local ARA, STO = "region:41726174686920486967686c616e6473", "region:53746f6e6574616c6f6e204d6f756e7461696e73"
    A.RegisterLoreNotes({
        Note("npc:talen", "Talen", "Person",
            "Talen is a night elf scholar camped on the Zoram Strand, the northwestern coast of Ashenvale, where the city of Zoram was drowned in the Sundering. He was skimming over its submerged ruins in a small boat when naga surged from the water and clawed at him, and he fled ashore with what supplies he could carry. On the way he lost his prized possession, an ancient statuette that he believes may be the key to many of the old city's secrets, and the reason he braved the coast at all.\n\nThe statuette has a lock of its own. Its key, Talen holds, is the Ring of Zoram, which belonged to the city's rulers and is said to open any lock within it. The ring was lost for years until the naga found it, and their leader, Ruuzel, keeps it on an isle at Zoram's northern edge.",
            {V .. " #1007 The Ancient Statuette; #1009 Ruuzel", LF("npc:talen", "Talen")},
            {"Talen"}, {"place:zoram-strand", "relic:ring-zoram", ASH}),
        Note("npc:piznik", "Piznik", "Person",
            "Piznik is a goblin of the Venture Company at Windshear Crag in the Stonetalon Mountains. He was once the second most important person at the site, until Gerenzo Wrenchwhistle took over, fired his boss, Ziz Fizziks, and sent him down to work in the mines. Ziz told him to stay and gather what he could of Gerenzo's plans, since Ziz's new employer will pay them both well to learn them.\n\nWhat Piznik knows so far is that Gerenzo has ordered large amounts of a gold-green ore to be mined. He can dig out a sample, though patrols and workers pass his spot constantly, and he expects the company's higher-ups to take a dim view of him once word of it spreads.",
            {V .. " #1090 Gerenzo's Orders; #1092 Gerenzo's Orders", LF("npc:piznik", "Piznik")},
            {"Piznik"}, {"npc:ziz-fizziks", "npc:gerenzo", "place:windshear-crag", STO}),
        Note("npc:drum-fel", "Drum Fel", "Person",
            "Drum Fel commands Hammerfall, the Horde's outpost in the Arathi Highlands, which is under constant attack. The Witherbark trolls and the Boulderfist ogres of Arathi have joined to drive the Horde out. In his words the trolls turned their backs on the Horde and the ogres would use its people for food and bedding, and he means to show both that the Horde has a home in the Highlands too. He strikes first at the Witherbark camps south of the outpost, then at the Boulderfist lair toward the dwarven bridge, and last at the Boulderfist lords and their shaman in the ruins of Stromgarde, where the attacks are led from.\n\nNew fighters reach him from Tarren Mill, where Tallow first sends them to test themselves on a Boulderfist ogre mound. Drum is not sure whether Tallow hopes they will die there. His wife, Korin Fel, has hidden from him the signs of the ogre Or'Kalar, who hates Drum for defeating him years ago and has laid a trap for him.",
            {V .. " #676 The Hammer May Fall; #677 Call to Arms; #678 Call to Arms; #679 Call to Arms; #680 The Real Threat", LF("npc:drum-fel", "Drum_Fel")},
            nil, {"place:hammerfall", "npc:korin-fel", "faction:boulderfist", ARA}),
        Note("npc:scooty", "Chief Engineer Scooty", "Person",
            "Chief Engineer Scooty is a goblin engineer at the wind rider roost of Booty Bay. When Kernobee sent word of a new gnomish rig at Gnomeregan, Scooty and his partner Sovik set to work on the Transpolyporter 6000, which they call the fastest and most reliable way to Gnomeregan, and its passengers board with Scooty. He calls it the pinnacle of goblin transport technology and admits that it has only exploded a dozen or so times. The alternative is a run to the gnome city through the dwarf-held mountains of Dun Morogh. To Scooty, Mekgineer Thermaplugg is a good-for-nothing backstabber.",
            {V .. " #2842 Chief Engineer Scooty; #2904 A Fine Mess", LF("npc:scooty", "Scooty")},
            {"Scooty"}, {"place:booty-bay", "npc:kernobee", "dungeon:gnomeregan", "npc:thermaplugg"}),
        Note("npc:seereth", "Seereth Stonebreak", "Person",
            "Seereth Stonebreak is a promising orc shaman whom the Horde sent to the Stonetalon Mountains when the land's spirits cried out against the goblins plundering and burning it. She camps near the Greatwood Vale, at the end of the road west from the Crossroads of the Barrens, and reports massive deforestation by the Venture Company. The spirits there, she says, are nearly blind with pain and rage, and she wants the company's workers in Windshear Crag shown the Horde's answer in the language they understand best, which is violence.\n\nShamans can hear the plea of those spirits, Seereth explains, because their spiritual magic is related to the natural magic of druids. Many of the whispers are lost to her, but one vision is clear, of two man-shaped machines marked with strange symbols felling the trees of Windshear Crag with impossible speed. She believes the wisdom of the tauren elders may be needed to calm the spirits, and the one elder she knows by name is Magatha of Elder Rise in Thunder Bluff.",
            {V .. " #1061 The Spirits of Stonetalon; #1062 Goblin Invaders; #1068 Shredding Machines; #1063 The Elder Crone", LF("npc:seereth-stonebreak", "Seereth_Stonebreak")},
            {"Seereth"}, {"place:greatwood-vale", "place:windshear-crag", "faction:venture-company", "npc:magatha"}),
        Note("npc:marukai", "Marukai", "Person",
            "Marukai is a Darkspear troll who holds Zoram'gar Outpost for the Horde on the Zoram Strand, the northwestern coast of Ashenvale. Beneath the sea there lies the doomed city of Zoram, long destroyed and nearly forgotten, and now the naga have returned to it for reasons no one knows. The reason matters little to Marukai. The Horde has worked hard to claim this land, and he wants the naga thrown back to the depths, with their heads brought to him as proof.",
            {V .. " #6442 Naga at the Zoram Strand", LF("npc:marukai", "Marukai")},
            {"Marukai"}, {"place:zoramgar", "place:zoram-strand", ASH}),
        Note("npc:daryn-lightwind", "Daryn Lightwind", "Person",
            "Daryn Lightwind is a night elf historian of Rut'theran Village, at the foot of Teldrassil, who has studied many subjects in her time. On her shelves is an old, worn history of Feralas, which she lends only in return for a favor. Troyas Moonbreeze of Feathermoon Stronghold counts her a colleague and sends her his questions. She, for her part, thinks he always believes he has found something important, and that anything of real value in the ruins of Feralas was hoarded long ago by the ogres or the harpies who live there now.\n\nHer latest fascination is the snapjaws of the beach in the Hinterlands, above all a giant one named Gammerita. Her research keeps her at home, so Curgle Cranklehop of Tanaris, who calls her quite a knowledgeable historian, built her a device that takes pictures, the Super Snapper FX. Her studies also keep her from the elven ruins of Winterspring, and she sends students there to Wynd Nightchaser at Starfall, who knows the area well.",
            {V .. " #2939 In Search of Knowledge; #2940 Feralas: A History; #2941 The Borrower; #2944 The Super Snapper FX; #2943 Return to Troyas; #5250 Starfall", LF("quest:2941", "Daryn_Lightwind")},
            nil, {"npc:troyas", "npc:curgle", "place:ruttheran", HIN}),
        ForeverNote("npc:trevan-rol", "Trevan Rol", "Person",
            "Trevan Rol is a paladin of Bandarion Keep and its man at the Sepulcher in Silverpine Forest. When two dignitaries of the Earthen Ring went missing in Silverpine on their way to Tarren Mill, rumor called it a diplomatic incident, and Danitha Morr saw in it a chance for the keep's paladins to prove their worth in the eyes of the Horde. Trevan says the pair were no ordinary diplomats. One was a tauren, and the other, cloaked, was a high elf, he would swear, for he has seen quel'dorei before. Why an elf would travel with a tauren through Horde lands he cannot say, and he sends those who ask to Deathguard Baldren near the entrance.\n\nThe worgen of Silverpine can be killed despite their strength, in Trevan's view, all but Old Fire-Eye, the biggest of them, who never seems to stay dead. Trevan has a list of what is needed to forge a blade that can put the beast down. For the smith he chose Ott of Tarren Mill, an orc who sells plain blades to travelers. Trevan once bought a sword from him, and the smiths of the Undercity who later saw it took it for the work of a known master.",
            {P1 .. " #91858 Diplomatic Incident; #91859 A Curious Pair; #95036 A Moon-Kissed Blade; #95111 An Underrated Talent; #95126 The Moonsilver Blade"},
            nil, {"place:sepulcher", "npc:danitha", "npc:ott", "place:bandarion"}),
    })
end

-- notes7 batch 2: Prospector Agmond and the word beside his hand, Ironband who sent him,
-- Arikara and the Magatha question, and the people of the 20-50 scenes still unnamed in the
-- catalogue (Nek'rosh, Valstag Ironjaw, Karl Boran, Darsok Swiftdagger, Orendil Broadleaf,
-- Sanath Lim-yo, J.D. Collie, Cliffwatcher Longhorn, Xavathras, Hagar Lightninghoof).
-- Agmond's death, his last report and his last word, Murdaloc as a name at all, and
-- Magatha's claim about Cairne with Motega's doubt are discoveries (LoreDiscoveryData.lua,
-- "agmond.*" and "arikara.*"). Hagar, Karl and the one-word "Longhorn" stay out as a given
-- name and a word; their full names link.
do
    local BAD, LOCH = "region:4261646c616e6473", "region:4c6f6368204d6f64616e"
    local TN, WET = "region:54686f7573616e64204e6565646c6573", "region:5765746c616e6473"
    local BAR, FEL = "region:5468652042617272656e73", "region:46656c776f6f64"
    A.RegisterLoreNotes({
        Note("npc:agmond", "Prospector Agmond", "Person",
            "Prospector Agmond is a dwarf in charge of the excavation sites in the Badlands that Prospector Ironband of Loch Modan oversees. His last known post was the southernmost dig site in the Badlands, a tiny operation past Angor Fortress. Ironband has not heard from him in weeks and wants his report.\n\nAgmond is dead, and his broken, battered bones lie picked clean at the southern dig.\n\nHis last report to Ironband told of ancient urns his diggers had uncovered at the dig site outside Uldaman. Ironband fears that the urns stirred up the troggs, just as the idols found at his own excavation did, and wants them gathered for study.\n\nBloody smears across rock and sand show that Agmond crawled some distance from the west before he died. Beside his dead hand the word Murdaloc is scrawled in a patch of sandstone.\n\nIronband takes it as sobering news. He believes the troggs killed Agmond, and he is sure that a dwarf with so strong an arm, so fierce a hammer swing and so thick a skull took a lot of them down with him.",
            {V .. " #738 Find Agmond; #704 Agmond's Fate; #739 Murdaloc", LF("subzone:agmond-s-end", "Agmond%27s_End")},
            {"Agmond"}, {"npc:ironband", "place:angor-fortress", "dungeon:uldaman", BAD}),
        Note("npc:murdaloc", "Murdaloc", "Person",
            "Murdaloc is the word scrawled in the sandstone of the southern Badlands beside the dead hand of Prospector Agmond, at the end of the bloody trail he crawled from the west. Prospector Ironband of Loch Modan wants Agmond's killer slain.\n\nIronband holds that the troggs killed Agmond, and he is sure the prospector took a lot of them down with him.",
            {V .. " #739 Murdaloc"},
            {"Murdaloc"}, {"npc:agmond", "faction:stonevault", BAD}),
        Note("npc:ironband", "Prospector Ironband", "Person",
            "Prospector Ironband heads an excavation of ancient ruins east of the lake in Loch Modan, at Ironband's Excavation. Jern Hornhelm of Thelsamar calls him a stout, honest dwarf who values results, which is why the slow progress of the dig worries Jern, given all the supplies sent to it. The trouble is the troggs. Ironband asks Thelsamar for more blastpowder, though Jern sent him plenty weeks ago and does not know where it went. Ironband believes the idols found at his excavation have stirred the troggs up.\n\nHis work reaches beyond Loch Modan. Prospector Agmond runs the excavation sites in the Badlands for him, and Ironband's reports go to Prospector Stormpike in Ironforge, who sends help when Ironband has legwork to be done.",
            {V .. " #436 Ironband's Excavation; #298 Excavation Progress Report; #302 Powder to Ironband; #707 Ironband Wants You!; #738 Find Agmond; #704 Agmond's Fate", LF("npc:prospector-ironband", "Prospector_Ironband")},
            {"Ironband"}, {"place:ironbands-excavation", "place:thelsamar", "npc:agmond", "npc:prospector-stormpike"}),
        Note("npc:arikara", "Arikara", "Person",
            "Arikara is a serpent of vengeance from an old tauren legend. Hagar Lightninghoof of Freewind Post saw something in Thousand Needles he could hardly believe, and to Motega Firemane of Whitereach Post it proved the legend true. Arikara cannot be hunted like an ordinary beast. She is summoned by lighting the sacred fire of life on Darkcloud Pinnacle, an isolated needle where the tauren bury their dead, and the fire is lit with a powder made from the rare Incendia agave of the Boiling Pool and enchanted by a shaman as powerful as Magatha Grimtotem.\n\nMagatha, who enchants the powder, calls Arikara a deadly creature born only to seek vengeance against those who have committed heinous acts.\n\nMagatha fears that Arikara may be stalking Cairne Bloodhoof, the High Chieftain, because too much tauren lore has changed and the change has angered the serpent.\n\nOnce Arikara is dead, Motega cannot see why she would have been after Cairne. Magatha could not be wrong, he reasons, for she is the tauren's most powerful shaman, and yet her explanation makes no sense to him.",
            {V .. " #4865 Serpent Wild; #5062 Sacred Fire; #5088 Arikara", LF("item:arikara-serpent-skin", "Arikara")},
            {"Arikara"}, {"npc:motega-firemane", "place:darkcloud-pinnacle", "npc:magatha", "npc:cairne"}),
        Note("npc:nekrosh", "Nek'rosh", "Person",
            "Nek'rosh is the chieftain of the Dragonmaw orcs in the Wetlands and the son of Nekros, who led the clan years ago. Nekros used powerful magic to tame the red dragons, and when that magic failed him the dragons killed him. His son has sworn revenge against them.\n\nThe Dragonmaw were all but destroyed by the end of the Second War, after they lost control of their dragons, and the few who were left fled from Grim Batol into the mountains east of Whelgar's Excavation. Under Nek'rosh they have gained strength again. They hold an encampment northeast of Menethil Harbor and have pushed into Dun Algaz, and in the encampment Nek'rosh has had catapults built to lay siege to Menethil, which the fighting in Dun Algaz has cut off from reinforcements.",
            {V .. " #464 War Banners; #465 Nek'rosh's Gambit; #474 Defeat Nek'rosh; #455 The Algaz Gauntlet", LF("item:nek-rosh-s-head", "Nek%27rosh")},
            {"Chieftain Nek'rosh"}, {"faction:dragonmaw", "place:menethil", "place:dun-algaz", "place:grim-batol"}),
        Note("npc:valstag", "Valstag Ironjaw", "Person",
            "Valstag Ironjaw takes the reports on the Dragonmaw orcs at Menethil Harbor, the Alliance's port and stronghold in the Wetlands. The orcs have spread from their haven in the Wetlands into Dun Algaz, and if they hold it, Loch Modan will be cut off from Menethil. The Dragonmaw usually hide in the hills, Valstag says, and what made them surge into Algaz is still a mystery to him.",
            {V .. " #455 The Algaz Gauntlet", LF("npc:valstag-ironjaw", "Valstag_Ironjaw")},
            {"Valstag"}, {"place:menethil", "place:dun-algaz", "faction:dragonmaw", WET}),
        Note("npc:karl-boran", "Karl Boran", "Person",
            "Karl Boran of Menethil Harbor wants back the cargo that murlocs dragged overboard when they raided the merchant vessel Blind Princess. The ship escaped intact, but among the lost cargo was the Menethil Statuette, a valuable statuette of Terenas Menethil. It is a silvery figure of a young, long-haired paladin with his hammer upraised, packed in fine straw. The murlocs carried the crates and barrels of the cargo to their hovels along the coast.",
            {V .. " #281 Reclaiming Goods; #286 Return the Statuette"},
            nil, {"place:menethil", WET}),
        Note("npc:darsok", "Darsok Swiftdagger", "Person",
            "Darsok Swiftdagger is an orc of the Crossroads in the Barrens who wants the Witchwing harpies of the Dry Hills cut down. They have ravaged the Horde's caravan supplies for too long. Darsok has snooped around their nests to learn who leads whom, so that the Horde can work its way up their chain of command from the bottom. Only Witchwing Slayers serve as lieutenants, and they are known by the rings they carry.\n\nAt the top stands Serena Bloodfeather, the sister of a harpy named Bloodfeather whom Rexxar slew long ago. Darsok believes the attacks on the caravans are her revenge for her sister's death. He wants her head placed on the next caravan the Horde sends out, to give the harpies something to think about.",
            {V .. " #867 Harpy Raiders; #875 Harpy Lieutenants; #876 Serena Bloodfeather", LF("npc:darsok-swiftdagger", "Darsok_Swiftdagger")},
            {"Darsok"}, {"place:crossroads", "npc:rexxar", BAR}),
        Note("npc:orendil", "Orendil Broadleaf", "Person",
            "Orendil Broadleaf tends the sick at Maestra's Post in western Ashenvale, and his skill with herbs and healing is great, in the words of those he has helped. A child of Astranaar, Relara, the daughter of Pelturas Whitemoon, grows weaker by the hour, and Orendil believes her illness is more than physical. To treat it he seeks Bathran's Hair, a plant once found in the old ruins of Bathran's Haunt, north of Maestra's Post and just south of the Darkshore border, which was known to cure ailments of the spirit.",
            {V .. " #1010 Bathran's Hair; #1020 Orendil's Cure", LF("npc:orendil-broadleaf", "Orendil_Broadleaf")},
            {"Orendil"}, {"place:maestras-post", "npc:pelturas", "place:bathrans-haunt", "region:417368656e76616c65"}),
        Note("npc:sanath", "Sanath Lim-yo", "Person",
            "Sanath Lim-yo serves Archmage Xylem in Azshara, whose tower stands high on the cliffs. He does not like adventurers and tells them so, with sarcasm first and plain words after. His master has asked him to send on anyone who proves worthy, and Sanath's price for leave to see Xylem is a couple of hippogryph feathers for his arrows.",
            {V .. " #3381 A Meeting with the Master"},
            {"Sanath"}, {"npc:xylem", "region:417a7368617261"}),
        Note("npc:jd-collie", "J.D. Collie", "Person",
            "J.D. Collie studies the crystals that lie all over Un'Goro Crater. Most people ignore them, but she has a strange feeling that they hold power, though her experiments have not found it yet, and she keeps running low on crystals. She has also heard rumors of crystal pylons in the crater, one of them somewhere in the north, and she cannot get them out of her head. By her own account she will usually believe anything people tell her.",
            {V .. " #4284 Crystals of Power; #4285 The Northern Pylon"},
            nil, {"region:556e27476f726f20437261746572"}),
        Note("npc:cliffwatcher-longhorn", "Cliffwatcher Longhorn", "Person",
            "Cliffwatcher Longhorn keeps watch at Freewind Post in Thousand Needles. The centaur have stepped up their attacks in the area, and they raided one of his supply caravans and slaughtered the whole party. Longhorn calls it an outrage that will not go unpunished, and he wants the centaur camp north of Freewind Post attacked. From the Great Lift comes a warning as well, that the Grimtotem nearby have been acting strangely toward the post's people.",
            {V .. " #4542 Message to Freewind Post; #4841 Pacify the Centaur", LF("npc:cliffwatcher-longhorn", "Cliffwatcher_Longhorn")},
            nil, {"place:freewind", "place:great-lift", "faction:galak", TN}),
        Note("npc:xavathras", "Xavathras", "Person",
            "Xavathras is a particularly cruel satyr who leads the Jadefire satyrs at the Ruins of Constellas in Felwood, northwest of the Emerald Sanctuary. The Jadefire spread the corruption to any creature they meet. Eridan Bluewind of the Emerald Circle, who seeks to heal the land the night elves once held, wants Xavathras slain and his minions destroyed, though she senses that something larger than the satyrs is at work in Felwood.",
            {V .. " #4421 The Corruption of the Jadefire", LF("npc:xavathras", "Xavathras")},
            {"Xavathras"}, {"npc:eridan", FEL}),
        Note("npc:hagar", "Hagar Lightninghoof", "Person",
            "Hagar Lightninghoof of Freewind Post in Thousand Needles has heard a rumor of an alien egg in the canyons. Those who claim to have seen it could not get close enough to examine it, for serpents guard it as if it were one of their own, in one of the serpent dens along the base of the cliffs south and northeast of the post. Hagar wants the egg brought to him so that he can learn what will hatch from it. When he sees something he can hardly believe, it is Motega Firemane of Whitereach Post he sends for.",
            {V .. " #4821 Alien Egg; #4865 Serpent Wild", LF("npc:hagar-lightninghoof", "Hagar_Lightninghoof")},
            nil, {"place:freewind", "npc:motega-firemane", TN}),
    })
end

-- notes7 batch 4: the shaman's teachers the class scenes name, Durotar's and the Barrens'
-- of the vanilla trials and Forever's dwarven ones in Dun Morogh, Loch Modan and the
-- Wetlands; Darnassus's druid trainer; Tinker Town's Overspark; the naga of Zoram and the
-- harpy matriarch of the Dry Hills. "Serena" stays out as a given name.
do
    local DUR, BAR, TN = "region:4475726f746172", "region:5468652042617272656e73", "region:54686f7573616e64204e6565646c6573"
    local DM, LOCH, WET = "region:44756e204d6f726f6768", "region:4c6f6368204d6f64616e", "region:5765746c616e6473"
    A.RegisterLoreNotes({
        Note("npc:canaga", "Canaga Earthcaller", "Person",
            "Canaga Earthcaller guides the young shaman of the Horde in the Valley of Trials in Durotar toward their first element, earth. Patience, he teaches, is earth's greatest virtue. The earth witnesses the cycle of all things, mountains becoming deserts and rivers becoming canyons, and it does not tolerate impatience. It calls now, Canaga says, because a time of conflict draws near.\n\nThose who bring him two hooves of the felstalkers to the north receive a sapta, a drink that binds the spirit to an element and is only ever drunk in a holy place, and only a select few shaman know how to make one. This one is drunk at Spirit Rock, at the end of the Hidden Path southwest of the valley. The earth spirit there gives a rough quartz to carry back, and around it Canaga crafts the shaman's first totem.",
            {V .. " #1516 Call of Earth; #1517 Call of Earth; #1518 Call of Earth", LF("npc:canaga-earthcaller", "Canaga_Earthcaller")},
            {"Canaga"}, {"place:spirit-rock", "place:valley-trials", DUR}),
        Note("npc:kranal", "Kranal Fiss", "Person",
            "Kranal Fiss teaches the young shaman of the Horde the way of fire from a small dwelling north of the Crossroads in the Barrens, short of the night elves' lands. Trainers such as Searn and Xanis send their students to him once they are strong in the ways of earth. He warns them that power and destruction will come easily, and that they must still know when to stay their hand, as earth taught them.\n\nHis trial sends them with a torch to Telf Joolam at the Shrine of the Dormant Flame in Durotar. The torch must come back lit at the shrine's brazier before Kranal gives them the totem of fire.",
            {V .. " #1522 Call of Fire; #1523 Call of Fire; #1524 Call of Fire; #1527 Call of Fire"},
            {"Kranal"}, {"npc:telf-joolam", "place:dormant-flame", "place:crossroads", BAR}),
        Note("npc:prate", "Prate Cloudseer", "Person",
            "Prate Cloudseer teaches the element of air, the hardest of the four to control, from a hiding place far in the east of Thousand Needles. Horde shaman who have made headway on their path are sent to her for their air totem. She expects to be treated with respect. A troll trainer who sends students her way jokes that she hides in a hole with her boyfriend, and warns them not to repeat it, since she would not take it kindly.",
            {V .. " #1531 Call of Air; #1532 Call of Air"},
            {"Prate"}, {"npc:kranal", TN}),
        ForeverNote("npc:bruegs", "Bruegs Kindleborn", "Person",
            "Bruegs Kindleborn is a dwarf shaman who lives in a cave in the mountains above South Gate Outpost, in the far east of Dun Morogh. Dwarven shaman who have learned patience from the stone come to him for the sapta of fire. Fire is easy to wield, he warns them, but harder to master, and a shaman must know when to hold back.\n\nHis trial sends them with a torch beyond the Valley of Kings in Loch Modan, up a hidden path to a sacred peak where Braldir Ashmantle keeps the Shrine of the Dormant Flame. Those who bring the torch back burning from the shrine's brazier receive their totem of fire, with the praise of Bruegs, who swears by Madoran's beard.",
            {P1 .. " #94449 Call of Fire; #94465 Call of Fire; #94468 Call of Fire"},
            {"Bruegs"}, {"npc:braldir", DM, LOCH}),
        ForeverNote("npc:braldir", "Braldir Ashmantle", "Person",
            "Braldir Ashmantle keeps the Shrine of the Dormant Flame in Loch Modan, on a sacred peak reached by a hidden path in the crags beyond the Valley of Kings. Few climb that far. Wanderers who come chasing rumors of treasure or beasts find only stone and silence, and Braldir lets no one about the shrine who does not carry the torch of a fire trial. To the dwarven shaman the shrine holds a sacred flame that waits to be awakened, a truth deeper than the Alliance can fathom.\n\nBraldir makes the fire sapta from fire tar carried by the Tunnel Rat geomancers in the kobold caves to the north and a reagent pouch from a Stonesplinter seer in the southern hills. Fire, he teaches, is not only fury and ruin but life, the forge and the breath of creation, and true wisdom in magic lies in knowing when to blend, not only how to burn.",
            {P1 .. " #94465 Call of Fire; #94466 Call of Fire; #94467 Call of Fire"},
            {"Braldir"}, {"npc:bruegs", LOCH}),
        ForeverNote("npc:hervdana", "Hervdana Saegrund", "Person",
            "Hervdana Saegrund is a dwarf shaman whose family lives in a cave beneath the southern falls of the Wetlands, with Dark Iron dwarves about and no guard in sight. Norric Lochthane of Loch Modan sends shaman who seek the water sapta to her. Water means rebirth, she teaches. It carves stone, cleanses filth and heals the weary when it is pure, and ruins all it touches when it is tainted.\n\nHer students gather water in its different forms. They fill skins at the foot of the falls, where the fresh water meets the brackish marsh, at Stonewatch Falls in Redridge, where she judges that the magic of the shadowseers is changing the murlocs, and at the lake beside Astranaar in Ashenvale. From the three she brews a vial of pure water for the last rite, which Norric oversees. The Dark Irons have crept so far north, she says, that it makes her wonder what dwarfkind could do if the clans ever stopped squabbling and worked as one.",
            {P1 .. " #94495 Call of Water; #94497 Call of Water; #94499 Call of Water; #94500 Call of Water; #94501 Call of Water"},
            {"Hervdana"}, {"npc:norric", "place:stendels-pond", WET}),
        Note("npc:mathrengyl", "Mathrengyl Bearwalker", "Person",
            "Mathrengyl Bearwalker is a druid of the Cenarion Circle in Darnassus who trains its young druids. Students come back to him from their lessons, from facing Lunaclaw at the Moonkin Stone east of Auberdine and from the trials of Moonglade, to learn what they have earned, among it the aquatic form and the power over poison.\n\nHe also hands out the Tharlendris seeds that the Circle grows in soil from Un'Goro Crater with what it calls an Evergreen Pouch, on a voucher from Arch Druid Fandral Staghelm. The seeds blossom into an array of potent herbs, among them morrowgrain, a mysterious herb the Arch Druid means to understand. When Falla in Ashenvale found a shard of the Emerald Dream that held a nightmare, it was to Mathrengyl that she sent it.",
            {V .. " #6001 Body and Heart; #5061 Aquatic Form; #6125 Power over Poison; #3781 Morrowgrain Research; #3370 In Nightmares"},
            {"Mathrengyl"}, {"place:cenarion-enclave", "faction:cenarion-circle", "npc:fandral", "region:4461726e6173737573"}),
        Note("npc:overspark", "Tinkmaster Overspark", "Person",
            "Tinkmaster Overspark is a gnome tinker in Tinker Town in Ironforge. When Gnomeregan fell, he believes, a rogue spark must have jolted his creation Techbot, which once helped him and his associates with its countless gizmos and limitless store of information. Its positronic brain has polarized and turned negatronic, and now Techbot's behaviors are reversed and it roams Gnomeregan in a frenzy. Overspark hopes its memory core will show him the cause, so that he can fix it.\n\nHe also needs a large supply of essential artificials, a nigh-universal component of Gnomeregan's tinkers and smiths that no one remembered to take in the frantic exodus. They are still in the deeper parts of the city, in containers called artificial extrapolators.",
            {V .. " #2923 Tinkmaster Overspark; #2922 Save Techbot's Brain!; #2924 Essential Artificials"},
            {"Overspark"}, {"npc:techbot", "place:tinker-town", "dungeon:gnomeregan"}),
        Note("npc:ruuzel", "Ruuzel", "Person",
            "Ruuzel leads the naga of the Zoram Strand in Ashenvale and dwells on an isle at the northern edge of drowned Zoram. The naga found the Ring of Zoram after it had been lost for years. It belonged to the rulers of the city before the waves of the Sundering drowned it and is said to open any lock within it, and Ruuzel keeps it.",
            {V .. " #1009 Ruuzel"},
            {"Ruuzel"}, {"place:zoram-strand", "relic:ring-zoram", "npc:talen"}),
        Note("npc:serena-bloodfeather", "Serena Bloodfeather", "Person",
            "Serena Bloodfeather leads the Witchwing harpies of the Dry Hills in the Barrens, above the lieutenants who carry rings. She is the sister of a harpy named Bloodfeather, whom Rexxar slew long ago, and Darsok Swiftdagger of the Crossroads believes the harpies' attacks on the Horde's caravans are her revenge for her sister's death.",
            {V .. " #876 Serena Bloodfeather; #875 Harpy Lieutenants"},
            nil, {"npc:darsok", "npc:rexxar", BAR}),
    })
end

-- notes7 batch 5: smaller people of the 15-50 scenes with no note yet. Menethil's Tarrel and
-- Dun Algaz's Rockgar, Dun Modr's explosives expert, Thousand Needles' Kanati, the lost one
-- Noboru, Thorium Point's Oilfist and Hansel, Bashana of Elder Rise, the banshee Nightlash,
-- Desolace's kodo goblins, Winterspring's medium and the Grimtotem who sacked Makaba's
-- village. Kanati, Noboru and Hansel stay out as given names; their full names link.
do
    local TN, DES, SG = "region:54686f7573616e64204e6565646c6573", "region:4465736f6c616365", "region:53656172696e6720476f726765"
    local WET, STO = "region:5765746c616e6473", "region:53746f6e6574616c6f6e204d6f756e7461696e73"
    A.RegisterLoreNotes({
        Note("npc:tarrel", "Tarrel Rockweaver", "Person",
            "Tarrel Rockweaver waits at Menethil Harbor in the Wetlands for news of his wife, Merrin, who works with the team at the Whelgar Excavation Site to the east. She sent him a letter every week for a month, and then nothing for nearly two weeks. Longbraid promised to send a scout if the team stayed silent. Tarrel was quick at all things excavation in his school days, when Hollee of Auberdine was his classmate. She has long been fond of him, and he admits there was a time he would have returned it, but he is married, happily, he says.",
            {V .. " #305 In Search of the Excavation Team; #306 In Search of The Excavation Team; #98461 Unrequited Love", LF("npc:tarrel-rockweaver", "Tarrel_Rockweaver")},
            {"Tarrel"}, {"npc:merrin", "place:menethil", "place:whelgars-excavation-site", "npc:hollee"}),
        Note("npc:rockgar", "Mountaineer Rockgar", "Person",
            "Mountaineer Rockgar commands the dwarves at Dun Algaz, the pass between Loch Modan and the Wetlands. He called for volunteers for a scouting mission into the Wetlands, but the mission has turned messier. The Dragonmaw orcs have spread from their haven in the Wetlands into Dun Algaz, and if they keep their foothold there, he warns, Loch Modan will be cut off from Menethil Harbor. He wants a fighter to break through the pass, kill some orcs on the way and report to Valstag Ironjaw at Menethil.",
            {V .. " #468 Report to Mountaineer Rockgar; #455 The Algaz Gauntlet", LF("quest:468", "Mountaineer_Rockgar")},
            {"Rockgar"}, {"place:dun-algaz", "faction:dragonmaw", "npc:valstag", "region:4c6f6368204d6f64616e"}),
        Note("npc:ashlan", "Ashlan Stonesmirk", "Person",
            "Ashlan Stonesmirk is an explosives expert assigned to the regiment that guards Dun Modr and the Thandol Span in the Wetlands. His ears ring so that he can hardly hear a thing. When Chief Engineer Hinderweir the Seventh of the Stonewrought Dam found a strange powder, it was Ashlan who knew it by its tiny silver crystals and its smell for Seaforium Powder. Seaforium is harmless enough, he says, but once it is wet it could blow Ironforge out of the mountain. The reaction can be defused with four components, lurker venom, a crushed Mo'Grosh crystal, a crocolisk tear and a disarming colloid of his own.",
            {V .. " #161 A Dark Threat Looms; #274 A Dark Threat Looms", LF("npc:ashlan-stonesmirk", "Ashlan_Stonesmirk")},
            {"Stonesmirk"}, {"place:dun-modr", "npc:hinderweir", "place:stonewrought-dam", WET}),
        Note("npc:kanati", "Kanati Greycloud", "Person",
            "Kanati Greycloud is a tauren hunter who has boldly set up a hunting camp in Thousand Needles, near Whitereach Post. The Galak centaur want him dead, and orders found on them call for a gathering at the small post southwest of the Great Lift to kill him and rid the Needles of his camp and of all who might follow him. Kanati means to show them how a tauren fights, though he fears there may be more centaur than he thought.",
            {V .. " #4881 Assassination Plot; #4966 Protect Kanati Greycloud", LF("npc:kanati-greycloud", "Kanati_Greycloud")},
            nil, {"place:whitereach-post", "faction:galak", "place:great-lift", TN}),
        Note("npc:noboru", "Noboru the Cudgel", "Person",
            "Noboru the Cudgel is one of the lost ones, the draenei of the Swamp of Sorrows who were driven mad, and he and his gang have plagued the draenei of the Harborage for months. They wander the swamp and kill any draenei who cross their path. His cudgel has become a symbol of the brutality the Harborage suffers at the hands of the lost ones, and its people count him a direct threat to their survival that they lack the strength to face.",
            {V .. " #1392 Noboru the Cudgel"},
            nil, {"place:harborage", "place:fallow-sanctuary", "region:5377616d70206f6620536f72726f7773"}),
        Note("npc:oilfist", "Overseer Oilfist", "Person",
            "Overseer Oilfist commands the Thorium Brotherhood at Thorium Point in the Searing Gorge, his eminence in the words of its bounties. By his order a price stands on the head of Overseer Maltorius, the rogue Brotherhood agent who now commands the Dark Iron crew of the Slag Pit. The greater lava spiders of the Gorge trouble him as well, since by his account they shoot fire from an unfortunate place.",
            {V .. " #7701 WANTED: Overseer Maltorius; #7724 Fiery Menace!"},
            {"Oilfist"}, {"faction:thorium-brotherhood", "place:thorium-point", "place:slag-pit", SG}),
        Note("npc:hansel", "Hansel Heavyhands", "Person",
            "Hansel Heavyhands is a huge Dark Iron dwarf of the Thorium Brotherhood at Thorium Point in the Searing Gorge. He is given the dangerous work below the outpost and passes it on, with complaints. The climate and the thin air of the Gorge, he says, make his fingers swell like Thelsamar blood sausages, his bunions have bunions, and the cold gives him sniffles. His jobs include pounding the heavy war golems of the Gorge, killing the greater lava spiders, and clearing the incendosaurs from the lava pools of the Slag Pit so that Scrange and Burninate can send expeditionary teams down.",
            {V .. " #7723 Curse These Fat Fingers; #7724 Fiery Menace!; #7727 Incendosaurs? Whateverosaur is More Like It", LF("npc:hansel-heavyhands", "Hansel_Heavyhands")},
            nil, {"place:thorium-point", "faction:thorium-brotherhood", "place:slag-pit", SG}),
        Note("npc:bashana", "Bashana Runetotem", "Person",
            "Bashana Runetotem is a tauren of Elder Rise in Thunder Bluff who aids the Cenarion Circle, the daughter of Arch Druid Hamuul Runetotem. Word from Blackfathom Deeps is meant for her. The Twilight's Hammer cultists there, allied with the naga and led by Kelris, sacrifice innocents to Aku'mai, servant of an Old God, and the wounded scout who calls for help wants Kelris slain and his head brought to Bashana. Peace between the earth and all her people should be the goal, Bashana says, for the Earth Mother has a grand plan for nature in which all have a role.",
            {V .. " #6561 Blackfathom Villainy", LF("npc:bashana-runetotem", "Bashana_Runetotem")},
            {"Bashana"}, {"place:elder-rise", "npc:hamuul", "dungeon:blackfathom", "npc:kelris"}),
        Note("npc:nightlash", "Nightlash", "Person",
            "Nightlash is a banshee who reinforces the rot hide gnolls at the Dead Fields, an old farm in northern Silverpine Forest. Every small assault the Forsaken sent against the rot hides there was routed by her magic, and High Executor Hadrec at the Sepulcher wants her destroyed. When she falls, her essence turns to dust.",
            {V .. " #437 The Dead Fields", LF("item:essence-of-nightlash", "Nightlash")},
            {"Nightlash"}, {"place:dead-fields", "group:rot-hides", "npc:hadrec"}),
        Note("npc:smeed", "Smeed Scrabblescrew", "Person",
            "Smeed Scrabblescrew is a goblin of Desolace who has learned to rejuvenate and control aged and dying kodos with his kodo kombobulator, which jolts such a beast into a tamed kodo that follows its handler. That made him a partner of Cork and Rigger Gizelton, whose caravan is the only one brave enough to travel those parts, and he supplies it with tamed kodos. He thinks little of Bibbly F'utzbuckle, who believes he is the only goblin in Desolace who knows how to make money.",
            {V .. " #5561 Kodo Roundup", LF("quest:5561", "Smeed_Scrabblescrew")},
            {"Smeed"}, {"npc:bibbly", "place:kodo-graveyard", DES}),
        Note("npc:bibbly", "Bibbly F'utzbuckle", "Person",
            "Bibbly F'utzbuckle is a goblin at Kormek's Hut in Desolace who trades in bones from the kodo graveyard to the south. Kodo bones, he says, will change the world. His customers make furniture, musical instruments and even blasting powder from them, and a caravan carries them to Shadowprey Village to be sold. He means to reach a career high, become the richest goblin in the world and see his face on the cover of Goblin'preneur.",
            {V .. " #5501 Bone Collector", LF("quest:5501", "Bibbly_F%27utzbuckle")},
            {"Bibbly"}, {"place:kodo-graveyard", "place:shadowprey", "npc:smeed", DES}),
        Note("npc:umbranse", "Umbranse the Spiritspeaker", "Person",
            "Umbranse the Spiritspeaker is a human medium in the east of Winterspring who speaks for the dead. Itharius of the green dragonflight counts him among the dragons' mortal allies, and when the voice of one who is not truly dead is sought, Umbranse lends his skill.",
            {V .. " #3512 In Eranikus' Own Words"},
            {"Umbranse"}, {"npc:itharius", "region:57696e746572737072696e67"}),
        Note("npc:grundig", "Grundig Darkcloud", "Person",
            "Grundig Darkcloud leads a personal band of Grimtotem brutes, by far the worst of the lot, at Grimtotem Post in the southeast of the Stonetalon Mountains. He led the brutal attack on the village of Makaba Flathoof, in which the Grimtotem killed most everyone. Makaba fought, barely escaped with his life, and wants Grundig and his brutes dead.",
            {V .. " #6548 Avenge My Village; #6629 Kill Grundig Darkcloud"},
            {"Grundig"}, {"place:grimtotem-post", "npc:makaba-flathoof", "faction:grimtotem", STO}),
    })
end
